local _, ns = ...
local E = ns.DB.entries
E["item:a-letter-to-grelin-whitebeard"] = {t="item",n="A Letter to Grelin Whitebeard",z="dunmorogh",s="This sealed correspondence is addressed to Grelin Whitebeard, an experienced dwarf stationed out in the snowy wilderness of Coldridge Valley. Sent from the mountain capital of Ironforge, it serves as a rare dispatch of news and instructions reaching the remote frontier.",h="This sealed correspondence is addressed to Grelin Whitebeard, an experienced dwarf stationed out in the snowy...",sec={{t="A Dispatch from the Mountain",b="Life in the snowy basin of Coldridge Valley can be isolated, especially for those stationed beyond the safety of Anvilmar. Letters like this represent the crucial link connecting scouts and scholars in the field to the halls of Ironforge. Carried southward along the mountain paths, the missive brings word from the capital to Grelin Whitebeard's wilderness campsite.",sp=0}},faq={{q="Who is Grelin Whitebeard?",a="Grelin Whitebeard is a dwarven scout and explorer encamped in the southeastern reaches of Coldridge Valley. He relies on messengers from Anvilmar to keep him informed of affairs and instructions from Ironforge.",al={"grelin whitebeard","who is grelin","recipient"},it="target"},{q="Where did this letter come from?",a="The correspondence originates from the dwarven capital of Ironforge, forwarded down through Coldridge Valley's local postal courier to be carried out into the field.",al={"letter origin","who sent the letter","where is it from"},it="origin"},{q="What is inside the letter?",a="It is a short note from King Magni Bronzebeard, who has no time to spare and grants Grelin the use of his authority to deal with the trolls however he sees fit, especially if he can find a quick solution. Grelin welcomes it, as it has been a while since he received word from Ironforge.",al={"letter contents","what does it say","letter text"},it="item"},{q="What is A Letter to Grelin Whitebeard?",a="It is a sealed missive sent from Ironforge, carried down through Coldridge Valley for delivery to Grelin Whitebeard at his camp along the road.",al={"what is grelin whitebeard letter","letter to grelin whitebeard","what is this letter"},it="identity",add="163f292d"},{q="Why does Grelin Whitebeard want this letter?",a="Grelin has been stationed out at his camp in Coldridge Valley for some time without news from the capital. He is eager to receive word from Ironforge.",al={"why deliver letter to grelin","why does grelin want the letter","who wants grelins letter"},it="why_wanted",add="b0fcb20c"}},ang={["race:Dwarf"]="Carrying dispatches across the freezing passes of Dun Morogh is a foundational duty for young dwarven mountaineers and recruits making a name for themselves."},kw={"coldridge valley","dun morogh","grelin whitebeard","ironforge","letter","mail delivery"},rel={"quest:233","npc:grelin-whitebeard","subzone:coldridge-valley","zone:ironforge","zone:dunmorogh"},src={"A Letter to Grelin Whitebeard","Coldridge Valley Mail Delivery (2)"}}
E["item:a-stack-of-letters"] = {t="item",n="A Stack of Letters",z="dunmorogh",s="A Stack of Letters is a small bundle of correspondence brought through the mountain pass into Coldridge Valley. Though initially believed to belong entirely to Talin Keeneye, the bundle holds communications meant for multiple scouts stationed in the freezing wilderness.",h="A Stack of Letters is a small bundle of correspondence brought through the mountain pass into Coldridge...",sec={{t="Through the Pass",b="Reaching remote camps within Dun Morogh's rugged mountains is grueling work, and postal runners often rely on passing travelers to carry mail out of Anvilmar. This bundle of letters arrived through the pass destined for scouts stationed deeper in Coldridge Valley. While thought to be solely for Talin Keeneye at his lakeside camp, sorting through the parcel reveals missives meant for other outposts across the snows, including mountaineer Grelin Whitebeard.",sp=0}},faq={{q="What is inside the stack of letters?",a="The bundle contains personal correspondence and dispatches for dwarves stationed in Coldridge Valley. While thought to be entirely for Talin Keeneye near the frozen lake, sorting through them reveals at least one letter addressed to Grelin Whitebeard.",al={"what is in the letters","stack of letters contents","who are letters for"},it="item"},{q="Who sends these letters to Coldridge Valley?",a="The letters came through the pass leading into Coldridge Valley, arriving at Anvilmar before being handed off to a traveler willing to deliver them down the road.",al={"where did the letters come from","who sent the letters"},it="origin"},{q="Who receives the letters?",a="The parcel is first handed directly to the dwarf scout Talin Keeneye at his camp by the frozen lake. After looking through the stack, he discovers a letter belonging to Grelin Whitebeard.",al={"who gets the letters","letter delivery target"},it="target"},{q="What is A Stack of Letters?",a="It is a bundle of mail that arrived in Coldridge Valley through the mountain pass. Entrusted to you at Anvilmar, the stack contains correspondence meant for local mountaineers stationed out in the snowy wilderness.",al={"what is the stack of letters","stack of letters item","what are the letters"},it="identity",add="6f17116a"},{q="Why does anyone want A Stack of Letters?",a="The mountaineers living and patrolling out in the cold rely on regular post to stay informed. Talin Keeneye has been waiting by the frozen lake for these dispatches for quite some time, though upon inspection, not every letter in the bundle belongs solely to him.",al={"why deliver the letters","why does talin want the letters","stack of letters purpose"},it="why_wanted",add="9fce371d"}},ang={["race:Dwarf"]="For young mountaineers starting their journeys in Coldridge Valley, running mail between snowy camps is an early introduction to the harsh roads and scattered watchers guarding Dun Morogh."},kw={"anvilmar","coldridge valley","coldridge valley mail delivery","grelin whitebeard","stack of letters","talin keeneye"},rel={"quest:233","subzone:coldridge-valley","npc:grelin-whitebeard","zone:dunmorogh"},src={"A Stack of Letters","Coldridge Valley Mail Delivery"}}
E["item:alterac-granite"] = {t="item",n="Alterac Granite",z="dunmorogh",s="Alterac Granite is a prized, durable stone quarried from the mountainous terrain of northern Lordaeron, specifically around Darrow Hill in the Hillsbrad Foothills. Revered by master stonecutters for its exceptional resilience and grain, it is chosen by King Magni Bronzebeard's royal mason to carve an enduring tribute for fallen soldiers.",h="Alterac Granite is a prized, durable stone quarried from the mountainous terrain of northern Lordaeron...",sec={{t="Stone of Memorials",b="When King Magni Bronzebeard ordered a monument to commemorate Sully Balloo—a brave dwarven defender who perished in the tragedy at the Thandol Span—ordinary quarry stone would not do. Grand Mason Marblesten, tasked with sculpting the memorial in Ironforge, insisted on obtaining Alterac Granite. Renowned as one of the finest stones available across the Eastern Kingdoms, its legendary durability ensures that the likeness and memory of a fallen hero can endure untarnished for generations.",sp=0},{t="Quarried in Peril",b="Harvesting Alterac Granite is far from a simple errand. The stone rests around Darrow Hill in the northern reaches of the Hillsbrad Foothills, close to the ruined territories of Alterac. With the region rife with hostile wildlife, lurking syndicate brigands, and lingering strife, retrieving unblemished slabs of this pristine stone requires bold adventurers willing to venture deep into contested lands to secure it for Ironforge's artisans.",sp=0}},faq={{q="What is Alterac Granite used for?",a="Alterac Granite is commissioned by Grand Mason Marblesten in Ironforge to carve a royal memorial honoring Sully Balloo, a dwarven soldier who fell defending the Thandol Span.",al={"alterac granite use","why alterac granite","marblesten stone"},it="why_wanted"},{q="Where can Alterac Granite be found?",a="It is gathered from stone deposits at Darrow Hill, located in the northern area of the Hillsbrad Foothills near the border of Alterac.",al={"alterac granite location","where to get alterac granite","darrow hill granite"},it="origin",gp=true},{q="Why did Grand Mason Marblesten specifically want this stone?",a="Grand Mason Marblesten considers Alterac Granite one of the finest and most resilient carving stones available, deeming it the only material worthy of a lasting royal monument commissioned by King Magni.",al={"why marblesten wants granite","why alterac stone"}},{q="Who was Sully Balloo?",a="Sully Balloo was a dwarven soldier who died during the fighting at the Thandol Span. King Magni Bronzebeard commissioned a monument in his honor to commemorate his sacrifice for the Alliance.",al={"sully balloo","who died at thandol span"}},{q="What is Alterac Granite?",a="Alterac Granite is a prized, high-quality quarry stone found in the northern hills. Renowned among master stonecutters as one of the finest carving stones available, it possesses the durability and pristine grain needed to craft epic, enduring monuments worthy of royal commissions.",al={"what is alterac granite","alterac granite item","alterac granite info"},it="identity",add="9814170d"},{q="Where does Alterac Granite come from, and who made it?",a="Alterac Granite is a natural stone quarried from Darrow Hill in the foothills of Hillsbrad, bordering the rugged mountains of Alterac. It is not manufactured by any craftsman; rather, it is hewn directly from the ancient rock of the hills, waiting for skilled masons to shape it into enduring works.",al={"alterac granite origin","where is alterac granite mined","who made alterac granite"},it="origin",add="842d3593"}},ang={["race:Dwarf"]="Dwarven stonemasons hold material quality above all else, making this robust mountain stone essential for honoring a fellow son of Ironforge.",["profession:Mining"]="Miners and prospectors appreciate Alterac Granite for its clean fracture and extraordinary density, distinguishing it from common crag rock."},kw={"alterac granite","darrow hill","hillsbrad","ironforge","marblesten","sully balloo","thandol span"},rel={"npc:grand-mason-marblesten","quest:686","subzone:darrow-hill","subzone:thandol-span","quest:631","zone:ironforge","topic:alterac-kingdom","zone:dunmorogh"},src={"Alterac Granite","A King's Tribute (2)"}}
E["item:barrel-of-barleybrew-scalder"] = {t="item",n="Barrel of Barleybrew Scalder",z="dunmorogh",s="The Barrel of Barleybrew Scalder is a cask of stout ale crafted by the Barleybrew family to prove their brewing prowess against their chief competitors. It is entrusted to covert couriers tasked with infiltrating the Thunderbrew Distillery in Kharanos to stage a sly taste-test sabotage.",h="The Barrel of Barleybrew Scalder is a cask of stout ale crafted by the Barleybrew family to prove their...",sec={{t="A Bitter Feud in Dun Morogh",b="Brewing is serious business among the dwarves of Dun Morogh, and few rivalries burn hotter than the feud between the Thunderbrews and the Barleybrews. While the Thunderbrews enjoy vast renown and pride of place from their busy distillery in Kharanos, Marleth Barleybrew refuses to sit in their shadow. Rather than relying solely on open taverns, Marleth brews the fiery 'Scalder' to prove his recipes are second to none—hoping that unsuspecting patrons who taste it will realize the Thunderbrews do not hold a monopoly on fine dwarven drink.",sp=0},{t="Subterfuge in the Cellar",b="The barrel is meant to be snuck straight into the cellars beneath the Thunderbrew Distillery, swapping places with a cask of the local favorite, Thunder Ale. The intent is not poisonous or ruinous, but a cheeky dwarven prank aimed at wounded pride: ensuring the next batch served upstairs is secretly Barleybrew's potent scalder instead.",sp=1}},faq={{q="What is inside the Barrel of Barleybrew Scalder?",a="It contains Marleth Barleybrew's signature scalder, a potent dwarven brew crafted to rival the famed recipes of the Thunderbrew family.",al={"barleybrew scalder contents","what kind of ale","what is scalder"},it="item"},{q="Why does Marleth want this barrel swapped?",a="Marleth admits the Thunderbrews craft good drinks, but he wants to teach them humility by letting cellar patrons inadvertently taste his own brew and see that Barleybrew craftsmanship is just as good, if not better.",al={"why swap barrels","bitter rivals reason","why marleth sneak brew"},it="why_wanted"},{q="Where does this barrel go?",a="It is taken down into the cellar beneath the Thunderbrew Distillery in Kharanos and swapped into the racks where a cask of Thunder Ale is due to be tapped.",al={"where do i put the barrel","scalder barrel location","distillery cellar"},it="purpose"},{q="Is the brew meant to harm anyone?",a="No. It is simply a strong, competing dwarven ale. The rivalry between the families is intense and competitive, but it is a matter of professional pride rather than malice.",al={"is scalder poisoned","is it poison","will it hurt anyone"},it="threat"},{q="What is the Barrel of Barleybrew Scalder?",a="It is a cask of potent ale crafted by Marleth Barleybrew. Rather than being sold through standard trade, this specific barrel serves as an instrument in a brewing rivalry, intended to be secretly substituted into a competitor's stock to win over unsuspecting drinkers.",al={"what is barleybrew scalder","barleybrew scalder barrel","barrel of barleybrew scalder"},it="identity",add="9f414f7e",nx={6}},{q="Where does the Barrel of Barleybrew Scalder come from, and who made it?",a="The cask was brewed and provided by Marleth Barleybrew. Proud of his family's craft, Marleth concocted the recipe to prove that the Barleybrews can match or exceed the renown of the rival Thunderbrew family.",al={"who made barleybrew scalder","where did barleybrew scalder come from","barleybrew scalder origin"},it="origin",add="00d1bcdd"}},ang={["race:Dwarf"]="For dwarves, ale crafting is both an art and a bloodsport; taking part in cellar intrigue over whose recipe is superior is practically a Dun Morogh pastime.",["class:Rogue"]="Distracting a cellar guard and sneaking heavy contraband into a guarded stash offers an amusing, low-stakes exercise in classic dwarven subterfuge."},kw={"ale","barleybrew","distillery","dun morogh","kharanos","marleth","scalder","thunderbrew"},rel={"quest:310","quest:311","item:barrel-of-thunder-ale","subzone:thunderbrew-distillery","subzone:kharanos","quest:117","zone:dunmorogh"},src={"Barrel of Barleybrew Scalder","Bitter Rivals"}}
E["item:barrel-of-shimmer-stout"] = {t="item",n="Barrel of Shimmer Stout",z="dunmorogh",s="A freshly brewed cask of Rejold Barleybrew's experimental dwarven ale, crafted in the cold reaches of Dun Morogh. Known for giving drinkers a potent jolt that supposedly brightens their vision, it is intended as a gift for guards keeping watch on the high mountain passes.",h="A freshly brewed cask of Rejold Barleybrew's experimental dwarven ale, crafted in the cold reaches of Dun...",sec={{t="A Brewer's Pride",b="Crafted by Rejold Barleybrew after gathering rare ingredients across Dun Morogh, Shimmer Stout represents the latest triumph of the storied Barleybrew family. Dwarven brewers take their craft with deadly seriousness, constantly competing to produce hearty concoctions capable of staving off the freezing mountain chill. Rejold's latest recipe is designed not only to warm the gut, but to sharpen the senses of those stationed out in the freezing winds.",sp=0},{t="Supplies for the Watch",b="This particular barrel is earmarked for Mountaineer Wellart Barleybrew, who stands guard at the southern tower along the pass leading into Loch Modan. Out on the lonely frontier, mountaineers endure bone-chilling cold and prolonged watches between skirmishes with troggs and wildlife. A fresh cask of family ale serves as both a welcome taste of home and an energizing tonic potent enough to make a tired sentry swear he can see clearly through the dark.",sp=0}},faq={{q="What is in the Barrel of Shimmer Stout?",a="It contains Shimmer Stout, a brand new dwarven recipe concocted by Rejold Barleybrew. The drink is famous for its remarkably potent kick, leaving anyone who samples it feeling energized with a literal shine in their eyes.",al={"what is shimmer stout","what kind of ale is this","shimmer stout drink"},it="identity"},{q="Who made this barrel of stout?",a="The ale was brewed by Rejold Barleybrew, a member of the renowned Barleybrew clan of Dun Morogh who spent time perfecting a recipe to impress his kin.",al={"who brewed shimmer stout","shimmer stout brewer","rejold barleybrew"},it="origin"},{q="Who is this barrel meant for?",a="It is intended for Rejold's brother, Mountaineer Wellart Barleybrew, who is stationed at the southern guard tower along the road into Loch Modan.",al={"who gets the barrel","where does the stout go","wellart barleybrew"},it="why_wanted"},{q="What effect does Shimmer Stout have on someone who drinks it?",a="Beyond delivering a potent buzz, the stout gives drinkers an intense jolt that makes their eyes sparkle and feel as though they can see in pitch blackness, making it quite popular among vigilant mountaineers.",al={"shimmer stout effect","does it make you see in dark","what does shimmer stout do"},it="power"}},ang={["race:Dwarf"]="Brewing is a cultural cornerstone of Ironforge society, and delivering a newly perfected stout to a kinsman on watch is an honorable mountain tradition.",["profession:Cooking"]="Dwarven ales frequently push the boundaries of culinary experimentation, balancing potent fermentation with hardy mountain ingredients to withstand biting weather."},kw={"barrel of shimmer stout","dun morogh","dwarven ale","loch modan","mountaineer barleybrew","rejold barleybrew","shimmer stout"},rel={"quest:413","npc:mountaineer-barleybrew","quest:415","quest:414","zone:dunmorogh","zone:lochmodan"},src={"Barrel of Shimmer Stout","Shimmer Stout (quest)"}}
E["item:barrel-of-thunder-ale"] = {t="item",n="Barrel of Thunder Ale",z="dunmorogh",s="The Barrel of Thunder Ale is a prized keg of Kharanos's signature brew, smuggled straight out of the Thunderbrew Distillery's cellar. Swapped out for a cask of Marleth's Barleybrew Scalder, it serves as undeniable proof of foul play in an escalating brewing rivalry.",h="The Barrel of Thunder Ale is a prized keg of Kharanos's signature brew, smuggled straight out of the...",sec={{t="A Bitter Trade",b="In Dun Morogh, competition between rival master brewers runs deep, and few disputes are fiercer than the feud between the Thunderbrews of Kharanos and the Barleybrews of Brewnall Village. Marleth Barleybrew sought to slip a barrel of his own Barleybrew Scalder into his rivals' cellar, so that the Thunderbrews' patrons would taste his brew over theirs. This heavy barrel of Thunder Ale was seized in the exchange, dragged out under the noses of the local guards as physical evidence that the switch succeeded.",sp=0}},faq={{q="What is inside this barrel?",a="It contains Thunder Ale, the famous stout brewed by the Thunderbrew family down in Kharanos. It is known across Dun Morogh as a stout, potent dwarven ale.",al={"thunder ale contents","what is thunder ale"},it="identity"},{q="Where did this barrel come from?",a="It is lifted directly from the cellar storage inside the Kharanos Distillery, taken during the clandestine delivery of Marleth's rival brew.",al={"where do you get it","thunder ale location"},it="origin"},{q="Who wants this barrel?",a="Marleth Barleybrew, located at Brewnall Village to the west. He expects the barrel brought to him as proof that his Scalder was successfully planted among the Thunderbrews' barrels.",al={"who do i bring thunder ale to","marleth barleybrew quest"},it="why_wanted"},{q="Why was the barrel taken?",a="Marleth wanted tangible proof that someone managed to sneak into the Thunderbrew cellar, slip past the distillery guard, and sabotage his competitors' supply.",al={"why steal thunder ale","bitter rivals story"},it="why_wanted"}},ang={["race:Dwarf"]="For dwarves, beer brewing is serious business and high politics; swapping out a rival clan's prized cask in their own cellar is an audacious insult.",["class:Rogue"]="Slipping into a guarded cellar and swapping out heavy ale barrels without raising the alarm is a classic, practical display of stealth and finesse."},kw={"barrel of thunder ale","brewnall village","dun morogh","kharanos","marleth barleybrew","thunder ale","thunderbrew"},rel={"quest:311","quest:310","npc:marleth-barleybrew","subzone:kharanos","subzone:brewnall-village","zone:dunmorogh"},src={"Barrel of Thunder Ale","Return to Marleth"}}
E["item:cask-of-shimmer-stout"] = {t="item",n="Cask of Shimmer Stout",z="dunmorogh",s="The Cask of Shimmer Stout is a sealed barrel of Rejold Barleybrew's potent new ale, crafted in the cold heights of Dun Morogh. Known for its remarkable kick and head-spinning vigor, it is sent eastward across the mountains as a spirited gift for fellow dwarven mountaineers.",h="The Cask of Shimmer Stout is a sealed barrel of Rejold Barleybrew's potent new ale, crafted in the cold...",sec={{t="A Spirited Delivery",b="Brewed in Kharanos by Rejold Barleybrew, Shimmer Stout quickly earned high marks among local patrons and mountaineers who braved the biting frosts of Dun Morogh. Impressed by his brother's concoction, Mountaineer Barleybrew commissioned a cask to be hauled through the eastern pass into Loch Modan. Dwarves hold strong drink in high regard as both a social staple and a practical defense against the biting mountain chill, and sharing a fresh vintage with far-flung comrades is a time-honored military tradition.",sp=0},{t="A Dwarven Pick-Me-Up",b="When opened and sampled by Mountaineer Kadrell along his watch in Thelsamar, the brew proves true to its reputation. Far from ordinary tavern draught, a single draught of Shimmer Stout is said to lighten limbs and leave a soldier feeling as though they could take flight—the exact sort of invigorating potion a dwarven scout relies upon while walking long, lonely patrols along the high roads.",sp=0}},faq={{q="What is Shimmer Stout?",a="Shimmer Stout is a potent dwarven ale concocted by Rejold Barleybrew in Dun Morogh. Highly regarded for its strong kick, it is renowned for invigorating the body and keeping the cold at bay.",al={"what is shimmer stout","shimmer stout lore","who brewed shimmer stout"},it="identity"},{q="Who is the cask being sent to?",a="The cask is dispatched to Mountaineer Kadrell, a guard stationed along the road passing through the settlement of Thelsamar in Loch Modan.",al={"who gets the cask","where does cask go","cask recipient"}},{q="Why send ale across the mountains?",a="Dwarven mountaineers frequently share exceptional brews with their fellows on far-flung patrols. After tasting Rejold's successful creation, his brother wished to treat Kadrell to a sample of Dun Morogh's finest new recipe.",al={"why delivery","why deliver beer","why send to kadrell"}},{q="What effect does Shimmer Stout have on the drinker?",a="The ale is surprisingly potent. Upon tasting it, Mountaineer Kadrell exclaims that it makes his head spin, lightens his limbs, and leaves him feeling as if he could fly.",al={"how strong is shimmer stout","shimmer stout effect"},it="power"},{q="Where does the Cask of Shimmer Stout come from, and who made it?",a="This potent brew was crafted by Rejold Barleybrew over at the Barleybrew Brewery in Dun Morogh. His brother, Mountaineer Barleybrew, was so impressed with the concoction that he packaged up this cask to share outside their homeland, having an adventurer carry it all the way into Loch Modan.",al={"who made shimmer stout","where is shimmer stout from","cask of shimmer stout brewer"},it="origin",add="32178f62"},{q="Why does anyone want the Cask of Shimmer Stout?",a="Mountaineer Barleybrew loves his brother's new recipe and wants a fellow watchman, Mountaineer Kadrell, to sample the batch. Kadrell patrols the chilly roads around Thelsamar, and a sturdy dwarven ale that warms the blood, lightens the limbs, and turns the head makes fine cheer during long watches.",al={"why send shimmer stout","who wants the cask of shimmer stout","why does kadrell want shimmer stout"},it="why_wanted",add="3b29018e"}},ang={["race:Dwarf"]="For dwarves, sharing fine ale between patrols is a respected tradition that binds the far-flung Mountaineers across the rugged peaks of Khaz Modan."},kw={"cask of shimmer stout","dun morogh","kadrell","loch modan","rejold barleybrew","shimmer stout","thelsamar"},rel={"quest:414","npc:mountaineer-kadrell","quest:413","quest:415","subzone:thelsamar","zone:lochmodan","zone:dunmorogh"},src={"Cask of Shimmer Stout","Stout to Kadrell"}}
E["item:consecrated-rune"] = {t="item",n="Consecrated Rune",z="dunmorogh",s="A Consecrated Rune is an inscribed sacred item passed to fledgling dwarven paladins training in Coldridge Valley. It serves as an introductory summons from Bromos Grummner, directing initiates to report to Anvilmar and begin their formal duties as Knights of the Silver Hand.",h="A Consecrated Rune is an inscribed sacred item passed to fledgling dwarven paladins training in Coldridge...",sec={{t="A Calling to the Silver Hand",b="Novice dwarven paladins proving themselves in Coldridge Valley are handed a Consecrated Rune once they have shown basic martial competence. Inscribed with sacred words and blessed by the Holy Light, the rune originates from Bromos Grummner, the paladin trainer residing inside Anvilmar. Dwarves hold immense respect for the traditions of the Holy Light introduced to them by their human allies. Reading the rune serves as both an official summons and a symbolic rite of passage, confirming the novice's place among the Knights of the Silver Hand.",sp=0}},faq={{q="What is the Consecrated Rune used for?",a="The rune is a written summons meant to be read by novice dwarven paladins. It directs them to seek out Bromos Grummner inside Anvilmar to advance their paladin training.",al={"consecrated rune purpose","what does the rune do","consecrated rune quest item"},it="item",gp=true},{q="Who sends the Consecrated Rune?",a="It is sent by Bromos Grummner, the dwarven paladin trainer stationed inside Anvilmar in Coldridge Valley.",al={"who gave me consecrated rune","rune origin","bromos grummner rune"},it="origin"},{q="Why do dwarven paladins follow the traditions of the Silver Hand?",a="Dwarves learned much of the Holy Light and the ways of the Silver Hand from human mentors. They hold high reverence for the order's history, traditions, and the belief that a single sacrifice can alter the fate of Azeroth.",al={"dwarf paladin silver hand","why are dwarves paladins","dwarves and holy light"},it="history"},{q="What is the Consecrated Rune?",a="It is an inscribed dwarven stone blessed in the Holy Light, sent as a formal summons to novice paladins training in Coldridge Valley. Dwarves blend runic craftsmanship with holy teachings, using stones like this one to impart solemn messages and call budding defenders of the Light to their mentors.",al={"what is consecrated rune","consecrated rune item","consecrated rune meaning"},it="identity",add="dda1df9e"},{q="Why does Bromos Grummner want you to have the Consecrated Rune?",a="Bromos Grummner sends the rune to test your readiness and direct you to Anvilmar for formal training. There is trouble brewing across Dun Morogh, and the Knights of the Silver Hand need capable, disciplined hands ready to uphold their sacred duty and safeguard Azeroth from harm.",al={"why consecrated rune","why bromos wants consecrated rune","why do i get consecrated rune"},it="why_wanted",add="924bde77"}},ang={["class:Paladin"]="For dwarven paladins, receiving this rune represents their formal step into the ranks of the Knights of the Silver Hand under the guidance of Bromos Grummner.",["race:Dwarf"]="The rune reflects the integration of human holy traditions into dwarven martial culture, rooted in the shared alliance and mutual respect between Ironforge and humanity."},kw={"anvilmar","bromos grummner","coldridge valley","consecrated rune","holy light","paladin","silver hand"},rel={"quest:3107","npc:bromos-grummner","subzone:anvilmar","subzone:coldridge-valley","topic:paladin","topic:light","topic:human","zone:dunmorogh"},src={"Consecrated Rune","Consecrated Rune (Classic)"}}
E["item:crate-of-inn-supplies"] = {t="item",n="Crate of Inn Supplies",z="dunmorogh",s="The Crate of Inn Supplies is a parcel packed in Coldridge Valley destined for the Thunderbrew Distillery in Kharanos. With the mountain pass overrun by troggs, regular supply routes are cut, leaving the inn dependent on passing travelers to carry goods through.",h="The Crate of Inn Supplies is a parcel packed in Coldridge Valley destined for the Thunderbrew Distillery in...",sec={{t="Through the Trogg Pass",b="Ordinarily, goods flow smoothly between the quiet training grounds of Anvilmar and the bustling towns of Dun Morogh. However, recent trogg incursions have severed Coldridge Pass, cutting off civilian couriers until armed Mountaineer escorts can clear the roads. Packed by Hands Springsprocket, this heavy crate holds essential tavern provisions that Tannok Frosthammer in Kharanos has been waiting on anxiously amid the disruption.",sp=0}},faq={{q="What is inside the crate?",a="The crate contains general tavern supplies dispatched from Coldridge Valley to keep the inn in Kharanos well-stocked for travelers and locals seeking warmth.",al={"crate contents","inn supplies contents","what is in the box"},it="item"},{q="Who sends the crate to Kharanos?",a="Hands Springsprocket, stationed near Anvilmar, packages the crate and asks adventurers heading out of Coldridge Valley to carry it across the mountain pass.",al={"who gives the crate","hands springsprocket","sender"},it="origin"},{q="Why couldn't the normal courier deliver it?",a="Troggs have overrun Coldridge Pass, making travel too dangerous for regular couriers without a full Mountaineer escort. Adventurers skilled enough to fight their way through are the inn's only immediate hope for receiving the goods.",al={"why can't hands deliver it","pass blocked","why use an adventurer"},it="motive"},{q="Who receives the supplies?",a="Tannok Frosthammer, the innkeeper's assistant at the Thunderbrew Distillery in Kharanos, takes delivery of the parcel.",al={"who gets the crate","tannok frosthammer","kharanos innkeeper"},it="target"},{q="What is the Crate of Inn Supplies?",a="It is a package of goods packed by Hands Springsprocket in Anvilmar, meant for the Thunderbrew Distillery and inn over in Kharanos. Because the southern pass out of Coldridge Valley has been choked off by troggs, the shipment sat delayed until an able-bodied traveler could haul it through.",al={"what is crate of inn supplies","crate of inn supplies quest item","what is this crate"},it="identity",add="d1b17704"},{q="Why is the Crate of Inn Supplies needed in Kharanos?",a="Tannok Frosthammer, assistant at the Kharanos inn, has been waiting on fresh stock from Coldridge Valley while word has been scarce due to the trogg uprising. With regular courier lines cut off, the inn needs these provisions brought through the pass to keep travelers and locals supplied by the fire.",al={"why does tannok want the crate","why do they need inn supplies","crate of inn supplies purpose"},it="why_wanted",add="e676223e"}},ang={["race:Dwarf"]="Carrying these supplies marks a young dwarf's first service beyond Coldridge Valley, braving the trogg-choked pass to aid their kin in Kharanos.",["race:Gnome"]="For newly arrived gnomes, hauling Hands Springsprocket's package is a practical way to earn goodwill among the local dwarves running the inns of Dun Morogh."},kw={"anvilmar","coldridge","crate","frosthammer","hands","kharanos","springsprocket","supplies","tannok","troggs"},rel={"quest:2160","npc:tannok-frosthammer","subzone:kharanos","subzone:anvilmar","topic:trogg","zone:dunmorogh"},src={"Crate of Inn Supplies","Supplies to Tannok"}}
E["item:durnan-s-scalding-mornbrew"] = {t="item",n="Durnan's Scalding Mornbrew",z="dunmorogh",s="Durnan's Scalding Mornbrew is a freshly poured, piping-hot dwarven beverage intended for Durnan Furcutter in Coldridge Valley. Because the drink quickly loses its heat in the frigid mountain air, it must be rushed directly to Anvilmar before it goes cold.",h="Durnan's Scalding Mornbrew is a freshly poured, piping-hot dwarven beverage intended for Durnan Furcutter in...",sec={{t="A Race Against the Cold",b="In the biting chill of Coldridge Valley, few comforts rival a mug of fresh mornbrew served piping hot. When a courier gets delayed delivering a round to Grelin Whitebeard, the fresh cup meant for Durnan Furcutter inside Anvilmar risks freezing over. Durnan specifically expects his brew scalding, leaving only a short window of a few minutes to carry the steaming mug up the snowy path into the mountain hall before it cools completely.",sp=0}},faq={{q="Who is the brew intended for?",a="The brew is meant for Durnan Furcutter, a dwarf stationed inside the settlement of Anvilmar in Coldridge Valley.",al={"who gets mornbrew","durnan mornbrew receiver","where does brew go"},it="target"},{q="Why does the delivery need to happen so quickly?",a="The icy air of Dun Morogh quickly leeches heat from open mugs. Durnan specifically ordered scalding mornbrew, and an unheated or lukewarm cup simply will not satisfy him.",al={"why time limit","brew getting cold","why rush mornbrew"}},{q="Where does the delivery originate?",a="The drink is handed off near Grelin Whitebeard's camp outside Anvilmar after the courier realizes they cannot reach the forge hall in time on their own.",al={"where is mornbrew from","who pours the brew"},it="origin"},{q="What happens once Durnan receives the mug?",a="Durnan takes an immediate break from his duties inside Anvilmar to savor the steaming drink while it still retains its heat.",al={"durnan reaction","turn in mornbrew"},it="next_step"},{q="What is Durnan's Scalding Mornbrew?",a="It is a freshly poured mug of hot dwarven mornbrew intended specifically for Durnan Furcutter in Anvilmar. Brewed to warm the bones against Coldridge Valley's biting mountain chill, it must be drunk piping hot to truly hit the spot.",al={"what is scalding mornbrew","durnan mornbrew item","mornbrew drink"},it="identity",add="93832100"},{q="Why does Durnan want the Scalding Mornbrew?",a="Durnan Furcutter ordered the steaming brew to enjoy during a well-earned break from his labors inside Anvilmar. Dwarves take their morning drink seriously, and letting such a hearty mug go chilly would ruin the entire refreshment.",al={"why durnan wants mornbrew","why mornbrew needed","durnan drink purpose"},it="why_wanted",add="c7c22f23"}},ang={["race:Dwarf"]="To a dwarf of Dun Morogh, few offenses are greater than letting good ale or mornbrew turn cold in the mountain frost."},kw={"anvilmar","coldridge valley","dun morogh","durnan furcutter","mornbrew","scalding"},rel={"npc:durnan-furcutter","quest:3364","subzone:anvilmar","zone:dunmorogh"},src={"Durnan's Scalding Mornbrew","Scalding Mornbrew Delivery"}}
E["item:encrypted-memorandum"] = {t="item",n="Encrypted Memorandum",z="dunmorogh",s="The Encrypted Memorandum is a coded missive handed to novice rogues starting out in Coldridge Valley. Though disguised as official communication, it is actually a clandestine invitation from the local rogue trainer, Solm Hargrin, calling for solidarity among scoundrels in exile.",h="The Encrypted Memorandum is a coded missive handed to novice rogues starting out in Coldridge Valley.",sec={{t="A Discrete Summons",b="In the bustling dwarven refuge of Anvilmar, rogues must maintain a low profile. Rather than approaching recruits in plain view, the trainer Solm Hargrin uses the Encrypted Memorandum to establish contact. Masked as an official directive from distant superiors, the coded parchment ensures that fledgling rogues know where to find mentorship without drawing unwanted attention from the local guards or suspicious townsfolk.",sp=0},{t="Kinship in Coldridge",b="Beneath the cipher lies a message of practical survival. With Gnomeregan lost and displaced gnomes crammed alongside their dwarven allies into the snowbound settlements of Dun Morogh, tensions simmer close to the surface. Solm uses the note to build a quiet camaraderie, reminding his students that practitioners of their trade must look out for one another when scapegoating and prejudice threaten to blame them for every missing trinket.",sp=1}},faq={{q="What is the Encrypted Memorandum?",a="It is a coded parchment delivered to beginning rogues in Coldridge Valley, instructing them to seek out rogue training under the guise of an official dispatch.",al={"what is encrypted memorandum","memorandum item","rogue note"},it="identity"},{q="Who wrote this memorandum?",a="It was drafted by Solm Hargrin, the rogue trainer stationed within Anvilmar, who disguised it as official orders to discreetly gather his fellow scoundrels.",al={"who wrote the memorandum","who sent encrypted memorandum","author of memorandum"},it="origin"},{q="Why is the message encrypted?",a="Rogues operating in Coldridge Valley avoid public scrutiny. Disguising the invitation as a routine bureaucratic memo prevents local authorities and nosy onlookers from noticing clandestine training.",al={"why encrypted","why ciphered","why is it coded"},it="motive"},{q="What does Solm Hargrin want?",a="Solm wants to offer combat training, guidance, and mutual protection, emphasizing that rogues must stick together in crowded Dun Morogh where thieves are quickly blamed for missing items.",al={"what does solm want","why find solm","solm purpose"},it="wants"},{q="Why does anyone want the Encrypted Memorandum?",a="The memorandum is intended solely for you. Solm Hargrin, the rogue trainer in Coldridge Valley, crafted it as an invitation to fellow practitioners of your shared craft. Disguised as official correspondence, it is meant to draw you into contact with him without attracting unwanted scrutiny from the locals in Anvilmar.",al={"why want encrypted memorandum","who wants the encrypted memorandum","encrypted memorandum purpose"},it="why_wanted",add="88db5375"}},ang={["class:Rogue"]="This coded letter serves as your formal summons to the shadows of Dun Morogh, connecting you directly with your local trainer in Anvilmar.",["race:Gnome"]="Living as refugees among the dwarves after the fall of Gnomeregan, gnomish rogues find in this note a quiet offer of solidarity and survival."},kw={"anvilmar","coldridge valley","dun morogh","encrypted memorandum","gnomeregan","rogue trainer","solm hargrin"},rel={"quest:3113","npc:solm-hargrin","subzone:anvilmar","subzone:coldridge-valley","topic:rogue","topic:gnome","zone:gnomeregan","zone:dunmorogh"},src={"Encrypted Memorandum","Encrypted Memorandum (quest)"}}
E["item:encrypted-rune"] = {t="item",n="Encrypted Rune",z="dunmorogh",s="An Encrypted Rune is a coded summoning message handed to promising new rogues in Coldridge Valley. Delivered covertly, it bids the bearer to decipher its contents and seek out the rogue trainer Solm Hargrin inside Anvilmar.",h="An Encrypted Rune is a coded summoning message handed to promising new rogues in Coldridge Valley.",sec={{t="A Coded Summons",b="In the sheltered snowy basin of Coldridge Valley, overt recruitment is rarely the style of the local scoundrels and scouts. Instead, novitiates showing a knack for stealth and cunning are slipped an Encrypted Rune. Marked with subtle ciphers, the inscribed stone carries a discreet invitation from Solm Hargrin, the rogue mentor quartered in Anvilmar. It serves as both a private test of literacy in thieves' cant and an introduction to the shadowy craft needed to survive Dun Morogh's harsh wilderness.",sp=0},{t="Eyes in the Shadows",b="Deciphering the rune directs new rogues to Solm, who looks to bolster the valley's covert ranks amidst rising local tensions. Beyond basic bladecraft and stealth techniques, Solm emphasizes vigilance and camaraderie, reminding incoming rogues that in this time of strained peace it is all the more important for their kind to stick together.",sp=0}},faq={{q="What is the Encrypted Rune?",a="It is a coded message delivered to fledgling rogues in Coldridge Valley, instructing them to report to Solm Hargrin inside Anvilmar for training.",al={"what is this rune","encrypted rune purpose","what does the rune do"},it="identity"},{q="Who sent the Encrypted Rune?",a="The message originates from Solm Hargrin, the rogue trainer stationed within Anvilmar, who uses it to quietly summon new recruits without drawing unwanted attention.",al={"who wrote it","who gave this","sender of rune"},it="origin"},{q="Where should I take the rune?",a="Take the deciphered instructions to Solm Hargrin, who can be found indoors at Anvilmar in Coldridge Valley.",al={"where do i go","who do i bring it to","where is solm"},it="next_step",gp=true},{q="Why is the message encrypted?",a="Rogues rely on secrecy, deception, and covert communication. Sending an encrypted rune ensures that only an aspiring rogue capable of reading the cipher heeds the call, keeping their methods out of plain view.",al={"why cipher","why is it coded","why secret rune"}},{q="Why was the Encrypted Rune sent to you?",a="Solm Hargrin, the rogue trainer in Anvilmar, sent the rune to catch your attention as an up-and-coming rogue in Coldridge Valley. With increased trouble stirring in Dun Morogh, he is scouting capable hands among the dwarves and gnomes who know how to keep a cold blade and stick to the shadows, inviting you to seek him out for further training.",al={"why do i have the encrypted rune","why did solm send the encrypted rune","purpose of encrypted rune"},it="why_wanted",add="1ca7ae1e"}},ang={["class:Rogue"]="This rune marks your first formal contact with the network of rogues in Dun Morogh, initiating you into the arts of stealth, quick blades, and survival.",["race:Dwarf"]="Passed along within Coldridge Valley, the rune calls another child of Ironforge to master the shadows and protect the clan's interests from beneath the surface."},kw={"anvilmar","cipher","coldridge valley","dun morogh","encrypted rune","rogue","solm hargrin"},rel={"npc:solm-hargrin","quest:3109","subzone:anvilmar","subzone:coldridge-valley","topic:rogue","zone:dunmorogh","zone:ironforge","zone:gnomeregan"},src={"Encrypted Rune","Encrypted Rune (Classic)"}}
E["item:etched-rune"] = {t="item",n="Etched Rune",z="dunmorogh",s="The Etched Rune is a carved stone tablet given to aspiring dwarven hunters in Coldridge Valley. It serves as an invitation from the hunter trainer Thorgas Grimson, directing fledglings to seek him out within Anvilmar to begin their formal wilderness instruction.",h="The Etched Rune is a carved stone tablet given to aspiring dwarven hunters in Coldridge Valley.",sec={{t="Call of the Wild",b="Carved with specific dwarven runes, this small stone tablet is passed along to novices who demonstrate potential out in the snowdrifts of Coldridge Valley. Sent by the mountaineer and hunter trainer Thorgas Grimson, the rune encourages fledgling trackers to pause their outdoor tasks and report to Anvilmar. Reading the stone marks a hunter's first step away from basic survival and toward understanding the deeper craft of the wild—learning to respect the beasts of Dun Morogh, track mountain predators, care for ranged weaponry, and endure the brutal elements.",sp=0}},faq={{q="What is the purpose of the Etched Rune?",a="The rune functions as an instructional summons for dwarven hunters. Reading the markings on the tablet instructs the bearer to seek out Thorgas Grimson inside the warmth of Anvilmar to receive formal guidance in the hunter's craft.",al={"what does etched rune do","etched rune use","why do i have etched rune"},it="purpose"},{q="Who wrote or sent the Etched Rune?",a="The rune was sent by Thorgas Grimson, the local hunter trainer stationed in Anvilmar. He passes these carved stones to novice outdoorsmen operating around Coldridge Valley who show a knack for surviving the frozen wilderness.",al={"who sent etched rune","who gave me this rune","etched rune author"},it="origin"},{q="Where do I take the Etched Rune once I have read it?",a="Take the rune inside the main lodge of Anvilmar in Coldridge Valley. You will find Thorgas Grimson standing near the forge and training halls, ready to teach you tracking, weapon maintenance, and the traditions of dwarven hunting.",al={"where do i bring etched rune","turn in etched rune","thorgas grimson location"},it="next_step",gp=true},{q="What is the Etched Rune?",a="The Etched Rune is an inscribed stone tablet passed to novice dwarven hunters beginning their training in Coldridge Valley. Rather than standard parchment, it serves as an enduring message summons carved with runes, reflecting the deep-rooted dwarven craft and tradition tied to the ways of wilderness survival.",al={"what is etched rune","etched rune item","etched rune lore"},it="identity",add="455fa37e"},{q="Why does Thorgas Grimson want you to bring the Etched Rune?",a="The rune is a formal call to training sent by Thorgas Grimson, the resident hunter trainer inside Anvilmar. Carrying it confirms that you have proven basic capability in the valley and are prepared to undertake serious instruction in tracking, weapon maintenance, and the traditions of the wild.",al={"why does thorgas want the rune","why want etched rune","purpose of etched rune summons"},it="why_wanted",add="537b1d7a"}},ang={["class:Hunter"]="The rune marks your first formal summons into the ancient craft of dwarven hunting, emphasizing tracking, respecting your animal companions, and surviving harsh wilderness on wits alone.",["race:Dwarf"]="Carved stones and runes are traditional dwarven means of passing down trade craft and urgent instructions, even for hardy wanderers in the snows of Coldridge Valley."},kw={"anvilmar","coldridge valley","dun morogh","dwarf hunter","etched rune","hunter training","thorgas grimson"},rel={"quest:3108","npc:thorgas-grimson","topic:hunter","subzone:anvilmar","subzone:coldridge-valley","zone:dunmorogh"},src={"Etched Rune","Etched Rune (Classic)"}}
E["item:fang-of-vagash"] = {t="item",n="Fang of Vagash",z="dunmorogh",s="The Fang of Vagash is a massive predator tooth taken from the notorious beast Vagash in the snowy crags of Dun Morogh. It serves as tangible proof for local breeders that the marauding monster threatening their prized rams has finally been slain.",h="The Fang of Vagash is a massive predator tooth taken from the notorious beast Vagash in the snowy crags of...",sec={{t="Trophy of the Hunt",b="Dun Morogh's high crags are home to bitter cold and ferocious predators, but none have plagued the local ranches quite like Vagash. Looming in the ridges above the Amberstill Ranch, this savage beast frequently stalks downhill under cover of darkness to slaughter prized rams. With Ironforge's troops already stretched thin, the local herdsmen cannot count on the city guard for protection. Slaying the beast and carving away one of its vicious fangs offers indisputable evidence that the pasturelands are safe once more.",sp=0}},faq={{q="What is the Fang of Vagash used for?",a="The fang is brought to the breeders at Amberstill Ranch in Dun Morogh as physical proof that Vagash has been eliminated. In exchange, the grateful ranchers reward the hunter who safeguarded their livelihood.",al={"fang of vagash use","what to do with fang of vagash","turn in vagash fang"},it="why_wanted",gp=true},{q="Who is Vagash?",a="Vagash is an unusually deadly beast that dens in the snowy hills just above the ram pastures in Dun Morogh. He has earned a fearsome reputation among local dwarves for raiding herds in the night.",al={"what is vagash","where is vagash","vagash lore"},it="target"},{q="Why hasn't the Ironforge guard killed Vagash?",a="Ironforge's troops are already spread thin. With few soldiers to spare for rural patrol work, the ranchers must rely on passing adventurers to deal with dangerous predators.",al={"why aren't guards helping","where is ironforge army","mountaineers vagash"},it="conflict"},{q="What is the Fang of Vagash?",a="The Fang of Vagash is a massive trophy taken from the mouth of Vagash, a vicious predator prowling the ridges of Dun Morogh. It serves as undeniable proof that the menacing beast has finally been hunted down and slain.",al={"what is fang of vagash","vagash fang lore","fang of vagash"},it="identity",add="fc16a334"},{q="Where does the Fang of Vagash come from?",a="This fang is not crafted; it is a natural tooth pried from the jaws of Vagash himself. The ferocious monster makes his lair in the snowy hills just above the Amberstill Ranch.",al={"where do you get fang of vagash","who made fang of vagash","origin of vagash fang"},it="origin",add="695a78ed"},{q="Why does Rudra Amberstill want the Fang of Vagash?",a="Rudra Amberstill seeks the fang as physical evidence of the predator's death. Vagash has been raiding the ranch in the night and devouring prized rams, threatening the Amberstill family's livelihood while Ironforge's guard is stretched too thin to defend them.",al={"why want fang of vagash","who wants vagash fang","rudra amberstill fang"},it="why_wanted",add="f04ec442"}},ang={["race:Dwarf"]="Amberstill Ranch provides the hardy mountain rams essential to dwarven mountaineers and travelers alike. Bringing back Vagash's fang directly preserves Ironforge's most prized breed of mount.",["class:Hunter"]="Tracking down an apex predator like Vagash in the freezing crags of Dun Morogh is an early test of tracking, wilderness survival, and beast-slaying prowess."},kw={"amberstill ranch","dun morogh","fang of vagash","ironforge","protecting the herd","ram","vagash"},rel={"quest:314","zone:dunmorogh","zone:ironforge","topic:alliance"},src={"Fang of Vagash","Protecting the Herd"}}
E["item:feather-charm"] = {t="item",n="Feather Charm",z="dunmorogh",s="Feather Charms are crude magical trinkets carried by Frostmane troll novices in the snow-swept valleys of Coldridge Valley. Though fashioned from simple materials, they harbor an innate sorcerous resonance that catches the eye of local warlock mentors.",h="Feather Charms are crude magical trinkets carried by Frostmane troll novices in the snow-swept valleys of...",sec={{t="Troll Trinkets and Dark Studies",b="The Frostmane trolls inhabiting the snowy caverns southwest of Anvilmar are known mostly for territorial savagery, but their novices dabble in primitive spellcraft. The feather charms carried by these young trolls hold a faint yet unmistakable magical power. In Anvilmar, warlock instructor Alamar Grimm considers them an intriguing subject of study—surprising for crude trollcraft—and uses them as a proving ground for fledgling warlocks seeking to master the binding of their first imp.",sp=0}},faq={{q="Who carries these feather charms?",a="They are carried by Frostmane novices found lurking in the snowy cave to the southwest of Anvilmar in Coldridge Valley.",al={"where do feather charms come from","who drops feather charm","frostmane novice charm"},it="residents"},{q="Why does Alamar Grimm want them?",a="Alamar Grimm finds the charms' inherent magic intriguing and worthy of research, which he notes is quite unexpected for troll craftsmanship. He demands them from aspiring warlocks to test their physical fortitude and magical potential before teaching them how to summon an imp.",al={"why does alamar need charms","alamar grimm feather charms","what does grimm do with them"},it="why_wanted"},{q="Are the Frostmane trolls adept magic users?",a="While the Frostmane tribe is largely seen as crude and hostile, their novices demonstrate rudimentary spellcasting. The feather charms they bear focus that basic magic, proving that even their fledgling casters harness arcane or shamanistic energies.",al={"can frostmane trolls use magic","frostmane novice magic"}},{q="What do the charms look like?",a="They are simple talismans woven with feathers and twine, fashioned by Frostmane novices as foci for their early magical training in the cold caves of Dun Morogh.",al={"feather charm description","appearance of feather charm"},it="item"},{q="What is a Feather Charm?",a="A Feather Charm is a crude magical talisman crafted and carried by Frostmane troll novices in Dun Morogh. Though seemingly simple trinkets made by the primitive mountain trolls, these charms actually channel a distinct magical energy that catches the attention of scholars and spellcasters studying troll mysticism.",al={"what is feather charm","feather charms lore","about feather charm"},it="identity",add="a2188847"},{q="Where do Feather Charms come from, and who makes them?",a="These charms are fashioned by the fledgling casters of the Frostmane tribe, found dwelling in the icy caves southwest of Anvilmar. The young troll novices imbue the feathers with their own emerging powers, carrying them as focuses while they practice their rudimentary spellcraft in Coldridge Valley.",al={"who makes feather charms","where do feather charms come from","frostmane feather charm origin"},it="origin",add="6facee45"}},ang={["class:Warlock"]="For novice warlocks in Dun Morogh, taking feather charms from troll spellcasters serves as the essential test of discipline before Alamar Grimm entrusts them with the ritual to summon an imp.",["race:Gnome"]="Gnomish warlocks operating out of Anvilmar study these rudimentary troll fetishes to dissect the raw, unrefined magic channelled by primitive Frostmane casters."},kw={"alamar grimm","anvilmar","coldridge valley","dun morogh","feather charm","frostmane novice","warlock"},rel={"npc:alamar-grimm","quest:1599","subzone:anvilmar","topic:warlock","topic:troll","zone:dunmorogh"},src={"Feather Charm","Beginnings"}}
E["item:felix-s-box"] = {t="item",n="Felix's Box",z="dunmorogh",s="Felix's Box is a small container of personal belongings belonging to Felix Whindlebolt, a refugee who fled the fall of Gnomeregan. Lost during the frantic evacuation into Dun Morogh, the box was looted by local Frostmane trolls and carried off to their camps southwest of Anvilmar.",h="Felix's Box is a small container of personal belongings belonging to Felix Whindlebolt, a refugee who fled...",sec={{t="Lost in the Flight from Gnomeregan",b="When radiation flooded Gnomeregan during the failed attempt to purge the trogg menace, Felix Whindlebolt joined the frantic exodus of gnomes into Coldridge Valley. In his desperation to escape the radioactive fumes, Felix dropped his most prized personal possessions and crafting gear along the snowy road. Before he could recover them, indigenous Frostmane trolls plundered the roadside remnants and dragged his box, along with his chest and bucket of bolts, back to their crude settlements southwest of Anvilmar.",sp=0},{t="A Refugee's Quandary",b="Unaccustomed to physical violence and ill-suited for the harsh wilderness of Dun Morogh, Felix was forced to seek the help of passing adventurers in Anvilmar to recover his belongings. Retrieving Felix's Box represents more than just returning a modest container; it restores a piece of normalcy and livelihood to a displaced artisan who lost everything in the catastrophe that consumed his underground homeland.",sp=0}},faq={{q="What is Felix's Box?",a="It is a container holding the personal belongings of Felix Whindlebolt, a gnome artisan who fled Gnomeregan following the city's disastrous contamination.",al={"felixs box","what is this box","felix box lore"},it="identity"},{q="How did the box end up with the Frostmane trolls?",a="Felix abandoned his equipment while fleeing the irradiated fumes pouring out of Gnomeregan. Frostmane trolls patrolling the hills southwest of Anvilmar scavenged the roadside gear and hauled it into their camp.",al={"why do trolls have felixs box","who stole felixs box","how was it lost"}},{q="Who is Felix Whindlebolt?",a="Felix Whindlebolt is a civilian gnome refugee currently residing in Anvilmar, traumatized by the fall of Gnomeregan and stranded without his vital tools and personal effects.",al={"felix whindlebolt","who is felix"},it="people"},{q="What other items did Felix lose?",a="Alongside the box, the Frostmane trolls plundered Felix's Chest and his Bucket of Bolts, scattering all three among their camps southwest of Anvilmar.",al={"other felix items","felix belongings","felix lost gear"}},{q="Why does Felix Whindlebolt want his box back?",a="Felix Whindlebolt is a displaced gnome refugee who had to flee Gnomeregan in sheer panic after radiation flooded the city. In his desperate scramble for safety, he lost his tools and personal gear to the Frostmane trolls. As an ordinary artisan and refugee stranded in Anvilmar, he lacks the martial skill to brave the troll camps himself, yet he desperately needs his stolen box and belongings returned to rebuild his life.",al={"why does felix want the box","why find felix's box","felix box purpose"},it="why_wanted",add="8f76c19d"}},ang={["race:Gnome"]="For gnomish adventurers starting in Coldridge Valley, retrieving Felix's personal effects brings direct relief to a fellow exile suffering the bitter consequences of Gnomeregan's evacuation.",["profession:Engineering"]="The recovered tools and containers represent a tinkerer's lifeline, highlighting the sheer hardship displaced gnomish craftsmen face when separated from their equipment."},kw={"anvilmar","coldridge valley","dun morogh","felix whindlebolt","felix's box","frostmane","gnomeregan","refugee"},rel={"npc:felix-whindlebolt","quest:3361","item:felix-s-chest","item:felix-s-bucket-of-bolts","subzone:anvilmar","zone:dunmorogh","zone:gnomeregan","topic:gnome"},src={"Felix's Box","A Refugee's Quandary (Classic)"}}
E["item:felix-s-bucket-of-bolts"] = {t="item",n="Felix's Bucket of Bolts",z="dunmorogh",s="Felix's Bucket of Bolts is a container of spare hardware and tools owned by Felix Whindlebolt, a gnome refugee who fled the fall of Gnomeregan. During his escape into Dun Morogh, the bucket was snatched by local Frostmane trolls and dragged into their nearby camps.",h="Felix's Bucket of Bolts is a container of spare hardware and tools owned by Felix Whindlebolt, a gnome...",sec={{t="A Refugee's Scattered Tools",b="When radiation flooded Gnomeregan following the disaster against the troggs, thousands of gnomes fled into the freezing wilds of Dun Morogh with whatever they could carry. Felix Whindlebolt managed to escape with his vital equipment, but in the chaos of his flight toward Anvilmar, he was ambushed by the Frostmane trolls who inhabit the crags southwest of town. The trolls plundered his belongings, including this bucket full of bolts and parts, leaving the artisan stranded without the essential materials needed to ply his craft in exile.",sp=0}},faq={{q="What is Felix's Bucket of Bolts?",a="It is a heavy container filled with metal bolts, hardware, and tinkering supplies belonging to Felix Whindlebolt, an exiled gnome taking refuge in Anvilmar.",al={"bucket of bolts","felixs bucket","felix bucket of bolts"},it="identity"},{q="Who stole the bucket?",a="The Frostmane trolls stole the bucket along with Felix's other personal belongings as he was fleeing the catastrophe at Gnomeregan.",al={"who took the bolts","trolls stole bucket","who has felixs bolts"},it="conflict"},{q="Where did the trolls take it?",a="The trolls carried it back to their encampments in the crags southwest of Anvilmar in Coldridge Valley.",al={"where are the bolts","bucket location","felix bolts camp"},it="place",gp=true},{q="Why is this bucket important to Felix?",a="Gnomish refugees fled their home with virtually nothing. For an engineer or craftsman like Felix, basic fasteners and parts are essential to surviving and rebuilding their lives away from Gnomeregan.",al={"why does felix want bolts","felix whindlebolt bolts importance"},it="why_wanted"}},ang={["race:Gnome"]="Every salvaged bucket of parts represents one small piece of Gnomeregan saved from ruin, helping refugees establish a new foothold in Coldridge Valley.",["profession:Engineering"]="No tinker can work without basic hardware, making a simple bucket of bolts a prized possession when starting over in the snows of Dun Morogh."},kw={"anvilmar","bolts","dun morogh","felix","frostmane","gnomeregan","refugee","trolls","whindlebolt"},rel={"npc:felix-whindlebolt","quest:3361","item:felix-s-box","item:felix-s-chest","subzone:anvilmar","zone:dunmorogh","zone:gnomeregan","topic:gnome"},src={"Felix's Bucket of Bolts","A Refugee's Quandary (Classic)"}}
E["item:felix-s-chest"] = {t="item",n="Felix's Chest",z="dunmorogh",s="Felix's Chest is a container of personal belongings lost by the exiled gnome Felix Whindlebolt during the flight from Gnomeregan. Carried away by Frostmane trolls lurking near Coldridge Valley, it sits abandoned within one of their primitive mountain camps.",h="Felix's Chest is a container of personal belongings lost by the exiled gnome Felix Whindlebolt during the...",sec={{t="A Refugee's Losses",b="When the subterranean techno-city of Gnomeregan fell to trogg incursions and toxic radioactive fallout, thousands of gnomes fled toward the snowy surface of Dun Morogh with whatever possessions they could carry. Felix Whindlebolt managed to escape the irradiated ruins, but amidst the panic of the evacuation, native Frostmane trolls scavenged the roads and overtook the scattered survivors. Felix lost his primary toolkits and belongings, with his sturdy chest hauled off to the crude camps the trolls maintain in the crags southwest of Anvilmar.",sp=0}},faq={{q="What is inside Felix's Chest?",a="The chest holds the personal belongings and effects Felix Whindlebolt managed to salvage when fleeing Gnomeregan. Left behind in his rush away from the lethal radiation, its contents are of little use to the trolls but represent the surviving remnants of his former life.",al={"felix chest contents","what is in the chest","felix's chest loot"},it="item"},{q="Why do the Frostmane trolls have Felix's belongings?",a="The Frostmane trolls regularly harass travelers and scavenge through Coldridge Valley. When disoriented gnomish refugees scattered across Dun Morogh to escape their ruined city, trolls ambushed the stragglers and hauled their discarded gear and luggage back to their campsites.",al={"why do trolls have felix chest","who stole felix chest","trolls felix whindlebolt"},it="why_here"},{q="Where is the chest located?",a="The chest is located southwest of Anvilmar in Coldridge Valley, kept near the tents of a Frostmane troll settlement alongside other looted supplies.",al={"where is felix chest","felix chest location","find felix chest"},it="place",gp=true},{q="What is Felix's Chest?",a="Felix's Chest is a container of personal belongings and tools owned by Felix Whindlebolt, a refugee gnome now taking shelter in Anvilmar. When Gnomeregan was irradiated, Felix fled into Dun Morogh, only to lose the chest to Frostmane trolls during his chaotic escape.",al={"what is felixs chest","felix chest","who owns felixs chest"},it="identity",add="cd14610d"},{q="Why does Felix want his chest back?",a="Felix Whindlebolt fled the tragic fall of Gnomeregan with virtually nothing to his name. The chest holds his personal effects and practical tools, essential supplies he needs to survive and start anew while displaced among the dwarves of Coldridge Valley. Lacking the martial prowess to fight the Frostmane trolls himself, he relies on willing adventurers to recover it.",al={"why does felix want his chest","why is felixs chest needed","why retrieve felix chest"},it="why_wanted",add="bcb95cf5"}},ang={["race:Gnome"]="The chest is a poignant reminder of the chaotic evacuation of Gnomeregan, where fleeing gnomes lost almost everything to the wilderness and opportunistic scavengers."},kw={"a refugee's quandary","anvilmar","coldridge valley","felix whindlebolt","felix's chest","frostmane","gnomeregan"},rel={"npc:felix-whindlebolt","quest:3361","item:felix-s-box","item:felix-s-bucket-of-bolts","subzone:anvilmar","zone:dunmorogh","zone:gnomeregan","topic:gnome"},src={"Felix's Chest","A Refugee's Quandary (Classic)"}}
E["item:glyphic-memorandum"] = {t="item",n="Glyphic Memorandum",z="dunmorogh",s="The Glyphic Memorandum is a written notice delivered to novice mages arriving in Coldridge Valley. Penned on behalf of the mage trainer Marryk Nurribit, it directs fledgling spellcasters indoors to begin their formal arcane instruction.",h="The Glyphic Memorandum is a written notice delivered to novice mages arriving in Coldridge Valley.",sec={{t="A Summons to Anvilmar",b="Novice spellcasters setting out into the bitter frost of Coldridge Valley receive this brief missive after completing their initial tasks. Authored by the local mage trainer Marryk Nurribit, the memorandum summons young practitioners into the warmth of Anvilmar. Rather than stern academic dogma, Marryk's guidance is informal and blunt: learn your incantations, set aside coin for training and tavern ale, and steer well clear of the irradiated ruin of Gnomeregan.",sp=0}},faq={{q="What is the Glyphic Memorandum?",a="It is a short written summons provided to newly arrived mages in Coldridge Valley, instructing them to seek out the local arcane trainer inside Anvilmar.",al={"glyphic memo","mage note","what is glyphic memorandum"},it="identity"},{q="Who wrote this memorandum?",a="The note originates from Marryk Nurribit, a gnome mage trainer stationed within the halls of Anvilmar in Dun Morogh.",al={"who wrote it","who sent glyphic memorandum","author of note"},it="origin"},{q="What advice does the trainer give when answering the memorandum?",a="Upon presenting the note, Marryk reminds the novice to practice restraint, save money for spells and tavern ale, and strictly avoid the radioactive halls of Gnomeregan.",al={"marryk advice","what does marryk say"}},{q="Why does Marryk Nurribit want you to bring him the Glyphic Memorandum?",a="The memorandum serves as an invitation and summons for aspiring mages starting out in Coldridge Valley. By delivering it to Marryk Nurribit in Anvilmar, you establish contact with your local mage trainer. He uses the opportunity to offer novice advice, remind you to stay clear of fallen Gnomeregan, and offer formal instruction in the arcane arts whenever you have the coin to spare.",al={"why bring glyphic memorandum","why does marryk want the memorandum","why want glyphic memorandum"},it="why_wanted",add="c67a7a55"}},ang={["class:Mage"]="For budding mages venturing through Dun Morogh, this note marks the formal beginning of their arcane apprenticeship under Marryk Nurribit.",["race:Gnome"]="Gnome mages starting their journeys in exile are reminded by their trainer to focus on their studies and stay away from their lost homeland of Gnomeregan."},kw={"anvilmar","coldridge valley","dun morogh","glyphic memorandum","mage","marryk nurribit"},rel={"quest:3114","npc:marryk-nurribit","subzone:anvilmar","subzone:coldridge-valley","zone:dunmorogh","zone:gnomeregan","topic:mage","topic:gnome"},src={"Glyphic Memorandum","Glyphic Memorandum (quest)"}}
E["item:grelin-s-report"] = {t="item",n="Grelin's Report",z="dunmorogh",s="Grelin's Report is a dispatch written by Grelin Whitebeard detailing the Frostmane troll situation in Coldridge Valley. Entrusted to an adventurer rather than a novice apprentice, it serves as the official link between the scouts guarding Anvilmar and Senir Whitebeard stationed in Kharanos.",h="Grelin's Report is a dispatch written by Grelin Whitebeard detailing the Frostmane troll situation in...",sec={{t="A Dispatch Past the Troggs",b="Written after observing the Frostmane trolls in Coldridge Valley, Grelin's Report concludes that they pose no large threat and can be dealt with by the Mountaineers already stationed there and mercenaries paid from Senate funds. Rather than trusting his fumbling apprentice with such vital intelligence, Grelin enlists a capable traveler to carry the document through the trogg-infested Coldridge Pass. The paper acts as an official pass through Mountaineer Thalos's blockade, proving the bearer travels on urgent business to the wider snowy expanse of Dun Morogh.",sp=0},{t="Ruffling Feathers in Kharanos",b="When delivered to Senir Whitebeard at the Thunderbrew Distillery in Kharanos, the report provides critical field updates intended for Ironforge. Senir notes with amused resignation that his brother invoked King Magni Bronzebeard's name liberally throughout the text. Grelin claims the King's sanction for the action, and Senir expects that appeal to royal authority to ruffle some feathers in the Ironforge Senate.",sp=0}},faq={{q="What is the purpose of Grelin's Report?",a="The report carries Grelin Whitebeard's assessment of the Frostmane trolls from Coldridge Valley to his brother Senir in Kharanos. It assures leadership outside the valley that the trolls pose no large threat and can be handled by local Mountaineers and Senate-funded mercenaries.",al={"what is grelins report","why send the report","grelin report purpose"},it="purpose"},{q="Why can't Grelin deliver it himself?",a="Grelin remains stationed in Coldridge Valley monitoring the trolls. While he initially considered sending his apprentice, the perilous journey through the trogg-infested tunnel prompted him to hand the vital papers to a battle-tested adventurer instead.",al={"why not deliver it","why entrust it to an adventurer"}},{q="Why does Mountaineer Thalos let you pass with the report?",a="Mountaineer Thalos guards the tunnel out of Coldridge Valley to keep civilians safe from vicious troggs. Possessing Grelin's Report proves you are traveling on pressing dwarven defense business, convincing Thalos to grant passage.",al={"why does thalos let me through","tunnel blockade","coldridge pass troggs"}},{q="Why is the Ironforge Senate annoyed by the report?",a="Senir Whitebeard notes that Grelin invoked King Magni's name liberally throughout the document. Bypassing standard diplomatic subtleties to demand royal attention often angers the bureaucrats in the Ironforge Senate, even if the brothers agree the politicians need a wake-up call.",al={"why senate mad","ruffle feathers","senir reaction"}},{q="What is Grelin's Report?",a="It is a written dispatch penned by Grelin Whitebeard in Coldridge Valley, addressed to his brother Senir Whitebeard in Kharanos. It details local observations and pressing matters in the valley, though Grelin invoked King Magni Bronzebeard's name liberally enough within its pages to stir up controversy among the senators back in Ironforge.",al={"what is grelins report","grelin report"},it="identity",add="cdcce173"},{q="Where does Grelin's Report come from, and who made it?",a="The document was drafted by Grelin Whitebeard while stationed at Coldridge Valley. Rather than entrusting it to his apprentice, Grelin decided to place it into the hands of a capable traveler to guarantee its safe journey east through the trogg-infested tunnel leading into greater Dun Morogh.",al={"who wrote grelins report","where did grelins report come from","who made grelins report"},it="origin",add="9a092709"},{q="Why does anyone want Grelin's Report?",a="His brother, Senir Whitebeard, is waiting for the dispatch in Kharanos to coordinate their findings before forwarding their combined reports to Ironforge. The document is also vital for you personally: presenting evidence of official Whitebeard business is the only reason Mountaineer Thalos permits you passage through the dangerous, trogg-plagued tunnel out of Coldridge Valley.",al={"why is grelins report needed","why does senir want grelins report"},it="why_wanted",add="6be6ebf1"}},ang={["race:Dwarf"]="Carrying this report is a dwarf's passage from the safe training grounds of Coldridge into the broader defense of the Dun Morogh heartland and the service of Ironforge.",["race:Gnome"]="Delivering Grelin's message allows gnomish refugees to prove their mettle to dwarven mountaineers while traversing the shared mountain passes of Dun Morogh."},kw={"coldridge valley","grelin whitebeard","grelin's report","ironforge senate","kharanos","mountaineer thalos","senir whitebeard"},rel={"npc:senir-whitebeard","quest:282","npc:mountaineer-thalos","subzone:kharanos","subzone:anvilmar","topic:trogg","zone:dunmorogh","zone:ironforge"},src={"Grelin's Report","Senir's Observations","Senir's Observations (2)"}}
E["item:grelin-whitebeard-s-journal"] = {t="item",n="Grelin Whitebeard's Journal",z="dunmorogh",s="Grelin Whitebeard's Journal is a personal field notebook kept by the dwarf scout Grelin Whitebeard in Coldridge Valley. Containing critical notes on local Frostmane troll activity, the journal was stolen by the chieftain Grik'nir the Cold and dragged into the troll cave in Coldridge Valley.",h="Grelin Whitebeard's Journal is a personal field notebook kept by the dwarf scout Grelin Whitebeard in...",sec={{t="A Scout's Ledger",b="While observing the aggressive movements of the Frostmane trolls near Coldridge Valley, Grelin Whitebeard diligently recorded his findings in this leatherbound notebook. The document contains his raw field observations regarding the strength, organization, and threat level posed by the indigenous winter trolls. However, during a confrontation or ambush, the journal was snatched away by Grik'nir the Cold—a heavily marked troll leader—forcing Grelin to recruit passing adventurers to delve into the troll cave and wrest it back before his report could be finalized.",sp=0},{t="Dispatch to Senir",b="Once recovered from Grik'nir's clutches, the notes inside this battered journal provide Grelin with enough reassurance to assess the Coldridge Valley troll threat as temporarily contained. Using the recovered jottings, Grelin finalizes his written dispatch on the Frostmane uprising, which is subsequently sealed and entrusted to couriers bound for his brother Senir Whitebeard stationed further abroad in Dun Morogh.",sp=1}},faq={{q="Who stole Grelin Whitebeard's journal?",a="The journal was taken by Grik'nir the Cold, a prominent and heavily marked Frostmane troll brute residing deep inside the troll cave in Coldridge Valley.",al={"who took the journal","who has grelin's journal","thief of grelin's journal"},it="target"},{q="What is written in the journal?",a="The journal contains Grelin Whitebeard's direct reconnaissance notes regarding the local Frostmane trolls, their threat level, and the state of safety within Coldridge Valley.",al={"journal contents","what is inside the journal","grelin whitebeard notes"}},{q="What happens after the journal is recovered?",a="After retrieving his notebook, Grelin uses his notes to write a finalized intelligence report on the troll situation, which he then asks an adventurer to deliver to his brother, Senir Whitebeard.",al={"what does grelin do with the journal","after the stolen journal"},sp=1,it="next_step"},{q="Why is this journal so important to Grelin?",a="Without his notebook, Grelin cannot compile an accurate scouting report on the Frostmane uprising for the dwarven authorities and his brother Senir, leaving Coldridge Valley's defenses uncertain.",al={"why does grelin want it back","importance of the journal"},it="why_wanted"},{q="What is Grelin Whitebeard's Journal?",a="It is a personal notebook kept by Grelin Whitebeard, an observer stationed in Coldridge Valley. Inside, Grelin records his findings regarding the local Frostmane troll activity and prepares field reports detailing the valley's defensive situation.",al={"what is grelin whitebeard journal","grelin journal","grelins notebook"},it="identity",add="15978139"},{q="Where does Grelin Whitebeard's Journal come from, and who made it?",a="The journal was compiled directly by the dwarf Grelin Whitebeard during his watch over Coldridge Valley. However, it was snatched from him and carried deep into the nearby troll cave by the Frostmane brute Grik'nir the Cold.",al={"who made grelin journal","where did grelin journal come from","grelin journal origin"},it="origin",add="9ed18e74"}},ang={["race:Dwarf"]="Recovering this journal safeguards crucial dwarven intelligence on the Frostmane threat encroaching on the very gates of Ironforge's training grounds."},kw={"coldridge valley","dun morogh","frostmane hold","grelin whitebeard","grik'nir the cold","senir whitebeard","stolen journal"},rel={"quest:218","npc:grelin-whitebeard","subzone:coldridge-valley","zone:dunmorogh","quest:182","quest:282","topic:troll"},src={"Grelin Whitebeard's Journal","The Stolen Journal"}}
E["item:gyromechanic-gear"] = {t="item",n="Gyromechanic Gear",z="dunmorogh",s="A Gyromechanic Gear is a salvaged piece of precision engineering recovered from the fallout outside Gnomeregan. Gnomish inventors in Kharanos seek these specific gears to construct an experimental device capable of reversing leper gnome mutations.",h="A Gyromechanic Gear is a salvaged piece of precision engineering recovered from the fallout outside...",sec={{t="Components for Recombobulation",b="When radiation flooded Gnomeregan to purge the trogg invasion, it corrupted a vast portion of the surviving gnome population into mad, irradiated leper gnomes. Refusing to abandon their twisted kin, inventors Ozzie Togglevolt and Razzle Sprysprocket set to work drafting schematics for the Recombobulator—an ambitious contraption designed to undo the radiation's horrific effects. Building the prototype requires precision mechanisms capable of enduring volatile internal pressures, particularly Gyromechanic Gears and complementary Restabilization Cogs. Because local manufacturing collapsed with the fall of their capital, researchers are forced to scavenge these delicate parts directly from the hostile leper gnomes roaming Dun Morogh.",sp=0}},faq={{q="What is a Gyromechanic Gear used for?",a="It serves as a core mechanical component needed by Razzle Sprysprocket in Kharanos. Alongside Restabilization Cogs, it is incorporated into the Recombobulator, a prototype machine designed to cure irradiated leper gnomes.",al={"gyromechanic gear purpose","what does gyromechanic gear do","gyromechanic gear quest"},it="why_wanted"},{q="Where do these gears come from?",a="They are salvaged from Leper Gnomes outside Gnomeregan and from Gibblewilt in Dun Morogh.",al={"where to find gyromechanic gear","gyromechanic gear drop","who drops gyromechanic gear"},it="origin"},{q="Can the Recombobulator actually cure leper gnomes?",a="Razzle Sprysprocket remains endlessly optimistic about Ozzie's schematics, believing adjustments to combustion pistons and electrogum gel will restore their kin. Whether the machine can truly reverse catastrophic radiation poisoning on a wide scale remains an untested gnomish theory.",al={"does the recombobulator work","can leper gnomes be cured","recombobulation success"}},{q="Why can't gnomes simply forge new gears?",a="The loss of Gnomeregan shattered gnomish industrial capacity, locking away their most sophisticated tooling, workshops, and automated foundries. Scavenging intact pre-fall precision hardware from the city's perimeter is often far faster than machining parts by hand.",al={"why scavenge gears","why not craft gyromechanic gears"}},{q="What is a Gyromechanic Gear?",a="A Gyromechanic Gear is an intricately engineered component crafted for complex gnomish machinery. Originally utilized within Gnomeregan's vast mechanical works, these precision parts are now scattered amidst the ruins and scavenged by the wretched creatures lurking outside the fallen tech-city.",al={"what is gyromechanic gear","gyromechanic gear info","about gyromechanic gears"},it="identity",add="93a017f3"}},ang={["race:Gnome"]="Every salvaged gear brings gnomish tinkerers one step closer to potentially rescuing their radioactive brethren wandering the snows outside Gnomeregan.",["profession:Engineering"]="Gnomish precision engineering is renowned for extreme intricacy, relying on tight-tolerance gyromechanic components to regulate unstable prototype machinery."},kw={"gnomeregan","gyromechanic gear","kharanos","leper gnome","operation recombobulation","razzle sprysprocket","recombobulator","restabilization cog"},rel={"quest:412","item:restabilization-cog","npc:razzle-sprysprocket","topic:leper-gnome","subzone:kharanos","zone:gnomeregan","zone:dunmorogh","topic:gnome"},src={"Gyromechanic Gear","Operation Recombobulation (Classic)"}}
E["item:hallowed-rune"] = {t="item",n="Hallowed Rune",z="dunmorogh",s="The Hallowed Rune is an inscribed stone passed to novice priests beginning their training in Coldridge Valley. Sent by the dwarven priest trainer Branstock Khalder, it calls aspiring wielders of the Holy Light into Anvilmar to begin their formal tutelage.",h="The Hallowed Rune is an inscribed stone passed to novice priests beginning their training in Coldridge Valley.",sec={{t="A Calling to the Light",b="When a fledgling priest demonstrates their resolve aiding the mountaineers and defenders of Coldridge Valley, Branstock Khalder sends forth the Hallowed Rune. Inscribed with teachings of the Holy Light, the stone serves as both an introduction and an invitation. Dwarven novices are directed to step away from minor skirmishes in the snow and report to Anvilmar, where Branstock prepares them to mend wounds and harness holy power against the trogg infestation threatening Dun Morogh.",sp=0}},faq={{q="What is the Hallowed Rune?",a="The Hallowed Rune is a small sacred stone bearing words of guidance for novice priests. It serves as an official summons from Branstock Khalder to begin formal spiritual and magical instruction inside Anvilmar.",al={"what is this item","hallowed rune item","rune purpose"},it="identity"},{q="Who sends the Hallowed Rune to you?",a="It is sent by Branstock Khalder, the dwarven priest trainer stationed within Anvilmar. He passes it through allies in Coldridge Valley to reach young priests who have begun proving themselves in the field.",al={"who sent the rune","who gave me this rune","branstock rune"},it="origin"},{q="What should I do after receiving the Hallowed Rune?",a="You should take a moment to read the rune and then head inside the main hall of Anvilmar to present yourself to Branstock Khalder, where he will offer to teach you new prayers and spells.",al={"where do i take the rune","what to do with hallowed rune"},it="next_step",gp=true},{q="Why does Branstock want novice priests trained so quickly?",a="Coldridge Valley is under steady harassment from trogg incursions, and the mountaineers need all the divine healing and offensive power they can muster to defend Dun Morogh.",al={"why need priests","trogg problem priests"},it="motive"},{q="Why was the Hallowed Rune given to me?",a="The rune acts as a formal summons and message directed to novice priests working in Coldridge Valley. Branstock Khalder sends it along to call aspiring acolytes of the Holy Light into Anvilmar so he can instruct them in their faith and teach them sacred spells vital for defending the valley.",al={"why do i have the hallowed rune","hallowed rune purpose","why hallowed rune"},it="why_wanted",add="fac25589"}},ang={["class:Priest"]="The Hallowed Rune marks the official beginning of a priest's formal mentorship under the Holy Light in Coldridge Valley.",["race:Dwarf"]="Dwarven priests blend devout reverence for the Light with steadfast duty to Ironforge, stepping up to defend their mountain homeland from troggs."},kw={"anvilmar","branstock khalder","coldridge valley","dun morogh","hallowed rune","priest","troggs"},rel={"quest:3110","npc:branstock-khalder","subzone:anvilmar","subzone:coldridge-valley","topic:priest","topic:light","topic:trogg","zone:dunmorogh"},src={"Hallowed Rune","Hallowed Rune (Classic)"}}
E["item:hildelve-s-journal"] = {t="item",n="Hildelve's Journal",z="dunmorogh",s="Hildelve's Journal is the final record of dwarven pilot Hildelve, recovered from his remains in the frigid wilderness of Dun Morogh. Its bloodstained pages recount his fatal encounter with a ferocious bear and convey his dying wish for vengeance.",h="Hildelve's Journal is the final record of dwarven pilot Hildelve, recovered from his remains in the frigid...",sec={{t="A Pilot's Final Words",b="When his steam tank broke down, dwarven pilot Hildelve left his partner Hammerfoot with the tanks and set out alone into the snow-swept crags of Dun Morogh in search of rumored chiron ore. According to the entries scrawled in his journal, he was stalked for days and then ambushed by a monstrous ice claw bear known as Mangeclaw. Though Hildelve fought bravely and managed to drive the beast off, he was left gravely mauled and stranded in the bitter cold. The journal details his agonizing final hours, concluding with a single, clear plea before the predator returned to finish him: that whoever discovered his body avenge his death by hunting down Mangeclaw.",sp=0},{t="Return to the Siege Brigade",b="The recovered journal serves as grim closure for Hildelve's comrade, Pilot Hammerfoot, stationed near North Gate Outpost in eastern Dun Morogh. As a member of the Ironforge Siege Brigade, Hammerfoot feared the worst when Hildelve never returned from his search for ore. Handing over the journal alongside the beast's severed claw provides proof that Hildelve's spirit has been put to rest and his final wish honored.",sp=1}},faq={{q="Who was Hildelve?",a="Hildelve was a dwarven steam tank pilot belonging to the Ironforge Siege Brigade. After his tank broke down, he set off alone into the wilds of Dun Morogh in search of chiron ore and was killed by the bear Mangeclaw before he could return.",al={"hildelve lore","who is hildelve","dwarf pilot hildelve"},it="people"},{q="What is Mangeclaw?",a="Mangeclaw is an unusually large and savage ice claw bear that stalks the snowy ridges of Dun Morogh. It ambushed Hildelve while he was stranded, mauled him severely, and later returned to end his life.",al={"who is mangeclaw","what killed hildelve","bear that killed hildelve"},it="threat"},{q="Who receives the journal once it is found?",a="The journal is delivered to Pilot Hammerfoot, a siege engine pilot stationed near North Gate Outpost in eastern Dun Morogh. Hammerfoot was a close friend of Hildelve and sought news of the missing pilot.",al={"where do i take the journal","who gets hildelves journal","turn in hildelves journal"},it="target"},{q="What does Hildelve ask for in the journal?",a="Knowing his wounds were mortal, Hildelve used his final pages to document the beast that attacked him and asked that any traveler finding his remains hunt down Mangeclaw to avenge his death.",al={"hildelves final wish","what is in the journal","pilot dying wish"},it="motive"},{q="What is Hildelve's Journal?",a="This battered logbook belonged to Hildelve, a downed dwarven pilot of the Ironforge Siege Brigade. Found beside his remains in the frozen reaches of Dun Morogh, it records his harrowing final moments—documenting his survival of an initial brutal mauling by the great bear Mangeclaw, and penning his dying wish for vengeance before the beast returned to finish him off.",al={"what is this journal","hildelves journal lore","about hildelves journal"},it="identity",add="b58cc0e1"},{q="Where does Hildelve's Journal come from, and who made it?",a="The journal was authored by Pilot Hildelve himself during his ordeal in Dun Morogh. After his steam tank broke down, he went searching for chiron ore on foot and was mauled by the bear Mangeclaw; he kept this personal record right up until his death, leaving behind a written testament of his struggle and his final request.",al={"who wrote the journal","where did hildelves journal come from","origin of hildelves journal"},it="origin",add="308c8265"},{q="Why does anyone want Hildelve's Journal?",a="His fellow steam tank pilot, Pilot Hammerfoot, was desperately searching for word of his lost comrade. The journal offers definitive proof of Hildelve's fate and honors his final request for retribution against the monster that took his life, bringing closure to his friends in the Ironforge Siege Brigade.",al={"why keep hildelves journal","who wants the journal","why bring hildelves journal back"},it="why_wanted",add="856dae3f"}},ang={["race:Dwarf"]="The journal honors the unyielding spirit of dwarven pilots, who defy freezing weather and wild beasts to secure the heights of Khaz Modan.",["faction:Alliance"]="Recovering the personal effects of fallen military personnel like Hildelve strengthens the bond between the Alliance and the Ironforge Siege Brigade."},kw={"dun morogh","hildelve","ice claw bear","journal","mangeclaw","pilot hammerfoot","siege brigade"},rel={"quest:417","quest:419","npc:pilot-hammerfoot","item:mangy-claw","zone:dunmorogh","zone:ironforge"},src={"Hildelve's Journal","A Pilot's Revenge (Classic)"}}
E["item:jordan-s-refined-ore-shipment"] = {t="item",n="Jordan's Refined Ore Shipment",z="dunmorogh",s="Jordan's Refined Ore Shipment is a crate of high-grade metal prepared specifically for the smith Jordan Stilwell. Acquired as part of a paladin's sacred trials, it provides the essential stock needed to forge a holy weapon of virtue.",h="Jordan's Refined Ore Shipment is a crate of high-grade metal prepared specifically for the smith Jordan...",sec={{t="A Smith's Materials",b="When Jordan Stilwell set out to forge a weapon worthy of a dedicated paladin, ordinary stock would not suffice. The blacksmith required an assortment of rare and exacting components: a Purified Kor Gem, sturdy Whitestone Oak lumber, his own lost smithing hammer, and a specialized shipment of refined ore. This consignment represents the metal foundation for that sacred labor, brought to Ironforge to complete the Test of Righteousness.",sp=0}},faq={{q="What is Jordan's Refined Ore Shipment used for?",a="The refined ore is delivered to Jordan Stilwell outside Ironforge as one of four key components required to forge a masterwork weapon for paladins undertaking the Test of Righteousness.",al={"refined ore purpose","what does jordan do with ore","ore shipment use"},it="why_wanted"},{q="Who prepares the refined ore?",a="The shipment is arranged through Bailor, who oversees the refining and dispatching of the specialist metal needed by Jordan Stilwell.",al={"who made the ore","bailor ore","who refines jordan's ore"},it="origin"},{q="Why does Jordan need this specific shipment?",a="Jordan Stilwell intends to craft a symbol of paladinhood and the Light, demanding superior materials beyond ordinary forge scraps. This specially processed metal ensures the blade or hammer head possesses the balance and purity worthy of a holy knight.",al={"why special ore","why cant jordan use regular iron","refined ore reason"},it="why_wanted"},{q="What is Jordan's Refined Ore Shipment?",a="Jordan's Refined Ore Shipment is a crate of high-grade, specially processed metal prepared for weaponsmith Jordan Stilwell. Intended for fine smithing rather than common forge work, this refined ore provides the pure metallic foundation Jordan requires to craft an exceptional weapon worthy of a dedicated paladin of the Light.",al={"what is jordans refined ore shipment","jordans refined ore shipment lore","what is jordan refined ore"},it="identity",add="ec64bb0f"}},ang={["class:Paladin"]="Procuring this refined shipment tests a paladin's patience and dedication, serving as one of the physical trials required to craft their symbolic weapon of the Light.",["profession:Blacksmithing"]="Every artisan understands that masterwork forging requires flawless, carefully prepared ingots rather than raw field ore."},kw={"bailor","ironforge","jordan stilwell","paladin weapon","refined ore","test of righteousness"},rel={"quest:1653","quest:1655","npc:jordan-stilwell","item:jordan-s-smithing-hammer","item:whitestone-oak-lumber","item:purified-kor-gem","zone:ironforge"},src={"Jordan's Refined Ore Shipment","The Test of Righteousness (2)"}}
E["item:jordan-s-smithing-hammer"] = {t="item",n="Jordan's Smithing Hammer",z="dunmorogh",s="Jordan's Smithing Hammer is a cherished family heirloom passed down to the human blacksmith Jordan Stilwell by his father. Its recovery from the haunted halls of Shadowfang Keep is essential for forging a holy weapon consecrated to the Light.",h="Jordan's Smithing Hammer is a cherished family heirloom passed down to the human blacksmith Jordan Stilwell...",sec={{t="A Craftsman's Legacy",b="To an ordinary observer, Jordan's Smithing Hammer might seem like mere smith's iron, but to Jordan Stilwell, it represents both heritage and destiny. Inherited from his father, this tool is central to Jordan's identity as a forge master outside Ironforge. Having somehow wound up within the forsaken stone walls of Shadowfang Keep in Silverpine Forest, it must be reclaimed before Jordan can attempt his masterwork—a sacred weapon fit for a holy champion.",sp=0}},faq={{q="Where is Jordan's Smithing Hammer located?",a="The hammer rests inside the cursed walls of Shadowfang Keep, located in the dark forests of Silverpine. Paladins undertaking the Test of Righteousness must venture into the occupied fortress to recover it.",al={"hammer location","where is jordan's hammer","where to find jordan's smithing hammer"},it="place",gp=true},{q="Why is this hammer so important to Jordan Stilwell?",a="The hammer was passed down to Jordan by his father. It carries deep sentimental value and is the instrument he requires to forge his finest creation, a holy weapon of the Light.",al={"why does jordan want the hammer","jordan stilwell hammer lore"},it="ties"},{q="What is the hammer used for once recovered?",a="Once brought back to Jordan outside the gates of Ironforge alongside lumber, ore, and a gem, he uses it to forge a grand, sacred armament to reward the paladin who assisted him.",al={"what does the hammer make","test of righteousness hammer use"},it="purpose"},{q="What is Jordan's Smithing Hammer?",a="Jordan's Smithing Hammer is a cherished forging tool belonging to the master smith Jordan Stilwell. Beyond its practical use at the anvil, it carries profound sentimental value as an heirloom passed down to Jordan directly from his father.",al={"what is jordans smithing hammer","jordans hammer item","about jordans smithing hammer"},it="identity",add="126e648c"},{q="Where does Jordan's Smithing Hammer come from, and who made it?",a="The hammer was passed down to Jordan Stilwell by his father. Its exact maker is unrecorded, but before you recover it, the heirloom had somehow ended up far from Ironforge, tucked away within the dark ramparts of Shadowfang Keep.",al={"where did jordans hammer come from","who made jordans smithing hammer","origin of jordans smithing hammer"},it="origin",add="1df19239"}},ang={["class:Paladin"]="Retrieving the heirloom hammer is part of the arduous trials of righteousness, proving a paladin's resolve to venture into perilous lands for the tools of holy craftsmanship.",["profession:Blacksmithing"]="Every blacksmith understands the sentimental and practical bond between a master smith and the hammer passed down to them by their forebears."},kw={"dun morogh","ironforge","jordan stilwell","paladin weapon","shadowfang keep","smithing hammer","test of righteousness"},rel={"quest:1653","npc:jordan-stilwell","zone:shadowfang","zone:dunmorogh","zone:ironforge","item:purified-kor-gem","item:whitestone-oak-lumber","item:jordan-s-refined-ore-shipment"},src={"Jordan's Smithing Hammer","The Test of Righteousness (2)"}}
E["item:macgrann-s-dried-meats"] = {t="item",n="MacGrann's Dried Meats",z="dunmorogh",s="MacGrann's Dried Meats are a month's worth of salted provisions prepared by the hunter Tundra MacGrann to survive the harsh Dun Morogh winter. Stored in a reinforced thorium meat locker, the entire cache was snatched by the ferocious yeti known as Old Icebeard.",h="MacGrann's Dried Meats are a month's worth of salted provisions prepared by the hunter Tundra MacGrann to...",sec={{t="A Winter Cache",b="Life in the freezing crags of Dun Morogh demands careful planning. To prepare for the blizzards of the cold season, the dwarf hunter Tundra MacGrann spent weeks hunting game, salting the meat, and securing it inside a sturdy chest. Aware that scavenging bears and prowling predators routinely plague his homestead, MacGrann took no chances and locked his food supply away inside a thorium meat locker. Even with those precautions, he did not anticipate an intruder strong enough to carry away the entire chest rather than trying to pry it open on the spot.",sp=0},{t="Into the Yeti's Lair",b="While MacGrann was away tracking deer, the notorious yeti Old Icebeard raided the hunter's camp and dragged the heavy chest back to his den in Chill Breeze Valley. Though the beast lacked the means to break through the solid thorium plating, MacGrann's injured leg left him unable to mount a swift rescue into the cavern. Without outside assistance to retrieve the cache before winter sets in, the stranded hunter faced starvation amidst the mountain snows.",sp=0}},faq={{q="What are MacGrann's Dried Meats?",a="They are a month's supply of salted provisions preserved by Tundra MacGrann to carry him through the bitter Dun Morogh winter.",al={"what is macgrann's dried meats","tundra's meat","macgrann meat stash"},it="identity"},{q="Why were the meats locked in a chest?",a="Dun Morogh is crawling with hungry predators like mountain bears. MacGrann kept his dried meats secured inside a reinforced thorium meat locker so scavenging beasts could not tear into his winter food supply.",al={"why lock the meat","why thorium locker","macgrann chest"}},{q="Who stole the meat locker?",a="A menacing yeti named Old Icebeard stole the entire locker while MacGrann was away hunting deer, dragging the heavy container back to his cavern lair in Chill Breeze Valley.",al={"who took the meat","who stole it","meat locker thief"},it="threat"},{q="Why can't Tundra MacGrann get his meats back himself?",a="MacGrann suffers from an injured leg that robs him of the speed and stealth needed to slip into Old Icebeard's den and escape before the ferocious yeti corners him.",al={"why doesn't macgrann get it","why does tundra need help","tundra injured"},it="motive"},{q="Where did MacGrann's Dried Meats come from, and who prepared them?",a="These dried meats were prepared and salted by Tundra MacGrann, a mountaineer living out in the cold wilds of Dun Morogh. He cured an entire month's worth of rations to see himself through the harsh freezing season ahead, storing them carefully away in a heavy thorium locker before the local beast Old Icebeard intervened.",al={"who made macgrann dried meats","where did the dried meat come from","macgrann meat origin"},it="origin",add="1f8f3b04"},{q="Why does Tundra MacGrann want his dried meats back?",a="Without this preserved stash, Tundra MacGrann faces starvation when the severe snow flurries sweep across Dun Morogh. It represents a whole month's supply of salted provisions. Since a bad leg prevents him from braving Old Icebeard's den to fetch it, recovering the meats is vital to his survival throughout the upcoming winter.",al={"why does tundra want the meat","why get the dried meats","why are macgrann's meats needed"},it="why_wanted",add="6a0307bf"}},ang={["profession:Cooking"]="Salting and curing game is an essential culinary survival technique in Dun Morogh, allowing hunters like MacGrann to preserve meats for months without spoiling in the freezing cold.",["race:Dwarf"]="Dwarven mountaineers know all too well that preparation means survival in the high peaks, and a lost winter cache can mean the difference between life and death."},kw={"chill breeze valley","dun morogh","macgrann's dried meats","meat locker","old icebeard","tundra macgrann"},rel={"quest:312","subzone:chill-breeze-valley","zone:dunmorogh"},src={"MacGrann's Dried Meats","Tundra MacGrann's Stolen Stash"}}
E["item:mangy-claw"] = {t="item",n="Mangy Claw",z="dunmorogh",s="The Mangy Claw is a severed claw taken from the great ice claw bear Mangeclaw in Dun Morogh. It serves as grim proof that the deadly beast responsible for killing a stranded dwarven pilot has finally been slain.",h="The Mangy Claw is a severed claw taken from the great ice claw bear Mangeclaw in Dun Morogh.",sec={{t="A Dying Pilot's Wish",b="When Pilot Hildelve's steam tank broke down in the frozen hills of Dun Morogh, he continued his search for ore on foot, only to face the mountain wilderness alone. As recorded in his recovered journal, Hildelve managed to fight off an initial attack by a monstrous ice claw bear named Mangeclaw, though he was savagely mauled in the struggle. The beast later returned to finish off the weakened pilot. Hildelve's final written entry pleaded for vengeance against the predator, a task fulfilled by taking the Mangy Claw from the fallen bear.",sp=0},{t="Vengeance for the Siege Brigade",b="Taking the Mangy Claw to Pilot Hammerfoot brings closure to the Ironforge Siege Brigade. Hammerfoot had dispatched searchers into the snowdrifts hoping to find his friend alive, only to learn of his grim fate. Presenting both Hildelve's journal and the severed claw of the predator proves that Hildelve's dying request was honored, ensuring his rest and securing the gratitude of Ironforge's pilots.",sp=1}},faq={{q="What is the Mangy Claw?",a="It is a trophy severed from Mangeclaw, a savage ice claw bear lurking in Dun Morogh. It serves as physical proof that the beast has been hunted down and killed.",al={"mangy claw purpose","what is this claw","mangeclaw item"},it="identity"},{q="Who wants the Mangy Claw?",a="Pilot Hammerfoot, stationed near the mountain passes of Dun Morogh, seeks the claw alongside the journal of his fallen friend Hildelve to confirm the killer bear is dead.",al={"who takes the mangy claw","mangy claw hand in","pilot hammerfoot turn in"},it="why_wanted"},{q="Why did Mangeclaw need to be hunted?",a="A dwarf pilot named Hildelve, searching for ore on foot after his steam tank broke down, was mauled and eventually killed by Mangeclaw. Hildelve's dying wish, written in his personal journal, was for someone to take vengeance on the beast.",al={"why kill mangeclaw","who died to mangeclaw","hildelve lore"},it="motive"},{q="Where does the beast Mangeclaw roam?",a="Mangeclaw prowls the snowy ridges and hills of Dun Morogh not far from where Pilot Hildelve's remains were discovered.",al={"mangeclaw location","where is mangeclaw","mangeclaw dun morogh"},it="place",gp=true},{q="Where does the Mangy Claw come from?",a="The Mangy Claw is taken directly from Mangeclaw, a savage ice claw bear that prowls the frozen wilderness of Dun Morogh. It is not an crafted artifact, but a grisly physical trophy carved from the beast after it is slain.",al={"mangy claw source","where does mangy claw drop","who has mangy claw"},it="origin",add="554d85fa"}},ang={["race:Dwarf"]="For dwarves, honoring a fallen comrade's dying wish and avenging a member of the Ironforge Siege Brigade is a matter of profound personal and clan honor.",["class:Hunter"]="Tracking down a notorious predator like Mangeclaw in the brutal mountain blizzards tests a hunter's ability to put down dangerous, territorial beasts."},kw={"dun morogh","hildelve","ice claw bear","mangeclaw","mangy claw","pilot hammerfoot","siege brigade"},rel={"quest:417","item:hildelve-s-journal","npc:pilot-hammerfoot","quest:419","zone:dunmorogh","zone:ironforge"},src={"Mangy Claw","A Pilot's Revenge (Classic)"}}
E["item:nori-s-mug"] = {t="item",n="Nori's Mug",z="dunmorogh",s="Nori's Mug is the personal drinking vessel of Nori Pridedrift, used to deliver scalding mornbrew across the frigid drifts of Dun Morogh. After delivering a warm drink to stave off the biting alpine chill, travelers are tasked with returning the empty cup to its thrifty owner.",h="Nori's Mug is the personal drinking vessel of Nori Pridedrift, used to deliver scalding mornbrew across the...",sec={{t="A Courier's Return",b="In the freezing mountain passes of Dun Morogh, a piping hot tankard of mornbrew is one of the few comforts capable of cutting through the bitter cold. Nori Pridedrift entrusts his mug to travelers delivering a fresh, steaming pour to Durnan Furcutter in Anvilmar. Once drained, the sturdy vessel must make the trek back. As Nori notes, mugs do not grow on trees, and keeping track of hard-wearing dwarven dishware is essential business when hospitality meets snowy wilderness.",sp=0}},faq={{q="What is Nori's Mug used for?",a="It serves as the vessel for delivering piping hot, scalding mornbrew to Durnan Furcutter in Anvilmar. Once Durnan drinks his fill to warm up, the empty mug must be carried back to Nori Pridedrift.",al={"purpose of noris mug","what was in the mug","noris cup"},it="item",gp=true},{q="Who owns this mug?",a="The mug belongs to Nori Pridedrift, a dwarf stationed in Dun Morogh who values his possessions and insists that couriers return his drinkware rather than leave it scattered across the snow.",al={"who is nori","owner of mug","whose mug is it"},it="identity"},{q="Why does Nori insist on getting the mug back?",a="Good earthenware and sturdy tankards are practical supplies in the harsh mountain climate. As Nori bluntly remarks, mugs do not grow on trees, making it a point of pride and practicality to ensure every borrowed cup returns to his possession.",al={"why return the mug","why does nori want it back","mugs dont grow on trees"},it="why_wanted"},{q="What was drunk from the mug?",a="It contained scalding mornbrew, a hearty warm beverage cherished by dwarves in Dun Morogh to ward off the biting cold and warm the soul.",al={"what was in the cup","what is mornbrew","mornbrew drink"}}},ang={["race:Dwarf"]="For dwarves weathering Dun Morogh's storms, sharing a warm drink is second nature, but letting good tavernware go missing in a snowdrift is an unforgivable waste."},kw={"bring back the mug","dun morogh","durnan furcutter","mornbrew","nori pridedrift","nori's mug"},rel={"quest:3365","npc:nori-pridedrift","zone:dunmorogh"},src={"Nori's Mug","Bring Back the Mug"}}
E["item:purified-kor-gem"] = {t="item",n="Purified Kor Gem",z="dunmorogh",s="A Purified Kor Gem is a rare, consecrated crystal required by the weaponsmith Jordan Stilwell outside Ironforge. Once tainted by dark energies, it must be reclaimed from the depths of Kalimdor and cleansed by elven magic before it can be forged into a holy arm of the Light.",h="A Purified Kor Gem is a rare, consecrated crystal required by the weaponsmith Jordan Stilwell outside...",sec={{t="From Corruption to Sanctity",b="The stone begins its journey as a Corrupted Kor Gem in the possession of the vile naga lurking within Blackfathom Deeps, deep beneath the coast of Ashenvale. To cleanse the stone of its aquatic, shadowy taint, a paladin must seek out the night elf Thundris Windweaver in Auberdine. Drawing upon arcane and natural arts, Thundris purges the corruption from the stone, transforming it into the radiant Purified Kor Gem. Only in this pristine state is it fit to serve as a conduit for holy power.",sp=0},{t="The Smith's Masterpiece",b="Outside Ironforge in the snowy crags of Dun Morogh, the human weaponsmith Jordan Stilwell requires the gem as a key component for forging a masterwork weapon. Having long possessed designs for an armament worthy of the Silver Hand, Stilwell lacked the exotic materials to realize his plans. The Purified Kor Gem, alongside Whitestone Oak Lumber and rare ore, provides the spiritual core necessary to channel the paladin's righteous wrath.",sp=0}},faq={{q="What is the Purified Kor Gem used for?",a="It is brought to the blacksmith Jordan Stilwell, stationed outside the gates of Ironforge in Dun Morogh. Stilwell uses the sanctified gem as an essential component in forging a consecrated weapon for a paladin undertaking their trials.",al={"purified kor gem use","why do i need kor gem","what is kor gem for"},it="why_wanted"},{q="Where does the gem originate?",a="The stone originates within the subterranean ruins of Blackfathom Deeps along the coast of Ashenvale, where it is held by the naga as a corrupted artifact.",al={"kor gem origin","where does kor gem drop","who drops kor gem"},it="origin"},{q="Who purifies the gem?",a="Thundris Windweaver, an elven scholar residing in the coastal settlement of Auberdine in Darkshore, cleanses the dark energies from the Corrupted Kor Gem, restoring it to a purified state.",al={"how to cleanse kor gem","who cleanses kor gem","thundris windweaver kor gem"}},{q="Can any adventurer make use of the Purified Kor Gem?",a="The gem is specifically sought by paladins undergoing the Test of Righteousness. Jordan Stilwell reserves his craft for holy warriors who bring him the purified crystal alongside other rare materials.",al={"is kor gem paladin only","can anyone use purified kor gem"},it="for_you"},{q="What is a Purified Kor Gem?",a="The Purified Kor Gem is a rare, sanctified mineral component cleansed of foul taint. Originally recovered as a corrupted stone held by the naga in Blackfathom Deeps, it has been painstakingly cleansed of its dark influence by Thundris Windweaver in Auberdine so that its latent properties can be safely harnessed for sacred works.",al={"what is purified kor gem","purified kor gem meaning","purified kor gem info"},it="identity",add="a30b14db"}},ang={["class:Paladin"]="Acquiring and cleansing this gem proves a paladin's devotion, taking them from the depths of Kalimdor back to Dun Morogh to forge an iconic weapon of the Light.",["faction:Alliance"]="Procuring the purified gem unites efforts across the Alliance, relying on night elven wisdom in Auberdine to empower a human smith working on the slopes of Dun Morogh."},kw={"auberdine","blackfathom deeps","corrupted kor gem","dun morogh","jordan stilwell","purified kor gem","test of righteousness","thundris windweaver"},rel={"item:corrupted-kor-gem","quest:1442","npc:jordan-stilwell","quest:4761","zone:blackfathom","subzone:auberdine","zone:dunmorogh","topic:paladin"},src={"Purified Kor Gem","The Test of Righteousness (2)"}}
E["item:restabilization-cog"] = {t="item",n="Restabilization Cog",z="dunmorogh",s="Restabilization Cogs are precision mechanical components salvaged from the leper gnomes wandering outside the irradiated ruins of Gnomeregan. In Kharanos, gnomish tinkerers require these intact parts to construct the Recombobulator, an ambitious machine intended to reverse leper mutation.",h="Restabilization Cogs are precision mechanical components salvaged from the leper gnomes wandering outside the...",sec={{t="Components for a Cure",b="When radiation flooded Gnomeregan in a disastrous attempt to wipe out the invading troggs, countless gnomes were twisted into sick, hostile leper gnomes. Despite their madness, these afflicted exiles still carry intricate gnomish machinery and salvageable fittings. Tinkers Ozzie Togglevolt and Razzle Sprysprocket believe the horrific transformation can be systematically undone. To finish their prototype Recombobulation Device, they rely on adventurers to recover vital parts directly from the afflicted outside Gnomeregan's gates, including intact Restabilization Cogs to balance the machine's inner combustion systems.",sp=0}},faq={{q="What is a Restabilization Cog used for?",a="Restabilization Cogs are required by tinker Razzle Sprysprocket in Kharanos. Alongside Gyromechanic Gears, they serve as crucial structural pieces for building the Recombobulator, an experimental invention designed to cure irradiated leper gnomes.",al={"cog purpose","what does restabilization cog do","why collect cogs"},it="why_wanted"},{q="Where can these cogs be found?",a="They are carried by the maddened leper gnomes and their deranged leader Gibblewilt, who roam the exterior gates and trenches outside Gnomeregan in western Dun Morogh.",al={"restabilization cog location","who drops cogs","where to farm cogs"},gp=true},{q="Can the Recombobulator actually cure the leper gnomes?",a="Razzle Sprysprocket and Ozzie Togglevolt are confident that properly calibrated machinery can reverse the mutation. However, gnomish engineering is famously volatile, and whether the Recombobulator can truly restore their people's minds and bodies remains an ongoing and untested endeavor.",al={"does recombobulator work","is there a cure for leper gnomes"}},{q="What is a Restabilization Cog?",a="A Restabilization Cog is a precision mechanical component salvaged from the fallen machines and irradiated leper gnomes wandering outside the ruined city of Gnomeregan. Designed to maintain structural and rotational equilibrium in complex gnomish devices, these cogs are prized by tinkerers seeking sturdy, pre-machined parts to stabilize temperamental inventions like Ozzie Togglevolt's Recombobulator.",al={"what is restabilization cog","restabilization cog lore","about restabilization cog"},it="identity",add="8ac7e8f1"},{q="Where do Restabilization Cogs come from?",a="These cogs originate from Gnomeregan's vast mechanical works. When the city was evacuated following the disastrous radiation venting, countless automated devices and the tragic survivors who succumbed to leper madness carried these standardized components out onto the snow outside the gates.",al={"who made restabilization cog","restabilization cog origin","where did restabilization cog come from"},it="origin",add="ceb0040c"}},ang={["race:Gnome"]="For exiled gnomes in Dun Morogh, retrieving these components is a somber duty—stripping machinery from corrupted brethren in the desperate hope of building a cure for Gnomeregan's fallen.",["profession:Engineering"]="The precise tolerances of Restabilization Cogs highlight classic gnomish design, built to withstand volatile friction and balance delicate mechanical assemblies like the Recombobulator."},kw={"dun morogh","gibblewilt","gnomeregan","kharanos","leper gnome","operation recombobulation","razzle sprysprocket","restabilization cog"},rel={"quest:412","item:gyromechanic-gear","npc:razzle-sprysprocket","topic:leper-gnome","zone:gnomeregan","subzone:kharanos","zone:dunmorogh","topic:gnome"},src={"Restabilization Cog","Operation Recombobulation (Classic)"}}
E["item:rumbleshot-s-ammo"] = {t="item",n="Rumbleshot's Ammo",z="dunmorogh",s="Rumbleshot's Ammo is a mislaid crate of munitions bound for the gunsmith Hegnar Rumbleshot in Dun Morogh. Lost when a frightened courier fled from hungry wendigos, the heavy crate sits abandoned in the snow near the Grizzled Den.",h="Rumbleshot's Ammo is a mislaid crate of munitions bound for the gunsmith Hegnar Rumbleshot in Dun Morogh.",sec={{t="A Stranded Shipment",b="Hegnar Rumbleshot operates a roadside arms shop along the mountain path leading down from Coldridge Pass toward Anvilmar. With Ironforge riflemen, mountaineers, and dwarven mortar teams constantly drilling in the snowy heights, his supplies burn away almost as fast as powder catches flame. This particular shipment of shot was dispatched by Loslor from Kharanos, but never reached the shelves. The courier tasked with transporting it pitched camp too close to the predatory wendigos of the Grizzled Den, panicked when attacked, and fled for his life, leaving the heavy supply crate sitting deep within the beast's hunting grounds.",sp=0}},faq={{q="Who is Hegnar Rumbleshot?",a="Hegnar Rumbleshot is a dwarven gunsmith who runs a shop off the road toward Anvilmar. He caters to local marksmen, hunters, and military gunners who burn through munitions quickly while practicing in the crags of Dun Morogh.",al={"rumbleshot","who is hegnar","gun vendor"},it="people"},{q="How did the ammo crate get lost?",a="A delivery courier dispatched with the crate made the mistake of camping near the entrance of the Grizzled Den. When the den's territorial wendigos attacked his camp, the terrified courier ran away, leaving the heavy crate behind in the snow.",al={"why was ammo lost","what happened to the ammo","courier ammo"},it="history"},{q="Where is the Grizzled Den?",a="The Grizzled Den is a cavern system carved into the mountains southwest of Kharanos. It serves as a notorious lair for Dun Morogh's vicious wendigos, making the surrounding slopes perilous for solitary travelers.",al={"grizzled den location","where is wendigo cave"},it="place",gp=true},{q="What is Rumbleshot's Ammo?",a="It is a crate of fresh ammunition packed for Hegnar Rumbleshot's shop out along the road to Anvilmar. With local dwarven riflemen and mortar teams constantly practicing nearby, Hegnar depends on steady bulk shipments like this to keep his shelves stocked and his customers armed.",al={"what is rumbleshots ammo","rumbleshot ammo crate","what are these munitions"},it="identity",add="4221fe47"},{q="Where does Rumbleshot's Ammo come from?",a="The crate was supplied and sent out by Loslor Rudge from Kharanos. Unfortunately, the courier tasked with bringing it southwest toward Anvilmar was ambushed by ferocious wendigos near the Grizzled Den and fled, abandoning the entire shipment in the snow.",al={"who made rumbleshots ammo","where did rumbleshots ammo come from","who sent the ammo"},it="origin",add="008970c2"},{q="Why does Hegnar Rumbleshot need this ammo?",a="Hegnar is on the verge of running out of stock entirely. The nearby mountaineers, riflemen, and mortar teams burn through gunpowder and shot at a blistering pace during target practice, leaving plenty of eager buyers waiting the moment the fresh shipment arrives.",al={"why is rumbleshots ammo needed","why want rumbleshot ammo","who needs rumbleshots ammo"},it="why_wanted",add="6d6b5eaa"}},ang={["class:Hunter"]="For marksmen roaming the bitter cold of Dun Morogh, keeping Hegnar's powder dry and shot stocked ensures a steady supply of ammunition for dwarven firearms.",["profession:Engineering"]="Dwarven engineers and tinkers rely heavily on a constant flow of shot and powder to test their crafted firearms and experimental weaponry."},kw={"ammo","crate","dun morogh","grizzled den","hegnar","loslor","rumbleshot","wendigo"},rel={"quest:5541","npc:hegnar-rumbleshot","subzone:grizzled-den","quest:313","subzone:kharanos","subzone:anvilmar","zone:dunmorogh"},src={"Rumbleshot's Ammo","Ammo for Rumbleshot"}}
E["item:sara-balloo-s-plea"] = {t="item",n="Sara Balloo's Plea",z="dunmorogh",s="Sara Balloo's Plea is a handwritten missive penned by a grieving widow in Ironforge. Unable to face the monarch directly in her sorrow, she entrusts this letter to a trusted champion of the Alliance to carry before King Magni Bronzebeard.",h="Sara Balloo's Plea is a handwritten missive penned by a grieving widow in Ironforge.",sec={{t="A Widow's Appeal",b="Written in the shadow of deep personal tragedy, Sara Balloo's Plea represents a humble appeal directly to Ironforge's throne. Rather than braving the High Seat herself in her grief-stricken condition, Sara seeks an adventurer who has demonstrated loyalty and valor to the Alliance to deliver her words. The message asks for the attention of King Magni Bronzebeard, drawing the sovereign's gaze toward the private mourning and sacrifices made by ordinary dwarven families serving the kingdom.",sp=0}},faq={{q="What is Sara Balloo's Plea?",a="It is a handwritten letter penned by Sara Balloo, addressed to King Magni Bronzebeard, asking for his royal attention while she mourns in private.",al={"sara balloo plea","widow note ironforge","sara note"},it="identity"},{q="Why does Sara Balloo need someone else to deliver it?",a="Sara feels overcome with grief and believes appearing before the King of Ironforge in such an emotional state would hinder her plea, prompting her to rely on an Alliance champion instead.",al={"why deliver note","why cant sara go","sara grief"},it="motive"},{q="Who receives this message?",a="The letter is addressed and delivered directly to King Magni Bronzebeard in the High Seat of Ironforge.",al={"who gets plea","who to deliver to","magni letter"},it="target"},{q="What does delivering the letter lead to?",a="Presenting the letter to King Magni draws his attention to Sara Balloo's bereavement and initiates a royal response honoring her fallen family.",al={"plea questline","a kings tribute link","what happens next"},sp=1,it="next_step"},{q="Where does Sara Balloo's Plea come from, and who made it?",a="This written note was penned directly by Sara Balloo, a grieving dwarven woman in Ironforge. Devastated by loss, she prepared the message herself to petition Ironforge's throne, entrusting it to an Alliance champion rather than attempting the emotional journey to the high seat on her own.",al={"who wrote sara balloos plea","where did sara balloos plea come from","who made sara balloos plea"},it="origin",add="2b83ea9f"},{q="Why does anyone want Sara Balloo's Plea?",a="King Magni Bronzebeard requires the letter to hear the petition of one of his grieving subjects. Sara Balloo cannot bring herself to appear before the monarch in her sorrowful state, so she relies on you to present the appeal directly into the hands of Ironforge's ruler.",al={"why is sara balloos plea needed","who wants sara balloos plea","why deliver sara balloos plea"},it="why_wanted",add="4ac5e6cf"}},ang={["race:Dwarf"]="For dwarves, carrying Sara's message to the High Seat is an act of deep kinship, ensuring that even in grief, no mountaineer or citizen goes unheard by King Magni.",["faction:Alliance"]="Sara entrusts her petition only to champions recognized for their service to the Alliance, trusting their reputation to grant her appeal an audience before royalty."},kw={"a king's tribute","high seat","ironforge","magni bronzebeard","sara balloo","sara balloo's plea"},rel={"npc:sara-balloo","quest:683","npc:magni-bronzebeard","quest:686","zone:ironforge","topic:alliance","zone:dunmorogh"},src={"Sara Balloo's Plea","Sara Balloo's Plea (quest)"}}
E["item:shimmerweed"] = {t="item",n="Shimmerweed",z="dunmorogh",s="Shimmerweed is a distinct herb cultivated by the Frostmane trolls on Shimmer Ridge in the snowy heights of Dun Morogh. While the trolls harvest it for their own tribal rituals, local dwarven brewers covet its sharp, unique flavor for experimental ales.",h="Shimmerweed is a distinct herb cultivated by the Frostmane trolls on Shimmer Ridge in the snowy heights of...",sec={{t="A Trollish Crop",b="High above the lowlands of Dun Morogh, the Frostmane trolls tend patches of shimmerweed along the icy crags of Shimmer Ridge. The trolls harvest and store the plant in woven baskets scattered throughout their camps, relying on it to fuel their sacred and enigmatic rituals. Outside of troll society, few mountaineers pay the weed much mind, though its potent properties have drawn the gaze of inventive outsiders.",sp=0},{t="A Secret Ingredient",b="In nearby Brewnall Village, brewmaster Rejold Barleybrew has taken a keen interest in the herb. Believing that brewing is in his blood, Rejold seeks to craft the ultimate dwarven stout and suspects that the pungent, unmistakable flavor of shimmerweed might be the missing piece. He frequently hires adventurous travelers to slip into the Frostmane encampments, dodge the hostile trolls, and haul back bushels to dump into his fermenting vats.",sp=0}},faq={{q="Where does shimmerweed grow?",a="Shimmerweed is found up on Shimmer Ridge, an icy rise northwest of Brewnall Village in Dun Morogh. It is cultivated and gathered by the Frostmane trolls, who keep it stored in baskets around their camps.",al={"shimmerweed location","where to find shimmerweed","shimmer ridge plant"},it="place"},{q="What do the Frostmane trolls use shimmerweed for?",a="The Frostmane trolls utilize shimmerweed in their mysterious tribal rites and ceremonies. While the precise details of their rituals remain opaque to outsiders, the herb plays an active role in their cultural and spiritual practices on Shimmer Ridge.",al={"troll shimmerweed use","why do trolls want shimmerweed"},it="motive"},{q="Why does Rejold Barleybrew want shimmerweed?",a="Rejold Barleybrew is striving to brew the perfect dwarven stout in Brewnall Village. Having detected a unique taste in the wild herb, he wants to toss fresh bushels of shimmerweed into his experimental mash to see if it delivers the bold profile his recipe needs.",al={"rejold barleybrew quest","who wants shimmerweed","why brew with shimmerweed"},it="why_wanted"},{q="Does shimmerweed grow anywhere outside Dun Morogh?",a="Varieties of shimmerweed have been gathered in arid lands like Durotar, where farseers such as Drek'Thar value the plant for potent herbal concoctions and medicinal brews, proving the weed can adapt beyond the frozen peaks of Khaz Modan.",al={"shimmerweed durotar","shimmerweed outside dun morogh"}},{q="What is Shimmerweed?",a="Shimmerweed is a distinctive plant cultivated high in the snowy heights of Dun Morogh by the Frostmane trolls, particularly around Shimmer Ridge. Notable for its unusual flavor and properties, the herb is gathered in troll baskets and plays a role in local tribal rituals, though ambitious dwarven brewers have recently taken an interest in testing its potent qualities in experimental ales.",al={"what is shimmerweed","shimmerweed plant","about shimmerweed"},it="identity",add="1978b4f9"},{q="Where does Shimmerweed come from, and who made it?",a="Shimmerweed is naturally cultivated by the Frostmane trolls in Dun Morogh, who tend and harvest the plant in baskets up on Shimmer Ridge. While the Frostmane maintain crops of it for their own rituals, wild varieties of the potent herb have also been known to grow in distant lands like Durotar, where wilderness herbalists and shamans prize it for brewing potions.",al={"where does shimmerweed come from","who made shimmerweed","shimmerweed origin"},it="origin",add="d2fd1cd1"}},ang={["race:Dwarf"]="True to dwarven ingenuity, if a strange plant grows on a nearby cliffside, someone will eventually try to ferment it into beer.",["profession:Herbalism"]="While not part of a standard field botanist's kit, shimmerweed showcases how regional flora is often adapted for local brewing traditions and ritual alchemy alike."},kw={"brewnall village","dun morogh","frostmane","perfect stout","rejold barleybrew","shimmer ridge","shimmerweed"},rel={"quest:315","subzone:shimmer-ridge","npc:rejold-barleybrew","subzone:brewnall-village","zone:dunmorogh","topic:troll","zone:durotar"},src={"Shimmerweed","The Perfect Stout"}}
E["item:simple-memorandum"] = {t="item",n="Simple Memorandum",z="dunmorogh",s="The Simple Memorandum is an official notice delivered to novice gnome warriors training in Coldridge Valley. Written on behalf of the warrior trainer Thran Khorman, it instructs fledglings to report to him in Anvilmar to advance their martial discipline.",h="The Simple Memorandum is an official notice delivered to novice gnome warriors training in Coldridge Valley.",sec={{t="A Summons to Anvilmar",b="Novice adventurers in Coldridge Valley frequently find themselves entrusted with letters of introduction as they demonstrate their mettle against the local wildlife and trogg threats. For young gnome fighters, this memorandum serves as a formal summons from Thran Khorman, the resident warrior trainer within Anvilmar. Dwarven veterans recognize that while gnomes may rely on intellect and contraptions, retaking Gnomeregan will demand pure physical resolve and martial discipline. The memorandum directs the bearer to put aside preliminary tasks and seek personalized instruction in the art of war.",sp=0}},faq={{q="What is the Simple Memorandum?",a="It is a written message delivered to novice gnome warriors working in Coldridge Valley, directing them to report to the dwarven warrior trainer inside Anvilmar.",al={"simple memorandum","what is this note","memorandum item"},it="identity"},{q="Who wrote the Simple Memorandum?",a="The memorandum originates from Thran Khorman, the dwarven warrior trainer stationed in Anvilmar, who aims to spot and prepare promising new combatants.",al={"who wrote memorandum","who sent note","author of simple memorandum"},it="origin"},{q="What happens after reading the Simple Memorandum?",a="Once you read the document, you take it to Thran Khorman inside Anvilmar. He acknowledges your determination to reclaim your lost home and offers to train you in foundational warrior techniques.",al={"what do i do with memorandum","where do i take it","turn in simple memorandum"},it="next_step"},{q="Why is a dwarf training gnome warriors?",a="Following the fall of Gnomeregan, gnome refugees settled under the hospitality of Ironforge and Anvilmar. Dwarven veterans like Thran Khorman have pledged their martial expertise to help their exiled allies train and ultimately take back their irradiated city.",al={"why thran training gnomes","dwarves training gnomes"}},{q="Why was the Simple Memorandum given to me?",a="The memorandum was sent by Thran Khorman, the warrior trainer inside Anvilmar, to summon promising recruits to his side. As a displaced gnome warrior fighting to one day reclaim Gnomeregan, you need veteran instruction to sharpen your martial skills. Thran recognized your tenacity and offered his guidance, using this note to formally call you into his service and begin your training in Coldridge Valley.",al={"why simple memorandum","purpose of simple memorandum","why do i need simple memorandum"},it="why_wanted",rc="Gnome",add="801fd269"}},ang={["class:Warrior"]="This note represents a warrior's initial step out of rudimentary skirmishing into formal combat instruction under Thran Khorman in Anvilmar.",["race:Gnome"]="For gnome exiles, the memorandum is a reminder of their shared objective: honing battle skills alongside their dwarven allies to prepare for the eventual liberation of Gnomeregan."},kw={"anvilmar","coldridge valley","dun morogh","gnomeregan","simple memorandum","thran khorman","warrior training"},rel={"quest:3112","npc:thran-khorman","subzone:anvilmar","subzone:coldridge-valley","zone:dunmorogh","zone:ironforge"},src={"Simple Memorandum","Simple Memorandum (quest)"}}
E["item:simple-rune"] = {t="item",n="Simple Rune",z="dunmorogh",s="A Simple Rune is an inscribed stone token passed to fledgling dwarven warriors training in Coldridge Valley. It serves as a summons from the warrior trainer Thran Khorman, directing recruits to seek instruction inside Anvilmar.",h="A Simple Rune is an inscribed stone token passed to fledgling dwarven warriors training in Coldridge Valley.",sec={{t="A Summons to Arms",b="Carved with basic martial marks, the Simple Rune is handed to promising recruits who have begun clearing out the threats around Coldridge Valley. Rather than a magical charm, it acts as a formal calling stone from Thran Khorman, the resident warrior trainer at Anvilmar. Upon reading its inscribed guidance, a young fighter is expected to report directly to Thran to learn basic combat techniques and hear practical advice on surviving Dun Morogh's hostile wilds.",sp=0}},faq={{q="What is the purpose of the Simple Rune?",a="The Simple Rune is an instructional tablet given to novitiate warriors in Coldridge Valley. Reading it directs the recruit to present themselves to Thran Khorman inside Anvilmar for formal training.",al={"simple rune use","what does rune do","simple rune quest item"},it="purpose"},{q="Who sends the Simple Rune?",a="It is sent by Thran Khorman, the dwarf warrior trainer stationed inside Anvilmar, who watches for promising fighters assisting around the valley.",al={"who wrote rune","who gave me simple rune","sender of rune"},it="origin"},{q="Where do I take the Simple Rune?",a="Take it to Thran Khorman inside the great forge hall of Anvilmar, located in central Coldridge Valley.",al={"where do i go","rune turn in","thran khorman location"},it="next_step",gp=true},{q="What is the Simple Rune?",a="The Simple Rune is an inscribed dwarven stone passed to promising warriors in Coldridge Valley. Rather than bearing mystical enchantments, it functions as a written summons from Thran Khorman, calling novice fighters to report to him in Anvilmar to begin their formal martial training.",al={"what is simple rune","simple rune lore","simple rune item"},it="identity",add="0f0eb9fb"},{q="Why does Thran Khorman want you to have the Simple Rune?",a="Thran Khorman sends the rune to recruit you into formal warrior instruction. Seeing potential in your early deeds around Coldridge Valley, he wants to ground you in proper dwarven martial discipline and teach you what it truly takes to fight for Ironforge amidst rising local threats.",al={"why thran sends rune","why do i need simple rune","why want simple rune"},it="why_wanted",add="2d1fc984"}},ang={["class:Warrior"]="For dwarven warriors, this inscribed stone marks the first step into formal military training under veteran instructor Thran Khorman.",["race:Dwarf"]="Dwarves traditionally rely on sturdy inscribed runes for orders, reminders, and martial summons rather than fragile parchment."},kw={"anvilmar","coldridge valley","dun morogh","dwarf rune","simple rune","thran khorman","warrior training"},rel={"quest:3106","npc:thran-khorman","subzone:anvilmar","subzone:coldridge-valley","zone:dunmorogh","topic:warrior","topic:dwarf"},src={"Simple Rune","Simple Rune (Classic)"}}
E["item:steelgrill-s-tools"] = {t="item",n="Steelgrill's Tools",z="dunmorogh",s="Steelgrill's Tools are a specialized set of mechanic implements requisitioned for Beldin Steelgrill, the master technician of Steelgrill's Depot. Renowned for pushing siege engines—and his own equipment—to their limits, Beldin frequently breaks gear and relies on shipments from nearby Kharanos to keep his workshop running.",h="Steelgrill's Tools are a specialized set of mechanic implements requisitioned for Beldin Steelgrill, the...",sec={{t="A Heavy-Handed Craftsman",b="Beldin Steelgrill is widely regarded as one of the finest siege engine technicians in Dun Morogh, but his aggressive repair style is infamous among local merchants. Working tirelessly on armored tanks and mechanical contraptions, Beldin tends to destroy delicate equipment almost as fast as it can be forged. Between snapping arclight spanners and stripping fang-ratchets, the mechanic is constantly placing fresh orders in Kharanos to keep his repair benches stocked.",sp=0},{t="Keeping the Engines Rolling",b="This particular delivery of tools is vital for keeping Ironforge's war machines operational. At his depot northeast of Kharanos, Beldin is actively servicing combat vehicles for seasoned drivers like Pilot Stonegear. Without freshly supplied wrenches and ratchets, critical siege engines would sit half-assembled in the snow, leaving both the depot and local defenses stalled.",sp=0}},faq={{q="What are Steelgrill's Tools used for?",a="They are replacement mechanic implements delivered to Beldin Steelgrill at Steelgrill's Depot. Beldin requires them to overhaul heavy dwarven machinery, particularly the damaged siege engine belonging to Pilot Stonegear.",al={"what are these tools","steelgrill tools purpose"},it="purpose"},{q="Why does Beldin Steelgrill go through so many tools?",a="Beldin is an exceptionally rough mechanic who pushes his gear to the breaking point. According to suppliers in Kharanos, he snaps arclight spanners and breaks fang-ratchets almost faster than local crafters can provide them.",al={"why broken tools","why does beldin need tools"},it="motive"},{q="Where did this crate of tools come from?",a="The shipment is assembled and fulfilled in the nearby settlement of Kharanos before being handed to travelers heading northeast toward Steelgrill's Depot.",al={"where do i get tools","tool shipment origin"},it="origin"},{q="Who is Beldin Steelgrill?",a="Beldin is a master dwarf mechanic who owns and operates Steelgrill's Depot, located northeast of Kharanos. He is considered the premier siege engine technician in the region.",al={"who is beldin","beldin steelgrill lore"},it="people"},{q="What is Steelgrill's Tools?",a="Steelgrill's Tools is a freshly packaged order of heavy mechanical equipment, including arclight spanners and fang-ratchets. It has been prepped for delivery directly to Beldin Steelgrill, the master siege engine technician working out of Steelgrill's Depot near Kharanos.",al={"what are steelgrills tools","steelgrills tools crate","what is steelgrill's tools"},it="identity",add="8eb066d8"},{q="Why does Beldin Steelgrill need this crate of tools?",a="Beldin is an expert mechanic, but he works his gear to the breaking point while servicing heavy machinery. Having just snapped his last fang-ratchet, he urgently needs this fresh shipment to complete critical repairs on siege engines like Pilot Stonegear's.",al={"why does beldin want tools","why need steelgrills tools","why are tools wanted"},it="why_wanted",add="11454cb4"}},ang={["profession:Engineering"]="Every engineer can sympathize with Beldin's dilemma, as high-torque repairs on heavy siege engines routinely sacrifice arclight spanners and delicate wrenches.",["race:Dwarf"]="Maintaining the Alliance's armored siege engines is a matter of dwarven pride, and keeping Beldin supplied ensures Ironforge's armored vanguard remains combat-ready."},kw={"beldin","depot","kharanos","ratchet","siege engine","spanner","steelgrill","tools"},rel={"npc:beldin-steelgrill","subzone:steelgrill-s-depot","quest:400","subzone:kharanos","npc:pilot-stonegear","zone:dunmorogh"},src={"Steelgrill's Tools","Tools for Steelgrill"}}
E["item:sully-balloo-s-letter"] = {t="item",n="Sully Balloo's Letter",z="dunmorogh",s="Sully Balloo's Letter is a waterlogged, tender missive recovered from the sunken remains of a dwarven soldier beneath the Thandol Span. Addressed to his wife Sara in Ironforge, it represents the quiet personal tragedies lingering beneath the grand conflicts of Khaz Modan.",h="Sully Balloo's Letter is a waterlogged, tender missive recovered from the sunken remains of a dwarven soldier...",sec={{t="A Final Farewell Beneath the Waves",b="Beneath the massive stone pillars of the Thandol Span, connecting the Wetlands to the Arathi Highlands, lies the skeletal remains of a dwarf pinned deep under the rushing water. Clutched in his grasp is a fragile, waterlogged envelope containing this letter. Written with painstaking care in his final days or hours, it begins with the poignant words, 'My dear Sara....' Though the parchment has suffered from prolonged submersion, the ink still holds the enduring love of a dwarven defender who never made it back home to the city of Ironforge.",sp=0},{t="Delivery to Ironforge",b="Bringing the letter to Sara Balloo in Ironforge brings a somber, devastating closure. Residing in the dwarven capital, Sara endures the agonizing uncertainty shared by so many whose kin marched off to war. Reading the final thoughts of her husband Sully confirms her worst fears—that he perished far from home beneath the icy currents of the northern crossing—yet preserves his devotion across death.",sp=1}},faq={{q="Where is Sully Balloo's Letter found?",a="The letter is retrieved from a waterlogged envelope clutched in the hand of a skeletal dwarf submerged at the bottom of the waters beneath the Thandol Span, which separates the Wetlands from the Arathi Highlands.",al={"letter location","where is sullys letter","where to find sully balloo letter"},gp=true},{q="Who was Sully Balloo?",a="Sully Balloo was a dwarven soldier who lost his life near the Thandol Span during the defense of the vital northern crossing, leaving his remains pinned under the river currents.",al={"who is sully balloo","sully balloo lore","what happened to sully"},it="people"},{q="Who is the letter addressed to?",a="The letter is addressed to Mrs. Sara Balloo, Sully's grieving wife, who lives within the great dwarven mountain city of Ironforge.",al={"who gets the letter","who is sara balloo","where to turn in sully letter"}},{q="What happens when you deliver the letter to Sara Balloo?",a="Upon receiving the letter, Sara Balloo is heartbroken to learn that her husband is pinned dead beneath the icy waters, but she cherishes the opportunity to read the final words he lovingly penned to her.",al={"sara balloo reaction","turning in the letter","quest completion sully letter"},sp=1,it="next_step",gp=true},{q="What is Sully Balloo's Letter?",a="It is a tender, war-torn letter penned with painstaking care by a dwarf soldier named Sully Balloo. Found preserved beneath the icy waters of the Thandol Span, it contains the final heartfelt words written to his wife in Ironforge before his death in battle.",al={"what is sullys letter","sully balloos letter","about sully balloo letter"},it="identity",add="efe638b9"},{q="Where does Sully Balloo's Letter come from, and who made it?",a="The letter was written by Sully Balloo, an Alliance soldier serving on the front lines at the Thandol Span between the Wetlands and Arathi Highlands. It survived submerged in a waterlogged envelope held in the grasp of his submerged remains beneath the great bridge.",al={"who wrote sully balloos letter","where did sully letter come from","creator of sully balloo letter"},it="origin",add="b8624ec6"},{q="Why does anyone want Sully Balloo's Letter?",a="Its recipient, Sara Balloo, resides in Ironforge unaware of her husband's tragic demise. Delivering the letter fulfills a fallen soldier's last wish and brings bittersweet closure to a grieving widow awaiting news of her beloved.",al={"why deliver sully balloo letter","who wants sullys letter","why bring letter to sara balloo"},it="why_wanted",add="b54d6872"}},ang={["race:Dwarf"]="For dwarves, the letter represents the heartbreaking sacrifices ordinary mountaineers and soldiers make to guard the high bridges and mountain passes of Khaz Modan.",["faction:Alliance"]="Delivering the letter offers a somber moment of compassion, ensuring that a fallen soldier's last thoughts reach his widow rather than being forgotten under the bridge."},kw={"arathi highlands","ironforge","letter","sara balloo","sully balloo","thandol span","waterlogged envelope","wetlands"},rel={"npc:sara-balloo","quest:637","subzone:thandol-span","zone:ironforge","zone:arathi","quest:631","zone:dunmorogh"},src={"Sully Balloo's Letter","Sully Balloo's Letter (quest)"}}
E["item:tainted-memorandum"] = {t="item",n="Tainted Memorandum",z="dunmorogh",s="The Tainted Memorandum is a discreet note handed to novice gnome warlocks starting out in Coldridge Valley. Penned by the warlock trainer Alamar Grimm, it urges the reader to cast aside traditional paths and seek out the true power offered by the dark arts.",h="The Tainted Memorandum is a discreet note handed to novice gnome warlocks starting out in Coldridge Valley.",sec={{t="A Discreet Summons",b="In the chilly dwarven outpost of Anvilmar, practitioners of fel magic are neither celebrated nor widely trusted. For young gnomes dabbling in forbidden arts, the Tainted Memorandum serves as an invitation from Alamar Grimm. The message rejects reliance on the Holy Light or mundane martial steel, pointing instead to the fall of Gnomeregan as proof that conventional methods and tinkering have failed their people. To Grimm, relying on dwarven charity is a dead end; gnomes must seize undeniable power and summon unquestioning minions if they ever hope to secure their own future.",sp=0}},faq={{q="Who wrote the Tainted Memorandum?",a="The memorandum was written by Alamar Grimm, the gnome warlock trainer stationed inside Anvilmar in Coldridge Valley.",al={"author tainted memorandum","who sent tainted memorandum","alamar grimm note"},it="origin"},{q="Why is the memorandum considered 'tainted'?",a="It deals directly with forbidden warlock magic. The title reflects the distrust and stigma surrounding demonic and fel power in Dun Morogh, where practitioners are kept at arm's length by their dwarven hosts.",al={"why tainted","tainted letter lore"}},{q="What does Alamar Grimm say about Gnomeregan?",a="Grimm is bitter about the fall of the gnome capital, blaming traditional arcane magic and careless tinkering for bringing their race close to extinction. He believes the dwarves view gnomes as second-class citizens and urges warlocks to find their own absolute power instead of waiting for Alliance help.",al={"alamar grimm gnomeregan","alamar grimm views"}},{q="What is the Tainted Memorandum?",a="The Tainted Memorandum is a discrete, personal message intended for promising gnome warlocks who are just beginning their training in Coldridge Valley. Passed along quietly by allies on the surface, the note serves as an invitation to look past the conventional traditions of the Holy Light or physical combat and seek out kindred, open-minded practitioners who harbor darker arts.",al={"what is tainted memorandum","tainted memo","what is this note"},it="identity",add="0c729b68"},{q="Why does someone want you to have the Tainted Memorandum?",a="The memorandum is given to recruit you into the fold of the warlock arts. The warlock trainer Alamar Grimm sends it to identify novice spellcasters who reject ordinary dwarf and gnome dogmas, urging you to meet him in Anvilmar to master obedient, summoned allies and unlock the true source of demonic power.",al={"why was i given the memorandum","why tainted memorandum","who wants the tainted memorandum"},it="why_wanted",add="e7be2e4a"}},ang={["class:Warlock"]="The note marks your formal introduction to warlock training under Alamar Grimm, framing dark summoning as a necessary pursuit of control and power.",["race:Gnome"]="Grimm's message taps into gnome resentment over the loss of Gnomeregan and their perceived status as dependent refugees in dwarven lands."},kw={"alamar grimm","anvilmar","coldridge valley","gnome warlock","gnomeregan","tainted memorandum"},rel={"npc:alamar-grimm","quest:3115","subzone:anvilmar","subzone:coldridge-valley","topic:warlock","zone:dunmorogh"},src={"Tainted Memorandum","Tainted Memorandum (quest)"}}
E["item:thick-bear-fur"] = {t="item",n="Thick Bear Fur",z="dunmorogh",s="Thick Bear Fur is a prized pelt gathered from the cold-hardened bears roaming the snowdrifts of Dun Morogh. Coveted for its heat retention, it is commonly used by traveling scouts and soldiers to craft insulation and warm bedding against the bitter alpine freeze.",h="Thick Bear Fur is a prized pelt gathered from the cold-hardened bears roaming the snowdrifts of Dun Morogh.",sec={{t="Warmth Against the Mountain Frost",b="The bears prowling the ridges of Dun Morogh endure some of the harshest snowfields in the Eastern Kingdoms. Their thick, resilient coats provide vital protection from blizzards, making the pelt an invaluable resource for locals and travelers alike. Rather than being discarded as scrap, these heavy pelts are regularly harvested by hunters and used to line clothes, insulate drafty outposts, and pad cold sleeping rolls.",sp=0},{t="Bedding for the Siege Brigade",b="When Pilot Bellowfiz began outfitting his siege tank, Jetsteam, at Steelgrill's Depot, he faced the harsh prospect of spending a full month in the field on a long mission for the Siege Brigade. Because cold iron offers little comfort in high-altitude snowbanks, he commissioned local scouts to gather thick bear furs from the snow fields south of the Grizzled Den to fashion warm bedding for his cabin quarters.",sp=0}},faq={{q="Where does Thick Bear Fur come from?",a="Thick Bear Fur is gathered from the indigenous bears of Dun Morogh, notably Young Black Bears and Ice Claw Bears. They can be found hunting across the snowy tundras and pine groves south of the Grizzled Den.",al={"where to get thick bear fur","who drops thick bear fur","bear fur location"},it="origin",gp=true},{q="Why does Pilot Bellowfiz need this fur?",a="Pilot Bellowfiz is outfitting his tank, Jetsteam, for an extended month-long mission on behalf of the Siege Brigade. He requires heavy furs to fashion warm bedding inside the metal chassis to endure the bitter mountain nights.",al={"bellowfiz fur","why does bellowfiz need fur","stocking jetsteam fur"},it="why_wanted"},{q="What creatures in Dun Morogh yield this pelt?",a="Both Young Black Bears and the larger, fiercer Ice Claw Bears that wander the highland snows possess the dense fur required for heavy winter bedding and insulation.",al={"which bears drop fur","dun morogh bear types"},it="target",gp=true},{q="What is Thick Bear Fur?",a="Thick Bear Fur is the heavy, insulated pelt harvested from the wild bears roaming the frigid crags and snowdrifts of Dun Morogh. Adapted to survive biting sub-zero blizzards, this dense hide provides vital warmth and protection against Khaz Modan's relentless alpine cold.",al={"thick bear fur","what is this fur","dun morogh bear fur"},it="identity",add="a2edc513"}},ang={["class:Hunter"]="Trekking into the cold brush to stalk Dun Morogh's bears teaches young hunters how to navigate dangerous mountain beasts and harvest durable materials from the wild.",["race:Gnome"]="Gnomish siege tank pilots operating around Steelgrill's Depot must rely on practical dwarf-country hunting to keep their machines survivable during long alpine deployments."},kw={"bellowfiz","dun morogh","grizzled den","ice claw bear","jetsteam","steelgrill's depot","thick bear fur"},rel={"quest:317","npc:pilot-bellowfiz","subzone:steelgrill-s-depot","subzone:grizzled-den","zone:dunmorogh","quest:318","topic:gnome"},src={"Thick Bear Fur","Stocking Jetsteam"}}
E["item:wendigo-mane"] = {t="item",n="Wendigo Mane",z="dunmorogh",s="Wendigo Manes are the thick, shaggy coats harvested from the savage wendigos roaming the frozen crags of Dun Morogh. Coveted for their heavy insulation against the biting mountain chill, these coarse pelts are tough enough to line cabin floors or the iron cabins of dwarven warmachines.",h="Wendigo Manes are the thick, shaggy coats harvested from the savage wendigos roaming the frozen crags of Dun...",sec={{t="Warmth for the Ironworks",b="The mountains of Dun Morogh are harsh and unyielding, prompting locals to make good use of the apex beasts stalking the snowdrifts. The coarse fur of a wendigo offers dense protection against bitter sub-zero drafts. Pilot Stonegear, stationed outside Kharanos, sends adventurers into the nearby Grizzled Den to gather these heavy manes. Rather than fashioning winter coats or cloaks, the eccentric pilot intends to weave them into a plush, insulating floor rug for the interior deck of his prized dwarven siege engine, Trollplow.",sp=0}},faq={{q="What creatures yield a Wendigo Mane?",a="The manes can be gathered from any wendigo inhabiting the snows of Dun Morogh. This includes common Young Wendigos, adult Wendigos, and notable alpha beasts such as Vagash, Edan the Howler, and Old Icebeard.",al={"where do wendigo manes drop","who drops wendigo mane","wendigo mane sources"},it="origin",gp=true},{q="Why does Pilot Stonegear want these manes?",a="Pilot Stonegear wants the manes to craft an insulating rug for the inside deck of his siege engine, Trollplow. Running a massive iron machine through frozen terrain gets intensely cold, and the thick fur helps keep the pilot's station warm and comfortable.",al={"why stonegear wants manes","pilot stonegear rug","what are manes used for"},it="why_wanted"},{q="Where is the best place to find wendigos for their manes?",a="The primary lair recommended by Pilot Stonegear is the Grizzled Den, a cave system cut into the mountains directly west of Kharanos. The cavern and its surrounding slopes teem with wendigos.",al={"grizzled den location","where to hunt wendigos","wendigo cave dun morogh"},it="place",gp=true},{q="Are wendigos dangerous to hunt?",a="Yes. Wendigos are feral, territorial predators endowed with brutal physical strength and thick hides. Dwarven trainers consider braving their dens an early rite of passage to prove a mountaineer's courage and combat grit.",al={"are wendigos hard to kill","fighting wendigos"},it="danger"},{q="What is a Wendigo Mane?",a="A Wendigo Mane is a thick, shaggy patch of coarse fur harvested from the fierce wendigos prowling the snowy crags of Dun Morogh. Known for insulating the savage beasts against biting mountain blizzards, this durable pelt is tough, warm, and highly prized for rough craftwork.",al={"what is wendigo mane","wendigo mane item","wendigo fur"},it="identity",add="9c5452b4"},{q="Where does a Wendigo Mane come from?",a="These manes are harvested directly from the wild wendigos that roam Dun Morogh, notably around dens such as the Grizzled Den west of Kharanos. They are natural beast pelts, taken by hunters willing to brave the claws and fangs of the mountain creatures.",al={"where do wendigo manes come from","who drops wendigo mane","origin of wendigo mane"},it="origin",add="e05af805"}},ang={["profession:Engineering"]="Operating dwarven machinery in Dun Morogh means dealing with freezing metal cockpits, making insulated linings like wendigo pelts a practical comfort modification.",["race:Dwarf"]="Hunting the wendigos of the Grizzled Den is a time-tested trial for young dwarves looking to prove their toughness to the veterans of Kharanos."},kw={"dun morogh","fur","grizzled den","kharanos","mane","pelt","stonegear","trollplow","wendigo"},rel={"quest:313","npc:pilot-stonegear","subzone:grizzled-den","subzone:kharanos","zone:dunmorogh"},src={"Wendigo Mane","The Grizzled Den (quest)"}}
E["item:whitestone-oak-lumber"] = {t="item",n="Whitestone Oak Lumber",z="dunmorogh",s="Whitestone Oak Lumber is a sturdy crafting timber sourced from the subterranean shipyards beneath Moonbrook. Prized for its strength, it serves as a critical shaft material for sacred armaments forged by Alliance master smiths.",h="Whitestone Oak Lumber is a sturdy crafting timber sourced from the subterranean shipyards beneath Moonbrook.",sec={{t="Timber of the Under-Docks",b="Found deep inside the labyrinthine Deadmines of Westfall, Whitestone Oak is shaped by Goblin Woodcarvers constructing the Defias Brotherhood's clandestine war fleet. Its dense, resilient grain makes it ideally suited to bear structural strain and high-impact wear, drawing the interest of seasoned armorers who require more than common ash or pine for ceremonial and martial craft.",sp=0},{t="A Sacred Haft",b="Outside Ironforge, the smith Jordan Stilwell demands Whitestone Oak Lumber to construct a weapon befitting a true champion of the Light. Joined with a purified Kor gem and refined metals, this lumber provides the balanced, unyielding haft needed to withstand the holy energies channeled during the Test of Righteousness.",sp=1}},faq={{q="Where is Whitestone Oak Lumber found?",a="It is recovered from Goblin Woodcarvers laboring deep within the Deadmines beneath Moonbrook in Westfall, where the Defias Brotherhood constructs its hidden juggernaut.",al={"where to get whitestone oak","whitestone oak location","who drops whitestone oak lumber"},it="place",gp=true},{q="Who uses this lumber?",a="Jordan Stilwell, a skilled blacksmith working near the gates of Ironforge in Dun Morogh, requires the timber to fashion a specialized weapon for rising paladins.",al={"who needs whitestone oak","whitestone oak turn in"},it="people"},{q="What is the wood used to make?",a="Jordan Stilwell uses the resilient timber as the haft for a mastercrafted two-handed holy hammer, forged as a reward for completing the Test of Righteousness.",al={"whitestone oak purpose","what does jordan stilwell forge"},it="item"},{q="Why is goblin lumber suitable for a holy weapon?",a="The Defias Brotherhood procures dense, high-grade timbers capable of supporting warships. Jordan Stilwell recognizes that such structural wood offers the physical resilience necessary to handle intense divine power.",al={"why goblin wood","why deadmines lumber"}},{q="What is Whitestone Oak Lumber?",a="Whitestone Oak Lumber is a fine, specialized timber sought after by skilled craftsmen. Prized for its sturdiness and quality, it serves as the essential wooden shaft or grip for forging a masterwork weapon of the Holy Light.",al={"what is whitestone oak lumber","whitestone oak lumber","what is whitestone lumber"},it="identity",add="3fba151d"},{q="Where does Whitestone Oak Lumber come from, and who made it?",a="The lumber is harvested and prepared deep within the Deadmines in Westfall. It is shaped by the goblin woodcarvers employed by the Defias Brotherhood, who cut and craft the timber amidst their illicit construction projects beneath the earth.",al={"where does whitestone oak come from","whitestone oak lumber source","who made whitestone oak lumber"},it="origin",add="9364a134"},{q="Why does Jordan Stilwell want Whitestone Oak Lumber?",a="The weaponsmith Jordan Stilwell requires this specific wood to forge a grand weapon fit for a holy paladin. Paired with refined ore, a purified Kor gem, and his father's hammer, the durable oak forms the foundation for what he considers his finest work.",al={"why is whitestone oak lumber wanted","why does jordan need whitestone oak","whitestone oak lumber use"},it="why_wanted",add="e7d39b03"}},ang={["class:Paladin"]="Procuring this timber from the Defias under-docks is a core requirement of Jordan Stilwell's Test of Righteousness, yielding a sacred hammer crafted for defenders of the Light.",["profession:Blacksmithing"]="Stilwell's weapon schematics pair dense Whitestone oak with refined ore and gemcraft to balance weight, durability, and metaphysical resonance."},kw={"deadmines","goblin woodcarver","jordan stilwell","paladin hammer","test of righteousness","whitestone oak lumber"},rel={"quest:1653","npc:jordan-stilwell","zone:deadmines","item:purified-kor-gem","item:jordan-s-smithing-hammer","item:jordan-s-refined-ore-shipment","topic:paladin","zone:dunmorogh"},src={"Whitestone Oak Lumber","The Test of Righteousness (2)"}}
E["npc:alamar-grimm"] = {t="npc",n="Alamar Grimm",z="dunmorogh",s="Alamar Grimm is a gnome warlock trainer stationed in Coldridge Valley at Anvilmar. Bitter over the tragic loss of Gnomeregan, he distrusts outsiders and focuses on teaching fledgling warlocks how to harness dark arts and summon their first demonic minions.",h="Alamar Grimm is a gnome warlock trainer stationed in Coldridge Valley at Anvilmar.",sec={{t="A Bitter Exile",b="While most gnomes in Coldridge Valley channel their energies into recovery and tinkering, Alamar Grimm harbors a deep resentment over the fall of Gnomeregan. He holds a cynical view of standard adventurers and even the host dwarves of Ironforge, grumbling that their allies care more about diplomacy with humans than reclaiming the fallen techno-city. Operating from Anvilmar, he seeks kindred spirits who understand that ruthless power may be what his people truly need.",sp=0},{t="Master of the Dark Arts",b="To young gnomes walking the path of fel magic, Grimm serves as an initial guide. When presented with a tainted memorandum, he offers a rare warm reception and begins tutoring recruits in fundamental spells. Before granting a novice the dangerous knowledge required to bind a demonic imp, however, he demands proof of their magical and physical endurance by sending them to retrieve the strange feather charms carried by local Frostmane troll novices.",sp=0}},faq={{q="Who is Alamar Grimm?",a="Alamar Grimm is a gnome warlock trainer located inside Anvilmar in Coldridge Valley. He trains starting gnomish warlocks in their foundational fel abilities and teaches them how to summon their first imp.",al={"alamar grimm","who is alamar","gnome warlock trainer anvilmar"},it="identity"},{q="Why is Alamar Grimm angry at the dwarves?",a="Alamar feels that despite sheltering the displaced gnomes, the dwarves of Ironforge do not truly prioritize the reclamation of Gnomeregan. He resents that dwarven interests seem tilted toward their alliance with humans rather than liberating his people's homeland.",al={"why does alamar hate dwarves","alamar dwarf opinion","why angry"}},{q="What does Alamar Grimm ask new warlocks to do?",a="To prove they possess the stamina and magical capability to control a demon, Grimm instructs novice warlocks to hunt local Frostmane troll novices and gather their feather charms. Once brought back, he uses them to test the recruit before teaching the ritual to summon an imp.",al={"alamar grimm imp quest","feather charms quest","frostmane charms warlock"}},{q="Whose side is Alamar Grimm on?",a="Alamar Grimm stands firmly with the exiled gnomish people, though he harbors sharp bitterness toward their current allies. While the dwarves shelter the displaced gnomes in Dun Morogh, Alamar resents Ironforge's leadership, believing they prioritize ties with distant humans over reclaiming Gnomeregan. He operates within the Alliance purely to rebuild gnomish strength on his own terms.",al={"alamar grimm faction","alamar grimm allegiance","who does alamar grimm fight for"},it="side",add="04c944ae"},{q="What does Alamar Grimm want?",a="Alamar wants nothing less than the reclamation of Gnomeregan and the empowerment of his people through dark magical arts. Dismissing conventional adventurers as ineffective failures who allowed the city to fall, he seeks to cultivate disciplined, capable warlocks who possess the true magical and physical strength required to take their homeland back.",al={"alamar grimm goals","what does alamar want","alamar grimm motive"},it="wants",add="949ab41a"},{q="Why is Alamar Grimm in Coldridge Valley?",a="Following the tragic fall of Gnomeregan, Alamar sought refuge alongside his fellow survivors in the safety of Coldridge Valley. Stationed near Anvilmar, he acts as a mentor and trainer to newly arrived gnomes who feel the pull toward fel magic, testing their potential and arming them with the dark spells needed to survive the harsh road ahead.",al={"why is alamar grimm here","why is alamar in anvilmar","alamar grimm purpose here"},it="why_here",add="1846448c"}},ang={["class:Warlock"]="For gnome warlocks starting out in Coldridge Valley, Grimm provides your earliest spells and tasks you with proving your worth to earn your first imp minion.",["race:Gnome"]="Grimm exemplifies the quiet bitterness of exiles who feel abandoned by their allies while Gnomeregan remains in trogg hands."},kw={"alamar","anvilmar","coldridge","gnomeregan","grimm","imp","trainer","warlock"},rel={"subzone:anvilmar","zone:dunmorogh","zone:gnomeregan","topic:gnome","quest:1599","npc:sten-stoutarm"},src={"Alamar Grimm"}}
E["npc:azar-stronghammer"] = {t="npc",n="Azar Stronghammer",z="dunmorogh",s="Azar Stronghammer is a dwarven paladin stationed at the Thunderbrew Distillery in Kharanos. Having completed his own training in the holy arts, he guides newly awakened dwarven champions of the Holy Light and directs promising recruits toward higher instruction in Ironforge.",h="Azar Stronghammer is a dwarven paladin stationed at the Thunderbrew Distillery in Kharanos.",sec={{t="A Guide in the Cold",b="While paladins are more commonly associated with the great cathedrals of humanity, the dwarves of Khaz Modan have fully embraced the virtues of the Holy Light. Stationed at the Thunderbrew Distillery in Kharanos, Azar Stronghammer watches over newly inducted dwarven paladins finding their footing amidst Dun Morogh's freezing slopes. Having mastered his own martial and spiritual vows, he serves as an approachable mentor. When a novice shows enough dedication and spiritual maturity, Azar directs them up the mountain path to Ironforge to study under veteran champions such as Tiza Battleforge.",sp=0}},faq={{q="Who is Azar Stronghammer?",a="Azar Stronghammer is a dwarven paladin trainer stationed in Kharanos at the Thunderbrew Distillery. He oversees the earliest training of young dwarven holy warriors before sending them onward to the capital.",al={"who is azar","azar stronghammer role","kharanos paladin trainer"},it="identity"},{q="Where can Azar Stronghammer be found?",a="He is located inside the Thunderbrew Distillery in the village of Kharanos, nestled in the central snowy hills of Dun Morogh.",al={"azar stronghammer location","where is azar","find azar stronghammer"},gp=true},{q="What training does he provide to young paladins?",a="Azar teaches fundamental paladin martial arts and spells to novices. Once an apprentice is ready to undertake the trials of the Tome of Divinity to learn the sacred rites of resurrection, he directs them to Tiza Battleforge in Ironforge.",al={"what does azar do","azar quest","paladin quests azar"},it="purpose",gp=true},{q="Why is a paladin trainer stationed at a distillery?",a="Dwarven culture intertwines civic life, camaraderie, and stout drink. The Thunderbrew Distillery acts as the heart of social life and defense in Kharanos, making it a natural gathering hall for local defenders and mentors.",al={"why is paladin in distillery","paladin in bar","distillery trainer"},it="why_here"},{q="Whose side is Azar Stronghammer on?",a="Azar Stronghammer stands firmly with the Kingdom of Ironforge and the Alliance. As an experienced dwarven paladin, his loyalties lie with his people, King Magni Bronzebeard, and the holy tenets of the Light.",al={"azar stronghammer faction","azar stronghammer allegiance","who does azar fight for"},it="side",add="38fe723c"},{q="What does Azar Stronghammer want?",a="Having completed his own extensive training in the Light, Azar aims to guide the next generation of dwarven paladins. He watches over promising apprentices in Dun Morogh and ensures they are prepared before sending them onward to master trainers like Tiza Battleforge in Ironforge.",al={"azar stronghammer goals","what is azar trying to do","azar stronghammer purpose"},it="wants",add="56baf4f4"},{q="Who is Azar Stronghammer tied to?",a="Azar maintains strong ties to his fellow dwarven paladins, notably coordinating with Tiza Battleforge in the Hall of Arms in Ironforge to advance the education of promising initiates. He may also share kinship with Commander Stronghammer of the dwarven military.",al={"azar stronghammer connections","azar stronghammer allies","who does azar know"},it="ties",add="0e6012b1"}},ang={["class:Paladin"]="For dwarven paladins starting their journey in Dun Morogh, Azar is an essential early mentor who eventually steers you to Ironforge to earn the sacred Tome of Divinity.",["race:Dwarf"]="Azar exemplifies the dwarven embrace of the Holy Light, showing that devotion to holy righteousness pairs seamlessly with a warm hearth and a mug of Thunderbrew."},kw={"azar","distillery","dun morogh","kharanos","paladin","stronghammer","thunderbrew","tome of divinity","trainer"},rel={"subzone:kharanos","subzone:thunderbrew-distillery","npc:tiza-battleforge","quest:2997","zone:ironforge","topic:light","topic:dwarf"},src={"Azar Stronghammer"}}
E["npc:balir-frosthammer"] = {t="npc",n="Balir Frosthammer",z="dunmorogh",s="Balir Frosthammer is a dwarven defender stationed in Coldridge Valley within Dun Morogh. Alarmed by the sudden and aggressive incursions of Rockjaw troggs into dwarven lands, he recruits fledgling adventurers to stem the tide before the valley is overrun.",h="Balir Frosthammer is a dwarven defender stationed in Coldridge Valley within Dun Morogh.",sec={{t="Holding Coldridge Valley",b="Perched in the snowy enclave of Coldridge Valley, Balir Frosthammer watches the perimeter against encroaching dangers. The valley has long served as a safe haven and training ground for dwarven and gnomish novices, but recent disturbances underground have unleashed violent Rockjaw troggs onto the surface. Balir is among the first to sound the alarm, rallying newly arrived recruits to cull the troggs before they breach deeper into Dun Morogh.",sp=0},{t="Kin of the Frosthammers",b="Bearing the proud Frosthammer surname, Balir may share a lineage with Tannok Frosthammer of Kharanos. Their family stands resolute in their duty to Ironforge, ensuring that the cold mountain passes remain secure for travelers, miners, and mountaineers even as regional threats multiply.",sp=0}},faq={{q="Who is Balir Frosthammer?",a="Balir Frosthammer is a dwarf stationed in Dun Morogh's Coldridge Valley. He tasks incoming adventurers with thinning out the hostile Rockjaw troggs threatening the valley's defenses.",al={"balir frosthammer who is he","who is balir"},it="identity"},{q="Why is Balir concerned about the troggs?",a="The Rockjaw troggs have recently surfaced in force, disrupting the peace of Coldridge Valley and attacking dwarven settlements. Balir recognizes them as an escalating menace that must be contained early.",al={"why troggs","trogg problem coldridge"},it="why_here"},{q="Is Balir related to Tannok Frosthammer?",a="Possibly. Balir shares the Frosthammer name with Tannok Frosthammer of Kharanos, suggesting a familial bond, though it is not confirmed.",al={"tannok relative","frosthammer family"},it="ties"},{q="Whose side is Balir Frosthammer on?",a="Balir stands firmly with Ironforge and the Alliance. Stationed in Coldridge Valley, he looks out for the safety of the dwarven homeland and works alongside fellow mountaineers and recruits to keep Dun Morogh secure against emerging dangers.",al={"balir frosthammer faction","who does balir serve","is balir alliance"},it="side",add="c02dfef8"},{q="What does Balir Frosthammer want?",a="Balir wants to drive back the Rockjaw troggs that have begun infesting the valley. Deeply alarmed by their sudden emergence and aggression, he enlists able-bodied adventurers to cull the invaders before they overrun Coldridge.",al={"balir frosthammer motive","what does balir need","why does balir need help"},it="wants",add="14c400d2"}},ang={["race:Dwarf"]="For young dwarves, Balir Frosthammer represents the frontline defense of their homeland, offering their very first opportunities to safeguard Dun Morogh from subterranean threats.",["faction:Alliance"]="Balir's efforts keep Coldridge Valley secure as a vital staging ground for Alliance recruits beginning their training in Khaz Modan."},kw={"a new threat","balir frosthammer","coldridge valley","dun morogh","rockjaw troggs","tannok frosthammer"},rel={"quest:170","subzone:coldridge-valley","zone:dunmorogh","npc:tannok-frosthammer","topic:trogg","topic:dwarf"},src={"Balir Frosthammer"}}
E["npc:beldin-steelgrill"] = {t="npc",n="Beldin Steelgrill",z="dunmorogh",s="Beldin Steelgrill is a renowned dwarven engineer and the master technician operating Steelgrill's Depot in Dun Morogh. Widely regarded as one of the finest siege engine mechanics in Khaz Modan, he oversees the maintenance of the Ironforge military's heavy armor and treaded warmachines. Keeping those massive contraptions running requires an endless supply of high-grade specialized tools.",h="Beldin Steelgrill is a renowned dwarven engineer and the master technician operating Steelgrill's Depot in...",sec={{t="Master of the Treaded Beast",b="Situated just down the road from Kharanos, Steelgrill's Depot serves as the primary proving ground and service station for dwarven steam tanks and siege engines. Beldin Steelgrill stands as its chief technician, celebrated far and wide for his unmatched expertise in repairing and tuning armored war wagons. Taming heavy metal and rumbling boilers is unforgiving work, and Beldin burns through gear rapidly. His constant demand for heavy wrenches, cutters, and precision instruments frequently pushes local ironworkers to their limits just to keep his workbench supplied.",sp=0}},faq={{q="Who is Beldin Steelgrill?",a="Beldin Steelgrill is a master dwarven mechanic and the proprietor of Steelgrill's Depot in Dun Morogh. He is famed throughout Khaz Modan as the preeminent technician for dwarven siege engines and war wagons.",al={"beldin steelgrill","who is beldin","tank mechanic dun morogh"},it="identity"},{q="What happens at Steelgrill's Depot?",a="Located just northeast of Kharanos, the depot functions as a busy maintenance and testing yard for the Alliance's steam tanks and heavy mechanized hardware.",al={"steelgrills depot","what is steelgrill depot","depot purpose"},it="why_here"},{q="Why does Beldin go through so many tools?",a="Servicing heavy armor plating, complex gears, and high-pressure steam boilers requires intense labor and specialized equipment. Beldin's heavy-handed work wears out tools at an astonishing pace, leading him to place demanding orders with nearby smiths.",al={"why does he need tools","steelgrill tools","tools for steelgrill"},it="wants"},{q="Whose side is Beldin Steelgrill on?",a="Beldin is loyal to the Bronzebeard clan of Ironforge and stands firmly with the Alliance. Working just down the road from Kharanos, he keeps the dwarven military and local defense forces outfitted with heavy mechanized armor and siege engines.",al={"beldin steelgrill faction","who does beldin serve","is beldin steelgrill alliance"},it="side",add="c08b01c8"},{q="Why is Beldin Steelgrill famous?",a="Beldin is renowned across Dun Morogh as the finest siege engine technician alive. His mastery over war machines and heavy mechanics gives him an unmatched reputation among dwarven engineers, though it also makes him notoriously demanding on local toolmakers.",al={"beldin steelgrill reputation","why is beldin known","greatest siege technician"},it="fame",add="940fd3ae"}},ang={["profession:Engineering"]="For engineers, Beldin represents the pinnacle of dwarven vehicular technology, offering a front-row view of the Alliance's most formidable mechanized war assets.",["race:Dwarf"]="Beldin's yard showcases the industrial might of Ironforge, proving that dwarven craftsmanship extends far beyond hand-held hammers and axes to devastating siege artillery."},kw={"beldin steelgrill","dun morogh","ironforge","kharanos","mechanic","siege engine","steam tank","steelgrill"},rel={"subzone:steelgrill-s-depot","quest:400","zone:dunmorogh","topic:dwarf"},src={"Beldin Steelgrill"}}
E["npc:bink"] = {t="npc",n="Bink",z="dunmorogh",s="Bink is a gnome mage trainer who resides within the Hall of Mysteries in Ironforge's Mystic Ward. Quick-witted and enthusiastic, she guides aspiring spellcasters through the intricacies of the arcane arts and connects them with prominent wizards across the Alliance.",h="Bink is a gnome mage trainer who resides within the Hall of Mysteries in Ironforge's Mystic Ward.",sec={{t="A Beacon in the Hall of Mysteries",b="Located in the Mystic Ward of Ironforge, Bink stands among the gathered scholars, priests, and arcanists in the Hall of Mysteries. Like many gnomes driven from Gnomeregan, she has adapted to life within the dwarven mountain stronghold, offering her keen intellect and knowledge of arcane craft to those learning the path of the mage. She is well connected to wizards across the Eastern Kingdoms and Kalimdor, regularly pointing promising apprentices toward greater mentors such as High Sorcerer Andromath in Stormwind or Tabetha in Dustwallow Marsh.",sp=0}},faq={{q="Who is Bink?",a="Bink is an Alliance gnome mage trainer stationed inside the Hall of Mysteries within the Mystic Ward of Ironforge. She teaches arcane spellcraft and serves as a mentor and contact for developing mages.",al={"bink lore","who is bink","bink ironforge"},it="identity"},{q="Where can I find Bink?",a="She can be found inside the Hall of Mysteries, which sits in the western wing of the Mystic Ward in the city of Ironforge.",al={"bink location","where is bink","find bink"},gp=true},{q="What quests involve Bink?",a="Developing mages are directed to her via quests like Speak with Bink. In turn, she directs mages toward further studies, sending them to authorities such as High Sorcerer Andromath in Stormwind Keep or the hermit mage Tabetha in Dustwallow Marsh.",al={"bink quests","speak with bink quest"},gp=true},{q="What does Bink say to non-mages?",a="If approached by someone who does not practice the arcane, she cheerfully offers some practical advice: 'Befriend a mage! We have a trick or two up our sleeves, we do...'",al={"bink gossip","bink dialogue"}},{q="Whose side is Bink on?",a="Bink stands firmly with the Alliance and the Gnomeregan Exiles sheltered within Ironforge. Operating out of the Hall of Mysteries alongside fellow scholars and sorcerers, she dedicates her magical talents to aiding her allies and instructing promising new mages who fight under the Alliance banner.",al={"bink faction","who does bink serve","bink alliance or horde"},it="side",add="cf09b30e"},{q="Why is Bink in the Hall of Mysteries?",a="Bink resides in Ironforge's Hall of Mysteries to serve as a gnome mage trainer. Following the fall of Gnomeregan, the displaced gnomes found refuge among the Bronzebeard dwarves, and Bink lends her arcane expertise to train aspiring mages and dispatch students on tasks vital to the arcane community.",al={"why is bink here","what is bink doing in ironforge","why is bink in ironforge"},it="why_here",add="d0de8b26"}},ang={["class:Mage"]="For Alliance mages visiting or based in Ironforge, Bink serves as a vital trainer and quest contact, dispatching students to study under powerful mentors across Azeroth.",["race:Gnome"]="Bink represents the continued pursuit of arcane mastery among exiled gnomes sheltering in the great halls of their dwarven allies."},kw={"andromath","bink","gnome","hall of mysteries","ironforge","mage trainer","mystic ward","tabetha"},rel={"subzone:hall-of-mysteries","subzone:mystic-ward","zone:ironforge","quest:1879","quest:1939","npc:tabetha","topic:gnome","zone:dunmorogh"},src={"Bink"}}
E["npc:branstock-khalder"] = {t="npc",n="Branstock Khalder",z="dunmorogh",s="Branstock Khalder is the priest trainer stationed at Anvilmar in Coldridge Valley. Friendly and grounded, he introduces novice dwarven priests to the Holy Light while keeping a watchful eye on the growing trogg threat outside.",h="Branstock Khalder is the priest trainer stationed at Anvilmar in Coldridge Valley.",sec={{t="A Guiding Hand in Coldridge",b="Inside the bustling hall of Anvilmar, Branstock Khalder serves as a patient mentor to aspiring priests embarking on their spiritual journey. An easy-going dwarf with a deep devotion to the Light, he helps new acolytes master their early prayers and sacred runes. While his primary duty is spiritual instruction, Branstock is acutely aware of the valley's mounting perils—most notably the aggressive trogg infestation menacing the local mountaineers. Once a novice demonstrates sufficient command of the Light, he directs them through Coldridge Pass to seek further guidance from his superior, Maxan Anvol, in Kharanos.",sp=0}},faq={{q="Who is Branstock Khalder?",a="Branstock Khalder is a dwarven priest trainer based in Anvilmar, the starter outpost of Coldridge Valley. He instructs fledgling priests in the ways of the Holy Light and offers spiritual counsel to defenders facing the valley's hardships.",al={"branstock lore","who is branstock","anvilmar priest trainer"},it="identity"},{q="Where does Branstock send his students next?",a="Once young priests have honed their early abilities and assisted with the troubles in Coldridge Valley, Branstock sends them through Coldridge Pass to Kharanos, directing them to his superior, Father Maxan Anvol.",al={"where do i go after branstock","branstock next quest","priest path from anvilmar"},it="next_step"},{q="What is Branstock concerned about in Coldridge Valley?",a="Beyond his spiritual duties, Branstock is deeply troubled by the recent trogg invasion creeping through Coldridge Valley, recognizing that the Light's power is urgently needed to mend wounds and bolster the valley's defenses.",al={"anvilmar problems","branstock worries","trogg threat coldridge"},it="danger"},{q="What does he say to non-priests?",a="Even if you walk another path, Branstock offers a piece of humble advice: never turn your back on the Light, reminding passersby that faith may well be the one thing that saves their lives someday.",al={"branstock quote","branstock gossip text"}},{q="Whose side is Branstock Khalder on?",a="Branstock stands firmly with Ironforge and the Alliance. As a priest of the Holy Light, he dedicates himself to nurturing novice dwarven and gnomish practitioners while safeguarding Coldridge Valley against outside threats.",al={"branstock khalder faction","who does branstock khalder serve","branstock khalder allegiance"},it="side",add="1c070136"},{q="What does Branstock Khalder want?",a="Branstock aims to instruct fledging acolytes in the ways of the Holy Light and ensure they possess the fortitude to survive outside Anvilmar. He also wants the local trogg menace subdued before it completely overwhelms Coldridge Valley.",al={"branstock khalder goals","what does branstock want","branstock khalder purpose"},it="wants",add="48c1936a"},{q="Why is Branstock Khalder in Coldridge Valley?",a="Branstock is stationed at Anvilmar to welcome newly awakened priests and train them in basic prayers and holy disciplines. From this quiet post, he prepares young initiates before directing them onward to Kharanos.",al={"why is branstock khalder here","branstock anvilmar purpose","why is branstock in anvilmar"},it="why_here",add="0b38c258"},{q="Who is Branstock Khalder tied to?",a="Branstock serves under Priest Maxan Anvol, his superior stationed further down the mountain in Kharanos. He also cooperates closely with local defenders like Sten Stoutarm to identify promising candidates among new recruits.",al={"branstock khalder connections","who does branstock report to","branstock khalder superior"},it="ties",add="15965ad4"}},ang={["class:Priest"]="For dwarven priests, Branstock Khalder is the very first spiritual guide you meet, deciphering your initial sacred rune and introducing you to the defensive and healing arts of the Holy Light.",["race:Dwarf"]="Branstock exemplifies the pragmatic, down-to-earth devotion typical of Ironforge dwarves, blending reverent faith in the Light with hearty resilience against the cold and local trogg incursions."},kw={"anvilmar","branstock","coldridge","dun morogh","khalder","light","priest","trainer"},rel={"subzone:anvilmar","subzone:coldridge-valley","npc:maxan-anvol","quest:5623","npc:sten-stoutarm","subzone:kharanos","subzone:coldridge-pass","topic:light"},src={"Branstock Khalder"}}
E["npc:bromos-grummner"] = {t="npc",n="Bromos Grummner",z="dunmorogh",s="Bromos Grummner is a dwarven paladin trainer stationed in Anvilmar within Coldridge Valley. He mentors fledgling dwarven holy warriors, preaching steadfast faith in the Holy Light and the vital bond between dwarves and humans in the Knights of the Silver Hand.",h="Bromos Grummner is a dwarven paladin trainer stationed in Anvilmar within Coldridge Valley.",sec={{t="A Beacon in Coldridge",b="Standing within the sturdy stone hall of Anvilmar, Bromos Grummner welcomes dwarven novices drawn to the discipline of the Holy Light. Confident and resolute, he instructs young paladins in martial rites and sacred invocations. Beyond the basic tenets of combat, Bromos emphasizes unity, reminding his pupils that the order of the Knights of the Silver Hand bridges the realms of Ironforge and the human kingdoms of the Alliance in righteous purpose.",sp=0}},faq={{q="Who is Bromos Grummner?",a="Bromos Grummner is the resident paladin trainer in Anvilmar, located in Coldridge Valley within Dun Morogh. He provides foundational training, spells, and spiritual guidance to new dwarven paladins.",al={"who is bromos","bromos grummner lore","anvilmar paladin trainer"},it="identity"},{q="What order does Bromos represent?",a="Bromos represents the Knights of the Silver Hand. He actively emphasizes the importance of the bond between humans and dwarves forged under the banner of the holy order.",al={"bromos silver hand","is bromos silver hand"},it="ties"},{q="What does he teach new recruits?",a="He instructs initiates in the basic combat arts and divine spells of the paladin class, tasking them with early trials to prove their dedication to the Light and readiness to protect Dun Morogh.",al={"bromos quests","what does bromos grummner do"}},{q="Whose side is Bromos Grummner on?",a="Bromos stands firmly with Ironforge and the Grand Alliance. As a devout member of the Knights of the Silver Hand, he places immense value on the enduring bond forged between dwarves and humans, believing their shared faith in the Holy Light is essential to holding their realms together.",al={"bromos grummner faction","bromos alliance","who does bromos fight for"},it="side",add="73c3e4de"},{q="Why is Bromos Grummner here in Coldridge Valley?",a="Bromos is stationed at Anvilmar to instruct novice dwarven paladins answering the call of the Holy Light. Amid the encroaching cold and local trogg threats, he ensures every aspiring defender learns to wield martial prowess and righteous blessings in service to their people.",al={"why is bromos in anvilmar","bromos grummner purpose","what is bromos doing here"},it="why_here",add="830a5136"},{q="What does Bromos Grummner want?",a="Bromos wants to foster a disciplined, unyielding generation of dwarven paladins. He aims to instill in his students not only mastery over the Light's holy powers, but also deep dedication to the sacred alliance between dwarves and humans within the Silver Hand.",al={"what does bromos want","bromos goals","bromos motive"},it="wants",add="33b2371f"}},ang={["class:Paladin"]="For dwarven paladins, Bromos serves as their very first spiritual mentor, introducing them to the sacred duties of the Silver Hand.",["race:Dwarf"]="Bromos embodies the enduring tradition of dwarven devotees of the Light who fight side-by-side with their human allies."},kw={"anvilmar","bromos","coldridge","dun morogh","grummner","paladin","silver hand","trainer"},rel={"subzone:anvilmar","zone:dunmorogh","topic:knights-of-the-silver-hand","topic:light","topic:dwarf","topic:alliance","quest:3107"},src={"Bromos Grummner"}}
E["npc:durnan-furcutter"] = {t="npc",n="Durnan Furcutter",z="dunmorogh",s="Durnan Furcutter is a dwarven clothier and leather merchant operating out of Anvilmar in Coldridge Valley. Standing just outside the local pub, he equips freshly trained dwarven and gnomish adventurers with lightweight attire suited to withstand the biting mountain chills.",h="Durnan Furcutter is a dwarven clothier and leather merchant operating out of Anvilmar in Coldridge Valley.",sec={{t="A Warm Stitch in the Cold",b="Anvilmar serves as the first proving ground for young dwarves and exiled gnomes, and not every warrior steps forth clad in heavy iron. Durnan Furcutter caters to scouts, rogues, and spellcasters who need light, pliable layers to stay agile without succumbing to the bitter winds of Dun Morogh. Positioned right near the hearth of Anvilmar, he sells everyday tailoring and stitched leather, claiming his stock is the finest to be found in the entire valley.",sp=0},{t="A Mug in Hand",b="Like any true dwarf stationed in the snowy foothills, Durnan appreciates a strong drink almost as much as an honest trade. He frequents Anvilmar's tavern and enjoys a steaming mug of Scalding Mornbrew to fight off the freezing draft. Adventurers running errands across the camp often find themselves delivering fresh brews directly into his welcoming hands or returning his empties to the barkeep.",sp=0}},faq={{q="Who is Durnan Furcutter?",a="Durnan Furcutter is a dwarven armor merchant stationed in Anvilmar within Coldridge Valley. He sells basic cloth and leather gear to novice adventurers starting their journeys in Dun Morogh.",al={"durnan","furcutter","who is durnan furcutter"},it="identity"},{q="Where can I find Durnan Furcutter?",a="He can be found standing outside near the entrance of Anvilmar's main hall in Coldridge Valley, close to the training masters and local tradesfolk.",al={"durnan location","where is durnan","anvilmar cloth vendor"},it="place",gp=true},{q="What does Durnan sell?",a="He offers an assortment of introductory cloth and leather armor pieces, catering to classes that rely on agility or spellcasting rather than heavy mail.",al={"durnan wares","what does durnan sell"},gp=true},{q="Why is he involved with Scalding Mornbrew deliveries?",a="Durnan works long hours in the icy coldridge winds and relies on warm pints of Scalding Mornbrew from the nearby inn to stay sharp and warm.",al={"durnan beer quest","scalding mornbrew durnan","durnan drink"},it="motive"},{q="Whose side is Durnan Furcutter on?",a="Durnan stands firmly with Ironforge and the Alliance. Stationed inside Anvilmar, he outfits the young dwarven and gnomish recruits who begin their journeys in Coldridge Valley.",al={"durnan faction","durnan furcutter alliance","who does durnan serve"},it="side",add="d97cf4a2"},{q="What does Durnan Furcutter want?",a="First and foremost, Durnan aims to ply his trade, boasting that he provides the finest cloth and leather garb this side of the valley. Beyond business, he never turns down a mug of steaming Scalding Mornbrew to fend off the biting chill of Coldridge Valley.",al={"what does durnan want","durnan furcutter goals","durnan purpose"},it="wants",add="afaf309b"},{q="Why is Durnan Furcutter in Anvilmar?",a="Anvilmar serves as the training hall and gathering hub for novitiates starting out in Coldridge Valley. Durnan remains here to supply fresh adventurers with essential garments and basic armor before they venture out into the snowy wilderness.",al={"why is durnan here","why is durnan in coldridge valley","durnan location why"},it="why_here",add="9750ade9"}},ang={["race:Dwarf"]="Durnan embodies the practical side of dwarven life in Coldridge Valley: sturdy craftwork, an appreciation for a hot brew, and friendly banter in the snow.",["profession:Tailoring"]="For fledging stitchers, vendors like Durnan represent the basic garments that keep scouts and apprentices alive in the snowy passes before mastercrafted cloth takes over."},kw={"anvilmar","cloth vendor","coldridge valley","dun morogh","durnan furcutter","leather vendor","scalding mornbrew"},rel={"subzone:anvilmar","subzone:coldridge-valley","zone:dunmorogh","quest:3364","quest:3365","quest:59","topic:dwarf"},src={"Durnan Furcutter"}}
E["npc:elder-goldwell"] = {t="npc",n="Elder Goldwell",z="dunmorogh",s="Elder Goldwell is an ancient earthen spirit lingering near the dwarven settlement of Kharanos in Dun Morogh. Appearing during the Lunar Festival, this revered ancestor represents the forgotten origins of modern dwarven civilization.",h="Elder Goldwell is an ancient earthen spirit lingering near the dwarven settlement of Kharanos in Dun Morogh.",sec={{t="A Spirit of the Earthen",b="Elder Goldwell manifests as a translucent earthen spirit, watching over the snowy slopes of Kharanos. Unlike modern mortal dwarves of flesh and bone, his stony form echoes the ancient Titan-forged race from which the Bronzebeard clan descended. His presence during ancestor celebrations offers travelers a chance to honor that ancient heritage.",sp=0}},faq={{q="Who is Elder Goldwell?",a="Elder Goldwell is an earthen ancestor spirit found in Dun Morogh. He visits Kharanos during seasonal ancestor observances so that modern travelers can pay their respects to the ancestors of dwarvenkind.",al={"elder goldwell identity","who is goldwell","goldwell lore"},it="identity"},{q="Where is Elder Goldwell located?",a="He can be found standing outside the dwarven town of Kharanos in Dun Morogh, usually near the local inn and gathering areas.",al={"elder goldwell location","where to find elder goldwell","find goldwell"},it="place",gp=true},{q="Why does Elder Goldwell look like an earthen rather than a dwarf?",a="Dwarves trace their ancestry back to the stone-skinned earthen created by the Titans. As one of the most ancient spirits honoring past generations, Goldwell retains the original earthen visage rather than the mortal flesh of living dwarves.",al={"why is goldwell earthen","is goldwell an earthen","goldwell rock dwarf"},it="origin"}},ang={["race:Dwarf"]="For dwarves, meeting Elder Goldwell offers a rare, direct look at their ancient stone-wrought heritage and the lineage connecting modern Ironforge to the earthen.",["faction:Alliance"]="Alliance travelers passing through Kharanos often seek out Goldwell to pay their respects and receive traditional blessings of good fortune."},kw={"ancestor","dun morogh","earthen","elder goldwell","goldwell","kharanos","lunar festival"},rel={"quest:8653","subzone:kharanos","zone:dunmorogh"},src={"Elder Goldwell"}}
E["npc:felix-whindlebolt"] = {t="npc",n="Felix Whindlebolt",z="dunmorogh",s="Felix Whindlebolt is a displaced gnome refugee taking shelter at Anvilmar in Coldridge Valley. In his haste to flee the radiation flooding Gnomeregan, he lost his personal belongings, and hostile Frostmane trolls made off with them.",h="Felix Whindlebolt is a displaced gnome refugee taking shelter at Anvilmar in Coldridge Valley.",sec={{t="A Displaced Traveler",b="Following the tragic fall of Gnomeregan, thousands of gnomes found themselves wandering the freezing reaches of Dun Morogh in search of safety. Felix Whindlebolt fled the irradiated city in such haste that he lost all his personal belongings and tools. To make matters worse, Frostmane ice trolls carried his chest, his box and his bucket of bolts back to their camps southwest of Anvilmar, leaving him stranded, destitute, and relying on sympathetic wanderers to retrieve his stolen gear.",sp=0}},faq={{q="Who is Felix Whindlebolt?",a="Felix Whindlebolt is a gnome refugee currently sheltered at Anvilmar in Coldridge Valley. He lost his belongings while fleeing Gnomeregan, and the local Frostmane trolls took them.",al={"who is felix","felix whindlebolt lore","gnome at whitebeard camp"},it="identity"},{q="Where was Felix trying to go?",a="Felix was fleeing the radiation that overran Gnomeregan after the gnomes' attempt to drive out the troggs went horribly wrong. He ended up at Anvilmar, the dwarven outpost in Coldridge Valley, though he finds the place poorly suited to a gnome.",al={"where was felix heading","felix destination","why is felix in coldridge valley"},it="why_here"},{q="What happened to his possessions?",a="In his haste to escape Gnomeregan, Felix lost his chest, his box and his bucket of bolts. The Frostmane ice trolls carried them off to their camps southwest of Anvilmar, leaving him stranded without supplies.",al={"who stole felix stuff","felix stolen gear","frostmane trolls felix"},it="wants"},{q="What does Felix sell to adventurers?",a="Nothing. Felix is no merchant: he lost all his belongings fleeing Gnomeregan, and all he can offer at Anvilmar is his thanks to anyone who recovers his chest, box and bucket of bolts.",al={"felix vendor items","what does felix offer","felix inventory"},gp=true},{q="Whose side is Felix Whindlebolt on?",a="Felix is aligned with the Gnomeregan Exiles and the Grand Alliance. Like many displaced gnomes, he fled the irradiated ruins of Gnomeregan and now shelters at Anvilmar in Coldridge Valley, hoping to rejoin his people.",al={"felix faction","is felix alliance","who does felix work for"},it="side",add="b1540142"}},ang={["race:Gnome"]="Felix represents the ongoing plight of your displaced kin, forced out into the unforgiving Dun Morogh cold after the catastrophe in Gnomeregan.",["race:Dwarf"]="The local Frostmane trolls have grown bolder throughout Coldridge Valley, striking at fragile gnome refugees wandering near Anvilmar."},kw={"anvilmar","coldridge valley","felix whindlebolt","frostmane","gnomeregan","refugee","whitebeard's encampment"},rel={"quest:3361","subzone:coldridge-valley","zone:dunmorogh","zone:gnomeregan","subzone:anvilmar","topic:gnome","topic:troll","topic:refugee"},src={"Felix Whindlebolt"}}
E["npc:foreman-stonebrow"] = {t="npc",n="Foreman Stonebrow",z="dunmorogh",s="Foreman Stonebrow is a dwarven overseer representing the Miners' League at Gol'Bolar Quarry in eastern Dun Morogh. After aggressive troggs erupted from the rock and overran the excavation site, he was forced to organize a defense and hire adventurers to clear the pits.",h="Foreman Stonebrow is a dwarven overseer representing the Miners' League at Gol'Bolar Quarry in eastern Dun...",sec={{t="The Crisis at Gol'Bolar",b="Foreman Stonebrow was charged with directing operations at Gol'Bolar Quarry, a key dwarven excavation nestled in the mountains east of Kharanos. When deep digging broke into hidden trogg burrows, subterranean beasts swarmed the pits and drove the miners from their equipment. Refusing to abandon the site entirely, Stonebrow remains at the rim of the quarry to enlist any able-bodied travelers willing to push the troggs back.",sp=0}},faq={{q="Who is Foreman Stonebrow?",a="Foreman Stonebrow is a dwarf affiliated with the Miners' League who oversees work at the Gol'Bolar Quarry in Dun Morogh. He coordinates operations and tries to keep the quarry secure.",al={"stonebrow","who is stonebrow","foreman stonebrow lore"},it="identity"},{q="Why is Foreman Stonebrow asking for help?",a="Excavations at Gol'Bolar Quarry inadvertently breached subterranean trogg caverns. Troggs swarmed the lower terraces, killing workers and forcing the surviving miners to retreat to the camp at the rim.",al={"gol bolar trogg problem","why need help","quarry quest"},it="wants"},{q="What is the Miners' League?",a="The Miners' League is a dwarven guild and trade organization centered in Ironforge that oversees mining expeditions, resource extraction, and quarry operations throughout Khaz Modan.",al={"miners league","what is miners league"},it="ties"},{q="Where can Foreman Stonebrow be found?",a="He is stationed at the rim camp overlooking Gol'Bolar Quarry, situated in the eastern hills of Dun Morogh, just off the road leading toward Loch Modan.",al={"stonebrow location","where is foreman stonebrow"},it="place",gp=true},{q="Whose side is Foreman Stonebrow on?",a="Foreman Stonebrow is loyal to the Miners' League and the dwarven kingdom of Ironforge, placing him firmly in the Alliance. He oversees civic excavation work in Dun Morogh and seeks Alliance adventurers to clear threats from Ironforge's mining operations.",al={"stonebrow faction","who does stonebrow serve","stonebrow alliance"},it="side",add="2635f3c5"},{q="Why is Foreman Stonebrow at Gol'Bolar Quarry?",a="Foreman Stonebrow was sent to Gol'Bolar Quarry to supervise excavation and resource extraction on behalf of the Miners' League. He remains stationed near the quarry pit to rally assistance and coordinate efforts to retake the site after a sudden trogg infestation overwhelmed the workforce.",al={"why is stonebrow here","stonebrow golbolar","what is stonebrow doing here"},it="why_here",add="c868fd05"}},ang={["race:Dwarf"]="For dwarves, the trogg invasion of Gol'Bolar Quarry is a direct blow to Ironforge's stone industry and a grim reminder of the ancient menaces lurking beneath their ancestral soil.",["profession:Mining"]="Miners have a professional stake in helping Stonebrow, as reclaiming the quarry's rich stone and ore deposits is vital to the guild operations of Khaz Modan."},kw={"dun morogh","foreman stonebrow","gol bolar","gol'bolar quarry","miners' league","stonebrow","troggs"},rel={"subzone:gol-bolar-quarry","quest:432","topic:trogg","topic:dwarf","zone:dunmorogh"},src={"Foreman Stonebrow"}}
E["npc:grelin-whitebeard"] = {t="npc",n="Grelin Whitebeard",z="dunmorogh",s="Grelin Whitebeard is a dwarven scout stationed in Coldridge Valley by royal decree to assess the Frostmane troll threat. Operating out of an isolated camp with a bumbling apprentice, he relies on rising adventurers to keep the trolls contained while Ironforge's attention remains consumed by the trogg crisis.",h="Grelin Whitebeard is a dwarven scout stationed in Coldridge Valley by royal decree to assess the Frostmane...",sec={{t="A Royal Mandate",b="Grelin Whitebeard and his brother Senir were dispatched to Coldridge Valley under direct orders from the Senate of Ironforge and King Magni Bronzebeard himself. Their mission was clear: assess and neutralize the threat posed by the native Frostmane trolls. With Ironforge's official military fully bogged down combating trogg outbreaks across Dun Morogh, the brothers were given very few resources to accomplish their task. Grelin had to establish an outpost in the snowy hills and look toward local recruits and passing initiates to carry out the necessary work.",sp=0},{t="Trouble in the South",b="From his camp, Grelin monitors the encroaching Frostmane tribe south of Coldridge Valley. The trolls have grown increasingly aggressive, staging bolder incursions outside their mountain caverns. During one such raid, a heavily painted brute named Grik'nir the Cold slipped into the unattended camp and made off with Grelin's field journal, containing his critical observations. Unwilling to fail the King, Grelin uses intrepid travelers to strike deep into the Frostmane caves, recover his stolen writings, and ensure his final intelligence reaches Senir in Kharanos.",sp=0}},faq={{q="Why is Grelin Whitebeard out here in the snow?",a="Grelin was officially commissioned by the Senate of Ironforge and King Magni Bronzebeard to investigate and quell the Frostmane troll threat in Coldridge Valley. Because the dwarven military is tied down fighting the trogg menace elsewhere, Grelin must rely on independent volunteers.",al={"why is grelin here","grelin whitebeard purpose","who is grelin whitebeard"},it="why_here"},{q="Who stole Grelin's journal?",a="A Frostmane troll named Grik'nir the Cold raided Grelin's camp while it was left unattended. Grelin only caught a glimpse of a heavily marked brute fleeing into the southern troll caves with his field notes.",al={"who stole the journal","stolen journal thief","grelin journal"}},{q="Who is Grelin's brother?",a="His brother is Senir Whitebeard, an operative stationed further down the mountain in the town of Kharanos. Grelin compiles his findings on troll movements into reports and sends trusted runners to deliver them directly to Senir.",al={"grelin brother","senir whitebeard","who is senir"},it="ties"},{q="Who is with Grelin at his camp?",a="Grelin shares his small encampment with an absent-minded dwarven apprentice, leaving him with little competent help until capable recruits arrive.",al={"whitebeard camp npcs","who is with grelin","grelin companions"}},{q="Why doesn't Ironforge send regular soldiers to help him?",a="Ironforge's defenders and Senate forces are almost entirely consumed by the widespread trogg infestations that have erupted across Dun Morogh. This leaves scouts like Grelin to solve regional threats using local recruits.",al={"why no dwarven army","where is the ironforge guard","why no soldiers"}},{q="What is Grelin's connection to Jona Ironstock?",a="Jona Ironstock is an old and trusted friend of Grelin. Stationed near the starting grounds of Coldridge Valley, Jona helps direct new dwarven and gnomish recruits toward Grelin's camp.",al={"grelin and jona","jona ironstock"},it="ties"},{q="Who is Grelin Whitebeard?",a="Grelin Whitebeard is an investigator sent into Coldridge Valley on behalf of the Ironforge Senate and King Magni Bronzebeard. Tasked with assessing the aggressive movements of the Frostmane trolls, he maintains a remote camp in the snowy valley, relying on fresh mountaineer recruits to push back the trolls while the main dwarven army is preoccupied elsewhere.",al={"who is grelin","grelin whitebeard lore","who is whitebeard"},it="identity",add="bc052fbe"},{q="Whose side is Grelin Whitebeard on?",a="Grelin is entirely loyal to the Kingdom of Ironforge and the Grand Alliance. He answers directly to the Senate of Ironforge and carries dispatches stamped by King Magni's own hand, working tirelessly to secure dwarven lands against external threats.",al={"grelin whitebeard faction","who does grelin work for","is grelin alliance"},it="side",add="d217c46a"},{q="What does Grelin Whitebeard want?",a="Grelin wants an expedient resolution to the Frostmane troll problem in southern Coldridge Valley. Because the dwarven guard is tied down fighting trogg incursions, he needs able-bodied adventurers to cull the aggressive trolls, recover his stolen journal from the troll leader Grik'nir, and deliver his finalized reconnaissance report to his brother in Kharanos.",al={"what is grelin trying to do","grelin whitebeard goal","what does grelin need"},it="wants",add="6d2fc414"}},ang={["race:Dwarf"]="Serving King Magni directly, Grelin represents the quiet, stubborn perseverance of Ironforge scouts holding Dun Morogh's borders together against mounting internal threats.",["race:Gnome"]="Fresh out of Gnomeregan's tragedy, gnome refugees passing through Coldridge Valley find Grelin working alongside a wandering gnome at his remote camp.",["faction:Alliance"]="Grelin's plight reveals just how thin the Alliance and Ironforge armies are stretched in Dun Morogh, forcing solitary scouts to wage quiet wars against troll enclaves."},kw={"coldridge valley","dun morogh","frostmane","grelin whitebeard","grik'nir","ironforge senate","senir whitebeard","the stolen journal"},rel={"subzone:coldridge-valley","npc:senir-whitebeard","quest:218","quest:182","quest:282","subzone:kharanos","zone:dunmorogh","topic:troll"},src={"Grelin Whitebeard"}}
E["npc:grif-wildheart"] = {t="npc",n="Grif Wildheart",z="dunmorogh",s="Grif Wildheart is a seasoned dwarven hunter trainer stationed outside the Thunderbrew Distillery in Kharanos. Renowned among the local mountaineers for his deep affinity with wildlife, he instructs budding marksmen in tracking, marksmanship, and the rites of beast taming. For young hunters emerging from Coldridge Valley, Grif provides the vital bridge between firing a rifle and walking alongside a loyal animal companion.",h="Grif Wildheart is a seasoned dwarven hunter trainer stationed outside the Thunderbrew Distillery in Kharanos.",sec={{t="A Life in the Wilds",b="While many Ironforge dwarves prefer the fiery warmth of a forge or the steady clink of pickaxes, Grif Wildheart has dedicated his life entirely to the frozen wilderness of Dun Morogh. Local mountaineers half-jokingly say he spends a bit too much time with four-legged beasts, but none dispute his mastery of the wild. Having spent years tracking across snowbound ridges alongside seasoned hunting companions, Grif possesses an intimate understanding of the natural predators that roam the crags.",sp=0},{t="The Way of the Beast",b="When young dwarf hunters finish their preliminary trials in Coldridge Valley, they are directed straight to Kharanos to seek Grif's guidance. While he sharpens their aim and teaches essential wilderness survival tricks, his true specialty lies in forging bonds between hunter and beast. Through a sequence of rigorous trials, Grif sends his pupils out into the freezing wastes with a taming rod to test their mettle against Dun Morogh's iconic predators: Large Crag Boars, Snow Leopards, and Ice Claw Bears.",sp=0},{t="Journey to the High Seat",b="Once a hunter demonstrates the will and composure needed to calm three distinct wild beasts, Grif's tutelage in Kharanos reaches its conclusion. Recognizing that a hunter must also learn to feed, discipline, and train their new ally, he sends his graduates up the mountainside to Ironforge. There, under the great vaulted roofs of the dwarven capital, novice hunters report to master beast trainers to learn the deeper art of caring for their permanent lifelong companion.",sp=0}},faq={{q="Who is Grif Wildheart?",a="Grif Wildheart is a dwarven hunter trainer located in Kharanos in Dun Morogh. He serves as the primary mentor for novice Alliance hunters learning their trade outside of Coldridge Valley.",al={"who is grif","grif wildheart identity","about grif"},it="identity"},{q="Where can I find Grif Wildheart?",a="He stands outside near the Thunderbrew Distillery in the village of Kharanos, along the snowy road connecting Coldridge Pass to Ironforge.",al={"grif wildheart location","where is grif","grif in kharanos"},gp=true},{q="What does Grif teach novice hunters?",a="Beyond offering general hunter abilities and ranged combat techniques, Grif guides young hunters through the trials of beast taming, teaching them to soothe and master wild boars, leopards, and bears.",al={"what does grif teach","grif hunter training","grif skills"},it="purpose",gp=true},{q="What beasts does Grif send hunters to tame?",a="Grif charges his students with tracking down and taming three specific creatures of Dun Morogh: a Large Crag Boar, a Snow Leopard, and an Ice Claw Bear.",al={"grif taming quests","which animals to tame dun morogh","taming the beast targets"},gp=true},{q="Where does Grif send hunters after completing their taming trials?",a="After proving their ability to tame wild animals, Grif directs hunters to travel into the city of Ironforge to consult with advanced beast trainers about feeding and commanding their pets.",al={"where after grif","training the beast next step","grif follow up quest"},it="next_step",gp=true},{q="What do the Ironforge mountaineers think of Grif?",a="The local Ironforge Mountaineers note that Grif spends a bit too much time in the company of animals rather than people, but they readily admit he knows the hunter's craft better than almost anyone.",al={"mountaineer opinion of grif","is grif respected","grif reputation"},it="ties"},{q="Whose side is Grif Wildheart on?",a="Grif Wildheart is firmly loyal to Ironforge and the Grand Alliance. He serves his people by mentoring young dwarven hunters in Kharanos, ensuring they have the discipline and survival skills needed to protect the mountain kingdom and its territories.",al={"grif wildheart faction","is grif alliance","grif wildheart loyalty"},it="side",add="5a030de6"},{q="What does Grif Wildheart want?",a="Grif is dedicated to passing on the craft of the wild. He wants aspiring hunters to master beast taming and wilderness survival, sending novitiates into the snows of Dun Morogh to learn respect, patience, and how to forge lifelong bonds with the creatures of the crags.",al={"grif wildheart goal","what does grif want","grif wildheart motive"},it="wants",add="a3b5e7f5"},{q="Why is Grif Wildheart in Kharanos?",a="Grif is stationed in Kharanos to train fresh recruits who venture down from Coldridge Valley. As a central crossroads in Dun Morogh, Kharanos is the ideal proving ground for young hunters ready to test their wits against the mountain's boars, leopards, and bears.",al={"why is grif here","grif wildheart dun morogh why","why is grif in kharanos"},it="why_here",add="20183458"}},ang={["class:Hunter"]="Grif is the essential mentor who initiates Alliance hunters into beast taming, offering the vital quests that allow you to bond with wild predators across Dun Morogh.",["race:Dwarf"]="Embodying the dwarven mountaineer tradition, Grif shows how a dwarf's rugged resilience makes them exceptionally suited for living side-by-side with wild mountain beasts.",["faction:Alliance"]="Stationed in Kharanos, Grif prepares Alliance scouts and sharpshooters to survive the harsh wilderness surrounding the mountain kingdom of Ironforge."},kw={"beast taming","dun morogh","grif wildheart","hunter trainer","kharanos","mountaineer","taming the beast","thunderbrew distillery"},rel={"subzone:kharanos","quest:6061","quest:6081","quest:6065","zone:dunmorogh","zone:ironforge","topic:dwarf","topic:alliance"},src={"Grif Wildheart"}}
E["npc:hands-springsprocket"] = {t="npc",n="Hands Springsprocket",z="dunmorogh",s="Hands Springsprocket is an industrious gnome stationed at the entrance of Coldridge Pass in Dun Morogh. He coordinates shipments between the secluded training grounds of Coldridge Valley and the town of Kharanos, though recent trogg incursions have severely hampered his efforts.",h="Hands Springsprocket is an industrious gnome stationed at the entrance of Coldridge Pass in Dun Morogh.",sec={{t="A Bottleneck in the Pass",b="Perched at the mouth of Coldridge Pass, Hands Springsprocket finds his regular supply runs thoroughly disrupted. He routinely delivers provisions to the Thunderbrew distillery and the inn in Kharanos, but hostile Rockjaw troggs have overrun the subterranean tunnel leading out of the valley. With trade and foot traffic halted by the beasts, Hands is forced to rely on capable travelers to carry essential crates through the dangerous mountain corridor.",sp=0}},faq={{q="Who is Hands Springsprocket?",a="He is an Alliance-aligned gnome stationed in Coldridge Valley just outside the entrance to Coldridge Pass, responsible for ferrying supplies to the lower reaches of Dun Morogh.",al={"who is hands springsprocket","hands springsprocket lore","who is this gnome"},it="identity"},{q="Why does he need help moving supplies?",a="The pass connecting Coldridge Valley to the rest of Dun Morogh has been infested by vicious Rockjaw troggs, making routine transport too hazardous without armed escorts or capable adventurers.",al={"why does hands need help","coldridge pass supplies","why are supplies stuck"},it="why_here"},{q="Where are his supplies destined?",a="He arranges regular shipments to Kharanos, including goods intended for Tannok Frosthammer and the local innkeepers who rely on regular provisions from across the snowy peaks.",al={"where do supplies go","hands supply route","who gets the crate"},it="target"},{q="Whose side is Hands Springsprocket on?",a="Hands is a loyal member of the Alliance and a friend to the dwarven folk of Dun Morogh. Like many gnomes displaced by the tragedy at Gnomeregan, he works closely alongside his Ironforge allies, handling logistics and deliveries to support local communities like Kharanos.",al={"hands springsprocket faction","is hands springsprocket alliance"},it="side",add="d7333ab8"},{q="What does Hands Springsprocket want?",a="Hands wants his deliveries safely shuttled through Coldridge Pass to Tannok Frosthammer at the Thunderbrew Distillery in Kharanos. The recent surge of hostile Rockjaw troggs throughout the tunnel has completely stalled his shipments, leaving him desperate for an adventurer willing to carry the crate through the danger.",al={"what does hands want","hands springsprocket goal"},it="wants",add="8576a218"},{q="Who is Hands Springsprocket tied to?",a="Hands regularly does business with Tannok Frosthammer, the innkeeper at the Thunderbrew Distillery in Kharanos. Whenever supplies are needed down in the lowlands, Hands coordinates the shipments through the pass, relying on travelers to help bridge the gap when the road turns hazardous.",al={"who does hands work with","hands springsprocket ties"},it="ties",add="d21580a2"}},ang={["race:Gnome"]="For gnomish refugees displaced from Gnomeregan, Hands represents the quiet determination of gnomes integrating into Dun Morogh's local trade and logistics alongside their dwarven allies.",["faction:Alliance"]="Hands keeps vital internal supply lines moving between the dwarven military recruits in Coldridge Valley and the settlements deeper within Dun Morogh."},kw={"coldridge pass","coldridge valley","dun morogh","hands springsprocket","kharanos","springsprocket","supplies to tannok"},rel={"subzone:coldridge-pass","subzone:coldridge-valley","quest:2160","subzone:kharanos","zone:dunmorogh","topic:trogg","topic:gnome","topic:alliance"},src={"Hands Springsprocket"}}
E["npc:hegnar-rumbleshot"] = {t="npc",n="Hegnar Rumbleshot",z="dunmorogh",s="Hegnar Rumbleshot is a dwarven gunsmith stationed along the snowy roadway leading from Coldridge Pass toward Kharanos. He maintains a busy shooting range and equips local hunters and mountaineers with firearms and ammunition.",h="Hegnar Rumbleshot is a dwarven gunsmith stationed along the snowy roadway leading from Coldridge Pass toward...",sec={{t="A Gunsmith on the Road",b="Set up at a small campsite between Coldridge Pass and Kharanos, Hegnar Rumbleshot caters to dwarven marksmen, travelers, and the local militia. His camp features a popular shooting range where mountain folk hone their aim against the wild beasts prowling Dun Morogh. Supplying so many eager shooters means Hegnar burns through munitions at a brisk pace, leaving him perpetually reliant on fresh shipments of ammunition from his supplier, the dwarf engineer Loslor Rudge.",sp=0}},faq={{q="Who is Hegnar Rumbleshot?",a="Hegnar Rumbleshot is a dwarven gunsmith who operates an outdoor target range and camp along the main path between Coldridge Pass and Kharanos.",al={"who is hegnar","hegnar rumbleshot npc","gunsmith in dun morogh"},it="identity"},{q="Where does Hegnar get his ammunition?",a="Hegnar relies on Loslor Rudge, a dwarf engineering supplier elsewhere in Dun Morogh, to manufacture and supply the ammunition needed to keep his shooting range running.",al={"hegnar supplier","who supplies rumbleshot","ammo for rumbleshot quest"},it="ties"},{q="What does Hegnar do for the local dwarves?",a="He outfits local hunters and militia members with firearms and shot, while providing a practice range for marksmen traveling through Dun Morogh.",al={"why is hegnar here","hegnar shooting range","rumbleshot role"},it="purpose"},{q="Whose side is Hegnar Rumbleshot on?",a="Hegnar is firmly loyal to Ironforge and the Alliance. Stationed along the mountain road, he equips Dun Morogh's local militia, defenders, and hunters with reliable firearms to keep the kingdom's snowy passes safe from encroaching threats.",al={"hegnar rumbleshot faction","is hegnar alliance","who does hegnar serve"},it="side",add="f158c8ab"},{q="What does Hegnar Rumbleshot want?",a="Hegnar needs a steady supply of ammunition to keep his workshop and practice range running. Because local marksmen and militia constantly train and restock at his camp, his supplies drain rapidly, requiring regular deliveries from his engineer partner, Loslor Rudge.",al={"what does hegnar need","hegnar rumbleshot goal","hegnar quest"},it="wants",add="932ff4bf"},{q="Why is Hegnar Rumbleshot here along the road?",a="He set up his camp and shooting range along the well-traveled road between Coldridge Pass and Kharanos. This ideal location allows him to furnish fresh recruits coming out of the valley as well as patrolmen defending the central snows of Dun Morogh.",al={"why is hegnar out here","hegnar camp location","why did hegnar set up camp"},it="why_here",add="3c40a283"}},ang={["class:Hunter"]="For marksmen heading out from Coldridge Valley into the wider snowy peaks of Dun Morogh, Hegnar provides essential shot, ammunition pouches, and spare firearms.",["race:Dwarf"]="Dwarves take pride in craftsmanship and marksmanship, making Hegnar's roadside practice range a natural gathering spot for travelers looking to test their triggers."},kw={"ammo","coldridge pass","dun morogh","gunsmith","hegnar rumbleshot","kharanos","shooting range"},rel={"quest:5541","npc:loslor-rudge","zone:dunmorogh","subzone:coldridge-pass","subzone:kharanos","topic:dwarf"},src={"Hegnar Rumbleshot"}}
E["npc:jordan-stilwell"] = {t="npc",n="Jordan Stilwell",z="dunmorogh",s="Jordan Stilwell is a skilled human weaponsmith stationed outside the snowy Gates of Ironforge in Dun Morogh. Though originally meant to become a paladin of the Holy Light, he followed his father's craft to become an artisan whose work serves paladins across the Alliance. He is best known for forging Verigan's Fist in honor of his old friend, Bosch Verigan.",h="Jordan Stilwell is a skilled human weaponsmith stationed outside the snowy Gates of Ironforge in Dun Morogh.",sec={{t="A Calling at the Anvil",b="Though Jordan Stilwell was expected to take holy vows and become a paladin within the Church of the Holy Light, he ultimately chose the way of the forge. He followed in his father's footsteps, taking up his father's enchanted smithing hammer. Jordan refined his craft under the tutelage of the dwarven blacksmith Bailor Stonehand. Despite setting aside the mantle of an anointed holy warrior, Jordan remains deeply faithful to the Light, dedicating his extraordinary craftsmanship to outfitting champions who fight in its name.",sp=0},{t="Flight from Silverpine",b="Long before setting up shop in the biting cold of Dun Morogh, Jordan served as a smith at the keep of Baron Silverlaine in Silverpine Forest. When Archmage Arugal unleashed the feral worgen upon the fortress, turning it into the cursed bastion known as Shadowfang Keep, Jordan managed to escape the bloodshed. Forced to abandon his forge and his former home, he eventually found refuge among the dwarves of Dun Morogh.",sp=0},{t="Forging Verigan's Fist",b="Jordan keeps his forge outdoors near the gates of Ironforge, favoring the brisk alpine air over the stifling heat of the Great Forge inside the mountain. When the Church of the Holy Light sends worthy paladins to him, Jordan tasks them with recovering rare materials from across the world to craft a legendary two-handed warhammer. Named Verigan's Fist in honor of his old friend Bosch Verigan, the weapon stands as a testament to the enduring bond between devoted faith and masterful steel.",sp=1}},faq={{q="Who is Jordan Stilwell?",a="Jordan Stilwell is a master human blacksmith found working outside the Gates of Ironforge in Dun Morogh. He crafts sacred armaments for paladins of the Church of the Holy Light, most notably the legendary warhammer Verigan's Fist.",al={"who is jordan stilwell","jordan stilwell lore","who is this blacksmith outside ironforge"},it="identity"},{q="Why does Jordan Stilwell work outside in the snow instead of inside Ironforge?",a="According to Duthorian Rall in Stormwind, Jordan prefers working in the crisp, cool mountain air of Dun Morogh rather than the stifling interior of the Great Forge within Ironforge.",al={"why is jordan outside ironforge","why work in dun morogh","why is he in the snow"},it="why_here"},{q="What is Jordan Stilwell's connection to Shadowfang Keep?",a="Jordan was once an armorer and blacksmith stationed at Baron Silverlaine's estate in Silverpine Forest. He managed to flee the keep before or during the disastrous uprising when Archmage Arugal and his feral worgen slaughtered the garrison and overtook the fortress.",al={"jordan stilwell shadowfang keep","jordan stilwell silverpine","did he live in pyrewood"}},{q="What is Verigan's Fist?",a="Verigan's Fist is a powerful two-handed holy hammer forged by Jordan Stilwell for Alliance paladins. It is named in honor of Jordan's old friend, Bosch Verigan.",al={"verigans fist","verigan hammer","who is verigan"}},{q="Who trained Jordan Stilwell in blacksmithing?",a="Jordan inherited his craft and an enchanted smithing hammer from his father, and went on to refine his expertise under the instruction of the dwarven blacksmith Bailor Stonehand.",al={"who trained jordan stilwell","jordan stilwell teacher","where did he learn smithing"},it="origin"},{q="Who is Jordan Stilwell's wife?",a="Jordan is married to Daphne Stilwell. Together, the couple has provided immense aid to the Church of the Holy Light over the years, and both are revered as deeply devout servants of the faith.",al={"jordan stilwell wife","daphne stilwell husband","daphne stilwell"},it="ties"},{q="Whose side is Jordan Stilwell on?",a="Jordan is steadfastly loyal to the Alliance and the Church of the Holy Light. Though he lives among the dwarves in Dun Morogh and plies his trade outside Ironforge, he remains deeply connected to Stormwind's paladins, dedicating his craft to arming the faithful against the darkness threatening the realm.",al={"jordan stilwell faction","is jordan stilwell alliance","jordan stilwell allegiance"},it="side",add="49deb919"},{q="What does Jordan Stilwell want?",a="Jordan seeks to honor his old friend Bosch Verigan by forging an extraordinary weapon for deserving paladins. To craft the holy warhammer Verigan's Fist, he requires rare materials gathered across Azeroth: refined ore, enchanted wood, and a gemstone infused with purity.",al={"what does jordan stilwell need","jordan stilwell goal","jordan stilwell purpose"},it="wants",add="4c63667e"},{q="Why is Jordan Stilwell famous?",a="Jordan is renowned as an exceptional weaponsmith whose devotion to the Holy Light matches his skill at the forge. Originally intended for the priesthood or paladinhood, he chose to follow in his father's footsteps, earning immense respect from the Knights of the Silver Hand for his ability to craft masterwork holy armaments.",al={"is jordan stilwell famous","jordan stilwell renown","why is jordan stilwell known"},it="fame",add="35033531"}},ang={["class:Paladin"]="Jordan Stilwell is a crucial figure in a paladin's early trials, tasking them with scouring Azeroth for rare components to forge their signature warhammer, Verigan's Fist.",["profession:Blacksmithing"]="Trained by the dwarf Bailor Stonehand and wielding an enchanted hammer inherited from his father, Jordan represents the pinnacle of mortal holy metalworking.",["faction:Alliance"]="Having fled the horrors of Arugal's worgen in Silverpine Forest, Jordan found sanctuary with the dwarves of Dun Morogh and now lends his craft directly to Alliance champions."},kw={"bailor stonehand","bosch verigan","daphne stilwell","dun morogh","ironforge","jordan stilwell","shadowfang keep","tome of valor","verigan's fist","verigans fist"},rel={"quest:1653","quest:1649","npc:duthorian-rall","npc:daphne-stilwell","npc:bailor-stonehand","zone:shadowfang","subzone:gates-of-ironforge","topic:church-of-the-holy-light"},src={"Jordan Stilwell"}}
E["npc:loslor-rudge"] = {t="npc",n="Loslor Rudge",z="dunmorogh",s="Loslor Rudge is an enterprising dwarven engineering supplier stationed at Steelgrill's Depot in Dun Morogh. He provides mechanical parts, tools, and munitions to tinkerers across the snowy mountain ridges, keeping critical connections open with gunsmiths like Hegnar Rumbleshot.",h="Loslor Rudge is an enterprising dwarven engineering supplier stationed at Steelgrill's Depot in Dun Morogh.",sec={{t="A Supplier in the Snow",b="Operating out of Steelgrill's Depot just down the road from Kharanos, Loslor Rudge keeps a steady inventory of engineering essentials—ranging from copper modulators and bronze tubing to blasting powder and spanners. Dun Morogh's harsh weather and sprawling tinker operations mean practical parts are constantly in demand, and Loslor prides himself on keeping the local gearheads supplied. However, the wilderness between outposts is treacherous; when a courier taking a shortcut near the Grizzled Den was chased away by wendigos, an essential shipment of ammunition meant for his valued client, gunsmith Hegnar Rumbleshot, was left behind in the snow.",sp=0}},faq={{q="Who is Loslor Rudge?",a="Loslor Rudge is a dwarven engineering supplier who runs his shop out of Steelgrill's Depot in Dun Morogh. He sells tinkering tools, parts, and munitions to adventurers and craftsmen throughout the region.",al={"loslor rudge","who is rudge","steelgrills depot engineer"},it="identity"},{q="What trouble does Loslor need help with?",a="He recently dispatched a courier to carry an ammunition shipment to the gunsmith Hegnar Rumbleshot. The courier took a shortcut past the Grizzled Den, ran afoul of wild wendigos, and fled, abandoning the crate in the snow. Loslor needs someone to recover the shipment before he loses his valued customer.",al={"ammo for rumbleshot quest","what does rudge want","rudge courier"},it="wants"},{q="Where is Steelgrill's Depot?",a="Steelgrill's Depot is a busy dwarven staging ground and machine workshop located just east of Kharanos along the main road toward Loch Modan.",al={"where is steelgrills depot","steelgrill location"},it="place",gp=true},{q="Who is Hegnar Rumbleshot?",a="Hegnar Rumbleshot is a dwarven gunsmith based out of a camp in Dun Morogh who depends on Loslor Rudge for fresh shipments of ammunition and mechanical components.",al={"who is hegnar","rumbleshot"},it="ties"},{q="Whose side is Loslor Rudge on?",a="Loslor Rudge is a loyal member of the Ironforge dwarven community and the Alliance. Based at Steelgrill's Depot, he conducts business directly supporting dwarven marksmen, crafters, and nearby settlements across Dun Morogh.",al={"loslor rudge faction","is loslor rudge alliance","who does loslor rudge serve"},it="side",add="774accc1"},{q="Why is Loslor Rudge at Steelgrill's Depot?",a="Loslor operates out of Steelgrill's Depot as an engineering supplier and merchant. The depot serves as a bustling hub of dwarven machinery, repair, and industry outside Ironforge, making it an ideal location for him to sell tinkers' parts, powder, and craft ammunition for regional gunsmiths.",al={"why is loslor rudge here","loslor rudge role steelgrill","why is loslor at the depot"},it="why_here",add="1a06e65e"}},ang={["profession:Engineering"]="Loslor stocks critical early crafting supplies—such as fluxes, blasting powders, tubes, and tinker's kits—making his post at the depot a convenient stop for any aspiring engineer traveling through Dun Morogh.",["race:Dwarf"]="Like many Dun Morogh artisans, Loslor's livelihood depends on reliable pack routes between the scattered dwarf camps, showing how even local predators like wendigos can disrupt mountain commerce."},kw={"ammo","dun morogh","engineering","grizzled den","hegnar rumbleshot","loslor rudge","steelgrill's depot"},rel={"subzone:steelgrill-s-depot","quest:5541","npc:hegnar-rumbleshot","subzone:grizzled-den","zone:dunmorogh","topic:dwarf"},src={"Loslor Rudge"}}
E["npc:magis-sparkmantle"] = {t="npc",n="Magis Sparkmantle",z="dunmorogh",s="Magis Sparkmantle is a gnome mage trainer stationed inside the Thunderbrew Distillery in Kharanos. He offers guidance and training to fledgling spellcasters who venture out from Coldridge Valley into the heart of Dun Morogh.",h="Magis Sparkmantle is a gnome mage trainer stationed inside the Thunderbrew Distillery in Kharanos.",sec={{t="A Spellcaster in the Distillery",b="While dwarves gather in the Thunderbrew Distillery for hearty ales, Magis Sparkmantle provides an arcane presence among the casks and kegs of Kharanos. Gnome mages often integrate closely with their dwarven allies across Dun Morogh, and Sparkmantle serves as a key mentor for novice spellcasters ready to expand their theoretical and practical grasp of the arcane arts.",sp=0},{t="Directing Young Arcanists",b="Beyond instructing novices in basic incantations, Magis ensures that promising students connect with broader magical circles. When mages outgrow early local instruction or require specialized guidance, Sparkmantle directs them further afield, sending them toward fellow practitioners like Bink or mentors stationed across the Alliance's primary hubs.",sp=0}},faq={{q="Who is Magis Sparkmantle?",a="Magis Sparkmantle is a gnome mage trainer residing in Kharanos, Dun Morogh. He instructs novice spellcasters in arcane fundamentals.",al={"magis sparkmantle","who is magis","kharanos mage trainer"},it="identity"},{q="Where can Magis Sparkmantle be found?",a="He can be found inside the Thunderbrew Distillery, the main inn and gathering hall of the town of Kharanos.",al={"magis location","where is magis","find sparkmantle"},it="place",gp=true},{q="Why is a gnome mage trainer staying in a dwarven distillery?",a="Following the fall of Gnomeregan, many gnomes settled among their dwarven cousins in Dun Morogh. The Thunderbrew Distillery acts as the central hub of Kharanos, making it an ideal post for mentoring wandering spellcasters.",al={"why in distillery","gnome in distillery","why thunderbrew distillery"},it="why_here"},{q="Does Magis Sparkmantle offer any quests?",a="Magis directs developing mages toward other arcane mentors as they advance, including sending practitioners to speak with Bink or report to instructors in human territories.",al={"sparkmantle quests","magis quests"},gp=true},{q="Whose side is Magis Sparkmantle on?",a="Magis Sparkmantle stands firmly with Gnomeregan and the Grand Alliance. Like many exiled gnomes who fled the catastrophe in their home city, he lives and works alongside Ironforge's dwarves, offering his arcane knowledge to the Alliance's defenders.",al={"magis sparkmantle faction","is magis alliance","who does sparkmantle serve"},it="side",add="1189c3a2"},{q="What does Magis Sparkmantle want?",a="Magis is dedicated to tutoring fledging mages in the arcane arts. While lodging at the distillery, he prepares novice spellcasters for the road ahead, instructing them in foundational magic before directing them toward senior masters like Jennea Cannon in Stormwind.",al={"what does magis want","magis sparkmantle goals","why train mages magis"},it="wants",add="e3e37731"},{q="Who is Magis Sparkmantle tied to?",a="As part of the wider network of Alliance mages, Magis maintains connections with fellow trainers across the realm, including Bink in the dwarven lands and Jennea Cannon in Stormwind's Mage Quarter, ensuring promising students find advanced instruction.",al={"magis sparkmantle allies","who is sparkmantle connected to","sparkmantle connections"},it="ties",add="318a77dd"}},ang={["class:Mage"]="For Alliance mages traversing Dun Morogh, Sparkmantle is an essential local contact for spell training and referrals to broader arcane networks.",["race:Gnome"]="Gnomes exiled from Gnomeregan often rely on mentors like Sparkmantle to keep their scholarly and arcane traditions flourishing while living among the dwarves."},kw={"dun morogh","gnome mage","kharanos","mage trainer","magis","magis sparkmantle","sparkmantle","thunderbrew distillery"},rel={"subzone:thunderbrew-distillery","subzone:kharanos","zone:dunmorogh","npc:bink","quest:1879","topic:gnome"},src={"Magis Sparkmantle"}}
E["npc:magni-bronzebeard"] = {t="npc",n="Magni Bronzebeard",z="dunmorogh",s="Magni Bronzebeard is the Lord of Ironforge, Thane of the Bronzebeard clan, and ruler of Khaz Modan. A peerless smith and veteran commander of the Second War, he leads his mountainous kingdom through grief and political tension while championing dwarven archaeology across Azeroth.",h="Magni Bronzebeard is the Lord of Ironforge, Thane of the Bronzebeard clan, and ruler of Khaz Modan.",sec={{t="Lord of the Mountain",b="The eldest of three brothers, Magni grew up keenly aware of the weight awaiting him under the mountain. When the Horde invaded during the Second War, he held Ironforge behind its impenetrable gates, emerging to pledge Khaz Modan to the Alliance of Lordaeron once the siege was broken. In the years of peace that followed, Magni welcomed his gnomish allies into the city after the fall of Gnomeregan, granting High Tinker Gelbin Mekkatorque and his refugees sanctuary within the mountain. To unite the fractured southern and northern kingdoms, Magni petitioned Mekkatorque to engineer an unprecedented subterranean marvel: the Deeprun Tram, connecting Ironforge directly to Stormwind.",sp=0},{t="A Hammer of Vengeance",b="Beneath Magni's regal bearing lies deep personal tragedy. During the Third War, word arrived from Northrend that Prince Arthas Menethil had betrayed and murdered Magni's beloved younger brother, Muradin. Overwhelmed by sorrow and wrath, Magni took up his hammer at the Great Anvil when High Inquisitor Fairbanks and Alexandros Mograine brought him a crystal of pure, radiant Light. Over three tireless days, the dwarven king poured all his grief, rage, and desire for vengeance into the metal. The resulting blade—the Ashbringer—stands as the greatest masterwork of his lifetime, forged to bring ruin to Arthas and the Scourge.",sp=0},{t="Excavating the Past",b="Under Magni's decree, dwarven society has turned much of its focus away from traditional commercial mining toward the unearthing of ancient history. Spurred by discoveries of strange titan relics deep beneath the earth, Magni co-founded the Explorers' League alongside his surviving brother, Brann Bronzebeard. Dwarven dig sites now dot the continents, from Dun Morogh to Kalimdor, striving to unlock the mystery of how the earthen became the modern dwarf. However, domestic peace remains fragile: Magni's daughter, Princess Moira, has gone missing, believed kidnapped by the hated Dark Iron clan.",sp=0}},faq={{q="Who is Magni Bronzebeard?",a="Magni Bronzebeard is the King of Khaz Modan, Thane of Ironforge, and chieftain of the Bronzebeard clan. He rules the mountain kingdom from the High Seat in Ironforge and is one of the staunch pillars of the Grand Alliance.",al={"king of ironforge","dwarf king","who is magni"}},{q="Who forged the Ashbringer?",a="King Magni forged the legendary sword himself at the Great Anvil in Ironforge. Alexandros Mograine and High Inquisitor Fairbanks brought him an enigmatic crystal of living Light, and Magni poured his grief and fury over Muradin's reported death into the blade over three days of nonstop smithing.",al={"did magni make ashbringer","ashbringer creator","who made the ashbringer"}},{q="What happened to Magni's brothers?",a="Magni is the eldest of three brothers. His brother Muradin served as an Alliance ambassador to Lordaeron and was reported killed by Prince Arthas in Northrend. His youngest brother, Brann, is a renowned explorer who travels the far corners of the world leading the Explorers' League.",al={"muradin and brann","magni brothers","muradin bronzebeard fate"}},{q="Where is Princess Moira?",a="Princess Moira Bronzebeard, Magni's only child, has disappeared from Ironforge. Official reports within the mountain hold that she was abducted by the antagonistic Dark Iron dwarves and is being held captive deep within Blackrock Mountain.",al={"magni daughter","where is moira","what happened to moira bronzebeard"}},{q="Why are gnomes living in Ironforge?",a="Following the trogg invasion and horrific irradiation of Gnomeregan, King Magni opened Ironforge's gates to High Tinker Gelbin Mekkatorque and the gnomish survivors. Magni granted them an entire district of the city, now known as Tinker Town.",al={"tinker town","why are gnomes in the dwarf city","gnome refugees ironforge"}},{q="What is the Explorers' League?",a="The Explorers' League is an archaeological organization founded by King Magni and his brother Brann. After discovering ancient titan ruins, Magni directed dwarven industries toward uncovering the truth behind their race's origins, sending survey teams across Azeroth.",al={"explorers guild","dwarf archaeologists","why are dwarves digging"}}},ang={["race:Dwarf"]="Magni is your undisputed sovereign and the protector of Khaz Modan, leading the Bronzebeard clan through external wars and the internal search for your race's earthen heritage.",["race:Gnome"]="King Magni offered his city as a refuge to the survivors of Gnomeregan, maintaining a close friendship and technological alliance with High Tinker Mekkatorque.",["faction:Alliance"]="A stalwart founder of the Grand Alliance alongside Lordaeron and Stormwind, Magni provides martial strength, engineering prowess, and steadfast loyalty to the coalition.",["profession:Blacksmithing"]="Magni is considered one of the greatest living smiths on Azeroth, having shaped the fabled Ashbringer from an otherworldly crystal at Ironforge's Great Anvil."},kw={"ashbringer","brann","bronzebeard","explorers league","ironforge","khaz modan","magni","moira","muradin"},rel={"zone:ironforge","topic:bronzebeard-clan","topic:dwarf","npc:gelbin-mekkatorque","topic:explorers-league","subzone:deeprun-tram","topic:arthas-menethil","topic:alliance"},src={"Magni Bronzebeard"}}
E["npc:marleth-barleybrew"] = {t="npc",n="Marleth Barleybrew",z="dunmorogh",s="Marleth Barleybrew is an ambitious dwarven brewer stationed out in Brewnall Village. Frustrated by the Thunderbrew clan's dominance over the local beer market, she constantly schemes to prove her family's brew is superior to Kharanos's famous Thunder Ale.",h="Marleth Barleybrew is an ambitious dwarven brewer stationed out in Brewnall Village.",sec={{t="The Brewing Rivalry",b="In Dun Morogh, alcohol is taken as seriously as steel, and the rivalry between the Barleybrew and Thunderbrew families is legendary. Marleth Barleybrew resents the near-monopoly that Ragnar Thunderbrew and his kin maintain out of the Thunderbrew Distillery in Kharanos. Convinced her own craft is every bit as robust, she seeks clever ways to slip Barleybrew kegs into the hands of tavern patrons. Rather than engaging in open conflict, she opts for petty subterfuge, recruiting passing travelers to secretly swap out Kharanos's prized ale casks with her own.",sp=0}},faq={{q="Who is Marleth Barleybrew?",a="Marleth is a dwarf brewmaster residing in Brewnall Village in western Dun Morogh. She represents the Barleybrew family and actively works to challenge the rival Thunderbrew family's stranglehold on the local drinking scene.",al={"who is marleth","marleth lore","marleth barleybrew"},it="identity"},{q="Where can I find Marleth Barleybrew?",a="She can be found in Brewnall Village, located in the western reaches of Dun Morogh near Iceflow Lake.",al={"marleth location","where is marleth","find marleth"},it="place",gp=true},{q="Why does Marleth want to swap Thunderbrew's beer?",a="Marleth believes her family's ale is just as good as, if not better than, Thunder Ale. Because the Thunderbrews dominate the trade in Kharanos, she hires adventurers to covertly replace the tavern's kegs with Barleybrew stock so drinkers will taste her product, while bringing back a sample of Thunder Ale for her to analyze.",al={"why swap the beer","bitter rivals quest reason","why hate thunderbrews"},it="wants"},{q="Who are the other members of the Barleybrew family?",a="Her extended clan includes other noted brewers and tradesmen such as Malgin, Rejold, Wellart, and Yorus Barleybrew, all dedicated to the craft of traditional dwarven brewing.",al={"barleybrew family","marleth relatives"},it="ties"},{q="Whose side is Marleth Barleybrew on?",a="Marleth is a proud Ironforge dwarf and loyal to the Alliance, though her immediate daily focus is entirely commercial. She belongs to the Barleybrew brewing family and fiercely champions their craft against their local rivals.",al={"marleth barleybrew allegiance","who does marleth barleybrew serve","marleth faction"},it="side",add="c401045b"},{q="Why is Marleth Barleybrew in Brewnall Village?",a="Brewnall Village serves as a regional brewing outpost in the snowy hills of Dun Morogh. Marleth operates from here to produce her craft beer and plot ways to break into the larger markets monopolized by the Thunderbrews.",al={"why is marleth here","marleth barleybrew brewnall village","why is marleth barleybrew in dun morogh"},it="why_here",add="716c9dd7"}},ang={["race:Dwarf"]="For dwarves, brewing is an art form tied intimately to clan prestige, making Marleth's feud with the Thunderbrews a matter of fierce family pride."},kw={"bitter rivals","brewnall village","dwarf brewer","kharanos","marleth barleybrew","thunder ale","thunderbrew"},rel={"subzone:brewnall-village","quest:310","quest:311","quest:308","subzone:thunderbrew-distillery","npc:ragnar-thunderbrew","subzone:kharanos","topic:dwarf"},src={"Marleth Barleybrew"}}
E["npc:marryk-nurribit"] = {t="npc",n="Marryk Nurribit",z="dunmorogh",s="Marryk Nurribit is the resident gnome mage trainer stationed at Anvilmar in Coldridge Valley. A bit more fond of local brews than disciplined pedagogy, he introduces fledgling gnomish arcanists to their craft while frequently soliciting spare coins for a drink.",h="Marryk Nurribit is the resident gnome mage trainer stationed at Anvilmar in Coldridge Valley.",sec={{t="Arcane Studies and Ale",b="Tucked away inside the warm hearth of Anvilmar, Marryk Nurribit offers arcane guidance to young gnomes taking their very first steps into magic. Though knowledgeable in the arcane arts, his demeanor is decidedly casual—often seeming far more interested in nursing a flagon of dwarven ale and bumming spare pocket change off his new pupils than drilling them in complex theorems. Despite his vices, Marryk remains acutely aware of the perils outside Coldridge Valley, regularly warning aspiring spellcasters about the lingering radioactive and trogg-infested horrors of fallen Gnomeregan.",sp=0}},faq={{q="Who is Marryk Nurribit?",a="Marryk Nurribit is a gnome mage trainer stationed inside Anvilmar in Dun Morogh's Coldridge Valley. He instructs newly arrived gnome mages in the fundamentals of arcane magic.",al={"marryk nurribit","who is marryk","anvilmar mage trainer"},it="identity"},{q="Why does Marryk keep asking for money for beer?",a="Marryk is known for enjoying local spirits far more than maintaining strict professional decorum. He regularly pesters his students for spare change to fund his drinking habits at the tavern.",al={"marryk drinking","marryk beer","why does he ask for coins"},it="wants"},{q="What does Marryk say about Gnomeregan?",a="Despite his relaxed attitude toward training, Marryk recognizes real danger and repeatedly cautions fresh mages against underestimating the perils lurking within the irradiated ruins of Gnomeregan.",al={"marryk gnomeregan","gnomeregan warning"}},{q="Whose side is Marryk Nurribit on?",a="Marryk is loyal to the Gnomeregan Exiles and stands squarely with the Alliance. Taking shelter alongside his dwarven hosts in Dun Morogh, he offers his arcane instruction to fledgling gnomes stepping forth into Coldridge Valley.",al={"marryk nurribit faction","who does marryk serve","marryk allegiance"},it="side",add="42f80152"},{q="Why is Marryk Nurribit in Anvilmar?",a="Following the tragic fall of Gnomeregan to the trogg infestation and toxic fallout, Marryk and his surviving kin fled into Dun Morogh. He now stays at Anvilmar in Coldridge Valley, nominally tasked with instructing novice gnome mages in the arcane arts.",al={"why is marryk here","marryk nurribit anvilmar","marryk purpose dun morogh"},it="why_here",add="241b0acf"}},ang={["class:Mage"]="For fledgling gnome mages beginning their journey in Coldridge Valley, Marryk is the first teacher you turn to for foundational spells and your Glyphic Memorandum.",["race:Gnome"]="Refugees taking shelter in Dun Morogh know Marryk as an example of a gnomish scholar who has adapted a bit too well to dwarven tavern hospitality."},kw={"anvilmar","beer","coldridge","gnome","mage","marryk","nurribit","trainer"},rel={"subzone:anvilmar","quest:3114","zone:dunmorogh","zone:gnomeregan","topic:gnome"},src={"Marryk Nurribit"}}
E["npc:maxan-anvol"] = {t="npc",n="Maxan Anvol",z="dunmorogh",s="Maxan Anvol is a dwarven priest trainer stationed within the Thunderbrew Distillery in Kharanos. Dedicated to the Holy Light, he guides fledgling dwarven priests as they learn to channel divine power amid Dun Morogh's frigid climes. He tests young acolytes to ensure they are worthy of wearing the vestments of the church.",h="Maxan Anvol is a dwarven priest trainer stationed within the Thunderbrew Distillery in Kharanos.",sec={{t="A Priest in the Pub",b="While it might seem strange to find an ordained minister of the Holy Light stationed inside Thunderbrew Distillery, it suits dwarven culture well. Kharanos serves as the primary hub between Coldridge Valley and Ironforge, and the local inn is where travelers, mountaineers, and acolytes naturally gather. Maxan tends to the spiritual welfare of the hamlet alongside pints of stout, offering prayers and counsel to any who step through the doors.",sp=0},{t="Testing the Faithful",b="Maxan Anvol is responsible for vetting novice priests before they venture into the wider world. He tasks initiates with demonstrating mastery over fundamental curative prayers on wounded defenders of Dun Morogh. Those who prove their devotion and practical competence are bestowed their first proper priestly vestments, formally marking their recognized standing within the Church of the Holy Light.",sp=0}},faq={{q="Where can I find Maxan Anvol?",a="Maxan Anvol is located inside the Thunderbrew Distillery, the main inn and gathering place in the town of Kharanos, nestled in the central snowdrifts of Dun Morogh.",al={"maxan anvol location","where is maxan","priest trainer kharanos"},it="place",gp=true},{q="What does Maxan Anvol teach?",a="He is a priest trainer who instructs novice and journeyman priests in spells of holy mending, shadow control, and divine protection. He also instructs dwarven priests in specialized supplications like Desperate Prayer.",al={"what does he train","maxan anvol spells"},it="purpose",gp=true},{q="Why is a holy priest hanging out in a distillery?",a="In dwarven society, life, communion, and celebration center around brewing and taverns. Thunderbrew Distillery functions as Kharanos's public forum, town hall, and traveler's rest. Maxan stays where he can reach common folk, guards, and passing travelers who need spiritual comfort.",al={"why distillery","priest in a bar"},it="why_here"},{q="Does Maxan Anvol offer any special tasks?",a="Yes. He tests aspiring priests with trials such as 'In Favor of the Light' and 'Garments of the Light,' sending them to heal injured mountaineers in the snow. Successfully completing these tasks earns the initiate their official acolyte robes.",al={"maxan quests","garments of the light"},gp=true},{q="What does he say to non-priests?",a="He warns other adventurers never to turn their back on the Holy Light, reminding them that divine grace might very well be the one thing that saves their life in battle some day.",al={"maxan dialogue","maxan quote"},gp=true},{q="Can gnomes learn from Maxan Anvol?",a="While gnomes as a culture do not naturally train as priests, Maxan is welcoming to all members of the Alliance who seek wisdom, training any priest who has pledged themselves to the Light.",al={"can gnomes talk to him","gnome priest trainer"},gp=true},{q="Who is Maxan Anvol?",a="Maxan Anvol is a dwarven priest of the Holy Light stationed in Kharanos. He serves as an instructor for fledgling devotees within Dun Morogh, testing young acolytes on their discipline and communion with the Light before granting them vestments fitting their station in the church.",al={"who is maxan","maxan anvol lore","priest trainer kharanos"},it="identity",add="32034ea0"},{q="Whose side is Maxan Anvol on?",a="He stands loyally with the Kingdom of Ironforge, the Holy Light, and the Grand Alliance. He dedicates his service to safeguarding the local populace of Dun Morogh and preparing new priests to uphold the faith across the Alliance's lands.",al={"maxan faction","is maxan alliance","maxan anvol allegiance"},it="side",add="310c3ecc"},{q="What does Maxan Anvol want?",a="Maxan seeks to foster devotion to the Holy Light and ensure novice priests are thoroughly prepared for the trials of the world. He tests aspiring students to ensure they are worthy of their sacred robes, while reminding all passersby never to abandon the Light's grace.",al={"maxan anvol goal","what does maxan want","maxan anvol motive"},it="wants",add="1141108e"}},ang={["class:Priest"]="Maxan serves as your early guide in Dun Morogh, granting you access to foundational holy discipline, teaching racial prayers like Desperate Prayer, and awarding your first formal church robes.",["race:Dwarf"]="Embodying the pragmatic piety of Ironforge, Maxan anchors dwarven faith where the people actually congregate: right alongside the ale kegs of Kharanos.",["faction:Alliance"]="Maxan tends to the physical and spiritual readiness of Alliance mountaineers and scouts guarding Dun Morogh from troggs, frost trolls, and wilderness beasts."},kw={"desperate prayer","dun morogh","garments of the light","holy light","kharanos","maxan anvol","priest trainer","thunderbrew distillery"},rel={"subzone:kharanos","subzone:thunderbrew-distillery","zone:dunmorogh","quest:5624","quest:5623","quest:5634","topic:light","topic:dwarf"},src={"Maxan Anvol"}}
E["npc:milli-featherwhistle"] = {t="npc",n="Milli Featherwhistle",z="dunmorogh",s="Milli Featherwhistle is a master gnomish mechanostrider engineer stationed at Steelgrill's Depot in Dun Morogh. Following the fall of Gnomeregan, she meticulously handcrafts and maintains the clockwork mounts favored by her kin. She sells her prized mechanical creations to fellow gnomes and trusted allies of the exiled Gnomeregan survivors.",h="Milli Featherwhistle is a master gnomish mechanostrider engineer stationed at Steelgrill's Depot in Dun...",sec={{t="Master of Mechanostriders",b="Operating outdoors in the biting chill of Steelgrill's Depot just east of Kharanos, Milli Featherwhistle oversees the supply of clockwork steeds for Gnomeregan's displaced populace. Unlike the biological beasts favored by dwarves and night elves, Milli builds her entire inventory herself, personally calibrating gears, pistons, and balancing gyros to ensure each mechanical bird runs at peak efficiency across the snowy crags of Dun Morogh.",sp=0},{t="Legacy of Mekkatorque",b="Every frame and spring in Milli's workshop is rooted in blueprints originally drafted by High Tinker Gelbin Mekkatorque. While Milli has integrated modern performance improvements over the years—streamlining chassis weights and refining exhaust vents—she faithfully adheres to the High Tinker's foundational schematics. Her mechanical wonders prove that even in exile, gnomish technological ambition remains thoroughly unbroken.",sp=0}},faq={{q="Who is Milli Featherwhistle?",a="Milli Featherwhistle is the primary mechanostrider breeder and engineer for the gnomes of Gnomeregan. Stationed at Steelgrill's Depot in Dun Morogh, she hand-builds and sells clockwork mechanostriders to eligible riders.",al={"milli featherwhistle","who is milli","mechanostrider vendor"},it="identity"},{q="Where can I find Milli Featherwhistle?",a="She is located at Steelgrill's Depot, an engineering outpost situated just a short walk east down the road from the town of Kharanos in Dun Morogh.",al={"milli location","where is milli featherwhistle","find milli"},it="place",gp=true},{q="Who is allowed to purchase mounts from her?",a="By default, only gnomish adventurers have the immediate clearance and aptitude to purchase her creations. Members of other Alliance races must earn the utmost trust and exalted status with the Gnomeregan Exiles before she will entrust them with a mechanostrider.",al={"can i buy a mechanostrider","mechanostrider requirements","who can ride mechanostriders"},gp=true},{q="How are mechanostriders made?",a="Milli Featherwhistle crafts each mechanostrider herself, basing her construction on the iconic blueprints drafted by High Tinker Gelbin Mekkatorque while implementing custom engine and balance enhancements.",al={"how mechanostriders are built","who makes mechanostriders","mechanostrider origins"}},{q="What mount varieties does she offer?",a="She provides several calibrated models, ranging from standard unpainted, blue, green, and red frames to finely tuned swift variants finished in white, green, and yellow coatings.",al={"milli mount colors","mechanostrider models","what mounts does milli sell"},gp=true},{q="Why is she working out in the snow at Steelgrill's Depot?",a="After the radioactive catastrophe and trogg invasion drove the gnomes from Gnomeregan, refugees gathered wherever they could. Steelgrill's Depot serves as a natural staging hub outside Kharanos for vehicular testing and mechanical maintenance alongside dwarven engineers.",al={"why is milli in dun morogh","why steelgrills depot"},it="why_here"},{q="Whose side is Milli Featherwhistle on?",a="Milli Featherwhistle is devoted to Gnomeregan and the Grand Alliance. Working out of Steelgrill's Depot alongside dwarven craftsmen, she provides mechanostriders directly to her fellow gnomes and trusted Alliance champions who have earned the full respect of the Gnomeregan Exiles.",al={"milli featherwhistle faction","who does milli featherwhistle serve","is milli alliance"},it="side",add="2267a2b3"},{q="What does Milli Featherwhistle want?",a="Milli wants to build and maintain the finest mechanostriders in Dun Morogh. Basing her creations on High Tinker Mekkatorque's original schematics, she continuously refines their engineering so reliable mechanized mounts remain readily available to gnome travelers and proven allies.",al={"what does milli featherwhistle do","milli featherwhistle goal","what is milli trying to do"},it="wants",add="f07f7c95"}},ang={["race:Gnome"]="Milli Featherwhistle is your people's premier mount engineer, carrying forward High Tinker Mekkatorque's technological genius even while exiled from your subterranean home.",["profession:Engineering"]="Milli's mechanostriders represent the pinnacle of large-scale gnomish locomotion, combining gyroscopic balance units with high-torque mechanical limbs.",["faction:Alliance"]="Alliance heroes who earn the utmost respect of the Gnomeregan Exiles can seek out Milli to command one of the swiftest mechanical mounts on Azeroth."},kw={"dun morogh","gnomeregan","kharanos","mechanostrider","mekkatorque","milli featherwhistle","mount vendor","steelgrill's depot"},rel={"subzone:steelgrill-s-depot","subzone:kharanos","zone:dunmorogh","zone:gnomeregan","npc:gelbin-mekkatorque","topic:gnome"},src={"Milli Featherwhistle"}}
E["npc:mountaineer-barleybrew"] = {t="npc",n="Mountaineer Barleybrew",z="dunmorogh",s="Mountaineer Barleybrew is an Ironforge mountaineer stationed at the South Gate Outpost in Dun Morogh. Guarding the pass leading eastward toward Loch Modan, he relies on hearty dwarven brews to keep sentries alert in the biting cold.",h="Mountaineer Barleybrew is an Ironforge mountaineer stationed at the South Gate Outpost in Dun Morogh.",sec={{t="A Watch on the Eastern Pass",b="Perched at the South Gate Outpost guarding the snowy roadway toward Loch Modan, Mountaineer Wellart Barleybrew stands as part of Ironforge's border watch. Like many mountaineers serving in the bitter winds of Dun Morogh, he appreciates the fortifying qualities of fine dwarven drink. Bearing the name of the renowned Barleybrew clan, he helps see to it that shipments of potent Shimmer Stout make their way to fellow watchmen who need warmth and stamina during long shifts along the mountain passes.",sp=0}},faq={{q="Where can I find Mountaineer Barleybrew?",a="Mountaineer Barleybrew is stationed at South Gate Outpost, the dwarven fortification guarding the eastern pass between Dun Morogh and Loch Modan.",al={"barleybrew location","where is mountaineer barleybrew","barleybrew npc"},it="place",gp=true},{q="What is his duty at South Gate Outpost?",a="He serves as a mountain sentry protecting the roadway and helps coordinate supplies, including Shimmer Stout for fellow mountaineers stationed throughout the passes.",al={"barleybrew purpose","what does barleybrew do"},it="purpose"},{q="Is he related to the other Barleybrews?",a="Yes. His brother is the brewer Rejold Barleybrew, and he may also be related to Marleth, Malgin, and Yorus Barleybrew.",al={"barleybrew family","yorus barleybrew relative"},it="ties"},{q="Who is Mountaineer Barleybrew?",a="Mountaineer Wellart Barleybrew is a dwarven sentry stationed to defend the eastern borders of Dun Morogh. Like all mountaineers of Ironforge, he stands vigilant against the beasts, troggs, and frost troll raiders that threaten the mountain roads, balancing his rigorous frontier duty with a distinct dwarven fondness for good ale.",al={"who is mountaineer barleybrew","who is barleybrew","mountaineer barleybrew lore"},it="identity",add="583559ff"},{q="Whose side is Mountaineer Barleybrew on?",a="He is a steadfast soldier of Ironforge and loyal to the Alliance. He follows the commands of the Bronzebeard clan and King Magni, ensuring the safety of travellers and key mountain passes across the realm.",al={"mountaineer barleybrew faction","who does barleybrew serve","is barleybrew alliance"},it="side",add="399d0350"},{q="What does Mountaineer Barleybrew want?",a="Beyond keeping the roadway secured from intruders, Mountaineer Barleybrew appreciates a hardy brew to cut through the freezing mountain air. He relies on passing travelers to courier word and supplies—including a draught of potent Shimmer Stout—between his station and nearby allies.",al={"barleybrew wants","what does wellart barleybrew need","what is barleybrew looking for"},it="wants",add="fc186c57"},{q="Why is Mountaineer Barleybrew here?",a="He is posted along the South Gate Outpost pass to guard the vital thoroughfare connecting Dun Morogh to Loch Modan. The high passes face regular peril from roving wildlife and aggressive trogg warbands, requiring disciplined mountaineers to keep the gates fortified and secure.",al={"why is barleybrew at south gate","why is mountaineer barleybrew stationed here","barleybrew location why"},it="why_here",add="b2269341"}},ang={["race:Dwarf"]="For dwarves, Barleybrew embodies the essential balance of frontier duty and high-proof refreshment that keeps Khaz Modan secure."},kw={"barleybrew","dun morogh","mountaineer","shimmer stout","south gate outpost","wellart"},rel={"subzone:south-gate-outpost","quest:413","quest:414","npc:marleth-barleybrew","quest:1698","zone:dunmorogh","zone:lochmodan","topic:dwarf"},src={"Mountaineer Barleybrew"}}
E["npc:mountaineer-kadrell"] = {t="npc",n="Mountaineer Kadrell",z="dunmorogh",s="Mountaineer Kadrell is a stalwart dwarven sentry stationed across from the Stoutlager Inn in Thelsamar. Serving as a crucial liaison within the Loch Modan Mountaineers, he coordinates reconnaissance, supply deliveries, and border defense across the region.",h="Mountaineer Kadrell is a stalwart dwarven sentry stationed across from the Stoutlager Inn in Thelsamar.",sec={{t="The Sentry of Thelsamar",b="Standing watch in the bustling settlement of Thelsamar, Mountaineer Kadrell acts as an anchor for dwarven defenses throughout Loch Modan. While outposts on the valley's fringes face relentless pressure from troggs, gnolls, and native beasts, Kadrell remains at the center of town to organize reinforcements, relay orders, and assess incoming field reports from wandering scouts.",sp=0},{t="Keeping the Lines Open",b="Kadrell's duties frequently involve maintaining contact between Thelsamar and remote forward positions. Whether coordinating with Mountaineer Stormpike or sending adventurers to report to sentries like Mountaineer Rockgar, Kadrell ensures that the isolated outposts guarding the mountain passes receive vital supplies, reinforcements, and defensive intelligence.",sp=0}},faq={{q="Where can Mountaineer Kadrell be found?",a="Kadrell is stationed directly across the road from the Stoutlager Inn in the town of Thelsamar, located within the rolling hills of Loch Modan.",al={"kadrell location","where is kadrell","find kadrell"},it="place",gp=true},{q="What is Kadrell's role in Loch Modan?",a="He is a member of the dwarven Mountaineers tasked with liaising between Thelsamar's local leadership and the remote guard posts scattered across the region, coordinating patrols, supplies, and border reports.",al={"what does kadrell do","kadrell purpose","kadrell job"},it="purpose"},{q="Why do other mountaineers send runners to Kadrell?",a="Because of his central position right by the inn and main thoroughfare in Thelsamar, Kadrell serves as the hub for field dispatches, ensuring that urgent reports from distant scouts reach the settlement's defense network.",al={"report to kadrell","why report to kadrell"},it="motive"},{q="Who does Kadrell coordinate with?",a="Kadrell frequently works with other mountaineers in the field, including Mountaineer Stormpike and Mountaineer Rockgar, managing scouting updates and defense assignments against local threats.",al={"kadrell contacts","who does kadrell know"},it="allies"},{q="Who is Mountaineer Kadrell?",a="Mountaineer Kadrell is a dwarven defender stationed in Thelsamar. As a member of the Mountaineers, Ironforge's dedicated territorial guard, he helps oversee the defense of the Loch Modan region, organizing local scouting efforts and keeping supply lines and outposts secure.",al={"who is kadrell","mountaineer kadrell","kadrell identity"},it="identity",add="fc9aa592"},{q="Whose side is Mountaineer Kadrell on?",a="Kadrell stands firmly with the Kingdom of Ironforge and the Alliance. His duties place him in the service of King Magni Bronzebeard, working alongside fellow mountaineers, town marshals, and local dwarves to hold the borders of Khaz Modan against encroaching threats.",al={"kadrell faction","is kadrell alliance","kadrell loyalty"},it="side",add="24c7e32d"},{q="What does Mountaineer Kadrell want?",a="Kadrell wants to secure Thelsamar and the surrounding wilderness of Loch Modan. With local forces stretched thin, he looks for capable travelers to help quell roving gnoll packs, encroaching murlocs, and other pests menacing the roads and outlying guard stations.",al={"what does kadrell want","kadrell goal","kadrell objectives"},it="wants",add="b20d3f6b"},{q="Why is Mountaineer Kadrell in Thelsamar?",a="Kadrell is stationed directly across from the Stoutlager Inn to act as a central contact point in Thelsamar. Because the town is the primary hub of Loch Modan, remaining here allows him to receive reports from remote guard posts and dispatch travelers where help is needed most.",al={"why is kadrell in thelsamar","why is kadrell here","kadrell post"},it="why_here",add="56ea1ebe"},{q="Who is Mountaineer Kadrell tied to?",a="Kadrell is closely connected to the network of Ironforge Mountaineers patrolling the valley, including Mountaineer Stormpike and Mountaineer Rockgar. He coordinates with outpost scouts across Loch Modan to channel information and reinforcements wherever border stations come under pressure.",al={"kadrell connections","who does kadrell work with","kadrell ties"},it="ties",add="f9923f59"}},ang={["faction:Alliance"]="Kadrell relies on Alliance travelers passing through Thelsamar to carry messages and lend a hand to distant mountaineer outposts struggling against regional threats.",["race:Dwarf"]="As part of the renowned Mountaineer corps, Kadrell represents the frontline watch that keeps Ironforge's eastern territories safe from encroaching wilderness dangers."},kw={"kadrell","loch modan","mountaineer","rockgar","stormpike","stoutlager inn","thelsamar"},rel={"subzone:thelsamar","zone:lochmodan","subzone:stoutlager-inn","quest:414","quest:468","npc:mountaineer-stormpike","quest:1339","quest:467"},src={"Mountaineer Kadrell"}}
E["npc:mountaineer-thalos"] = {t="npc",n="Mountaineer Thalos",z="dunmorogh",s="Mountaineer Thalos is a dwarven sentry stationed at the Coldridge Valley mouth of Coldridge Pass. Tasked with guarding the route, he warns travelers about the sudden trogg infestation choking the tunnel. Adventurers carrying urgent reports from the valley rely on him to point the way safely toward Kharanos.",h="Mountaineer Thalos is a dwarven sentry stationed at the Coldridge Valley mouth of Coldridge Pass.",sec={{t="Guardian of Coldridge Pass",b="Perched on the snowy border where Coldridge Valley gives way to the deeper crags of Dun Morogh, Mountaineer Thalos serves as the first line of defense for travelers leaving the dwarven training grounds. Coldridge Pass has become a treacherous chokepoint overrun by hostile troggs who have burrowed up from the subterranean depths. Thalos stands vigil in the cold, warning the unready to turn back and assessing whether hardy couriers possess the grit to fight their way through to the wider kingdom.",sp=0},{t="A Courier's Checkpoint",b="When Grelin Whitebeard finishes his report on the Frostmane troll movements within the secluded valley, the courier carrying it to his brother Senir in Kharanos is told to speak with Mountaineer Thalos before entering the tunnel. After verifying that an adventurer is capable of braving the infested passage, Thalos directs them onward to Kharanos, where regional commanders coordinate Dun Morogh's defense. His watchful presence ensures that vital intelligence reaches Ironforge's military leaders rather than dying in the snow.",sp=0}},faq={{q="Who is Mountaineer Thalos?",a="Mountaineer Thalos is an Ironforge mountaineer stationed at the southern opening of Coldridge Pass. His post guards the threshold between Coldridge Valley and the broader expanses of Dun Morogh.",al={"thalos lore","who is thalos","mountaineer thalos"},it="identity"},{q="Why is Mountaineer Thalos warning travelers away?",a="A vicious infestation of Rockjaw troggs has overrun Coldridge Pass. Thalos warns civilians and novice fighters against attempting the crossing, allowing only capable couriers and hardened fighters to venture inside.",al={"why is pass closed","troggs in pass","coldridge pass danger"},it="why_here"},{q="Where does Mountaineer Thalos send adventurers?",a="After reviewing urgent field reports arriving from Coldridge Valley, Thalos points travelers through the pass toward Kharanos, the nearest settlement on the road to Ironforge.",al={"where do i go after thalos","thalos destination","next town"},it="next_step"},{q="What report does Thalos receive from Senir Whitebeard?",a="None from Senir himself. The report that passes Thalos is Grelin Whitebeard's account of the Frostmane troll threat in Coldridge Valley, carried by a courier bound for Grelin's brother Senir in Kharanos. Thalos warns the messenger about the troggs and sends them on through the tunnel.",al={"senirs observations","senir dispatch","what does thalos read"}},{q="What faction does Mountaineer Thalos belong to?",a="Thalos is a sworn member of the Ironforge Mountaineers, the rugged frontier rangers tasked with patrolling Dun Morogh's borders, tunnels, and snow-swept mountain trails for the Alliance.",al={"thalos faction","is thalos ironforge","mountaineers alliance"},it="side"},{q="Is Coldridge Pass impassable without speaking to Thalos?",a="The pass is physically open to anyone daring enough to walk into it, but speaking to Thalos ensures an adventurer delivers vital reconnaissance to Kharanos and learns the hazards lying ahead.",al={"do i need to talk to thalos","bypass thalos"},gp=true},{q="What does Mountaineer Thalos want?",a="Mountaineer Thalos wants to keep travelers safe by warning them away from the treacherous Coldridge Pass. The tunnel has been overrun by hostile troggs, making passage dangerous for anyone unprepared. When he encounters adventurers with urgent business, he urges them to tread cautiously through the tunnel and carry Grelin Whitebeard's report safely onward to his brother Senir in the dwarven town of Kharanos.",al={"what does thalos want","thalos goal","mountaineer thalos purpose"},it="wants",add="37207617"},{q="Who is Mountaineer Thalos tied to?",a="Thalos serves as a sentry for the Ironforge mountaineers, guarding the pathway leading out of Coldridge Valley. Couriers carrying Grelin Whitebeard's report on the Frostmane trolls to Grelin's brother, Senir Whitebeard in Kharanos, are sent to speak with Thalos before braving the trogg-infested tunnel.",al={"thalos allies","who does thalos work with","thalos senir whitebeard"},it="ties",add="ae07b8df"}},ang={["race:Dwarf"]="For young dwarves leaving their homeland's nursery, Thalos is the solemn reminder that the trogg threat is no mere training drill, but a siege pressing hard against Ironforge's thresholds.",["race:Gnome"]="Gnomes traveling outward from Gnomeregan's refugee shelters find Thalos standing guard along the main overland route leading down toward Kharanos and Ironforge.",["faction:Alliance"]="Thalos maintains communication along the vital mountain conduit linking the valley's defensive forces with central Ironforge command."},kw={"coldridge pass","coldridge valley","dun morogh","ironforge mountaineer","kharanos","mountaineer thalos","senir whitebeard","troggs"},rel={"subzone:coldridge-pass","subzone:coldridge-valley","quest:282","subzone:kharanos","zone:dunmorogh","topic:trogg","topic:dwarf"},src={"Mountaineer Thalos"}}
E["npc:nori-pridedrift"] = {t="npc",n="Nori Pridedrift",z="dunmorogh",s="Nori Pridedrift is an enterprising dwarf peddling his piping-hot Scalding Mornbrew throughout snowy Coldridge Valley. He makes his living braving the cold to supply shivering mountaineers with their morning pick-me-up, often enlisting swift recruits to run deliveries while the drink remains steaming.",h="Nori Pridedrift is an enterprising dwarf peddling his piping-hot Scalding Mornbrew throughout snowy Coldridge...",sec={{t="A Steaming Cup in the Snow",b="Life in Coldridge Valley is harsh and bitterly cold, and nothing cuts through the chill quite like a draught of Scalding Mornbrew. Nori Pridedrift has carved out a living by brewing and distributing this hot, coffee-like morning drink across the frozen drifts. Because the brew must be consumed while still scalding to be fully appreciated, delivery is a race against the elements. Nori frequently recruits brisk couriers to sprint fresh draughts out to freezing sentries before the mountain air robs the brew of its heat. Just as important as the brew itself are his limited supplies of sturdy mugs, which he expects his runners to return promptly.",sp=0}},faq={{q="Who is Nori Pridedrift?",a="Nori Pridedrift is an enterprising dwarf peddler based in Coldridge Valley. He brews and sells Scalding Mornbrew, a hot, coffee-like beverage that keeps the local guards and miners warm.",al={"who is nori","nori pridedrift lore","scalding mornbrew vendor"},it="identity"},{q="What is Scalding Mornbrew?",a="Scalding Mornbrew is a specialty hot drink brewed by Nori Pridedrift. Similar to piping-hot coffee or spiced morning ale, it is deeply favored by valley locals for cutting through the bitter chill of Dun Morogh.",al={"scalding mornbrew","what drink does nori sell","mornbrew"},it="item"},{q="Why are deliveries so urgent?",a="The drink's entire appeal rests on it being piping hot. In the sub-zero mountain winds of Coldridge Valley, a cup loses its heat rapidly, forcing Nori's delivery runners to sprint to their thirsty customers.",al={"why rush the delivery","mornbrew delivery rush","why does the drink go cold"},it="motive"},{q="Why does Nori care so much about returning mugs?",a="Nori maintains a limited supply of drinking vessels in the valley. If customers wander off with his mugs or break them in the snowdrifts, his morning trade quickly grinds to a halt.",al={"why bring back the mug","nori's mugs","mug return"}},{q="Whose side is Nori Pridedrift on?",a="Nori stands squarely with the Ironforge dwarves and the Alliance. He is an independent local merchant operating out of Coldridge Valley, serving the mountaineers, trainees, and residents who defend and live in the valley.",al={"nori pridedrift faction","who does nori work for","nori pridedrift alliance"},it="side",add="ddac60d5"},{q="What does Nori Pridedrift want?",a="Nori wants to run a profitable brewing business in Coldridge Valley. His main concern is ensuring his signature Scalding Mornbrew reaches his thirsty customers while it is still piping hot, and making certain that every empty mug makes its way back to his inventory.",al={"nori pridedrift goal","what does nori want","nori motivations"},it="wants",add="26ccfe8e"},{q="Why is Nori Pridedrift here?",a="Nori wanders Coldridge Valley because that is where his thirsty patrons are. The harsh, freezing mountain climate makes his piping-hot morning drink especially popular with the local guards and trainees, providing him with a steady trade.",al={"why is nori in coldridge valley","why is nori here","nori pridedrift location"},it="why_here",add="10ad6fd1"}},ang={["race:Dwarf"]="Every dwarf understands the vital comfort of a strong drink in freezing weather, making Nori's piping Mornbrew a welcome sight on mountain watch posts.",["profession:Cooking"]="Culinary adventurers in Dun Morogh appreciate Nori's dedication to serving his specialty beverage piping hot despite the freezing ambient air."},kw={"brew","coldridge valley","dun morogh","dwarf","mornbrew mug","nori pridedrift","scalding mornbrew"},rel={"subzone:coldridge-valley","zone:dunmorogh","quest:3364","quest:3365","topic:dwarf"},src={"Nori Pridedrift"}}
E["npc:pilot-bellowfiz"] = {t="npc",n="Pilot Bellowfiz",z="dunmorogh",s="Pilot Bellowfiz, affectionately known as 'Fizzer,' is a dwarven driver stationed at Steelgrill's Depot in Dun Morogh. As a member of the Ironforge Siege Brigade, he is responsible for maintaining and fielding heavy dwarven war machines, specifically his own siege engine, Jetsteam.",h="Pilot Bellowfiz, affectionately known as 'Fizzer,' is a dwarven driver stationed at Steelgrill's Depot in Dun...",sec={{t="Master of the Jetsteam",b="Stationed just outside the bustling halls of Ironforge at Steelgrill's Depot, Pilot Bellowfiz represents the mechanical backbone of the dwarven military. Piloting the powerful siege engine known as Jetsteam, Bellowfiz spends his days tuning components, procuring essential parts, and keeping his machine battle-ready. Alongside his comrade Pilot Stonegear, Bellowfiz is constantly discussing vehicular designs, armor plating, and engine output, ensuring that the mountain kingdom's mechanized firepower remains unmatched across Khaz Modan.",sp=0}},faq={{q="Who is Pilot Bellowfiz?",a="Pilot Bellowfiz is a dwarf pilot serving in the Ironforge Siege Brigade. Located at Steelgrill's Depot in Dun Morogh, he maintains and operates heavy siege engines for the defense of Khaz Modan.",al={"pilot bellowfiz","fizzer","who is fizzer"},it="identity"},{q="What machine does Bellowfiz drive?",a="He pilots a dwarven siege engine named Jetsteam. He frequently works to stock it with replacement parts, specialized gear, and maintenance supplies to keep it running smoothly.",al={"bellowfiz tank","jetsteam","what siege engine does bellowfiz pilot"}},{q="Where can Pilot Bellowfiz be found?",a="You can find him stationed in the snow at Steelgrill's Depot, an engineering and staging yard just down the road east of Kharanos in Dun Morogh.",al={"bellowfiz location","where is pilot bellowfiz","find bellowfiz"},it="place",gp=true},{q="What does he do with Pilot Stonegear?",a="Bellowfiz and Pilot Stonegear are fellow drivers in the Siege Brigade. When not taking care of their vehicles, the two often banter and debate the fine points of siege engine design, armor, and mechanics.",al={"stonegear and bellowfiz","bellowfiz conversation"},it="ties"},{q="Whose side is Pilot Bellowfiz on?",a="Bellowfiz serves the Kingdom of Ironforge and the Grand Alliance as an active driver in the Ironforge Siege Brigade. His loyalties lie firmly with King Magni Bronzebeard and the dwarven defense forces safeguarding Dun Morogh.",al={"pilot bellowfiz faction","who does bellowfiz serve","is bellowfiz alliance"},it="side",add="8ff6759c"},{q="What does Pilot Bellowfiz want?",a="Bellowfiz focuses on keeping his siege tank, Jetsteam, battle-ready and fueled. He frequently relies on travelers to gather munitions and supplies—such as specialized gear and local dwarven spirits—to maintain both his warmachine and his spirits.",al={"what does bellowfiz need","pilot bellowfiz goals","why does bellowfiz need supplies"},it="wants",add="f1970f66"},{q="Why is Pilot Bellowfiz here at Steelgrill's Depot?",a="Steelgrill's Depot serves as the staging ground and proving yard for Ironforge's heavy armored vehicles. Bellowfiz is stationed here to tune, test, and stock his siege engine alongside fellow mechanics and drivers before deploying out into the snow.",al={"why is bellowfiz at steelgrills depot","why is pilot bellowfiz in dun morogh","bellowfiz purpose dun morogh"},it="why_here",add="53346562"}},ang={["profession:Engineering"]="For dwarven and gnomish tinkerers, Bellowfiz represents the pinnacle of practical field engineering—keeping high-powered siege engines functional in the freezing mountain weather.",["race:Dwarf"]="Bellowfiz embodies the pride of Ironforge's mechanized brigades, showcasing the engineering prowess and heavy firepower that safeguard Khaz Modan."},kw={"bellowfiz","dun morogh","fizzer","jetsteam","pilot bellowfiz","pilot stonegear","siege brigade","steelgrill's depot"},rel={"subzone:steelgrill-s-depot","npc:pilot-stonegear","quest:317","quest:318","quest:415","zone:dunmorogh","zone:ironforge","topic:dwarf"},src={"Pilot Bellowfiz"}}
E["npc:pilot-hammerfoot"] = {t="npc",n="Pilot Hammerfoot",z="dunmorogh",s="Pilot Hammerfoot is a dwarven siege engine pilot of the Ironforge Siege Brigade, stationed near the mountain passes connecting Dun Morogh and Loch Modan. Worried for a fellow pilot lost in the hills, he seeks willing adventurers to search for his friend. His presence highlights the dangers faced by dwarves along the high alpine ridges.",h="Pilot Hammerfoot is a dwarven siege engine pilot of the Ironforge Siege Brigade, stationed near the mountain...",sec={{t="Eyes in the Mountains",b="Ironforge's siege engines are the pride of its Siege Brigade, but driving them across harsh mountainous terrain carries extreme risk. Stationed at the North Gate Outpost overlooking the border between Dun Morogh and Loch Modan, Pilot Hammerfoot guards the pilots' engines and watches the mountain passes. When a pilot goes missing, finding him quickly becomes a priority, especially with savage beasts prowling the nearby hills.",sp=0},{t="Avenging a Comrade",b="Hammerfoot was close friends with Pilot Mori Hildelve, a fellow siege engine pilot who busted his engine on a steep hill while the two searched for a rare ore, then went on alone on foot. Upon learning that Hildelve was mauled to death by Mangeclaw, a huge ice claw bear, Hammerfoot's mission shifts from routine border watch to personal vengeance, demanding retribution against the beast responsible for his friend's death.",sp=1}},faq={{q="Who is Pilot Hammerfoot?",a="Pilot Hammerfoot is a dwarven siege engine pilot serving Ironforge. He is stationed at North Gate Outpost along the pass connecting Dun Morogh to Loch Modan, watching over the region's borders and his fellow pilots.",al={"hammerfoot lore","who is hammerfoot","pilot hammerfoot info"},it="identity"},{q="Where can Pilot Hammerfoot be found?",a="He is located at North Gate Outpost, situated along the mountain highway guarding the tunnel pass between Dun Morogh and Loch Modan.",al={"hammerfoot location","where is pilot hammerfoot","where is hammerfoot"},it="place",gp=true},{q="What happened to Hammerfoot's partner, Pilot Hildelve?",a="Pilot Mori Hildelve broke his siege engine on a steep hill while searching for rare ore and continued on foot. Hammerfoot has not heard from him and asks travelers to investigate.",al={"pilot morter fate","what happened to morter","morter death"},it="ties"},{q="Why is Hammerfoot worried about his partner?",a="Hammerfoot and Mori Hildelve are close friends and fellow Siege Brigade pilots. Hildelve has gone missing in dangerous mountain terrain, and Hammerfoot needs someone to discover what happened.",al={"pilot revenge why","why avenge morter","mangeclaw grudge"},it="wants"},{q="Whose side is Pilot Hammerfoot on?",a="Pilot Hammerfoot is a loyal dwarf of Ironforge and serves the Alliance. Stationed at the outpost guarding the pass between Dun Morogh and Loch Modan, he works to keep the mountaineers supplied and the local mountain passes clear of encroaching threats.",al={"hammerfoot faction","who does pilot hammerfoot serve","is hammerfoot alliance"},it="side",add="9955f46b"},{q="Why is Pilot Hammerfoot stationed here?",a="Hammerfoot guards the siege engines at North Gate Outpost near the pass between Dun Morogh and Loch Modan. He and Mori Hildelve came to the hills looking for rare ore, but Hildelve continued on foot after his engine broke down and has not returned.",al={"why is hammerfoot here","hammerfoot post","why is pilot hammerfoot at the outpost"},it="why_here",add="4a134edc"}},ang={["race:Dwarf"]="Hammerfoot embodies the fierce camaraderie of the Ironforge mountaineers, refusing to let a fallen brother's murder go unanswered.",["faction:Alliance"]="Aiding Hammerfoot secures vital reconnaissance outposts along the primary highway linking Dun Morogh and Loch Modan."},kw={"dun morogh","ironforge","loch modan","mangeclaw","morter","north gate outpost","pilot hammerfoot","troggs"},rel={"subzone:north-gate-outpost","quest:419","quest:417","zone:dunmorogh","zone:lochmodan","topic:dwarf","subzone:south-gate-outpost"},src={"Pilot Hammerfoot"}}
E["npc:pilot-stonegear"] = {t="npc",n="Pilot Stonegear",z="dunmorogh",s="Pilot Stonegear, nicknamed 'Stone', is a dwarf mechanic and driver in the Ironforge Siege Brigade stationed at Steelgrill's Depot. He operates the formidable siege engine known as Trollplow and works tirelessly to enhance its performance and armor. Adventurers traveling through Dun Morogh often help him secure rare materials to keep his war machine battle-ready.",h="Pilot Stonegear, nicknamed 'Stone', is a dwarf mechanic and driver in the Ironforge Siege Brigade stationed...",sec={{t="Master of the Trollplow",b="Stationed among the rumbling boilers and clanking tracks of Steelgrill's Depot, Pilot Stonegear serves Ironforge as a proud driver in the Siege Brigade. His pride and joy is Trollplow, a heavy siege tank built to smash through enemy lines. Stonegear takes his machine seriously—knowing that in the heat of battle, a driver's life depends entirely on the resilience of gears, plates, and steam pressure. He constantly seeks to fine-tune both Trollplow's combat efficiency and the everyday livability of its cramped cockpit.",sp=0},{t="Tinkering and Metallurgy",b="Like many dwarven and gnomish grease-monkeys at the depot, Stonegear is rarely content with factory specifications. He often spends off-duty hours debating engineering schematics with comrades like Pilot Bellowfiz and Pilot Hammerfoot. Whether chasing down rumors of exotic ores or tracking down volatile minerals to fuel enhanced plating and munitions, Stonegear relies on eager recruits to venture into the snowy wilderness and dangerous caves of Dun Morogh on supply runs.",sp=0}},faq={{q="Who is Pilot Stonegear?",a="Pilot Stonegear, often called 'Stone', is an Ironforge dwarf and member of the Ironforge Siege Brigade. He is stationed at Steelgrill's Depot in Dun Morogh, where he maintains and operates his siege engine, the Trollplow.",al={"pilot stonegear lore","who is stonegear","pilot stone"},it="identity"},{q="Where is Pilot Stonegear located?",a="Stonegear is located just outside Kharanos at Steelgrill's Depot in Dun Morogh, surrounded by siege tanks, spare parts, and fellow pilots.",al={"pilot stonegear location","where is stonegear","find stonegear"},it="place",gp=true},{q="What is the Trollplow?",a="The Trollplow is Pilot Stonegear's personal siege engine. He constantly works to upgrade its mechanical reliability, armor plating, and internal comfort so it can survive the brutal demands of front-line combat.",al={"what is trollplow","trollplow tank","stonegear's tank"},it="item"},{q="What does Stonegear need adventurers for?",a="Stonegear enlists travelers to scout nearby threats and collect rare minerals—such as incendicite ore—to help upgrade and maintain the Siege Brigade's heavy war machinery.",al={"pilot stonegear quests","why does stonegear have quests","stonegear's search"},it="wants"},{q="Who does Pilot Stonegear work with?",a="He serves in the Ironforge Siege Brigade alongside other renowned drivers like Pilot Bellowfiz and Pilot Hammerfoot, frequently debating mechanical upgrades and machine designs with them at the depot.",al={"stonegear friends","siege brigade pilots","bellowfiz and stonegear"},it="ties"},{q="What is the Ironforge Siege Brigade?",a="The Ironforge Siege Brigade is the mechanized armor division of the dwarven military. Operating steam tanks, siege engines, and heavy artillery, they provide armored support to defend Dun Morogh and project Ironforge's military might across Khaz Modan.",al={"ironforge siege brigade","siege brigade lore","dwarf tank brigade"},it="allies"},{q="Whose side is Pilot Stonegear on?",a="Pilot Stonegear serves Ironforge and the Alliance as a dedicated driver in the Ironforge Siege Brigade. Stationed at Steelgrill's Depot, his loyalty lies entirely with the dwarven kingdom, defending the snowy ridges of Dun Morogh and working to keep the city's heavy war machines tuned for any threat to his people.",al={"pilot stonegear faction","stonegear allegiance","who does pilot stonegear serve"},it="side",add="6ae24a1f"},{q="Why is Pilot Stonegear here at Steelgrill's Depot?",a="Stonegear is stationed at Steelgrill's Depot to test, maintain, and refine his siege engine, the Trollplow. Alongside fellow brigade drivers, he uses the depot's workshops to oversee repairs, talk shop about engine mechanics, and acquire the rare ores and minerals needed to improve his machine's resilience in the field.",al={"why is stonegear in dun morogh","why is pilot stonegear here","stonegear steelgrills depot"},it="why_here",add="5e3743ba"}},ang={["race:Dwarf"]="Stonegear exemplifies the dwarven love for heavy steel, roaring engines, and crushing mountain foes under massive iron treads.",["race:Gnome"]="Gnomes working alongside the Siege Brigade find a kindred spirit in Stonegear, who is always eager to tinker with experimental designs and optimize output.",["profession:Engineering"]="Engineers can appreciate Stonegear's dedication to field-modifying the Trollplow, balancing deadly combat performance with pilot ergonomics.",["profession:Mining"]="Miners provide the vital raw ores and volatile subterranean deposits Stonegear requires to forge reinforced plating and munitions."},kw={"dun morogh","ironforge siege brigade","pilot bellowfiz","pilot hammerfoot","pilot stonegear","siege engine","steelgrill's depot","stonegear","trollplow"},rel={"subzone:steelgrill-s-depot","npc:pilot-bellowfiz","npc:pilot-hammerfoot","zone:dunmorogh","zone:ironforge","quest:467","quest:466","quest:313"},src={"Pilot Stonegear"}}
E["npc:ragnar-thunderbrew"] = {t="npc",n="Ragnar Thunderbrew",z="dunmorogh",s="Ragnar Thunderbrew is a dwarven brewer and co-owner of the renowned Thunderbrew Distillery in Kharanos. Known across Dun Morogh for serving his family's signature Beer Basted Boar Ribs, he works constantly to keep the busy tavern stocked and its patrons satisfied.",h="Ragnar Thunderbrew is a dwarven brewer and co-owner of the renowned Thunderbrew Distillery in Kharanos.",sec={{t="A Pillar of Kharanos Hospitality",b="Standing inside the Thunderbrew Distillery at Kharanos, Ragnar Thunderbrew manages the establishment's culinary reputation alongside his family's brewing operations. The distillery is a central gathering place for local mountaineers, traveling adventurers, and gnome refugees fleeing Gnomeregan. Chief among his duties is preparing the family's renowned Beer Basted Boar Ribs, a hearty Dun Morogh specialty cooked with stout dwarven ale. However, maintaining steady supplies has become difficult; his usual meat provider enlisted in the King's Army, leaving Ragnar dependent on wandering mountaineers and hunters to keep fresh crag boar flanks coming into the kitchen.",sp=0},{t="The Thunderbrew Legacy",b="The Thunderbrew name is synonymous with dwarven alcohol and pub culture throughout Ironforge territory. Ragnar has kept the family distillery running since his older brother, Grimbooze Thunderbrew, disappeared in a drunken haze a few harvests ago, defending the family's fiercely guarded brewing heritage against rival operations like the Barleybrews. Between restless patrons, missing supply lines, and rowdy tavern disputes, Ragnar keeps a steady hand on the taps, ensuring no traveler departs Kharanos with an empty mug or an empty belly.",sp=0}},faq={{q="Who is Ragnar Thunderbrew?",a="Ragnar Thunderbrew is a dwarven brewer and part-owner of the Thunderbrew Distillery in Kharanos. He tends the tavern and handles the preparation of the clan's famous ale-basted boar ribs.",al={"who is ragnar","ragnar thunderbrew role","ragnar kharanos"},it="identity"},{q="Why is Ragnar looking for boar ribs?",a="Ragnar's regular meat supplier enlisted in King Magni's army, leaving the kitchen short on ingredients. To satisfy hungry patrons, he buys fresh flanks from passing hunters and travelers.",al={"why need boar meat","beer basted ribs quest","boar rib supply"},it="wants"},{q="How is Ragnar related to Grimbooze Thunderbrew?",a="Grimbooze is Ragnar's older brother. Their father, Arkilus, founded the Thunderbrew Distillery, and Ragnar has kept it running ever since Grimbooze disappeared in a drunken haze a few harvests ago.",al={"ragnar and grimbooze","grimbooze thunderbrew relation"},it="ties"},{q="Where is Ragnar Thunderbrew located?",a="Ragnar can be found inside the Thunderbrew Distillery in the village of Kharanos, nestled in the central snowy hills of Dun Morogh.",al={"ragnar location","where to find ragnar thunderbrew"},it="place",gp=true},{q="Whose side is Ragnar Thunderbrew on?",a="Ragnar stands firmly with Ironforge and the Grand Alliance. Operating out of Kharanos, he proudly caters to dwarven travelers, mountaineers, and local patrols who frequent the distillery.",al={"ragnar thunderbrew faction","ragnar alliance","is ragnar friendly to alliance"},it="side",add="a4e8a35c"},{q="Why is Ragnar Thunderbrew here in Kharanos?",a="Ragnar is in Kharanos to run the Thunderbrew Distillery. As co-owner, he works out of the local inn to brew dwarven ales, prepare hearty meals, and manage the family's busy trade in Dun Morogh.",al={"why is ragnar in kharanos","ragnar thunderbrew location motive","what does ragnar do in kharanos"},it="why_here",add="6e9b3705"},{q="Why is Ragnar Thunderbrew famous?",a="Ragnar is renowned for holding the secret family recipe for Beer Basted Boar Ribs, one of Dun Morogh's most famous and beloved dwarven culinary traditions.",al={"what is ragnar famous for","ragnar thunderbrew fame","why is thunderbrew famous"},it="fame",add="6804fc69"}},ang={["profession:Cooking"]="Ragnar is famous for the Thunderbrew family's Beer Basted Boar Ribs recipe, making him a worthwhile contact for aspiring cooks looking to master hearty dwarven pub dishes.",["race:Dwarf"]="For dwarves passing through Dun Morogh, Ragnar's tavern is a home away from home, showcasing the finest ale and rib cooking the clan has to offer."},kw={"ale","beer basted boar ribs","dun morogh","dwarf","grimbooze thunderbrew","kharanos","ragnar thunderbrew","thunderbrew distillery"},rel={"subzone:thunderbrew-distillery","subzone:kharanos","quest:384","npc:grimbooze-thunderbrew","zone:dunmorogh","topic:dwarf"},src={"Ragnar Thunderbrew"}}
E["npc:razzle-sprysprocket"] = {t="npc",n="Razzle Sprysprocket",z="dunmorogh",s="Razzle Sprysprocket is a gnomish engineer and pilot residing in Kharanos in Dun Morogh. Known for his technical tinkering alongside Ozzie Togglevolt, he enlists travelers to help salvage disrupted gnomish machinery and components around the snowy hills.",h="Razzle Sprysprocket is a gnomish engineer and pilot residing in Kharanos in Dun Morogh.",sec={{t="Tinkering in Kharanos",b="Following the tragedy at Gnomeregan, Razzle Sprysprocket found refuge among the snowdrifts of Dun Morogh, setting up his workshop in Kharanos. Renowned among his peers as a record-holding pilot with a knack for delicate mechanical parts, Razzle works alongside fellow engineer Ozzie Togglevolt. Their efforts frequently involve recovering gyro-mechanisms and cog assemblies that were lost or scavenged during the flight from their irradiated homeland.",sp=0},{t="Defense of the Workshop",b="Life in Dun Morogh is far from peaceful for a gnome inventor. Between the wild beasts of the frozen ridges and raids by local Frostmane trolls, Razzle's experiments have sometimes led to chaotic mishaps—such as mistaking ticking time bombs for standard explosive ordnance. Despite such engineering misadventures, he remains dedicated to keeping gnomish contraptions functional and recovering the lost wonders of Gnomeregan.",sp=0}},faq={{q="Who is Razzle Sprysprocket?",a="Razzle Sprysprocket is an eccentric gnome tinkerer and reputed record-holding pilot stationed in Kharanos within Dun Morogh, working alongside Ozzie Togglevolt.",al={"razzle sprysprocket","who is razzle","razzle kharanos"},it="identity"},{q="What does Razzle Sprysprocket need help with?",a="Razzle frequently requires adventurers to venture out into Dun Morogh to gather errant gizmos, cog assemblies, and parts to aid in the recombobulation of gnomish engineering projects.",al={"razzle quest","operation recombobulation help","what does razzle want"},it="wants"},{q="Where can I find Razzle Sprysprocket?",a="He can be found working outdoors near the tinker's post in Kharanos, just outside the inn and forge in central Dun Morogh.",al={"razzle location","where is razzle","razzle sprysprocket map"},it="place",gp=true},{q="Is Razzle Sprysprocket related to other Sprysprockets?",a="Razzle is believed to be closely related to Crazzle Sprysprocket, sporting an identical beard style, and has a cousin named Gimble, though he shares no close ties to Rizzle Sprysprocket.",al={"crazzle sprysprocket brother","sprysprocket family","razzle relatives"},it="ties"},{q="Whose side is Razzle Sprysprocket on?",a="Razzle Sprysprocket is aligned with Gnomeregan Exiles and the Alliance. Stationed in Kharanos alongside his fellow refugees, he works closely with other gnomish inventors like Ozzie Togglevolt to aid their displaced people in Dun Morogh.",al={"razzle sprysprocket faction","is razzle alliance","razzle sprysprocket allegiance"},it="side",add="b527298b"},{q="Why is Razzle Sprysprocket in Kharanos?",a="Like many gnomes, Razzle Sprysprocket took refuge in Kharanos following the tragic fall of Gnomeregan. Setting up shop in the snowy town, he continues his tinkerings and seeks materials to support ongoing gnomish recovery efforts.",al={"why is razzle here","razzle sprysprocket kharanos why","what brought razzle to kharanos"},it="why_here",add="fcfe3829"},{q="Why is Razzle Sprysprocket famous?",a="Razzle is celebrated among gnomes as a record-holding pilot. His aerial achievements have earned him quite a reputation, though in Kharanos you will mostly find him tinkering on the ground with explosives and machinery alongside fellow inventors.",al={"is razzle sprysprocket famous","razzle pilot record","what is razzle known for"},it="fame",add="56002c4d"}},ang={["race:Gnome"]="For exiled gnomes passing through Dun Morogh, Razzle represents the enduring inventive spirit and the determination to rebuild and recover after the fall of Gnomeregan.",["profession:Engineering"]="Engineers will find a kindred spirit in Razzle, whose projects highlight the fine line between brilliant gnomish invention and explosive miscalculation."},kw={"dun morogh","engineer","kharanos","ozzie togglevolt","pilot","razzle","recombobulation","sprysprocket"},rel={"subzone:kharanos","zone:dunmorogh","npc:ozzie-togglevolt","quest:412","topic:gnome","topic:troll"},src={"Razzle Sprysprocket"}}
E["npc:rejold-barleybrew"] = {t="npc",n="Rejold Barleybrew",z="dunmorogh",s="Rejold Barleybrew is a master dwarven brewer stationed in the lakeside settlement of Brewnall Village in western Dun Morogh. Devoted to perfecting hearty mountain spirits, he regularly enlists travelers to gather regional ingredients and test his potent recipes across the snowy valley.",h="Rejold Barleybrew is a master dwarven brewer stationed in the lakeside settlement of Brewnall Village in...",sec={{t="A Master of the Craft",b="In Dun Morogh, brewing is treated not merely as trade, but as a defining art form. Rejold Barleybrew embodies this tradition from Brewnall Village, an outpost nestled near the frozen lake of the Iceflow River. Rather than settling for common tavern swill, Rejold continually refines his blends, seeking rare hops, mountain minerals, and pristine ice water to produce stouts capable of warming the stoutest dwarven warriors.",sp=0},{t="The Search for the Perfect Stout",b="Rejold is relentless in his quest for ideal flavor profiles, sending adventurous spirits across Dun Morogh to collect vital components for drinks like Shimmer Stout. Whether trading favors with the siege pilots of Steelgrill's Depot or arranging deliveries to thirsty patrons, his work ensures that the cold, trogg-plagued roads of Dun Morogh remain tolerable with an ample supply of hearty ale.",sp=0}},faq={{q="Who is Rejold Barleybrew?",a="Rejold Barleybrew is a dwarven brewmaster residing in Brewnall Village in Dun Morogh. He is dedicated to concocting legendary dwarven ales and enlists passing adventurers to fetch ingredients and deliver experimental brews.",al={"rejold","who is rejold","rejold barleybrew info"},it="identity"},{q="Where can Rejold Barleybrew be found?",a="Rejold is located in Brewnall Village, situated in the western reaches of Dun Morogh beside the frozen waters of the Iceflow Basin.",al={"rejold location","where is rejold barleybrew","rejold barleybrew brewnall"},it="place",gp=true},{q="What is Rejold working on?",a="Rejold is working on perfecting potent mountain recipes, including his signature Shimmer Stout and new experimental ales, requiring cold mountain flora and special brewing components found across the snowy hills.",al={"rejold quest","perfect stout quest","what is rejold brewing"},it="wants"},{q="Why does Rejold send travelers to gnomes?",a="His errands actually tie him to fellow dwarves rather than gnomes: Pilot Bellowfiz of Steelgrill's Depot sends travelers to Rejold for a batch of Evershine, and Rejold's Shimmer Stout goes on to his brother, Mountaineer Barleybrew.",al={"rejold gnomes","rejold evershine","bellowfiz rejold"},it="motive"},{q="What is Shimmer Stout?",a="Shimmer Stout is a well-known, potent dwarven drink crafted by Rejold Barleybrew, brewed using unique mountain ingredients that give it a distinctive kick in the freezing winter climates.",al={"what is shimmer stout","shimmer stout lore"},it="item"},{q="Whose side is Rejold Barleybrew on?",a="Rejold is a proud Ironforge dwarf aligned firmly with the Alliance. Like many of his kin in Dun Morogh, he spends his days perfecting dwarven craft and serving travelers passing through Brewnall Village, maintaining friendly ties with fellow dwarves such as Pilot Bellowfiz of Steelgrill's Depot.",al={"rejold faction","rejold alliance or horde","is rejold barleybrew alliance"},it="side",add="86e90b5e"},{q="Why is Rejold Barleybrew here in Brewnall Village?",a="Rejold is stationed in Brewnall Village pursuing his life's passion: crafting the finest ales in Khaz Modan. Brewnall Village provides him access to fresh mountain water and local ingredients for his ambitious brews.",al={"why is rejold here","rejold brewnall village why","what brought rejold to brewnall"},it="why_here",add="ede674a2"}},ang={["race:Dwarf"]="For dwarves, Rejold represents the proud mountaineering tradition of brewing strong ales that provide warmth and strength against Khaz Modan's bitter winter chill.",["profession:Cooking"]="Culinary adventurers will appreciate Rejold's pursuit of pristine ingredients and precise recipes, treating the brewing process as an exact, venerable art.",["faction:Alliance"]="Rejold's supply of stout helps keep Alliance spirits high across Dun Morogh, strengthening guards and travelers who brave trogg raids and harsh blizzards."},kw={"ale","barleybrew","brewer","brewnall","dun morogh","rejold","shimmer stout","stout"},rel={"subzone:brewnall-village","quest:315","quest:413","quest:415","quest:318","quest:319","zone:dunmorogh","topic:dwarf"},src={"Rejold Barleybrew"}}
E["npc:sara-balloo"] = {t="npc",n="Sara Balloo",z="dunmorogh",s="Sara Balloo is a grieving dwarven widow residing in the Military Ward of Ironforge. She spends her days mourning her late husband, Sully Balloo, clinging to any remnant or message left behind from his final days in service.",h="Sara Balloo is a grieving dwarven widow residing in the Military Ward of Ironforge.",sec={{t="A Widow's Vigil",b="Standing within the bustling Military Ward of Ironforge, Sara Balloo presents a somber contrast to the clatter of weaponry and martial drills. Her husband, Sully Balloo, fell in battle far from home, leaving her alone with memories and lingering grief. For Sara, closure arrives only through recovered words—a final letter carrying Sully's devotion across the mountains from the scene of his demise.",sp=0},{t="A Cry for Remembrance",b="Unwilling to let her husband's sacrifice slip quietly into oblivion, Sara seeks more than mere solace. Through her heartfelt appeals, she petitions King Magni Bronzebeard to ensure that Sully and fallen soldiers like him are formally honored and remembered by the throne, ensuring the cost paid by ordinary dwarven families is never forgotten.",sp=1}},faq={{q="Who is Sara Balloo?",a="Sara Balloo is a dwarven woman living in the Military Ward of Ironforge. She is the widow of Sully Balloo, a fallen dwarven soldier.",al={"sara balloo","who is sara balloo","sara balloo ironforge"},it="identity"},{q="Where can I find Sara Balloo?",a="She can be found in the Military Ward of the mountain city of Ironforge, standing near the training grounds and barracks.",al={"where is sara balloo","sara balloo location","find sara balloo"},it="place",gp=true},{q="What happened to her husband?",a="Her husband, Sully Balloo, died during military service. His belongings and a final waterlogged letter were lost until an adventurer recovered them.",al={"sara balloo husband","who is sully balloo","what happened to sully"},sp=1,it="ties"},{q="What does Sara do with Sully's letter?",a="After reading her late husband's heartfelt words, Sara crafts a plea to King Magni Bronzebeard, asking for proper recognition and remembrance of Sully's sacrifice.",al={"sully balloo letter","sara balloos plea","what does sara balloo want"},sp=1,it="wants"},{q="Whose side is Sara Balloo on?",a="Sara Balloo is a loyal citizen of Ironforge and an adherent of the Alliance. Her late husband, Sully Balloo, died in service to the dwarven kingdom while his unit stood watch over the Thandol Span, and she remains among her people under King Magni Bronzebeard's rule.",al={"sara balloo faction","sara balloo alliance","who does sara balloo serve"},it="side",add="736253da"},{q="Why is Sara Balloo in the Military Ward?",a="Sara makes her home in Ironforge's Military Ward, living among the kingdom's soldiers and veterans. Having lost her husband Sully to war, she remains close to the civic and martial heart of the mountain city, where memories of those who fell defending the realm are honored.",al={"why is sara balloo in ironforge","why is sara balloo here","sara balloo military ward"},it="why_here",add="658d468d"}},ang={["race:Dwarf"]="For dwarves passing through the Military Ward, Sara Balloo is a poignant reminder of the personal toll borne by families whose kin march off to defend Khaz Modan.",["faction:Alliance"]="Delivering news to Sara brings closure to an Alliance soldier's family, highlighting the tragic domestic realities behind the battles fought across Azeroth."},kw={"dun morogh","ironforge","magni bronzebeard","military ward","sara balloo","sully balloo","widow"},rel={"quest:637","quest:683","zone:ironforge","subzone:military-ward","topic:dwarf","zone:dunmorogh"},src={"Sara Balloo"}}
E["npc:senator-mehr-stonehallow"] = {t="npc",n="Senator Mehr Stonehallow",z="dunmorogh",s="Senator Mehr Stonehallow is an Ironforge politician and member of the Explorers' League stationed at the Gol'Bolar Quarry in Dun Morogh. Rather than debating policy in the capital, he has traveled to the front lines to personally oversee the containment of the local trogg infestation. He enlists eager adventurers to cull the beasts before they overrun the quarry completely.",h="Senator Mehr Stonehallow is an Ironforge politician and member of the Explorers' League stationed at the...",sec={{t="A Politician in the Pits",b="While most members of the Ironforge Senate spend their days safely sequestered within the great stone halls of the capital, Senator Mehr Stonehallow prefers direct action. As a dwarf dedicated both to governance and the historical pursuits of the Explorers' League, he understands the practical dangers facing the realm. When vicious Rockjaw troggs began clawing out of the deep rock in Gol'Bolar Quarry, Stonehallow made the journey to the mining pit himself. Convinced that bureaucratic posturing will not save the workers, he offers bounties to capable travelers to eradicate the aggressive troggs and reclaim the quarry.",sp=0}},faq={{q="Who is Senator Mehr Stonehallow?",a="Senator Mehr Stonehallow is a dwarven statesman serving in the Ironforge Senate. Unlike many of his legislative peers, he takes an active hand in frontier matters and belongs to the Explorers' League. He can currently be found standing guard and organizing defense efforts at Gol'Bolar Quarry.",al={"stonehallow role","who is the senator","mehr stonehallow"},it="identity"},{q="Why is a senator stationed at Gol'Bolar Quarry?",a="Stonehallow traveled down into the quarry to take personal charge of the crisis unfolding there. The mining site was suddenly invaded by Rockjaw troggs burrowing up from beneath the earth, threatening both dwarven workers and valuable excavations, and Stonehallow refused to let the problem fester while waiting on distant bureaucrats.",al={"why is stonehallow here","why is he at the quarry","senator in dun morogh"},it="why_here"},{q="What does Senator Stonehallow want adventurers to do?",a="He hires newly arrived adventurers to cull the Rockjaw trogg population inside and around Gol'Bolar Quarry. By wiping out the troggs infesting the lower levels, recruits help secure the excavation site and safeguard the remaining miners.",al={"the public servant quest","stonehallow task","quarry quests"},it="wants"},{q="What organization does Stonehallow belong to besides the Senate?",a="Alongside his legislative duties in the Senate, Mehr Stonehallow is a member of the Explorers' League. This background fuels his interest in subterranean excavations and explains his willingness to venture far beyond the comforts of the capital.",al={"stonehallow faction","is stonehallow explorers league","stonehallow affiliation"},it="ties"},{q="Whose side is Senator Mehr Stonehallow on?",a="Senator Mehr Stonehallow stands firmly with the Kingdom of Ironforge and the Grand Alliance. As a sitting member of the Ironforge Senate and an active associate of the Explorers' League, his loyalties lie directly with King Magni Bronzebeard and the safety of the dwarven homeland.",al={"senator stonehallow faction","who does stonehallow serve","is stonehallow alliance"},it="side",add="67284ec7"}},ang={["race:Dwarf"]="For dwarves, seeing an elected senator standing knee-deep in quarry mud rather than sipping ale in the High Seat of Ironforge is a welcome demonstration of true dwarven grit.",["faction:Alliance"]="Stonehallow offers an early look at how dwarven leadership operates, providing young Alliance heroes with straightforward civic duty: slaying monsters to protect working citizens."},kw={"dun morogh","explorers' league","gol'bolar","ironforge senate","mehr","quarry","rockjaw","senator","stonehallow","trogg"},rel={"subzone:gol-bolar-quarry","quest:433","topic:explorers-league","topic:trogg","zone:dunmorogh","zone:ironforge","topic:dwarf"},src={"Senator Mehr Stonehallow"}}
E["npc:senir-whitebeard"] = {t="npc",n="Senir Whitebeard",z="dunmorogh",s="Senir Whitebeard is a dwarven dignitary and field agent stationed outside the Thunderbrew Distillery in Kharanos. Serving as a special envoy from the Senate of Ironforge, he is tasked with monitoring the growing threats encircling Dun Morogh. His mission centers on evaluating the Frostmane troll offensive and reporting their movements directly back to the dwarven leadership.",h="Senir Whitebeard is a dwarven dignitary and field agent stationed outside the Thunderbrew Distillery in...",sec={{t="Envoy of the Senate",b="While most travelers visit Kharanos for its bustling inn and famous stout, Senir Whitebeard is here on official business. As a representative sent directly by the Senate of Ironforge, his presence highlights how seriously the high halls take the destabilization of Dun Morogh. He serves as an essential bridge between local scouts facing danger on the snowy frontier and the legislators arguing policy behind the city's stone gates.",sp=0},{t="Eyes on the Frostmanes",b="Senir's primary concern is the escalating aggression of the Frostmane trolls. Displaced and desperate in the frozen crags, the trolls have begun pushing dangerously close to dwarven settlements and roads. Rather than charging into battle himself, the venerable envoy gathers reconnaissance on troll positions, particularly around their stronghold, compiling meticulous reports so Ironforge's military commanders can strike decisively.",sp=0}},faq={{q="Who is Senir Whitebeard?",a="Senir Whitebeard is an envoy sent by the Senate of Ironforge to Dun Morogh. He stands outside Kharanos gathering intelligence on regional threats, especially the local Frostmane troll tribes.",al={"who is this dwarf","senir whitebeard lore","who is senir"},it="identity"},{q="What is Senir doing in Kharanos?",a="Senir is stationed in Kharanos to observe troll activity and coordinate scout reports. Because Kharanos is the crossroad of Dun Morogh, it serves as the ideal hub to receive field intelligence before relaying it to the Senate in Ironforge.",al={"why is senir here","senir kharanos role","what does senir do"},it="why_here"},{q="Why does the Senate of Ironforge need an envoy here?",a="The Ironforge Senate requires reliable, firsthand field data to allocate resources and direct guards. Senir serves as an impartial official assessing whether the Frostmane threat warrants immediate military escalation from the capital.",al={"why envoy","ironforge senate kharanos","senate business"},it="ties"},{q="What is Senir's primary concern in Dun Morogh?",a="His chief focus is the Frostmane troll incursions. The trolls have been pushing aggressively out of their camps into dwarf territory, culminating in direct threats against nearby settlements like Kharanos.",al={"senir main problem","what threat is senir watching","senir trolls"},it="wants"},{q="Does Senir fight the trolls himself?",a="No, Senir functions as an administrator and intelligence gatherer. He depends on local scouts, Mountaineers, and passing adventurers to enter hostile sites like Frostmane Hold and retrieve critical reconnaissance for him.",al={"does senir fight","is senir a warrior","senir combat"}},{q="Where do Senir's reports go?",a="Once Senir has compiled field notes regarding troll positions and strengths, the finished reports are sent directly up the mountain road to the Senate and leadership in Ironforge.",al={"where do reports go","senir reports destination","who gets the reports"},it="purpose"},{q="Whose side is Senir Whitebeard on?",a="Senir Whitebeard serves the Kingdom of Ironforge and the Grand Alliance. Operating as an official envoy under the direct authority of the Senate of Ironforge, his loyalty lies entirely with the dwarven government and the defense of the realm's heartland.",al={"senir whitebeard allegiance","who does senir serve","senir faction"},it="side",add="40f66e19"}},ang={["race:Dwarf"]="For dwarves, Senir represents the bureaucratic yet essential connection between frontier defenders and the governing body in Ironforge.",["faction:Alliance"]="Alliance recruits passing through Dun Morogh aid Senir to safeguard the heartland of Ironforge from being cut off by indigenous troll uprisings."},kw={"dun morogh","frostmane","ironforge","kharanos","reports","senate","senir","whitebeard"},rel={"subzone:kharanos","zone:dunmorogh","zone:ironforge","topic:dwarf","quest:282","quest:287","quest:291"},src={"Senir Whitebeard"}}
E["npc:solm-hargrin"] = {t="npc",n="Solm Hargrin",z="dunmorogh",s="Solm Hargrin is the rogue trainer stationed within Anvilmar in Coldridge Valley. A pragmatic dwarf who values honor amongst thieves, he instructs novice dwarven and gnomish scoundrels in the art of subterfuge. He firmly believes that covert operatives will prove vital as geopolitical tensions simmer across Azeroth.",h="Solm Hargrin is the rogue trainer stationed within Anvilmar in Coldridge Valley.",sec={{t="A Mentor in the Shadows",b="Tucked away in the dwarven stronghold of Anvilmar, Solm Hargrin watches the snowy passes of Coldridge Valley with a keen, calculating eye. While Ironforge relies heavily on the brute strength of its mountaineers and warriors, Hargrin understands that some threats require a quieter, sharper touch. He welcomes budding rogues of both dwarven and gnomish heritage, deciphering coded missives for them and drilling them in essential techniques like Eviscerate. Above all, Hargrin champions a creed of professional loyalty and honor among thieves, preparing his pupils for an increasingly volatile world where subtle knives often shape the fate of nations.",sp=0}},faq={{q="Who is Solm Hargrin?",a="Solm Hargrin is a dwarven rogue trainer located in Anvilmar, the starter outpost in Dun Morogh's Coldridge Valley. He initiates young dwarves and gnomes into the covert arts of thievery, stealth, and bladecraft.",al={"who is solm","solm hargrin lore","anvilmar rogue trainer"},it="identity"},{q="What is Solm Hargrin's philosophy on rogue work?",a="Hargrin strongly believes in 'honor amongst thieves.' He teaches his recruits that while their methods may be underhanded, loyalty to their craft and to one another is essential, especially as fragile peace between rival powers threatens to break.",al={"solm beliefs","honor among thieves","solm view"}},{q="What quests does Solm Hargrin provide or receive?",a="Novice dwarven rogues are directed to him with an Encrypted Rune, while new gnomish rogues deliver an Encrypted Memorandum. Once he deciphers these introductory orders, he tasks trainees with mastering offensive maneuvers in the field.",al={"solm quests","encrypted rune solm","encrypted memorandum solm"},gp=true},{q="Does Solm Hargrin train races other than dwarves?",a="Yes. Following the fall of Gnomeregan, gnome refugees share the Coldridge Valley starting grounds with the dwarves. Solm gladly takes gnomish operatives under his wing alongside his dwarven kin.",al={"can gnomes train with solm","gnome rogue trainer anvilmar"},gp=true},{q="Whose side is Solm Hargrin on?",a="Solm Hargrin is loyal to Ironforge and the Alliance. Stationed in Coldridge Valley, he prepares fledgling operatives to defend dwarven lands, firmly believing that shadowy arts are essential tools for securing the realm amidst growing political unrest.",al={"solm hargrin faction","solm hargrin loyalty","is solm hargrin alliance"},it="side",add="3b6a2fc5"},{q="What does Solm Hargrin want?",a="Hargrin aims to instruct promising new rogues in the fundamentals of stealth, precision, and personal honor. Watching tensions escalate across the world, he believes practitioners of the subtle craft will soon play a vital role, and he wants his students properly honed and disciplined.",al={"solm hargrin goal","what does solm hargrin want","solm hargrin motive"},it="wants",add="7da5d6e5"},{q="Why is Solm Hargrin in Coldridge Valley?",a="He is stationed at Anvilmar to mentor newly arrived adventurers who walk the path of the shadows. As a trainer, he inspects encrypted missives sent by covert contacts and initiates young dwarves and gnomes into the art of silent combat.",al={"why is solm hargrin here","solm hargrin anvilmar purpose","why is solm hargrin in anvilmar"},it="why_here",add="d84d95b0"}},ang={["class:Rogue"]="For dwarves and gnomes taking their first steps into the shadows, Solm Hargrin provides foundational training and decrypts your very first guild orders.",["race:Dwarf"]="Solm represents a less conventional dwarven path, proving that stealth, cunning, and quiet steel have as much a place in Dun Morogh as heavy armor and axes."},kw={"anvilmar","coldridge valley","dun morogh","encrypted memorandum","encrypted rune","rogue trainer","solm hargrin"},rel={"subzone:anvilmar","zone:dunmorogh","quest:3109","quest:3113","topic:dwarf","topic:gnome"},src={"Solm Hargrin"}}
E["npc:sten-stoutarm"] = {t="npc",n="Sten Stoutarm",z="dunmorogh",s="Sten Stoutarm is a practical dwarven outfitter and courier stationed outside Anvilmar in Coldridge Valley. Responsible for keeping new recruits equipped and managing local dispatches, he helps ensure that novice mountaineers stay warm, fed, and informed despite the harsh mountain conditions.",h="Sten Stoutarm is a practical dwarven outfitter and courier stationed outside Anvilmar in Coldridge Valley.",sec={{t="A Helping Hand in the Snow",b="Positioned near the heart of Coldridge Valley, Sten Stoutarm is one of the first friendly faces new dwarven and gnomish recruits encounter outside Anvilmar's tavern. With the valley isolated by winter blizzards and encroaching dangers, Sten takes it upon himself to outfit green apprentices with sturdy gear before they freeze or wander unprepared into the drifts.",sp=0},{t="Keeping the Lines Open",b="Beyond assembling winter outfitting from local wolf hides, Sten serves as an informal postmaster for Coldridge Valley. He handles messages passed through the treacherous Coldridge Pass and distributes official runes, memoranda, and orders to class trainers throughout the basin, ensuring novice warriors, priests, and mages get their instructions despite the hostile trogg presence blocking the tunnels.",sp=0}},faq={{q="Who is Sten Stoutarm?",a="Sten Stoutarm is a dwarven outfitter and messenger stationed outside Anvilmar in Coldridge Valley. He assists fresh recruits by supplying warm clothing and delegating local mail deliveries.",al={"sten stoutarm","who is sten","anvilmar postman"},it="identity"},{q="What role does he play in Coldridge Valley?",a="Sten serves as both a quartermaster and courier contact for Anvilmar. He collects local resources like wolf meat and pelts to craft protective gear for apprentices, while also routing correspondence and training memoranda across the valley.",al={"sten job","what does sten do","sten role"},it="purpose"},{q="Why does Sten need mail delivered?",a="With Coldridge Pass endangered by troggs and winter weather, mail and supplies struggle to flow into the valley. Once messages make it through, Sten relies on dependable novices to deliver parcels and letters to residents such as Talin Keeneye.",al={"why coldridge mail delivery","sten mail","coldridge valley mail delivery"}},{q="What does Sten think about the troggs in the valley?",a="Sten takes a weary, unimpressed view of the pests infesting the surrounding hills, famously remarking that once you have seen one trogg, you have seen them all.",al={"sten troggs","trogg quote","sten on troggs"},it="threat"},{q="Why does he ask for wolf meat?",a="Sten trades durable, warm gloves to passing adventurers in exchange for tough wolf meat, helping sustain the valley's defenders while outfitting them against the biting Dun Morogh cold.",al={"dwarven outfitters quest","wolf meat quest","sten wolf meat"},it="why_wanted"},{q="What are the runes and memoranda Sten gives to new adventurers?",a="They are sealed letters and training tokens dispatched from superiors across Ironforge and Dun Morogh, directing young apprentices to report to their respective class trainers inside Anvilmar.",al={"consecrated rune","simple memorandum","sten notes"},it="item"},{q="Whose side is Sten Stoutarm on?",a="Sten Stoutarm is a loyal dwarf of Ironforge and stands firmly with the Alliance. Stationed at Anvilmar in Coldridge Valley, he supports the local training grounds and ensures that freshly arrived dwarven and gnomish recruits have the supplies and orders they need to defend the valley.",al={"sten stoutarm faction","who does sten stoutarm serve","sten stoutarm alliance"},it="side",add="be997a27"},{q="What does Sten Stoutarm want?",a="Sten wants to keep logistics running smoothly in Coldridge Valley despite the surrounding perils. With the valley pressed by troggs and wild beasts, he looks for capable new recruits to distribute critical mail from the pass, collect wolf meat for rugged outfitter gloves, and carry written orders to their respective class trainers.",al={"what does sten want","sten stoutarm goals","why does sten need help"},it="wants",add="9084afa8"},{q="Why is Sten Stoutarm here in Coldridge Valley?",a="Sten is stationed at Anvilmar to act as a vital coordinator and postman for Coldridge Valley. Because the pass connecting the valley to the rest of Dun Morogh is dangerous and infested, incoming communications and dispatches require someone on-site to direct traffic, outfit novice defenders, and route messages to Anvilmar's instructors.",al={"why is sten here","why is sten stoutarm in coldridge valley","sten stoutarm location reason"},it="why_here",add="d8d60996"}},ang={["race:Dwarf"]="Sten embodies the no-nonsense hospitality of Dun Morogh, making sure his kin are clad in thick leather and fed before sending them into the snow.",["race:Gnome"]="As gnomish refugees train alongside dwarves in Anvilmar, Sten treats them with the same practical expectations, dispatching them with mail and outfitting them for the elements.",["faction:Alliance"]="Maintaining communication through Coldridge Pass is critical for Ironforge's training grounds, and Sten's mail network keeps the valley connected to the wider Alliance."},kw={"anvilmar","coldridge","dun morogh","mail","outfitter","sten","stoutarm","trogg"},rel={"subzone:anvilmar","subzone:coldridge-valley","quest:179","quest:233","subzone:coldridge-pass","quest:3107","topic:dwarf","topic:trogg"},src={"Sten Stoutarm"}}
E["npc:tannok-frosthammer"] = {t="npc",n="Tannok Frosthammer",z="dunmorogh",s="Tannok Frosthammer is a dwarven resident found at Thunderbrew Distillery outside Kharanos in Dun Morogh. He serves as an anxious recipient of goods coming from Coldridge Valley, deeply troubled by how trogg attacks have cut off the roads to Anvilmar.",h="Tannok Frosthammer is a dwarven resident found at Thunderbrew Distillery outside Kharanos in Dun Morogh.",sec={{t="A Severed Supply Line",b="Stationed around the Thunderbrew Distillery in Kharanos, Tannok Frosthammer keeps a watchful eye on incoming deliveries and local tidings. The sudden surge of troggs swarming Coldridge Pass has severed normal transit from Coldridge Valley, leaving Tannok cut off from regular communication with the settlement at Anvilmar. Relying on couriers like the gnome tinkerer Hands Springsprocket to ferry vital supplies and news through the perilous, snowy mountain pass, Tannok represents the quiet worry shared by many Bronzebeards as subterranean threats crawl closer to their doorsteps.",sp=0}},faq={{q="Where is Tannok Frosthammer located?",a="Tannok Frosthammer is located outside the Thunderbrew Distillery, situated just east of the main crossroads in Kharanos within Dun Morogh.",al={"tannok location","where is tannok","find tannok frosthammer"},it="place",gp=true},{q="Why is Tannok worried about Coldridge Valley?",a="Tannok is deeply concerned by the trogg infestation choking Coldridge Pass. The overrun pathway has severed regular communication and trade between the valley settlement of Anvilmar and the rest of Dun Morogh.",al={"tannok concerns","why is tannok worried","coldridge pass troggs"},it="wants"},{q="Who does Tannok work with in Coldridge Valley?",a="Tannok receives deliveries from Hands Springsprocket, a gnomish supplier stationed down in Coldridge Valley who enlists passing travelers to carry goods through the dangerous pass.",al={"tannok supplier","hands springsprocket delivery","who supplies tannok"},it="ties"},{q="Who is Tannok Frosthammer?",a="Tannok Frosthammer is an Ironforge dwarf residing in Kharanos, stationed at Thunderbrew Distillery. He helps oversee the flow of local goods and supplies through Dun Morogh, maintaining vital logistical links between the central towns and more isolated outposts like Coldridge Valley.",al={"who is tannok","tannok frosthammer lore","tannok identity"},it="identity",add="22aa1045"},{q="Whose side is Tannok Frosthammer on?",a="Tannok is a loyal subject of Ironforge and a steadfast member of the Alliance. His chief concern is the safety and well-being of Dun Morogh's townsfolk and ensuring their trade routes remain functional despite rising threats in the snow.",al={"tannok faction","is tannok alliance","tannok frosthammer allegiance"},it="side",add="93f9fc20"},{q="Why is Tannok Frosthammer here?",a="Tannok conducts business out of Thunderbrew Distillery in Kharanos. He remains here to receive critical shipments and maintain communication with distant suppliers, though recent disruptions in Coldridge Pass have cut off deliveries and left him waiting anxiously for word.",al={"why is tannok in kharanos","why is tannok here","tannok frosthammer purpose"},it="why_here",add="eebd916b"}},ang={["race:Dwarf"]="For dwarves leaving Anvilmar for the wider world, delivering supplies to Tannok at Thunderbrew Distillery marks one of their very first steps into the heart of Dun Morogh.",["faction:Alliance"]="Tannok's stranded shipments highlight how even heartland settlements like Kharanos are feeling the strain of rising trogg incursions."},kw={"anvilmar","coldridge","distillery","frosthammer","kharanos","tannok","thunderbrew","troggs"},rel={"quest:2160","npc:hands-springsprocket","subzone:thunderbrew-distillery","subzone:kharanos","subzone:coldridge-pass","subzone:coldridge-valley","subzone:anvilmar","topic:trogg"},src={"Tannok Frosthammer"}}
E["npc:tharek-blackstone"] = {t="npc",n="Tharek Blackstone",z="dunmorogh",s="Tharek Blackstone is a hardworking toolsmith residing in Kharanos, in the snowy heart of Dun Morogh. Known for supplying heavy hardware to local craftsmen, his primary patron is Beldin Steelgrill of Steelgrill's Depot. Though constantly busy at his trade, he also serves as a reliable point of contact for travelers seeking work around the settlement.",h="Tharek Blackstone is a hardworking toolsmith residing in Kharanos, in the snowy heart of Dun Morogh.",sec={{t="A Busy Toolsmith in Kharanos",b="Situated amidst the cold drifts of Kharanos, Tharek Blackstone keeps busy turning out reliable dwarven tools. Between repairing gear for the locals and supplying larger operations, he rarely finds a moment to rest. His biggest headache—and most reliable customer—is Beldin Steelgrill, whose mechanostrider depot just outside town demands a steady stream of heavy wrenches, gears, and replacement implements. To keep his forge running without falling behind on deliveries, Tharek often hires wandering travelers to haul newly finished tool crates over to the depot for him.",sp=0},{t="A Community Figure",b="Beyond his trade at the anvil, Tharek carries considerable respect among the folk of Dun Morogh. While he holds no formal military title, his standing in town makes him an approachable liaison for odd jobs, supply runs, and coordinating local efforts.",sp=0}},faq={{q="Who is Tharek Blackstone?",a="Tharek Blackstone is a dwarven toolsmith based in the town of Kharanos in Dun Morogh. He crafts and maintains heavy tools for local workers and frequently employs passing adventurers to deliver supplies around the valley.",al={"tharek blackstone","who is tharek","blackstone dun morogh"},it="identity"},{q="What is his relationship with Beldin Steelgrill?",a="Beldin Steelgrill runs Steelgrill's Depot just east of Kharanos, where mechanostriders and siege engines undergo repairs. Beldin is Tharek's primary customer, ordering so much ironware that Tharek frequently relies on adventurers to deliver finished shipments to the depot.",al={"tharek and beldin","steelgrill tools","why beldin"},it="ties"},{q="Where can I find Tharek Blackstone?",a="He can be found standing outside near the center of Kharanos in Dun Morogh, within easy walking distance of the local inn and forge.",al={"tharek location","where is tharek blackstone","tharek blackstone loc"},it="place",gp=true},{q="Does Tharek hold any official rank in Ironforge?",a="He holds no military commission or political office. He is a busy, overworked toolsmith who hires newcomers in need of coin to carry supplies for him.",al={"is tharek a leader","tharek authority","blackstone rank"}},{q="Whose side is Tharek Blackstone on?",a="Tharek is a loyal dwarf of Ironforge and stands firmly with the Alliance. Based in Kharanos, he serves his community through honest labor, outfitting local craftsmen and lending a hand to travelers and neighbors across Dun Morogh whenever troubles arise.",al={"tharek blackstone faction","who does tharek blackstone serve","tharek alliance"},it="side",add="cb940f84"},{q="What does Tharek Blackstone want?",a="Tharek mostly wants to keep up with his relentless workload. As a hardworking toolsmith, he is constantly swamped with orders—especially from demanding clients like Beldin Steelgrill. He looks for reliable travelers willing to run deliveries and take on odd jobs so he can keep his forge running smoothly.",al={"what does tharek want","tharek blackstone motive","why does tharek need help"},it="wants",add="eaa270fb"},{q="Why is Tharek Blackstone here in Kharanos?",a="Kharanos is the central hub for Dun Morogh's travelers and tradesfolk, making it the natural place for Tharek to set up shop. From here, he can supply nearby hubs like Steelgrill's Depot with essential gear.",al={"why is tharek in kharanos","tharek blackstone kharanos"},it="why_here",add="fa8e7e80"}},ang={["profession:Blacksmithing"]="For smiths passing through Kharanos, Tharek exemplifies the day-to-day grind of a working toolsmith, churning out hard-wearing wrenches and iron fittings to sustain dwarven machinery.",["race:Dwarf"]="Tharek represents the sturdy, self-reliant spirit of Dun Morogh's working class, helping keep local industry running through sheer perseverance at the anvil."},kw={"beldin","blackstone","dun morogh","kharanos","steelgrill","tharek","toolsmith"},rel={"npc:beldin-steelgrill","subzone:kharanos","subzone:steelgrill-s-depot","quest:400","quest:415","zone:dunmorogh","topic:dwarf","subzone:anvilmar"},src={"Tharek Blackstone"}}
E["npc:thorgas-grimson"] = {t="npc",n="Thorgas Grimson",z="dunmorogh",s="Thorgas Grimson is the resident dwarf hunter trainer stationed inside Anvilmar in Coldridge Valley. A seasoned outdoorsman of Dun Morogh, he firmly believes that hands-on survival in the freezing wilds is the finest teacher any fledgling marksman can have.",h="Thorgas Grimson is the resident dwarf hunter trainer stationed inside Anvilmar in Coldridge Valley.",sec={{t="A Guide in the Cold",b="Perched inside the stone halls of Anvilmar, Thorgas Grimson welcomes novice mountaineers and scouts taking their very first steps into the harsh snowdrifts of Coldridge Valley. Rather than bogging young hunters down with dry lectures, Grimson espouses a practical philosophy: real skill is forged out in the freezing winds, bow or gun in hand, tracking Dun Morogh's rugged beasts firsthand.",sp=0}},faq={{q="Who is Thorgas Grimson?",a="Thorgas Grimson is a dwarven hunter trainer located within Anvilmar, the central outpost of Coldridge Valley in Dun Morogh. He provides initial guidance and basic field skills to new Alliance hunters starting their adventures.",al={"thorgas grimson","who is thorgas","anvilmar hunter trainer"},it="identity"},{q="What training does Thorgas offer?",a="He instructs novice hunters in foundational wilderness techniques, such as tracking wild beasts across the snowy terrain and honing basic ranged marksmanship, setting them on the path to becoming true mountaineers.",al={"what does thorgas teach","hunter skills anvilmar"},gp=true},{q="What is his training philosophy?",a="Thorgas maintains that theoretical drills pale in comparison to raw experience. He believes the only way to truly master the wild is to step out into the freezing drifts and face the beasts of Dun Morogh directly.",al={"thorgas personality","how does thorgas train"},it="purpose"},{q="Will Thorgas Grimson speak with non-hunters?",a="While polite enough, Thorgas will candidly inform adventurers of other callings that he cannot assist them with their training, advising them to seek out a mentor suited to their own chosen path.",al={"can other classes talk to thorgas","thorgas gossip"},gp=true},{q="Whose side is Thorgas Grimson on?",a="Thorgas stands firmly with the Ironforge dwarves and the broader Alliance. Stationed at Anvilmar in Coldridge Valley, he devotes his skills to preparing novice hunters to defend the realm and safeguard dwarven lands from encroaching beasts and hostiles.",al={"thorgas grimson faction","thorgas grimson allegiance","who does thorgas grimson serve"},it="side",add="c3cc0970"},{q="What does Thorgas Grimson want?",a="Thorgas wants to mold green recruits into self-reliant, capable marksmen. He believes true skill cannot be taught merely through talk, seeking instead to push new hunters out into the snowy wilderness where real field experience can forge their tracking and combat instincts.",al={"thorgas grimson goals","what does thorgas want","thorgas grimson purpose"},it="wants",add="8eae34e9"},{q="Why is Thorgas Grimson in Anvilmar?",a="He is stationed at Anvilmar to guide newly recruited hunters stepping out into Coldridge Valley. With the valley cut off by harsh weather and threatened by troggs and wild beasts, seasoned trackers like Thorgas are needed to ensure new recruits learn to survive and fight.",al={"why is thorgas in anvilmar","thorgas grimson location why","why is thorgas grimson here"},it="why_here",add="d81e027b"}},ang={["class:Hunter"]="For dwarven marksmen, Thorgas Grimson is often the very first mentor you encounter, offering early guidance on tracking beasts and surviving the freezing valley.",["race:Dwarf"]="Grimson embodies the hardy, self-reliant spirit of the Ironforge mountaineers who patrol the frozen peaks of Dun Morogh."},kw={"anvilmar","coldridge valley","dun morogh","dwarf hunter","hunter trainer","thorgas grimson"},rel={"subzone:anvilmar","zone:dunmorogh","quest:3108","topic:dwarf"},src={"Thorgas Grimson"}}
E["npc:thorvald-deepforge"] = {t="npc",n="Thorvald Deepforge",z="dunmorogh",s="Thorvald Deepforge is a dwarven weapon merchant stationed near the border pass in the Valley of Kings. He helps arm travelers and defenders securing the critical pathway between Dun Morogh and Loch Modan.",h="Thorvald Deepforge is a dwarven weapon merchant stationed near the border pass in the Valley of Kings.",sec={{t="Arming the Eastern Pass",b="Positioned within the towering monument of the Valley of Kings, Thorvald Deepforge serves the Alliance as a reliable arms dealer. The mountain passes connecting Khaz Modan's interior to the outlying territories are plagued by trogg incursions and roving wildlife, making well-forged steel essential for any Mountaineer or recruit on the road. Thorvald ensures that those arriving from Dun Morogh or heading deeper into Loch Modan carry the blades and axes needed to defend dwarven lands.",sp=0}},faq={{q="Who is Thorvald Deepforge?",a="Thorvald Deepforge is a dwarf vendor stationed in the Valley of Kings, where the road leads out of Dun Morogh into Loch Modan. He provides essential weaponry to travelers and defenders along the border.",al={"who is thorvald","thorvald deepforge npc","deepforge loch modan"},it="identity"},{q="What role does he play in the region's defense?",a="He acts as a forward quartermaster and weapon merchant for travelers traversing the mountain passes, assisting in arming recruits sent to reinforce outposts across Loch Modan.",al={"what does thorvald do","thorvald purpose","supplying the front"},it="why_here"},{q="Is he related to the other Deepforges in Khaz Modan?",a="He may be. Several dwarves share the Deepforge name, including Murgot and Bengus Deepforge, but no family tie has been confirmed. Tormus Deepforge of the Great Forge calls Thorvald his colleague.",al={"deepforge family","thorvald deepforge relatives","murgot deepforge relative"},it="ties"},{q="Whose side is Thorvald Deepforge on?",a="Thorvald Deepforge is a loyal dwarf of Ironforge and stands firmly with the Alliance. Positioned at the Valley of Kings, he aids the Mountaineers and defends Khaz Modan by supplying weapons and equipment to local forces battling troggs and other threats.",al={"thorvald deepforge faction","thorvald deepforge alliance","who does thorvald serve"},it="side",add="7578ebb9"},{q="What does Thorvald Deepforge want?",a="Thorvald focuses on keeping Alliance defenders armed and ready. He seeks capable adventurers to deliver vital arms and gear out to the defense posts holding the line across the region, ensuring the front lines remain properly supplied.",al={"thorvald deepforge goals","what does thorvald need","thorvald deepforge motive"},it="wants",add="96d38bac"}},ang={["race:Dwarf"]="Standing beneath the ancestral monoliths of the Valley of Kings, Thorvald represents the enduring craft and supply line that keeps Khaz Modan's borders secure.",["profession:Blacksmithing"]="Carrying the renowned Deepforge family name, Thorvald trades in the functional, reliable ironmongery that dwarven smiths are famous for."},kw={"deepforge","dun morogh","loch modan","mountaineers","thorvald deepforge","valley of kings","weaponsmith"},rel={"subzone:valley-of-kings","zone:lochmodan","zone:dunmorogh","quest:1578","topic:dwarf"},src={"Thorvald Deepforge"}}
E["npc:thran-khorman"] = {t="npc",n="Thran Khorman",z="dunmorogh",s="Thran Khorman is the resident dwarven warrior trainer stationed in Anvilmar, nestled within the snowy Coldridge Valley. He oversees the basic combat drilling for newly minted warriors stepping out into Dun Morogh.",h="Thran Khorman is the resident dwarven warrior trainer stationed in Anvilmar, nestled within the snowy...",sec={{t="Drillmaster of Coldridge Valley",b="Standing near the training grounds of Anvilmar, Thran Khorman is tasked with turning raw dwarven recruits and visiting gnomes into disciplined combatants. He maintains a gruff, uncompromising demeanor toward anyone who lacks the grit for front-line fighting. In his eyes, even though the Third War has concluded, peace is merely an illusion: troggs encroach upon Coldridge Pass, and the mountains remain fraught with peril. He demands relentless practice with axe, mace, and shield so that Ironforge's defenders never grow dull.",sp=0}},faq={{q="Who is Thran Khorman?",a="Thran Khorman is the dwarven warrior trainer stationed at Anvilmar in Dun Morogh. He provides initial combat guidance and instruction to novice warriors starting their journeys in Coldridge Valley.",al={"thran khorman role","who is thran","anvilmar warrior trainer"},it="identity"},{q="What training does he offer?",a="He instructs novice warriors in the fundamental disciplines of martial combat, helping them refine their stances, melee techniques, and battlefield grit before they head out to face the troggs and wild beasts of the pass.",al={"what does thran teach","warrior skills thran"},gp=true},{q="Why is he dismissed or curt with certain travelers?",a="Thran lives and breathes martial warfare and has little patience for those who pursue the arcane, shadow, or subtle arts. If you are not a warrior, he will frankly tell you that you wouldn't survive a single day under his training regimen.",al={"why is thran rude","thran gossip","thran non warrior text"}},{q="Whose side is Thran Khorman on?",a="Thran Khorman stands proudly with Ironforge and the Alliance. Stationed at Anvilmar in Coldridge Valley, he dedicates his strength to drilling fresh dwarven and gnome recruits so Dun Morogh remains defended against any threat.",al={"thran khorman allegiance","thran khorman faction","who does thran serve"},it="side",add="97dd6db6"},{q="What does Thran Khorman want?",a="He wants prospective fighters to take martial discipline seriously and keep their battle skills razor-sharp. Even though the major wars have ceased for the moment, he refuses to let anyone grow soft, demanding rigorous commitment from every aspiring warrior.",al={"thran khorman goal","what does thran khorman care about","thran khorman motivation"},it="wants",add="1baa464c"},{q="Why is Thran Khorman here?",a="Thran is posted at Anvilmar to mold raw adventurers into disciplined warriors. Coldridge Valley serves as the proving ground for Ironforge's newest defenders, and he ensures no one ventures into Dun Morogh without knowing how to hold a blade and bear armor.",al={"why is thran khorman in anvilmar","what brings thran to coldridge valley","thran khorman purpose"},it="why_here",add="d4f40481"}},ang={["class:Warrior"]="For dwarven and gnomish warriors awakening in Coldridge Pass, Thran is the very first master to test your mettle, hand you your starter runes or orders, and teach you the basics of martial survival.",["race:Dwarf"]="Thran epitomizes the stubborn, steadfast resolve of Ironforge's defenders, maintaining readiness even during peacetime so the kingdom is never caught unprepared."},kw={"anvilmar","coldridge pass","dun morogh","ironforge","thran khorman","warrior trainer"},rel={"subzone:anvilmar","zone:dunmorogh","quest:3106","quest:3112","topic:dwarf"},src={"Thran Khorman"}}
E["npc:tormus-deepforge"] = {t="npc",n="Tormus Deepforge",z="dunmorogh",s="Tormus Deepforge is a dwarven smith working at the center of the Great Forge in Ironforge. A dependable craftsman, he coordinates iron deliveries and supplies armaments for Alliance defense efforts across Khaz Modan and beyond.",h="Tormus Deepforge is a dwarven smith working at the center of the Great Forge in Ironforge.",sec={{t="Master of the Great Forge",b="Positioned right beside the roaring fires of the Great Forge, Tormus Deepforge oversees substantial metalworking tasks on behalf of the Bronzebeard clan. Beyond hammering steel himself, Tormus mourns his mentor, Sturgy Ironband, whose smithing compound south of Helm's Bed Lake in eastern Dun Morogh was overrun by Dark Iron dwarves after a load of strange umbral ore arrived there.",sp=0}},faq={{q="Where can I find Tormus Deepforge?",a="Tormus stands on the circular walkway encircling the lava pool of the Great Forge, the central hub of Ironforge.",al={"tormus location","where is tormus","tormus deepforge map"},it="place",gp=true},{q="What role does Tormus play in the Alliance war effort?",a="Tormus forges weapons for young warriors sent to him at the Great Forge. In return he asks them to avenge his mentor, Sturgy Ironband, by entering Ironband's Compound in Dun Morogh and recovering the umbral ore the Dark Iron dwarves killed for, which he then works into new grey iron weapons.",al={"what does tormus do","tormus purpose","why talk to tormus"},it="purpose"},{q="Who are the other Deepforges?",a="Several dwarves share the Deepforge name, including Bengus, Murgot, and Kaita Deepforge, as well as Tormus's colleague Thorvald in Loch Modan, but whether they are related has never been confirmed.",al={"deepforge clan","deepforge family","is tormus related to murgot"},it="ties"},{q="Who is Tormus Deepforge?",a="Tormus Deepforge is a master dwarven blacksmith working at the Great Forge within Ironforge. Renowned for his skill at shaping iron and steel, he plays a crucial role in crafting equipment and managing shipments of armaments to support allied forces across the Eastern Kingdoms.",al={"who is tormus","tormus deepforge lore","who is deepforge"},it="identity",add="7c43f5fd"},{q="Whose side is Tormus Deepforge on?",a="Tormus is fiercely loyal to King Magni Bronzebeard and the Alliance. Stationed at the very heart of the dwarven capital, he dedicates his craft directly to ensuring Alliance soldiers and distant outposts receive the weapons and supplies they need to stand against their enemies.",al={"tormus deepforge faction","who does tormus serve","is tormus alliance"},it="side",add="43326af9"},{q="What does Tormus Deepforge want?",a="Tormus wants to forge fine weapons and to see his mentor, Sturgy Ironband, avenged. Dark Iron dwarves slaughtered everyone at Ironband's Compound in Dun Morogh after a load of strange umbral ore arrived there, and Tormus asks adventurers to strike back at them and bring him that ore so he can learn its properties.",al={"what does tormus want","tormus goals","tormus deepforge quests"},it="wants",add="6189f272"},{q="Why is Tormus Deepforge in Ironforge?",a="He plies his trade at the Great Forge, the industrial heart of Khaz Modan. There, alongside Ironforge's finest armorers and weaponsmiths, he commands the vast fires and anvils required to forge heavy arms for the kingdom's military efforts.",al={"why is tormus in ironforge","why is tormus here","tormus at the great forge"},it="why_here",add="14a6c7e2"}},ang={["profession:Blacksmithing"]="For smiths plying their trade at the Great Forge, Tormus represents the essential link between raw bar stock and frontline military outfitting.",["race:Dwarf"]="A proud artisan of the mountain kingdom, Tormus demonstrates Ironforge's readiness to smelt and deliver arms whenever allies in the Grand Alliance call for aid."},kw={"blacksmith","deepforge","dwarf","great forge","ironforge","lochinver","tormus"},rel={"subzone:great-forge","zone:ironforge","topic:dwarf","quest:1618","quest:1578","subzone:ironband-s-compound","zone:dunmorogh"},src={"Tormus Deepforge"}}
E["npc:veron-amberstill"] = {t="npc",n="Veron Amberstill",z="dunmorogh",s="Veron Amberstill is a dwarven ram breeder residing at Amberstill Ranch in eastern Dun Morogh. He tends to the rugged mountain rams that serve as the traditional mounts of Ironforge and offers them to skilled riders who have earned his trust.",h="Veron Amberstill is a dwarven ram breeder residing at Amberstill Ranch in eastern Dun Morogh.",sec={{t="Master of the Mounts",b="Tucked away in the snow-dusted hills of eastern Dun Morogh, Veron Amberstill oversees the celebrated stock of Amberstill Ranch. Mountain rams are perfectly suited for Khaz Modan's treacherous slopes, sure-footed and thick-coated against the bite of mountain blizzards. Veron breeds and trains these beasts to carry dwarven scouts, mountaineers, and traveling adventurers. While he gladly provides standard and swift mounts to fellow dwarves, outsiders must prove their unwavering loyalty to the throne of Ironforge before he will part with any of his prized herd.",sp=0}},faq={{q="Who is Veron Amberstill?",a="Veron Amberstill is a dwarven mount breeder and vendor located at Amberstill Ranch in Dun Morogh. He raises sturdy mountain rams for the kingdom of Ironforge and sells them to qualified riders.",al={"veron amberstill","who is veron","amberstill ram vendor"},it="identity"},{q="Can non-dwarves purchase rams from Veron?",a="Yes, but only if they have earned an exalted reputation with Ironforge. Dwarves can buy his rams naturally, but outsiders must prove themselves staunch champions of the mountain kingdom before Veron entrusts them with his stock.",al={"can humans buy rams","ram mount non dwarf","ironforge reputation ram"},gp=true},{q="Where is Veron Amberstill located?",a="You can find him standing outside at Amberstill Ranch, situated nestled in the hills of eastern Dun Morogh, just northeast of Gol'Bolar Quarry.",al={"veron location","where is veron","where to find veron amberstill"},it="place",gp=true},{q="Why do dwarves ride rams instead of horses?",a="Mountain rams possess thick coats, robust frames, and extraordinary balance, making them far better suited to the freezing winds and sheer rocky ledges of Dun Morogh and the surrounding peaks than ordinary horses.",al={"why do dwarves ride rams","dwarven mounts lore","mountain ram mount lore"}},{q="Whose side is Veron Amberstill on?",a="Veron Amberstill is firmly loyal to the dwarven kingdom of Ironforge and the Grand Alliance. He tends to the mountain rams that serve as the prized mounts of the dwarven people, supplying dependable steeds to his kin and trusted Alliance allies who have earned high standing in Ironforge.",al={"veron amberstill faction","is veron amberstill alliance","veron amberstill loyalty"},it="side",add="601a0646"},{q="Why is Veron Amberstill here?",a="Veron Amberstill manages Amberstill Ranch nestled in the windswept hills of Dun Morogh. The cold, rocky terrain provides ideal conditions for raising stout and hardy mountain rams, making the ranch the central hub for breeding and training these iconic dwarven riding beasts.",al={"why is veron amberstill in dun morogh","veron amberstill location reason","amberstill ranch purpose"},it="why_here",add="b4666b3f"},{q="What does Veron Amberstill want?",a="Veron Amberstill wants to protect his livelihood and maintain the ranch's prized stock of mountain rams. He focuses on breeding, rearing, and safeguarding his herds from the dangers prowling the snowy ridges of Dun Morogh, providing sturdy mounts to worthy riders.",al={"veron amberstill goal","what does veron want","veron amberstill purpose"},it="wants",add="8bafbe3f"},{q="Who is Veron Amberstill tied to?",a="Veron is tied to the Amberstill clan and the ranch that carries their family name. Together with his kin at the ranch, he oversees the care and breeding of the mountain rams that have served the dwarves of Dun Morogh for generations.",al={"veron amberstill family","who is veron related to","amberstill family"},it="ties",add="921d6dac"}},ang={["race:Dwarf"]="Veron represents your people's deep heritage with mountain beasts, providing standard and swift rams that every dwarven adventurer relies on to navigate Khaz Modan.",["faction:Alliance"]="Allies of Ironforge who wish to master riding a mountain ram must first prove their dedication to the dwarven kingdom to earn Veron's respect."},kw={"amberstill ranch","dun morogh","ironforge","mount vendor","mountain ram","ram vendor","veron amberstill"},rel={"subzone:amberstill-ranch","zone:dunmorogh","zone:ironforge","topic:dwarf"},src={"Veron Amberstill"}}
E["quest:1578"] = {t="quest",n="Supplying the Front",z="dunmorogh",s="Supplying the Front is an early task for developing dwarven blacksmiths, commissioned by Tormus Deepforge in Ironforge. It tasks smiths with forging weapons and armor to support the Mountaineers stationed in Loch Modan against the relentless trogg incursions.",h="Supplying the Front is an early task for developing dwarven blacksmiths, commissioned by Tormus Deepforge in...",sec={{t="Arming the Mountaineers",b="In the great forges of Ironforge, master smith Tormus Deepforge keeps a keen eye on the Kingdom of Khaz Modan's borders. The Mountaineers defending the valleys of Loch Modan are hard-pressed by sudden trogg attacks spilling out from unearthed ruins and caverns. Keeping their defensive lines supplied requires a non-stop rotation of fresh blades, belts, and fittings, prompting local artisans to pitch in.",sp=0},{t="The Deepforge Kinship",b="To keep the defense supplied without pulling veteran craftspeople away from city forges, Tormus dispatches apprentices east to Loch Modan. There, his colleague Thorvald Deepforge maintains a field armory out of the southern guard tower. By delivering sturdy copper axes and copper chain belts directly to Thorvald, blacksmiths prove their reliability and earn advanced smithing techniques.",sp=0}},faq={{q="Who offers this quest and what is required?",a="Tormus Deepforge, a blacksmith found in the Great Forge of Ironforge, offers this task to apprentice smiths with a skill level of at least thirty. You must craft six copper axes and six copper chain belts.",al={"who gives supplying the front","quest starter","blacksmith quest requirements"},it="purpose",gp=true},{q="Where is Thorvald Deepforge located?",a="Thorvald Deepforge is stationed inside the southern guard tower of Loch Modan. To reach him, head south along the main road past Thelsamar toward the Badlands border, where the tower stands beside the mountain pass.",al={"where is thorvald","thorvald location","southern guard tower loch modan"},it="place",gp=true},{q="Why do the Mountaineers need so many copper supplies?",a="Mountaineers stationed in Loch Modan are engaged in constant skirmishes with violent troggs. The harsh combat rapidly chips, dulls, and breaks their equipment, requiring an endless influx of basic weapons and chain armor.",al={"why do they need axes","what is the copper for"},it="motive"},{q="What relation is Thorvald to Tormus?",a="Tormus refers to Thorvald as his colleague, and sharing the Deepforge clan name, they are closely linked craftsmen working together to bridge Ironforge's industrial capacity with field defenses.",al={"are thorvald and tormus related","tormus colleague"},it="ties"},{q="What kind of reward does Thorvald offer?",a="In appreciation for relieving the supply strain on the southern guard tower, Thorvald shares his craft knowledge by providing plans for new armor.",al={"quest reward","what does thorvald teach"},it="for_you",gp=true},{q="Why are the troggs such an issue in Loch Modan right now?",a="Recent dwarven excavations have uncovered subterranean vaults and hollows throughout Khaz Modan, accidentally awakening and unearthing swarms of aggressive troggs that now menace surrounding settlements and watchtowers.",al={"why are troggs attacking","trogg problem loch modan"},it="threat"},{q="Why does Tormus Deepforge need more Copper Axes?",a="The Ironforge Mountaineers fighting in Loch Modan are engaged in nonstop skirmishes against the troggs. Weapons break quickly in constant battle, and Thorvald Deepforge desperately needs fresh armaments to ensure the defenders can maintain their front line.",al={"what are copper axes for","copper axe use supplying front","why copper axes"},it="item",add="0062256f"},{q="Why does Thorvald need Copper Chain Belts?",a="Trogg attacks are brutal and relentless, wearing down the Mountaineers' protective gear as fast as they can repair it. Thorvald relies on steady shipments of durable armor pieces like copper chain belts to keep the dwarven sentries properly protected in the southern passes.",al={"what are copper chain belts for","copper chain belt use","why copper chain belts"},it="item",add="c19cb0c2"},{q="Why does Tormus Deepforge ask an adventurer to help supply the front?",a="Thorvald is swamped trying to keep up with repairs at the front, and Tormus cannot abandon his own anvil in Ironforge. As a budding smith, forging the gear and carrying it east through the tunnels tests your craft while directly relieving the strain on the mountain guard.",al={"why me supplying front","why does tormus need me","why send an adventurer to thorvald"},it="why_me",add="f96d051f"}},ang={["profession:Blacksmithing"]="This task serves as an early rite of passage for aspiring metalworkers, testing their ability to produce reliable, uniform copper weapons and armor for real military use.",["race:Dwarf"]="The defense of Loch Modan relies directly on dwarven craftsmanship, proving that an artisan working the bellows is just as crucial to the kingdom's survival as a mountaineer holding a rifle.",["faction:Alliance"]="Khaz Modan's border security safeguards the mountain roads linking Ironforge with Stormwind and Alliance operations in the southern reaches."},kw={"blacksmithing","copper axe","copper chain belt","ironforge","loch modan","supplying the front","thelsamar","thorvald deepforge","tormus deepforge","troggs"},rel={"npc:tormus-deepforge","npc:thorvald-deepforge","zone:lochmodan","subzone:thelsamar","topic:trogg","zone:dunmorogh"},m={start="Tormus Deepforge",["end"]="Thorvald Deepforge",faction="Alliance",id=1578,ri={"Copper Axe","Copper Chain Belt"}},src={"Supplying the Front"}}
E["quest:1599"] = {t="quest",n="Beginnings",z="dunmorogh",s="Beginnings is a rite of passage for fledgling Alliance warlocks starting in Dun Morogh. Under the begrudging tutelage of Alamar Grimm, novices are dispatched to harvest magical feather charms from nearby Frostmane troll novices to prove their competence before mastering the art of summoning an imp.",h="Beginnings is a rite of passage for fledgling Alliance warlocks starting in Dun Morogh.",sec={{t="A Reluctant Mentor",b="Within the safe haven of Anvilmar, dark magic is not openly celebrated, but it is tolerated out of necessity. Alamar Grimm, an established warlock, conducts his occult research in relative discretion. When new practitioners show raw promise, Grimm is persuaded by unknown backers among Ironforge's darker circles to step away from his studies and assess the recruits personally.",sp=0},{t="The Spark of Dark Magic",b="Before granting a novice the secrets to enslaving lesser demons, Grimm requires practical proof of both physical endurance and magical affinity. Nearby Frostmane troll novices, gathering in a cave southwest of Anvilmar, carry primitive feather charms infused with subtle primal magics. Harvesting these charms proves the aspiring warlock can conquer a magical adversary, while also providing Grimm with curious specimens for his ongoing research.",sp=0},{t="Summoning the Imp",b="Returning with the charms satisfies Grimm that the novice has sufficient will to survive. The trial culminates in teaching the summoning of the imp, the warlock's most foundational minion. Grimm offers a stern warning alongside the ritual: despite their diminutive stature, imps wield chaotic fire magic that can easily overpower an undisciplined master.",sp=0}},faq={{q="Who gives the quest Beginnings?",a="Alamar Grimm gives the quest. He is a warlock trainer located inside Anvilmar in Coldridge Valley, Dun Morogh.",al={"who starts beginnings","beginnings quest giver","alamar grimm location"},it="identity"},{q="What are the feather charms used for?",a="The feather charms serve a dual purpose: they prove an aspiring warlock can face and defeat magically adept enemies, and they provide Alamar Grimm with curious enchanted troll trinkets to examine in his research.",al={"why feather charms","feather charm purpose","frostmane charms"},it="item"},{q="Where are the Frostmane novices located?",a="They reside in a cave to the southwest of Anvilmar in Coldridge Valley, where the Frostmane trolls have established a presence.",al={"where are the troll novices","frostmane cave location","frostmane novice spot"},it="target",gp=true},{q="What reward does a warlock gain upon completing this task?",a="Completing the task earns Alamar Grimm's approval and grants the knowledge required to summon an imp, a warlock's first demonic companion.",al={"what does beginnings teach","quest reward beginnings","imp spell quest"},gp=true},{q="Why is Alamar Grimm teaching new warlocks?",a="Grimm mentions that influential voices have taken an interest in the fledgling warlock, convincing him to pause his private occult studies to test and mentor the recruit.",al={"why does alamar train me","who told alamar to train me"},it="why_me"},{q="Is the imp dangerous for a novice warlock?",a="Yes. Alamar Grimm explicitly cautions that despite an imp's small size, its fel fire and cunning make it volatile, and an inexperienced summoner can easily be overpowered by one.",al={"imp danger","can imps kill you","imp warnings"}},{q="Why does Alamar Grimm want this done?",a="Alamar Grimm was persuaded to pause his own research and train you because notable patrons took an interest in your potential. Before teaching you to summon your first demon, an imp, he requires proof that you have the magical fortitude and physical mettle to survive it. Recovering the feather charms also serves his curiosity, offering curious troll magic for him to study.",al={"alamar grimm motive","why feather charms","why does alamar want feather charms"},it="motive",add="5dfeed0e"},{q="Who are the Frostmane novices you are sent against?",a="The Frostmane novices are young ice trolls practicing rudimentary magic in a cave southwest of Anvilmar. The indigenous Frostmane tribe is locked in conflict with the Ironforge dwarves across Dun Morogh, using nearby caverns to regroup and train their fledgling spellcasters.",al={"frostmane novices dun morogh","who are the frostmane novices","troll novices cave"},it="target",add="f653bf22"}},ang={["class:Warlock"]="This quest marks the defining first step of an Alliance warlock's journey in Dun Morogh, unlocking the ability to summon your first demonic servant.",["race:Gnome"]="Gnome warlocks learning their craft in Coldridge Valley must prove their intellect and magical dominance by outsmarting the local Frostmane trolls."},kw={"alamar grimm","anvilmar","beginnings","coldridge valley","dun morogh","feather charm","frostmane novice","imp"},rel={"npc:alamar-grimm","subzone:anvilmar","zone:dunmorogh","topic:troll"},m={start="Alamar Grimm",level="4",faction="Alliance",id=1599,ri={"Feather Charm"}},src={"Beginnings"}}
E["quest:1654"] = {t="quest",n="The Test of Righteousness",z="dunmorogh",s="The Test of Righteousness represents a defining trial for rising paladins seeking a sanctified weapon of the Light. The master weaponsmith Jordan Stilwell offers to craft an extraordinary holy armament, tasking the champion with scouring distant lands for rare smithing components, including his lost family hammer.",h="The Test of Righteousness represents a defining trial for rising paladins seeking a sanctified weapon of the...",sec={{t="A Sacred Commission",b="Outside the grand gates of Ironforge, Jordan Stilwell seeks a worthy companion of the Light. Recognising the deeds of a rising paladin, the smith proposes a sacred pact: he will forge a legendary weapon that stands as an enduring symbol of devotion, provided the paladin undertakes the perilous legwork required to secure the master-grade materials.",sp=0},{t="Components of Consecration",b="Crafting a weapon fit to channel the Light demands ingredients from across the Eastern Kingdoms and beyond. Stilwell's design requires four distinct items: sturdy Whitestone Oak lumber, refined ore from master prospectors, a purified Kor Gem thrumming with raw power, and the reclamation of Jordan's own smithing hammer, left behind when he escaped Shadowfang Keep. Tracking them down forces the paladin to test their mettle against distant threats.",sp=0},{t="The Smith's Heritage",b="For Jordan Stilwell, the undertaking is far more than simple commerce. Among the required pieces is his father's hammer, an heirloom deeply tied to his craft and lineage. By uniting this reclaimed tool with a rare, purified Kor Gem, Jordan finally obtains the opportunity to realize plans he has harbored for years, turning family devotion into a sacred instrument of justice.",sp=1}},faq={{q="What is the purpose of this quest?",a="This quest sends rising paladins across the realm to gather the rare materials needed by Jordan Stilwell to forge a powerful holy weapon, serving as a rite of passage.",al={"what does this quest do","why do test of righteousness","test of righteousness goal"},it="purpose"},{q="Who is Jordan Stilwell?",a="Jordan Stilwell is a skilled human weaponsmith stationed outside the gates of Ironforge in Dun Morogh. He possesses ancient crafting designs for sacred paladin weaponry and seeks to recover his father's lost smithing hammer.",al={"jordan stilwell lore","who is the smith outside ironforge","stilwell background"},it="identity"},{q="What materials are needed to forge the weapon?",a="Jordan requires four specific components: Jordan's Smithing Hammer, Whitestone Oak Lumber, Bailor's Refined Ore Shipment, and a Purified Kor Gem.",al={"what items do i need","materials for jordan stilwell","test of righteousness ingredients"},it="item",gp=true},{q="Why is Jordan's hammer so important to him?",a="The smithing hammer originally belonged to Jordan's father. Recovering it returns an irreplaceable family heirloom to his forge, allowing him to produce his finest craftsmanship.",al={"why his father hammer","jordans smithing hammer lore","stilwell hammer history"},it="ties"},{q="What is a Kor Gem?",a="A Kor Gem is an exceedingly rare and potent stone. Once purified of corrupting influences, it serves as an extraordinary focal point for consecrating holy weapons.",al={"kor gem lore","what is kor gem","purified kor gem"},it="origin"},{q="Where does Jordan Stilwell craft this weapon?",a="Jordan Stilwell works just outside the snowy gates of Ironforge in the mountainous region of Dun Morogh.",al={"jordan stilwell location","where is jordan","where do i turn this in"},it="place",gp=true},{q="Why does Jordan Stilwell want this done?",a="Jordan has harbored designs for a grand weapon of righteousness for a long time, but he lacked both the rare materials and the means to venture across the world to claim them. By entering an alliance with you, he finally has the chance to recover his family's lost hammer and craft his finest masterpiece to date, rewarding a champion of the Light in the process.",al={"jordan stilwell motive","why does jordan want these items","jordan stilwell why"},it="motive",add="c050f299"},{q="What is Jordan's Smithing Hammer for?",a="Jordan's Smithing Hammer is an heirloom passed down to Jordan Stilwell from his father. Jordan needs the trusted, familiar tool in his hands before he can undertake the intricate and exacting labor of forging your holy weapon.",al={"what is jordan's smithing hammer","jordan's smithing hammer purpose","why need jordan's hammer"},it="item",add="4a2d94b4"},{q="What is the Jordan's Refined Ore Shipment for?",a="This refined ore shipment provides the tempered metal needed to forge the head of your weapon. Ordinary iron cannot channel the sacred energies of a paladin, making high-grade refined ore essential to withstand both heavy combat and the Light itself.",al={"jordan's refined ore shipment use","what is the refined ore for","ore shipment jordan"},it="item",add="deb75c2f"},{q="What is the Whitestone Oak Lumber for?",a="Whitestone oak is a dense, exceptionally durable wood prized for crafting resilient hafts. Jordan requires this lumber to carve a sturdy handle capable of supporting the weighty forged head of the hammer without splintering under immense holy power.",al={"whitestone oak lumber use","why whitestone oak","whitestone lumber purpose"},it="item",add="a71ac5b5"},{q="What is the Purified Kor Gem for?",a="A Kor gem possesses an innate affinity for channeling magical and spiritual force. Once cleansed of dark taint and purified, the gem serves as a sacred focal point set into the weapon, allowing you to harness and project the Light through your strikes.",al={"purified kor gem use","what is the kor gem for","why purified kor gem"},it="item",add="ab9031e0"},{q="Why does Jordan Stilwell need you to gather the materials?",a="Jordan is a humble smith bound to his forge outside Ironforge, lacking the combat training and freedom to venture into hazardous lands across Azeroth. The items required are scattered in distant, dangerous places, demanding a skilled paladin of the Light capable of braving peril to recover them.",al={"why me jordan stilwell","why does jordan need help","why can't jordan get the ore"},it="why_me",add="c2f50c47"}},ang={["class:Paladin"]="This quest represents a traditional proving ground, rewarding devotion and sacrifice with a weapon forged to channel the holy power of the Light.",["profession:Blacksmithing"]="Jordan Stilwell exemplifies the heights of mortal smithing, combining reclaimed heirloom tools with purified arcane and mineral components to craft holy relics.",["faction:Alliance"]="The collaborative effort bridges human craftsmanship and Alliance holdings across Khaz Modan and beyond to arm defenders against rising dark threats."},kw={"bailor's ore","dun morogh","ironforge","jordan stilwell","kor gem","paladin weapon","test of righteousness","whitestone oak"},rel={"npc:jordan-stilwell","quest:1653","quest:1655","quest:1442","zone:dunmorogh","zone:ironforge","topic:light","topic:alliance"},m={start="Jordan Stilwell",level="22",faction="Alliance",id=1654,ri={"Jordan's Refined Ore Shipment","Jordan's Smithing Hammer","Purified Kor Gem","Whitestone Oak Lumber"}},src={"The Test of Righteousness (2)"}}
E["quest:1681"] = {t="quest",n="Ironband's Compound",z="dunmorogh",s="Ironforge smith Tormus Deepforge seeks vengeance for his mentor, Sturgy Ironband, whose remote teaching outpost in eastern Dun Morogh fell to a sudden and bloody assault. The slaughter followed the arrival of a rare umbral ore shipment, which immediately drew the violent attention of the Dark Iron dwarves.",h="Ironforge smith Tormus Deepforge seeks vengeance for his mentor, Sturgy Ironband, whose remote teaching...",sec={{t="A Master's Fall",b="Sturgy Ironband was revered across Ironforge as an unmatched instructor of the smithing craft. From his secluded compound south of Helm's Bed Lake, he instructed promising pupils far from the crowded anvils of the Great Forge. That peaceful enterprise ended abruptly when one of his students acquired an unfamiliar mineral dubbed umbral ore. Intrigued by its properties, Ironband resolved to experiment with the sample, entirely unaware that possessing it had marked his school for ruin.",sp=0},{t="The Dark Iron Raid",b="Shortly after the umbral ore reached the compound, hostile Dark Iron dwarves launched a ruthless surprise attack against the outpost. The assailants showed no mercy, slaughtering Sturgy Ironband and every apprentice under his care before occupying the grounds. Tormus Deepforge, one of Ironband's surviving proteges based in the capital, refuses to let the massacre stand, dispatching Alliance travelers to avenge his teacher and recover the cursed ore that brought destruction to the encampment.",sp=0}},faq={{q="Where is Ironband's Compound located?",a="Ironband's Compound lies in eastern Dun Morogh, tucked into the snowy hills south of Helm's Bed Lake.",al={"ironband location","where is compound","find ironband's compound"}},{q="Who was Sturgy Ironband?",a="Sturgy Ironband was a renowned dwarven master blacksmith. He operated a dedicated teaching compound outside Ironforge where he trained students in advanced metalworking before being slain in a Dark Iron raid.",al={"who is ironband","sturgy ironband lore","who was sturgy"}},{q="Why did the Dark Iron dwarves attack the compound?",a="The attack was provoked by a shipment of umbral ore brought in by one of Ironband's students. Shortly after the ore arrived, the Dark Irons descended upon the compound, slaughtering everyone present and taking control of the site.",al={"why attack","why dark iron raid","dark iron motive"}},{q="What is umbral ore?",a="Umbral ore is an uncommon and mysterious mineral. Master Ironband was eager to forge it, but its arrival immediately attracted the lethal interest of the Dark Iron clan.",al={"umbral ore lore","what is umbral","strange ore"}},{q="Who is Tormus Deepforge?",a="Tormus Deepforge is a blacksmith in Ironforge and a former apprentice of Sturgy Ironband. Devastated by the loss of his teacher, he sends adventurers to punish the Dark Iron intruders and retrieve the ore.",al={"who gives ironbands compound","tormus deepforge lore","who is deepforge"}},{q="What does Tormus want recovered from the compound?",a="Tormus tasks travelers with eliminating the Dark Iron raiders to avenge Ironband and securing the shipment of umbral ore that caused the catastrophe.",al={"what to get","compound objective","quest turn in"}}},ang={["profession:Blacksmithing"]="The tragic fate of Sturgy Ironband serves as a cautionary tale of how the pursuit of exotic, untested ores can attract deadly perils to the forge.",["race:Dwarf"]="The raid on Ironband's outpost highlights the bitter and lingering hatred between the Bronzebeard dwarves of Ironforge and their Dark Iron kin."},kw={"blacksmithing","dark iron","dun morogh","helm's bed lake","ironband's compound","sturgy ironband","tormus deepforge","umbral ore"},rel={"subzone:ironband-s-compound","npc:tormus-deepforge","subzone:helm-s-bed-lake","zone:dunmorogh","zone:ironforge"},m={level="11",id=1681},src={"In-game quest text: Ironband's Compound"},fv=true}
E["quest:170"] = {t="quest",n="A New Threat",z="dunmorogh",s="A New Threat is an early combat assignment issued by Balir Frosthammer in Coldridge Valley. Dwarven mountaineers have been caught off-guard by a sudden surge of troggs bursting out across Dun Morogh, threatening local settlements and camps.",h="A New Threat is an early combat assignment issued by Balir Frosthammer in Coldridge Valley.",sec={{t="Breaching Coldridge Valley",b="Coldridge Valley was long regarded as a protected haven for young dwarven warriors and mountaineers training in Dun Morogh. That peace shattered when subterranean Rockjaw troggs began clawing their way to the surface in startling numbers. Reports quickly reached Anvilmar that troggs were swarming the frozen lake and surrounding foothills, disrupting daily patrols and cutting off vital supply routes through the valley pass.",sp=0},{t="A Camp Overrun",b="The crisis peaked when the creatures mounted a coordinated assault on a dwarven encampment to the west, forcing the mountaineers to retreat and abandon their posts. Shorthanded and unable to spare full battle regiments from Ironforge, Balir Frosthammer has turned to newly recruited adventurers to caw through the Rockjaw ranks and secure the hills before the beasts push straight to Anvilmar's doorstep.",sp=0}},faq={{q="Who is Balir Frosthammer?",a="Balir Frosthammer is a seasoned dwarven mountaineer stationed outside Anvilmar in Coldridge Valley. He organizes defensive operations against the wild beasts and invading troggs threatening the local recruits.",al={"balir frosthammer","who gives a new threat","frosthammer anvilmar"},it="identity"},{q="Why are troggs suddenly in Coldridge Valley?",a="Rockjaw troggs have begun tunneling up from deep subterranean fissures all across Dun Morogh. Coldridge Valley is among the first populated valleys to suffer sudden, violent breaches as the creatures overrun surface camps.",al={"where did troggs come from","why troggs attacking","trogg invasion"},it="threat"},{q="What camp was overrun by the troggs?",a="A dwarven mountaineer camp situated in the western reaches of Coldridge Valley was recently ambushed and overwhelmed by troggs, forcing the survivors to fall back toward Anvilmar.",al={"overrun camp","western camp","where did troggs attack"},it="place"},{q="What kind of troggs are threatening the valley?",a="The attackers belong to the Rockjaw tribe, primarily consisting of standard Rockjaw Troggs and the larger, sturdier Burly Rockjaw Troggs that lead the advance around the frozen lake and foothills.",al={"rockjaw troggs","which troggs","burly rockjaw troggs"},it="target"},{q="Is King Magni aware of the trogg problem?",a="Local guards hope King Magni Bronzebeard and the Ironforge Senate are preparing a wider response, but frontier outposts like Coldridge Valley are currently forced to handle localized surges on their own.",al={"does magni know","ironforge response to troggs","ironforge senate troggs"},it="in_charge"},{q="What happens after culling these troggs?",a="Thinning the troggs helps stabilize Anvilmar's immediate surroundings, though Balir and other dwarven officers continue organizing counter-offensives to reclaim the lost western camp and drive the pests back underground.",al={"follow up quest","after a new threat","coldridge trogg questline"},it="next_step"},{q="Why does Balir Frosthammer want the troggs culled?",a="Coldridge Valley is under immediate siege. The troggs have not only infested the southern hills and the frozen lake, but just nights ago they violently overran the dwarven camp to the west. Balir needs their numbers thinned before the savage creatures push deeper into the valley and overwhelm Anvilmar entirely.",al={"why kill troggs","balir frosthammer motive","why does balir need troggs dead"},it="motive",add="54af52f4"},{q="Why does Balir Frosthammer need your help instead of the local guards?",a="The defenders at Anvilmar are dangerously shorthanded. The recent surprise attack on their western camp scattered their forces and left the garrison stretched thin trying to hold the settlement's perimeter. With no surplus soldiers to spare for an offensive counterattack, Balir must recruit any able-bodied adventurer who arrives.",al={"why me balir","why not use guards","why does balir need me"},it="why_me",add="3d273126"}},ang={["race:Dwarf"]="For young Bronzebeard dwarves stepping out of Anvilmar, driving back the trogg incursions is a personal duty to safeguard the sacred grounds and tunnels of Dun Morogh.",["faction:Alliance"]="Containing the subterranean menace in Coldridge Valley keeps Ironforge's training grounds viable and ensures the southern mountain gate remains secure for Alliance recruits."},kw={"a new threat","anvilmar","balir frosthammer","burly rockjaw","coldridge valley","dun morogh","rockjaw trogg"},rel={"npc:balir-frosthammer","subzone:coldridge-valley","topic:trogg","zone:dunmorogh"},m={start="Balir Frosthammer",level="2",faction="Alliance",id=170},src={"A New Threat (Dun Morogh)"}}
E["quest:179"] = {t="quest",n="Dwarven Outfitters",z="dunmorogh",s="Dwarven Outfitters is an introductory survival task in Coldridge Valley offered by Sten Stoutarm. In exchange for culling local wolves and gathering their tough meat for winter rations, fresh recruits are rewarded with sturdy gloves to ward off frostbite in Dun Morogh's biting cold.",h="Dwarven Outfitters is an introductory survival task in Coldridge Valley offered by Sten Stoutarm.",sec={{t="A Fair Trade in Coldridge",b="The high mountain pass of Coldridge Valley is brutally cold, and unprepared travelers quickly learn that standard kit is no match for the elements. Standing outside Anvilmar, Sten Stoutarm offers a straightforward frontier bargain to new recruits: venture into the snowy drifts, hunt down the prowling wolves, and bring back cuts of tough meat to help supply the outpost. In return, he provides proper cold-weather gloves to ensure young adventurers keep all ten fingers.",sp=0},{t="Living Off the Valley",b="While wolves represent a perpetual hazard to dwarven scouts and fledgling gnomes training in the valley, they are also a vital resource. Their meat sustains the garrison stationed at Anvilmar, and culling their numbers keeps the paths between the local encampments somewhat safer. Stoutarm's arrangement serves a double purpose—testing a recruit's ability to handle the local wildlife while stockpiling food for the bitter nights ahead.",sp=0}},faq={{q="Who is Sten Stoutarm?",a="Sten Stoutarm is a dwarf stationed outside Anvilmar in Coldridge Valley. He keeps an eye out for newly arrived recruits and ensures they are properly equipped to survive the freezing Dun Morogh weather, offering practical gear in exchange for hunting local game.",al={"sten stoutarm","who gives dwarven outfitters","anvilmar outfitter"},it="identity"},{q="Why does Sten need wolf meat?",a="The outpost at Anvilmar relies on local hunting to keep its supplies stocked. Wolf meat provides hardy, dependable sustenance for the troops and trainers living in the secluded, snowbound valley.",al={"why wolf meat","tough wolf meat","what is the meat for"},it="motive"},{q="Where do you find the wolves for this task?",a="Wolves roam the snowy clearings all throughout Coldridge Valley, particularly just beyond the main courtyard of Anvilmar and along the paths leading toward the outlying camps.",al={"where are wolves","wolf locations coldridge","where to get meat"},it="place",gp=true},{q="What reward does Sten provide?",a="Sten rewards recruits with a dependable pair of warm gloves, designed specifically to stave off frostbite and shield a fighter's hands from Dun Morogh's bitter winds.",al={"dwarven outfitters reward","what gloves do you get","quest reward"},it="for_you",gp=true},{q="Is wolf meat considered good food among dwarves?",a="Tough wolf meat is coarse and chewy, but in the harsh mountain climate of Dun Morogh, dwarves prioritize hearty, filling sustenance over gourmet dining. When stewed or roasted over a campfire, it serves the garrison well.",al={"is wolf meat tasty","dwarf wolf meat","eating wolf"},it="item"},{q="Can gnomes do this quest too?",a="Yes. Gnomes training alongside their dwarven allies in Coldridge Valley face the exact same biting winds and need warm clothing just as urgently.",al={"gnome dwarven outfitters","can gnomes get gloves","gnome cold weather"},gp=true},{q="What are the wolves doing in Coldridge Valley?",a="Ragged young wolves and ragged timber wolves roam the frozen crags of Coldridge Valley as native predators. While they are a natural part of Dun Morogh's harsh mountain ecology, their aggressive prowling right outside Anvilmar makes them a constant nuisance to young recruits and a convenient source of fresh provisions for the outpost.",al={"why are there wolves here","coldridge valley wolves","wolf threat dun morogh"},it="target",add="cf6e8786"}},ang={["race:Dwarf"]="For young Bronzebeard dwarves stepping out into Coldridge Valley, this task is an early lesson in frontier self-reliance: earn your keep, provide for the camp, and respect the mountain cold.",["race:Gnome"]="Having taken refuge with their dwarven cousins in Dun Morogh, gnomes quickly discover that surviving Anvilmar requires practical mountain apparel just as much as sharp intellect."},kw={"anvilmar","coldridge valley","dun morogh","dwarven outfitters","frostbite","gloves","sten stoutarm","tough wolf meat"},rel={"npc:sten-stoutarm","zone:dunmorogh"},m={start="Sten Stoutarm",level="1",faction="Alliance",id=179,ri={"Tough Wolf Meat"}},src={"Dwarven Outfitters"}}
E["quest:1806"] = {t="quest",n="The Test of Righteousness",z="dunmorogh",s="The Test of Righteousness culminates at Jordan Stilwell's forge outside Ironforge in Dun Morogh. After gathering perilous components from across the Eastern Kingdoms and Kalimdor, a paladin waits while the smith crafts a mighty warhammer. It marks the transition of an apprentice into a recognized champion of the Light.",h="The Test of Righteousness culminates at Jordan Stilwell's forge outside Ironforge in Dun Morogh.",sec={{t="A Smith's Tribute",b="Master smith Jordan Stilwell plies his craft outside the gates of Ironforge. While he admits to a touch of envy toward wandering paladins, he takes profound pride in supporting the cause through his hammer and anvil. Once presented with rare materials gathered from shadowy crypts, sunken ruins, and dangerous mines, Stilwell fulfills his promise to forge a weapon worthy of a true defender.",sp=0},{t="The Legacy of Bosch Verigan",b="The finished warhammer is christened Verigan's Fist in honor of Bosch Verigan, an honored dwarven paladin and dear personal friend of Jordan Stilwell. By passing this sacred weapon into a young champion's hands on behalf of himself and his wife, Stilwell ensures that the memory and valor of his fallen friend endure against the darkness threatening Azeroth.",sp=0}},faq={{q="What happens during this step of the quest?",a="Jordan Stilwell walks over to his anvil and strikes hot metal to assemble the components you collected throughout your arduous trials. After working the forge, he returns to present you with the finished weapon.",al={"test of righteousness ending","jordan forging weapon","verigan cutscene"},gp=true},{q="Who is Bosch Verigan?",a="Bosch Verigan was an esteemed dwarven paladin and a close friend of Jordan Stilwell. Jordan named the newly forged two-handed hammer in his memory, honoring his dedication to the Holy Light.",al={"who is verigan","verigans fist namesake","bosch verigan"},it="people"},{q="Where does this forging take place?",a="The forging takes place just outside the great gates of Ironforge in the snowy peaks of Dun Morogh, where Jordan Stilwell maintains his forge and anvil.",al={"jordan stilwell location","where is the forge","dun morogh anvil"},it="place",gp=true},{q="Why did Jordan need rare materials from all over the world?",a="Jordan designed a weapon of exceptional balance and holy resonance. To forge something capable of enduring a paladin's sacred wrath, he required rare ores, wood, and gemstones that could only be recovered from perilous places across the world.",al={"why gathering materials","quest components test of righteousness"},it="why_wanted"},{q="Does Jordan Stilwell ever fight in battle himself?",a="Jordan Stilwell is a blacksmith rather than a wandering warrior. Though he admits to occasionally envying adventurers who roam the land, he finds his true purpose and pride in crafting weapons to equip defenders of the Light.",al={"is jordan a warrior","jordan stilwell fighter"},it="identity"},{q="What does receiving this hammer signify for a paladin?",a="Receiving the hammer marks the successful completion of a paladin's long trials. It proves that the bearer possesses the courage, persistence, and holy conviction needed to champion the Light in Azeroth's most dangerous corners.",al={"verigans fist meaning","paladin rite of passage"},it="power"},{q="Why does Jordan Stilwell want to forge this hammer?",a="Jordan Stilwell admits to feeling a pang of envy seeing the daring exploits of champions across Azeroth, as he is a smith rather than an adventurer. By forging Verigan's Fist from the rare components you gathered, he can directly aid a defender of the Light and contribute to keeping the realm safe in his own vital way.",al={"jordan stilwell motive","why forge the weapon","why does jordan forge the hammer"},it="motive",add="49955bc3"}},ang={["class:Paladin"]="This rite of passage rewards your perilous journeys across distant lands with Verigan's Fist, an iconic weapon dedicated to upholding righteousness.",["profession:Blacksmithing"]="Watching Jordan Stilwell work his anvil demonstrates how master craftsmanship can channel holy purpose into raw steel and salvaged materials.",["race:Dwarf"]="The hammer forged here immortalizes the memory of Bosch Verigan, an honored dwarven paladin who embodied the resilience of Khaz Modan."},kw={"bosch verigan","dun morogh","forge","hammer","ironforge","jordan stilwell","paladin","test of righteousness","verigan"},rel={"npc:jordan-stilwell","topic:light","zone:dunmorogh"},m={start="Jordan Stilwell",level="22",faction="Alliance",id=1806},src={"The Test of Righteousness (3)"}}
E["quest:182"] = {t="quest",n="The Troll Cave",z="dunmorogh",s="Assigned by the mountaineer Grelin Whitebeard, this mission dispatches adventurers to cull young Frostmane trolls gathering in the southern caves of Coldridge Valley. With the Ironforge Senate preoccupied by an escalating trogg crisis, lone scouts and willing recruits must handle border skirmishes before the trolls establish a permanent foothold.",h="Assigned by the mountaineer Grelin Whitebeard, this mission dispatches adventurers to cull young Frostmane...",sec={{t="Eyes in the Cold",b="While Ironforge's regular forces are consumed with repelling rock-jawed trogg incursions across the snowfields, the southern approaches cannot be left unguarded. Grelin Whitebeard and his brother Senir were deployed by the mountain authorities to assess whether the native ice trolls posed an immediate danger to the heartland. Perched on a bluff overlooking the frozen valley, Grelin maintains a solitary watch on their movements.",sp=0},{t="A Preemptive Strike",b="Grelin's reconnaissance revealed that the local Frostmane clan had begun settling in a deep cave along the southern ridgeline of Coldridge Valley. Believing full military mobilization would be an unnecessary waste of dwarven manpower, the scout favored hiring capable local volunteers to cull the aggressive whelps. Thinning their young fighters serves to disrupt their encampment before the Frostmane can mount coordinated raids against nearby dwarven homesteads.",sp=0}},faq={{q="Why doesn't Ironforge send regular soldiers to deal with these trolls?",a="The Ironforge Senate and the dwarven military are stretched thin dealing with a sudden, devastating trogg invasion across Dun Morogh. Minor threats like small troll warbands are relegated to scouts like Grelin Whitebeard, who hire independent adventurers to handle them.",al={"why no dwarven army","where are the guards","why hire adventurers"},it="why_me"},{q="Who are the Frostmane trolls?",a="The Frostmane are an indigenous tribe of ice trolls native to the frigid crags of Dun Morogh. Long hostile to the Bronzebeard dwarves, they continually clash with mountaineers over hunting grounds, territory, and ancient mountain passes.",al={"frostmane clan","dun morogh trolls","who are the frostmanes"},it="target"},{q="Where is the troll cave located?",a="The cave is tucked along the southern mountain ridge of Coldridge Valley, south of Grelin Whitebeard's observation camp.",al={"troll cave location","where is the cave","where are the whelps"},it="place",gp=true},{q="Who is Grelin Whitebeard?",a="Grelin Whitebeard is an Ironforge scout stationed in Coldridge Valley. Along with his brother Senir, who surveys other corners of Dun Morogh, Grelin tracks hostile troll populations to report back to dwarven leaders.",al={"grelin","quest giver","whitebeard"},it="identity"},{q="Why does Grelin specifically target Frostmane whelps?",a="The encampment in southern Coldridge Valley is a burgeoning settlement filled with juvenile warriors. Striking down their growing fighters prevents the band from becoming strong enough to threaten dwarven supply lines.",al={"why whelps","why target young trolls"}},{q="What happens after culling the cave?",a="Upon returning, you discover that the trolls retaliated in the night, raiding Grelin's campsite and stealing his personal field journal, requiring an immediate recovery effort deeper in their dens.",al={"what next","troll cave follow up"},sp=1,it="next_step"},{q="Why does Grelin Whitebeard want the trolls dealt with?",a="Grelin and his brother Senir were dispatched across Dun Morogh to evaluate whether the native Frostmane trolls pose a serious threat to the realm. With Ironforge's Senate already overwhelmed by trogg uprisings elsewhere, Grelin hopes to nip this gathering in the bud before it escalates into a crisis that demands regular troops.",al={"why kill the trolls","grelin whitebeard motive","why clear the troll cave"},it="motive",add="9e422164"}},ang={["race:Dwarf"]="For young Bronzebeard dwarves stepping out into the snow, putting down Frostmane warbands is both a matter of frontier security and an ancient mountain feud.",["race:Gnome"]="Taking shelter in Dun Morogh after the fall of Gnomeregan, gnomes gladly lend their wits and weapons to help relieve their dwarven hosts from surrounding threats.",["class:Hunter"]="The crags around the southern cave are harsh proving grounds for young trackers learning to flush hostile quarry from mountain heights."},kw={"coldridge valley","dun morogh","frostmane","grelin whitebeard","troggs","trolls","whelp"},rel={"npc:grelin-whitebeard","quest:218","quest:282","subzone:coldridge-valley","zone:dunmorogh","topic:troll","topic:trogg"},m={start="Grelin Whitebeard",level="4",faction="Alliance",id=182},src={"The Troll Cave"}}
E["quest:183"] = {t="quest",n="The Boar Hunter",z="dunmorogh",s="The Boar Hunter is an early errand given by the dwarf hunter Talin Keeneye in Coldridge Valley. A surge in the local crag boar population has made the woods overly dangerous, and young recruits are tasked with culling the aggressive beasts so seasoned hunters can track in peace.",h="The Boar Hunter is an early errand given by the dwarf hunter Talin Keeneye in Coldridge Valley.",sec={{t="A Crowded Valley",b="Coldridge Valley is typically a quiet, protected training ground for young mountaineers and scholars of Ironforge. However, the wildlife often grows restless and overabundant in the harsh winter climate. Talin Keeneye, a veteran hunter stationed outside Anvilmar, notices that the aggressive small crag boars have multiplied so rapidly that they pose a genuine threat to anyone wandering the snow-covered trails.",sp=0},{t="Tending the Snows",b="Hunting is a cornerstone of dwarven life, providing meat, hide, and essential fieldcraft practice. Yet when game becomes a nuisance that attacks on sight, culling is required to restore balance. By trimming the crag boar numbers across the valley slopes, young adventurers prove their combat readiness while giving local hunters room to pursue their sport without getting overwhelmed.",sp=0}},faq={{q="Who is Talin Keeneye?",a="Talin Keeneye is a dwarven hunter stationed in Coldridge Valley, near Anvilmar. He spends his days tracking game in the snow and helps train novice adventurers in the practical realities of clearing hostile beasts.",al={"talin keeneye","who gives the boar hunter quest","boar hunter npc"},it="identity"},{q="Why are the crag boars such a problem?",a="The small crag boars in Coldridge Valley have grown unusually thick on the ground and attack anyone in sight without provocation. Their high numbers make ordinary travel and hunting dangerous for locals.",al={"why kill boars","boar problem coldridge","why are boars dangerous"},it="threat"},{q="Where can the crag boars be found?",a="Small crag boars roam the open snowy plains and lightly forested areas surrounding Anvilmar throughout Coldridge Valley.",al={"where are the boars","crag boar location","small crag boar map"},it="place",gp=true},{q="Does this quest connect to a larger threat in the valley?",a="No. Unlike the trogg infestations unsettling the dwarven outposts, this task is simply local wildlife management to keep the footpaths safe and let Talin hunt in peace.",al={"is there a follow up quest","boar hunter chain","story behind boars"},it="conflict"},{q="What makes crag boars suited to Dun Morogh?",a="Crag boars are tough, thick-hided swine built to endure the freezing temperatures of Dun Morogh. Their aggressive temperament and sharp tusks allow them to forage through frozen soil and fend off mountain predators.",al={"crag boar lore","dwarf boars","dun morogh wildlife"},it="origin"},{q="Why doesn't Talin Keeneye kill the boars himself?",a="Talin notes that there are so many aggressive boars that his leisurely hunts have become unpleasantly dangerous. He enlists eager new adventurers passing through Anvilmar to thin the pack so he can return to normal tracking.",al={"why does talin need help","talin lazy","why can't talin hunt them"},it="why_me"},{q="Why does Talin Keeneye want the small crag boars culled?",a="Talin Keeneye considers boar hunting a fine pastime, but the sheer number of small crag boars infesting Coldridge Valley has ruined his sport. Their aggressive nature and explosive numbers have made his daily routine perilous rather than leisurely. By thinning out a dozen of the beasts, you restore some safety to the valley so he can enjoy his hunting without constantly being swarmed.",al={"why kill boars","talin keeneye motive","why does talin need boars dead"},it="motive",add="aa61ef91"},{q="What are small crag boars and why are they in Coldridge Valley?",a="Small crag boars are the hardy native swine of Dun Morogh, naturally equipped with thick hides and fierce tempers to survive the frigid mountainous terrain. Coldridge Valley provides ample foraging along the snowy foothills, but lately their population has surged so dramatically that they roam everywhere, aggressively charging anyone who draws near.",al={"what are crag boars","why are boars here","small crag boars lore"},it="target",add="cf0c4f7e"}},ang={["race:Dwarf"]="Living in the mountains means sharing the land with fierce wildlife. Culling the belligerent crag boars around Anvilmar is a rite of passage for every young dwarf taking their first steps outside the forge.",["class:Hunter"]="Talin Keeneye embodies the straightforward dwarven attitude toward tracking: keep your aim true, respect the beasts, and clear the brush when game becomes overly hostile.",["race:Gnome"]="For gnome refugees newly arrived from Gnomeregan, facing Dun Morogh's ferocious wild boars is a harsh, practical introduction to life in the rugged dwarf country."},kw={"anvilmar","boar hunter","coldridge valley","crag boar","dun morogh","hunting","talin keeneye"},rel={"subzone:coldridge-valley","zone:dunmorogh"},m={start="Talin Keeneye",level="3",faction="Alliance",id=183},src={"The Boar Hunter"}}
E["quest:1879"] = {t="quest",n="Speak with Bink",z="dunmorogh",s="\"Speak with Bink\" is an Alliance summons directing novice mages from Dun Morogh to the capital city of Ironforge. Dispatched by Magis Sparkmantle, the call sends promising spellcasters to assist Bink, an arcane researcher working out of the Hall of Mysteries.",h="\"Speak with Bink\" is an Alliance summons directing novice mages from Dun Morogh to the capital city of...",sec={{t="A Colleague's Summons",b="Novice mages training in the cold crags of Dun Morogh eventually catch the eye of Magis Sparkmantle. Recognizing when an apprentice has outgrown the rudimentary exercises around Kharanos, Sparkmantle passes along word from his colleague, Bink. The request is specific and uncompromising: Bink requires an arcane specialist and refuses to trust the matter to anyone who cannot wield magic.",sp=0},{t="The Hall of Mysteries",b="The assignment carries young mages into Ironforge's Mystic Ward, where scholars, priests, and arcanists convene beneath the soaring stone vaults of the Hall of Mysteries. Here Bink conducts her studies, evaluating arriving apprentices with sharp-eyed scrutiny. In her view, raw potential is merely a beginning; an undisciplined spellcaster quickly becomes a hazard rather than an asset in arcane matters.",sp=0}},faq={{q="Who gives this quest?",a="Magis Sparkmantle offers the quest to novice Alliance mages who have advanced their early training in Dun Morogh.",al={"quest giver","where to start","who starts speak with bink"},it="identity"},{q="Where can I find Bink?",a="Bink resides in the Hall of Mysteries, located within the Mystic Ward in the northern district of Ironforge.",al={"bink location","where is bink","find bink"},it="place",gp=true},{q="Why does Bink only want a mage?",a="Bink is undertaking research that deals directly with arcane energies and sensitive monitoring equipment. She considers non-mages ill-suited to handle the magical nuances and dangers involved.",al={"why mages only","mage requirement","bink only wants mages"},it="motive"},{q="What happens after meeting Bink?",a="Upon greeting you and assessing your abilities, Bink enlists your help with her research, continuing into the quest 'Mage-tastic Gizmonitor'.",al={"next quest","bink follow up","what comes after speak with bink"},it="next_step"},{q="Is this quest available to classes other than mages?",a="No. This quest is exclusively tailored for mages as a transition from local novice training into specialized capital city assignments.",al={"can other classes do this","is this mage only","mage specific"},gp=true},{q="What is the Hall of Mysteries?",a="The Hall of Mysteries is Ironforge's center for arcane and holy study, housing trainers, scholars, and researchers representing the magical arts of both dwarves and gnomes.",al={"ironforge hall of mysteries","what is hall of mysteries"},it="place"},{q="Why does Magis Sparkmantle send you to Bink?",a="Magis Sparkmantle is a gnome mage trainer stationed in Kharanos who serves as a mentor for rising spellcasters. His colleague in Ironforge, Bink, specifically sent word requesting an adept mage for an important undertaking. Recognizing your growing mastery over the arcane, Magis directs you into the dwarven capital to answer her call and further your magical training.",al={"why magis sends you","magis sparkmantle motive","why talk to bink"},it="motive",add="96ce9827"}},ang={["class:Mage"]="This summons marks your departure from introductory valley training into the broader affairs of Ironforge's academic arcanists.",["race:Gnome"]="Bink and Magis Sparkmantle represent the continuation of gnomish arcane tradition within the hospitable halls of Ironforge following the loss of Gnomeregan.",["faction:Alliance"]="The shared study within the Hall of Mysteries showcases the close integration of gnomish intellect and dwarven hospitality under the Alliance banner."},kw={"bink","dun morogh","hall of mysteries","ironforge","mage","magis sparkmantle","mystic ward"},rel={"npc:bink","npc:magis-sparkmantle","subzone:hall-of-mysteries","subzone:mystic-ward","zone:ironforge","zone:dunmorogh","topic:gnome"},m={start="Magis Sparkmantle",["end"]="Bink",level="10",faction="Alliance",id=1879},src={"Speak with Bink"}}
E["quest:2160"] = {t="quest",n="Supplies to Tannok",z="dunmorogh",s="Supplies to Tannok is an errand entrusted to fledgling adventurers departing Coldridge Valley through the dangerous mountain pass into greater Dun Morogh. The gnome tinkerer Hands Springsprocket sends a crate of needed provisions to Tannok Frosthammer at the Thunderbrew Distillery inn in Kharanos, bypassing the trogg-infested trails that have severed routine trade.",h="Supplies to Tannok is an errand entrusted to fledgling adventurers departing Coldridge Valley through the...",sec={{t="A Blockaded Valley",b="Coldridge Valley is traditionally the proving ground and sanctuary for young Ironforge dwarves and exiled Gnomeregan survivors, but recent events have strained its connection to the rest of Dun Morogh. Trogg incursions have overrun Coldridge Pass, leaving the mountain defile perilous to cross. Mountaineers are spread thin guarding settlements and defensive perimeters, delaying scheduled supply escorts for days on end.",sp=0},{t="Hands and the Innkeeper's Assistant",b="Hands Springsprocket, a gnome staying in Anvilmar, found himself saddled with a crate of vital inn supplies meant for Kharanos without any safe way to deliver it personally. Recognizing that hearty adventurers are already preparing to brave the perilous pass, he enlists outward-bound travelers to carry the cargo to Tannok Frosthammer, the assistant at the bustling Thunderbrew inn.",sp=0},{t="A Welcoming Hearth in Kharanos",b="Reaching Kharanos marks an adventurer's entry into the broader world of Dun Morogh. Tannok Frosthammer eagerly receives the delivery, noting that word from Anvilmar has been scarce ever since the troggs disrupted travel through the pass. Delivering the goods restores a fragile line of communication and trade between the two isolated dwarf communities.",sp=0}},faq={{q="Who is Hands Springsprocket?",a="Hands Springsprocket is an enterprising gnome stationed at Anvilmar in Coldridge Valley. Unable to traverse the dangerous mountain pass alone, he relies on capable travelers to transport goods to Kharanos.",al={"hands springsprocket","quest giver","who gives supplies to tannok"},it="identity"},{q="Who is Tannok Frosthammer?",a="Tannok Frosthammer is the innkeeper's assistant at the Thunderbrew Distillery in Kharanos. He helps manage local tavern logistics and receives incoming provisions sent from outposts like Anvilmar.",al={"tannok","tannok frosthammer","kharanos innkeeper assistant"},it="identity"},{q="Why can't Hands deliver the supplies himself?",a="The pass connecting Coldridge Valley to Kharanos has been overrun by hostile troggs. Hands is not equipped to fight his way through alone, and official Mountaineer escorts are heavily delayed.",al={"why can't hands deliver it","why need adventurer","why is the pass dangerous"},it="why_me"},{q="Where is the inn in Kharanos located?",a="Tannok Frosthammer is located inside the Thunderbrew Distillery, the large inn situated right in the center of Kharanos along the main road leading eastward toward Ironforge.",al={"where is tannok","thunderbrew distillery location","kharanos inn location"},it="place",gp=true},{q="What is inside the Crate of Inn Supplies?",a="The crate contains essential tavern sundries and provisions gathered in Anvilmar to replenish the stocks at the Thunderbrew inn in Kharanos.",al={"what is in the crate","crate of inn supplies"},it="item"},{q="Why is communication between Anvilmar and Kharanos cut off?",a="Troggs emerging from subterranean tunnels have flooded Coldridge Pass. Their aggressive presence has severed easy foot travel and regular dispatches between Coldridge Valley and the rest of Dun Morogh.",al={"why scarce word from anvilmar","trogg problem pass"},it="threat"},{q="Why does Hands Springsprocket want the supplies delivered to Kharanos?",a="Hands Springsprocket promised vital provisions to Tannok Frosthammer, the assistant at the Kharanos inn, but trogg attacks have shut down travel through the pass out of Coldridge Valley. With regular shipments stranded and Mountaineer escorts days away, Tannok is left waiting and worrying with dwindling supplies. Hands wants to honor his delivery and ensure the bustling Thunderbrew Distillery and inn stay stocked for road-weary travelers.",al={"why send supplies to tannok","hands springsprocket motive","why deliver crate of inn supplies"},it="motive",add="6d15a4f4"}},ang={["race:Dwarf"]="Carrying supplies from Anvilmar to Kharanos marks your rite of passage out of the sheltered valley and into service to the broader kingdom of Ironforge.",["race:Gnome"]="Helping Hands Springsprocket demonstrates the reliable cooperation between Gnomeregan exiles and their dwarven hosts in Dun Morogh.",["faction:Alliance"]="Restoring trade between isolated outposts keeps Ironforge's inland supply lines moving despite wild trogg incursions."},kw={"anvilmar","coldridge pass","hands springsprocket","kharanos","supplies to tannok","tannok frosthammer","thunderbrew","troggs"},rel={"npc:hands-springsprocket","npc:tannok-frosthammer","subzone:kharanos","subzone:anvilmar","topic:trogg","zone:dunmorogh"},m={start="Hands Springsprocket",["end"]="Tannok Frosthammer",level="5",faction="Alliance",id=2160},src={"Supplies to Tannok"}}
E["quest:218"] = {t="quest",n="The Stolen Journal",z="dunmorogh",s="The Stolen Journal is an early Alliance quest in Dun Morogh where Grelin Whitebeard tasks adventurers with entering the troll cave in Coldridge Valley to reclaim his stolen notebook. To recover it, you must defeat the formidable troll leader Grik'nir the Cold. Reclaiming the journal allows Grelin to finalize his appraisal of the troll threat within Coldridge Valley.",h="The Stolen Journal is an early Alliance quest in Dun Morogh where Grelin Whitebeard tasks adventurers with...",sec={{t="A Scholar's Lost Notes",b="Grelin Whitebeard has been observing the Frostmane trolls encroaching on Coldridge Valley, keeping detailed notes on their habits and sudden aggression. During the unrest, an unusually imposing troll made off with his personal journal and retreated into the depths of their den. For Grelin, the loss is not merely sentimental; the notebook contains the bulk of his reconnaissance, leaving his official assessment stalled until it is recovered from the cavern.",sp=0},{t="Confronting Grik'nir the Cold",b="The brute responsible for taking the journal is Grik'nir the Cold, a powerful Frostmane troll marked with distinctive body and facial paint who holds court in the heart of the valley's troll cave. Slaying Grik'nir breaks the immediate local leadership of the cave's trolls and secures Grelin's journal. With the leader dispatched, Grelin feels confident enough to report that the valley's troll situation is manageable, sending his finished findings on to his brother Senir.",sp=0}},faq={{q="Who took Grelin Whitebeard's journal?",a="The journal was taken by Grik'nir the Cold, a large Frostmane troll distinguished by strange markings on his skin and face who lurks deep within the troll cave.",al={"who stole the journal","who has grelin's journal","journal thief"},it="target"},{q="Where can Grik'nir the Cold be found?",a="Grik'nir the Cold is located inside the troll cave in the southern reaches of Coldridge Valley.",al={"where is griknir","grik'nir location","how to find grik'nir"},gp=true},{q="Why is the journal important to Grelin?",a="The journal holds Grelin Whitebeard's notes and findings regarding troll activity in Coldridge Valley. He needs it returned to assemble a complete report for his brother Senir.",al={"why does grelin want his journal","what is in grelin's journal"},it="item"},{q="What happens after you return the journal?",a="Once the journal is recovered, Grelin finishes his report assessing the troll situation in Coldridge Valley and asks you to courier his observations to his brother Senir Whitebeard at Kharanos.",al={"what is next after the stolen journal","stolen journal next quest"},sp=1,it="next_step"},{q="Are the Frostmane trolls driven out of Coldridge Valley after this?",a="Grelin believes the troll situation in Coldridge Valley is under control following Grik'nir's defeat, though the Frostmane remain an enduring threat across the broader mountain passes of Dun Morogh.",al={"are trolls defeated in coldridge","is coldridge safe from trolls"},it="conflict"},{q="Who is Senir Whitebeard?",a="Senir Whitebeard is Grelin's brother, an Alliance scout stationed outside Coldridge Valley near Kharanos who gathers intelligence on threats facing the kingdom.",al={"who is senir","grelin brother senir"},it="ties"},{q="Why does Grelin Whitebeard want this done?",a="Grelin is compiling an official report on the Frostmane threat in Coldridge Valley for his brother Senir. Without his journal, he cannot complete his notes or assess the safety of the valley, leaving local leaders without crucial intelligence on troll activity.",al={"why does grelin want his journal","grelin whitebeard motive","why recover grelin's journal"},it="motive",add="78f0c4e3"},{q="Why does Grelin need you to retrieve his journal?",a="Grelin is an observer rather than a frontline fighter, and the journal was carried deep into the troll cave of Coldridge Valley by a formidable troll brute. Having already witnessed your success fighting back the trolls in the valley, he turns to you to delve into the cave and handle the danger.",al={"why does grelin need me","why send an adventurer for the journal","why can't grelin get his own journal"},it="why_me",add="beb6a987"}},ang={["race:Dwarf"]="Clearing out Frostmane leadership in Coldridge Valley protects young dwarven recruits taking their first steps outside Anvilmar.",["race:Gnome"]="Gnomish refugees sheltering in Anvilmar rely on the safety of Coldridge Valley's passes as they regroup in dwarven territory.",["faction:Alliance"]="Suppressing the aggressive Frostmane tribe ensures that Dun Morogh's starting valleys remain secured against internal disruption."},kw={"coldridge valley","dun morogh","frostmane hold","frostmane troll","grelin whitebeard","grik'nir the cold","senir whitebeard","stolen journal"},rel={"npc:grelin-whitebeard","quest:182","quest:282","subzone:coldridge-valley","zone:dunmorogh","topic:troll"},m={start="Grelin Whitebeard",level="5",faction="Alliance",id=218,ri={"Grelin Whitebeard's Journal"}},src={"The Stolen Journal"}}
E["quest:233"] = {t="quest",n="Coldridge Valley Mail Delivery",z="dunmorogh",s="Coldridge Valley Mail Delivery is a simple courier task entrusted to recruits by Sten Stoutarm at Anvilmar. With mountain passes often choked with snow and troggs pressing nearby, carrying fresh correspondence out to the camps along the frozen lake keeps the valley's isolated defenders connected.",h="Coldridge Valley Mail Delivery is a simple courier task entrusted to recruits by Sten Stoutarm at Anvilmar.",sec={{t="A Courier in the Snow",b="Life in Coldridge Valley is secluded even in the calmest of seasons. When winter couriers successfully navigate the mountain pass with mail from the rest of Dun Morogh, the missives pile up quickly at Anvilmar. Sten Stoutarm, busy managing local supply concerns and security, relies on wandering recruits to carry these bundles down the western road rather than letting vital tidings languish in the hall.",sp=0},{t="Frontier Outposts",b="The intended recipient, Talin Keeneye, keeps watch by the frozen lake to the west, observing trogg movements and dangerous wildlife. Even out in the cold, word from Ironforge and surrounding outposts remains precious. However, mail sorting under harsh mountain conditions is rarely flawless, and letters bound for different scouts often travel together in a single bundle.",sp=0}},faq={{q="Who starts the mail delivery?",a="Sten Stoutarm gives you the delivery task outside Anvilmar. He has received a stack of letters freshly brought through the mountain pass but cannot spare the time to personally leave his duties to deliver them.",al={"quest giver","who gives coldridge valley mail delivery","sten stoutarm quest"},gp=true},{q="Where is Talin Keeneye located?",a="Talin Keeneye is camped to the west of Anvilmar, right alongside the road next to the frozen lake in Coldridge Valley.",al={"where is talin keeneye","talin keeneye location","finding talin keeneye"},gp=true},{q="Are all the letters in the stack actually for Talin?",a="No. When Talin sorts through the bundle, he discovers that one of the letters is addressed to Grelin Whitebeard, who is stationed nearby in the valley.",al={"is the mail all for talin","grelin whitebeard letter","misplaced mail"},sp=1},{q="Why does Sten need an adventurer to run the mail?",a="With Anvilmar actively dealing with trogg incursions and local threats, dwarven defenders like Sten are tied down with pressing logistical and defensive responsibilities. Passing travelers and young recruits provide the fastest way to get letters to outlying posts.",al={"why run mail","why doesnt sten deliver it","mail delivery duty"},it="why_me"},{q="Does this quest lead to other tasks?",a="Yes. Upon completing the delivery, Talin asks you to take the misdirected letter to Grelin Whitebeard in the second part of the mail delivery chain.",al={"next quest","mail chain","follow up to mail delivery"},sp=1,it="next_step",gp=true},{q="Where did the letters originally come from?",a="The letters came through the pass leading into Coldridge Valley, sent into the sheltered basin from the broader lands of Dun Morogh and Ironforge.",al={"where did mail come from","source of letters"},it="origin"},{q="Why does Sten Stoutarm want the letters delivered?",a="A fresh bundle of correspondence just arrived through the mountain pass, but Sten is tied down with his own duties at Anvilmar and cannot step away to run them out himself. Rather than let vital news and dispatches sit collecting dust while mountaineers out in the field wait for word, he relies on a helpful traveler to see them safely carried down the road.",al={"why deliver the letters","sten stoutarm motive","why send mail"},it="motive",add="bf556c8e"}},ang={["race:Dwarf"]="Carrying word between outposts highlights the communal grit of Ironforge dwarves, ensuring even far-flung valley scouts remain bound to their clans.",["race:Gnome"]="As guests and allies in Dun Morogh after Gnomeregan's fall, helping run communication lines reinforces trust with local dwarven defenders.",["faction:Alliance"]="Every outpost in Coldridge Valley plays a part in keeping Dun Morogh secure, making reliable correspondence essential for early military coordination."},kw={"anvilmar","coldridge valley","dun morogh","grelin whitebeard","mail delivery","sten stoutarm","talin keeneye"},rel={"npc:sten-stoutarm","npc:grelin-whitebeard","subzone:coldridge-valley","zone:dunmorogh"},m={start="Sten Stoutarm",["end"]="Talin Keeneye",level="3",faction="Alliance",id=233},src={"Coldridge Valley Mail Delivery"}}
E["quest:234"] = {t="quest",n="Coldridge Valley Mail Delivery",z="dunmorogh",s="This errand completes a courier run across the snowy drifts of Coldridge Valley. Passing the dispatch from mountaineer Talin Keeneye down the southeastern road ensures that Grelin Whitebeard stays connected to the dwarven capital.",h="This errand completes a courier run across the snowy drifts of Coldridge Valley.",sec={{t="A Link to the Mountain",b="Even in an isolated basin like Coldridge Valley, news and formal correspondence must travel. While Anvilmar serves as the administrative heart of the valley, field scouts and sentries stationed along the trails rely on foot couriers to relay dispatches between the high passes and Ironforge.",sp=0},{t="Word for Whitebeard",b="Grelin Whitebeard maintains a small camp down the road to the southeast of Talin Keeneye's post. Enduring freezing drifts and constant trogg harassment, veteran mountaineers stationed at these remote watchpoints depend on regular missives to stay informed of broader affairs across Dun Morogh and the kingdom beyond.",sp=0}},faq={{q="Who is Grelin Whitebeard?",a="Grelin Whitebeard is a dwarven veteran stationed at an outpost along the southeastern road of Coldridge Valley. He monitors the valley roads and keeps watch against local threats like encroaching troggs and beasts.",al={"grelin","grelin whitebeard info","who is grelin"},it="identity"},{q="Where did this letter originate?",a="The letter was dispatched from the dwarven capital of Ironforge. It was brought into Coldridge Valley and carried down the mountain passes by local runners and sentries before reaching its final recipient.",al={"where is letter from","ironforge letter","letter sender"},it="origin"},{q="Why is mail delivered by foot here?",a="Coldridge Valley is surrounded by sheer, frostbitten peaks and cut off from the main roads of Dun Morogh. Without gryphon routes directly reaching isolated field camps, trusted travelers and mountaineers carry dispatches between outposts by hand.",al={"why foot courier","why run mail","no mailboxes in coldridge"},it="purpose"},{q="Where is Grelin Whitebeard's camp located?",a="His camp is situated further down the southeastern road leading through Coldridge Valley, past the hunting and scouting grounds of the upper pass.",al={"where is grelin camp","grelin whitebeard location","find grelin"},it="place",gp=true},{q="Who handed off the letter to deliver to Grelin?",a="Talin Keeneye, an experienced hunter and scout stationed along the pass, handed the letter over after it had been brought out from the primary staging grounds near Anvilmar.",al={"who gave the letter","talin keeneye role","who starts quest"}},{q="What happens after Grelin receives his mail?",a="Once Grelin receives the news from Ironforge, he turns his focus to the pressing dangers menacing the valley, often directing recruits to assist with the local Frostmane troll and trogg incursions.",al={"what next after mail","grelin next quest","after mail delivery"},it="next_step"},{q="Why does Talin Keeneye want this done?",a="Talin Keeneye is stationed out in the cold along the road and knows Grelin Whitebeard has been waiting out at his camp without news. Having taken the dispatch from Anvilmar, Talin wants to ensure his fellow dwarf finally receives his correspondence from Ironforge rather than leaving him stranded and uninformed in the valley.",al={"why does talin need this delivered","talin keeneye motive","why send the letter to grelin"},it="motive",add="c573251b"},{q="Why does Talin Keeneye ask you to deliver the letter instead of taking it himself?",a="Talin Keeneye is stationed on watch along the road of Coldridge Valley, keeping an eye on the trails and local wildlife. Abandoning his post to hike all the way down to Grelin Whitebeard's camp would leave the pass unguarded, making a passing traveler like you the natural choice to carry the letter the rest of the way.",al={"why does talin need me","why cant talin deliver the letter","why me talin"},it="why_me",add="d47c3713"}},ang={["race:Dwarf"]="Every outpost in Dun Morogh counts on dispatches from King Magni's seat in Ironforge to keep the defenses of the realm coordinated.",["faction:Alliance"]="Reliable courier routes through treacherous snowy passes keep remote Alliance scouts supplied with orders and vital intelligence."},kw={"coldridge valley","courier","dun morogh","grelin whitebeard","ironforge","mail delivery","talin keeneye"},rel={"quest:233","npc:grelin-whitebeard","subzone:coldridge-valley","zone:dunmorogh","zone:ironforge"},m={start="Talin Keeneye",["end"]="Grelin Whitebeard",level="4",faction="Alliance",id=234},src={"Coldridge Valley Mail Delivery (2)"}}
E["quest:282"] = {t="quest",n="Senir's Observations",z="dunmorogh",s="Having gathered vital intelligence on local threats in Coldridge Valley, Grelin Whitebeard entrusts you with carrying his findings to his brother, Senir Whitebeard, out in Kharanos. However, leaving the sheltered valley requires passing through a tunnel recently overrun by hostile troggs, guarded by Mountaineer Thalos.",h="Having gathered vital intelligence on local threats in Coldridge Valley, Grelin Whitebeard entrusts you with...",sec={{t="A Courier for the Whitebeards",b="Grelin Whitebeard spent considerable effort documenting the troll activity stirring around Coldridge Valley. When his journal was pilfered and subsequently recovered, it became clear that the collected intelligence was far too critical to trust to an inexperienced apprentice. Looking to bypass intermediate hands, Grelin selects a seasoned adventurer to convey his report directly to his brother, Senir Whitebeard, who conducts operations outside the valley in Kharanos.",sp=0},{t="The Blocked Pass to Kharanos",b="Leaving Coldridge Valley is no longer a simple trek down the main road. The eastern tunnel connecting the valley to the wider snowy plateau of Dun Morogh has been violently overrun by burrowing troggs. To prevent unwary civilians from wandering into a deathtrap, the Ironforge guard has stationed Mountaineer Thalos just outside the passage. Only travelers carrying urgent, official business are granted leave to push past the sentry post and brave the subterranean gauntlet.",sp=0}},faq={{q="Who is Grelin sending this report to?",a="The report is addressed to Senir Whitebeard, Grelin's brother, who is stationed beyond the mountains in Kharanos assessing regional concerns.",al={"who gets report","senir whitebeard","report recipient"},it="purpose"},{q="Why can't Grelin's apprentice deliver the report?",a="Grelin intended to send his apprentice originally, but after the recent troubles with Frostmane trolls stealing his journal, he deemed the information too important to leave in inexperienced hands.",al={"why not apprentice","grelin apprentice"},it="why_me"},{q="Why is the tunnel out of Coldridge Valley guarded?",a="The tunnel connecting Coldridge Valley to the rest of Dun Morogh has been completely overrun by troggs. Mountaineer Thalos is stationed at the mouth to keep civilians safe until the way can be cleared.",al={"why thalos guarding","tunnel blocked","why is tunnel closed"},it="place"},{q="Where is Mountaineer Thalos located?",a="Thalos is stationed east of Anvilmar, standing watch right near the entrance to the tunnel that leads out of Coldridge Valley toward Kharanos.",al={"thalos location","where is thalos","find mountaineer thalos"},it="target",gp=true},{q="What allows you to pass through the trogg-infested tunnel?",a="Mountaineer Thalos will not let ordinary travelers into the tunnel, but carrying an urgent dispatch from Grelin Whitebeard proves your business is essential enough to risk the journey.",al={"pass through tunnel","tunnel permission"},it="item"},{q="What happens after speaking with Mountaineer Thalos?",a="Thalos provides warnings and guidance for traversing the dangerous subterranean route before clearing you to continue eastward toward Kharanos.",al={"next step","what after thalos"},it="next_step",gp=true},{q="Why does Grelin Whitebeard want this report delivered?",a="Grelin Whitebeard has been documenting the growing Frostmane troll activity and threats in Coldridge Valley. His brother, Senir Whitebeard, is stationed out in Kharanos gathering intelligence on wider troubles across Dun Morogh. Getting this report safely to Senir is vital for coordinating the defense of the region, especially now that the Frostmane are pushing closer to dwarven settlements.",al={"why send grelin report","grelin whitebeard motive","why deliver senirs observations"},it="motive",add="ba85e128"}},ang={["race:Dwarf"]="For dwarven mountaineers and recruits, passing through the eastern tunnel marks your first official deployment beyond the training grounds of Coldridge Valley.",["race:Gnome"]="As gnomish refugees living among the Bronzebeards, this dispatch offers a path out of the initial haven toward the wider issues gripping Dun Morogh.",["faction:Alliance"]="Maintaining secure passage between dwarven valleys is critical to the defense of Ironforge and the safety of Alliance couriers."},kw={"anvilmar","coldridge valley","grelin whitebeard","grelin's report","kharanos","mountaineer thalos","senir whitebeard","troggs","tunnel"},rel={"quest:218","npc:mountaineer-thalos","npc:grelin-whitebeard","subzone:kharanos","subzone:anvilmar","zone:dunmorogh","topic:trogg","quest:182"},m={start="Grelin Whitebeard",["end"]="Mountaineer Thalos",level="5",faction="Alliance",id=282},src={"Senir's Observations"}}
E["quest:287"] = {t="quest",n="Frostmane Hold",z="dunmorogh",s="Frostmane Hold is an Alliance recon mission assigned by Senir Whitebeard in Kharanos. Having tracked the hostile Frostmane trolls to their heavily guarded cavern stronghold near Iceflow Lake, Senir enlists adventurous scouts to brave the interior, eliminate their headhunters, and supply vital intel for his scouting reports.",h="Frostmane Hold is an Alliance recon mission assigned by Senir Whitebeard in Kharanos.",sec={{t="A Scout Behind Schedule",b="Stationed in Kharanos, mountaineer and scout Senir Whitebeard was tasked with monitoring the encroaching Frostmane troll threat across Dun Morogh. While he successfully traced the aggressive tribes back to their primary cavern dwelling southwest of Brewnall Village, the sheer volume of armed trolls gave him pause. Reluctant to step foot inside alone and falling severely behind on his official reports, Senir hires passing adventurers to venture into the icy recesses on his behalf.",sp=0},{t="Breaching the Cavern",b="The stronghold sits carved into the western peaks overlooking Iceflow Lake, a freezing redoubt packed with hostile ice trolls. To fulfill Senir's mission, scouts must fight their way deep through the subterranean tunnels, cull the fierce Frostmane Headhunters stationed along the ledges, and map the interior layout. Surviving the delve provides the critical intelligence Senir requires to finalize his findings for Ironforge's military commanders.",sp=0}},faq={{q="Where is Frostmane Hold located?",a="Frostmane Hold is a cavern situated southwest of Brewnall Village on the far western side of Dun Morogh. From Kharanos, take the road north to the bridge, follow the frozen river west past Iceflow Lake to Brewnall Village, and head southwest up into the mountains.",al={"find frostmane hold","where is the cave","frostmane hold location"},it="place",gp=true},{q="Who is Senir Whitebeard?",a="Senir Whitebeard is a dwarven scout stationed outside the Thunderbrew Distillery in Kharanos. He tracks local threats across Dun Morogh and compiles strategic intelligence reports regarding the aggressive Frostmane trolls.",al={"senir whitebeard","who gives quest","quest giver kharanos"},it="identity"},{q="Why didn't Senir explore the hold himself?",a="Senir scouted out the entrance and discovered where the tribe was concentrating, but found the cave swarming with so many armed trolls that he was afraid to enter alone. Worried about his safety and running late on his scouting deadlines, he delegates the hazardous recon to capable adventurers.",al={"why is senir scared","why didn't senir go"},it="why_me"},{q="Who are the Frostmane trolls?",a="The Frostmane are an indigenous tribe of ice trolls native to the snowy crags of Dun Morogh. Bitter enemies of the Ironforge dwarves and gnomes, they frequently raid trade routes, camps, and settlements from hidden encampments throughout the region.",al={"frostmane","trolls dun morogh","dun morogh trolls"},it="threat"},{q="What happens after completing the recon of the hold?",a="Once you return with news of the hold's layout and casualties among their headhunters, Senir finishes writing his report and promptly asks you to deliver the urgent paperwork to Senir's superiors in Dun Morogh.",al={"next quest","what after frostmane hold","the reports quest"},sp=1,it="next_step",gp=true},{q="How deep into the cave do you have to go?",a="You need to advance well past the threshold and into the interior chambers until the cave layout is scouted and five Frostmane Headhunters are slain, confirming the cavern's depths have been thoroughly investigated.",al={"fully explore frostmane hold","cave exploration trigger"},gp=true},{q="Why does Senir Whitebeard want Frostmane Hold explored?",a="Senir Whitebeard is an operative working on intelligence reports regarding Dun Morogh's mounting threats. He fell behind on his scouting duties and needs firsthand information on the Frostmane troll encampment to complete his assessment for Ironforge command before his superiors take note.",al={"why does senir want this done","senir whitebeard motive","why scout frostmane hold"},it="motive",add="889a57f0"},{q="Why are you sent against the Frostmane Headhunters?",a="The Frostmane Headhunters form the militant defense of Frostmane Hold, the deep caverns southwest of Brewnall Village where the displaced trolls have massed in force. Killing them thins their patrols and clears a path to properly scout the cavern's depths.",al={"who are frostmane headhunters","why kill headhunters","frostmane headhunters purpose"},it="target",add="860fac70"}},ang={["race:Dwarf"]="The Frostmane trolls contest Ironforge's dominance in the snowy peaks of Dun Morogh; scouting their primary cavern stronghold is critical for the realm's defense.",["race:Gnome"]="With gnomes settled throughout Dun Morogh and Kharanos after the fall of Gnomeregan, curbing the Frostmane troll offensive keeps fragile refugee supply corridors safe.",["faction:Alliance"]="Securing Dun Morogh ensures the mountain roads linking Ironforge to neighboring kingdoms remain free from hostile tribal ambushes."},kw={"brewnall village","dun morogh","frostmane headhunter","frostmane hold","ice trolls","iceflow lake","kharanos","senir whitebeard","the reports"},rel={"npc:senir-whitebeard","quest:291","subzone:kharanos","subzone:brewnall-village","subzone:iceflow-lake","zone:dunmorogh","topic:troll"},m={start="Senir Whitebeard",level="9",faction="Alliance",id=287},src={"Frostmane Hold (quest)"}}
E["quest:308"] = {t="quest",n="Distracting Jarven",z="dunmorogh",s="Down in the cellar of Thunderbrew Distillery, guard Jarven Thunderbrew finds himself surrounded by barrels he is forbidden to touch. Craving a taste of the family craft, he asks a passing adventurer for a mug of Thunder Ale to help sharpen his wits on duty.",h="Down in the cellar of Thunderbrew Distillery, guard Jarven Thunderbrew finds himself surrounded by barrels he...",sec={{t="A Thirsty Guard on Duty",b="Jarven Thunderbrew is tasked with keeping watch over the deep stores of Thunderbrew Distillery in Kharanos. Despite being surrounded by the finest stout in Dun Morogh, he works under strict family orders not to dip into the stock while on guard. The temptation proves too much, prompting him to enlist passing travelers to fetch him a pint of potent Thunder Ale from the taps upstairs.",sp=0},{t="A Dubious Sharpener",b="Jarven insists that a good drink will only hone his senses and bolster his watch. Whether indulging a guard on duty is wise remains an open question, but among the hardy dwarves of Dun Morogh, few can fault a Thunderbrew for wanting a taste of his own kin's world-famous brew.",sp=0}},faq={{q="Who is Jarven Thunderbrew?",a="Jarven is a member of the renowned Thunderbrew family, stationed downstairs in the cellar of the Thunderbrew Distillery in Kharanos to watch over the stored casks.",al={"who is jarven","jarven lore","guard in cellar"},it="identity"},{q="Why does Jarven need someone to bring him ale?",a="Jarven is under strict orders from his family not to drink from the cellar stock while on watch. To skirt the rules without breaking into the sealed casks, he asks an outsider to bring him a fresh mug from upstairs.",al={"why cant jarven drink","jarven ale quest","why fetch booze"},it="why_me"},{q="Where is Thunder Ale found?",a="Thunder Ale is served right upstairs in the main taproom of Thunderbrew Distillery in Kharanos, sold by the innkeeper and bartenders.",al={"get thunder ale","where is thunder ale","buy thunder ale"},it="place",gp=true},{q="Where is the Thunderbrew Distillery located?",a="The distillery serves as the bustling central inn of Kharanos, nestled in the snowy heart of Dun Morogh just down the mountain from Ironforge.",al={"kharanos distillery","thunderbrew cellar location","where is jarven"},it="place"},{q="Why is Thunderbrew ale so famous?",a="Crafted by the Thunderbrew clan, their stout and ales are legendary across Khaz Modan and beyond for their exceptional punch, flavor, and dwarven kick.",al={"thunderbrew reputation","what is thunder ale"},it="fame"},{q="Does getting Jarven drunk cause any trouble?",a="Jarven claims the ale sharpens his wits rather than dulling them, though it certainly keeps his attention off anyone poking around the lower storage.",al={"jarven drunk consequences","what happens after distracting jarven"},it="conflict"},{q="Why does Jarven Thunderbrew want a cask of Thunder Ale?",a="Jarven is stationed guarding the cellars surrounded by barrels of dwarven spirits, but strict orders forbid him from tapping into any of the stock in his care. Craving a drink to sharpen his wits and pass the long watch, he needs someone discreet to slip him a taste of Thunderbrew's finest brew so he can indulge without openly breaking discipline.",al={"why does jarven want ale","jarven motive","why jarven drink"},it="motive",add="a200e5d8"},{q="What is the Thunder Ale used for?",a="The cask of Thunder Ale serves as a potent personal refreshment to satisfy Jarven Thunderbrew's thirst. While on guard duty deep in the distillery cellars, he relies on you to fetch it from the taps above so he can drink without abandoning his post or tampering with the stored reserves.",al={"what is thunder ale for","thunder ale use","why get thunder ale"},it="item",add="8c39bfa0"}},ang={["race:Dwarf"]="Every dwarf understands the agony of standing guard beside casks of legendary ale without being allowed a single swallow.",["class:Rogue"]="Keeping a watchman distracted with strong liquor is an age-old trick of the trade, even if Jarven happily asks for the distraction himself."},kw={"cellar","distillery","distracting jarven","dun morogh","jarven thunderbrew","kharanos","thunder ale"},rel={"zone:dunmorogh"},m={start="Jarven Thunderbrew",level="7",faction="Alliance",id=308,ri={"Thunder Ale"}},src={"Distracting Jarven"}}
E["quest:310"] = {t="quest",n="Bitter Rivals",z="dunmorogh",s="Bitter Rivals is an early Alliance quest in Dun Morogh born from the fierce competition between two proud dwarven brewing families. Marleth Barleybrew sends an adventurer to infiltrate the Thunderbrew Distillery in Kharanos and tamper with their rival's stock.",h="Bitter Rivals is an early Alliance quest in Dun Morogh born from the fierce competition between two proud...",sec={{t="A Taste of Competition",b="Few things in Khaz Modan stir passions as quickly as a pint of ale. The Barleybrews have long bristled under the shadow of the famed Thunderbrew Distillery in Kharanos. While Marleth Barleybrew begrudgingly concedes that Thunderbrew craft is respectable, she cannot stomach the notion that it is the only renowned vintage in Dun Morogh. To shake up the local palate, she devises a plan to swap a cask of Thunder Ale with her own fiery concoction, Barleybrew Scalder.",sp=0},{t="Cellar Subterfuge",b="Carrying out the scheme requires slipping directly beneath the noses of Kharanos patrons. Beneath the kitchen of the distillery lies the basement storeroom where aging casks await tapping. Because the Thunderbrews keep a guard posted near their most prized reserve, a would-be saboteur must find a way to lure the watchman away before secretly substituting the barrels.",sp=0}},faq={{q="Who gives the quest Bitter Rivals?",a="Marleth Barleybrew gives the quest. She is determined to prove that her family's craft can rival the renowned drinks poured at the Thunderbrew Distillery.",al={"who starts bitter rivals","marleth quest starter"},gp=true},{q="Where is the Thunderbrew cellar located?",a="The cellar is beneath the Thunderbrew Distillery in the town of Kharanos. The stairs leading down are tucked away behind a table in the kitchen.",al={"where is thunderbrew basement","how to get to distillery cellar"},it="place",gp=true},{q="What is Barleybrew Scalder?",a="Barleybrew Scalder is Marleth Barleybrew's potent house ale. She believes that if patrons in Kharanos taste it under the guise of Thunder Ale, they will finally recognize her brewing superiority.",al={"barleybrew scalder","what brew do i swap"},it="item"},{q="How do you bypass the guard watching the barrels?",a="The Thunderbrew guard posted down in the basement will drop hints about what might draw his attention away, giving you just enough time to swap the barrels while he is distracted.",al={"cellar guard distraction","unguarded thunder ale barrel","guard barrel"},gp=true},{q="Why are the Barleybrews and Thunderbrews feuding?",a="It is a matter of professional dwarven pride. The Thunderbrews dominate the local tavern scene in Kharanos, and the Barleybrews want to prove that their own recipes are just as good, if not better.",al={"brewer feud","why barleybrew hate thunderbrew"},it="conflict"},{q="What quest follows Bitter Rivals?",a="Once the cask of Barleybrew Scalder is in place, the quest leads directly into Return to Marleth to report your success.",al={"next quest after bitter rivals","what comes after bitter rivals"},it="next_step",gp=true},{q="Why does Marleth Barleybrew want to switch the ale barrels?",a="Marleth Barleybrew is locked in a fierce, long-standing competition with the Thunderbrew clan over who crafts Dun Morogh's finest ale. While she begrudgingly admits that the Thunderbrews make a decent drink, she cannot stand their boasting and wants to prove that her own Barleybrew Scalder is superior. By slipping her keg into the Thunderbrew Distillery's cellar, she hopes their own loyal patrons will drink it, realize how good it is, and knock the Thunderbrews down a peg.",al={"why swap barrels","marleth motive","why switch the brew"},it="motive",add="6a423fcc"},{q="Why does Marleth Barleybrew need you instead of doing it himself?",a="Marleth is far too recognizable in Kharanos to wander into his rival's basement unnoticed. The Thunderbrew Distillery keeps a close watch on its cellar, and any appearance by a known Barleybrew would instantly raise an alarm. As an unfamiliar traveler, you can slip into the distillery, find a way past the cellar guard, and swap the barrels without immediately blowing the whole scheme.",al={"why cant marleth do it","why me bitter rivals","why hire an outsider"},it="why_me",add="c3ae0653"}},ang={["race:Dwarf"]="For dwarves, brewing is serious business that rivals blacksmithing in prestige. Getting involved in a cellar feud over rival ales feels right at home in the snows of Dun Morogh.",["class:Rogue"]="Infiltrating a guarded cellar, distracting the sentry, and pulling a stealthy switch of contraband is familiar work for any rogue, even if the prize is beer instead of gold.",["faction:Alliance"]="Kharanos is the cultural and logistical hub of Dun Morogh for Alliance travelers, making local inn disputes a frequent diversion for passing recruits."},kw={"barleybrew scalder","bitter rivals","dun morogh","kharanos","marleth barleybrew","thunder ale","thunderbrew distillery"},rel={"quest:311","npc:marleth-barleybrew","subzone:thunderbrew-distillery","subzone:kharanos","quest:117","zone:dunmorogh"},m={start="Marleth Barleybrew",["end"]="Unguarded Thunder Ale Barrel",level="6",faction="Alliance",id=310},src={"Bitter Rivals"}}
E["quest:3106"] = {t="quest",n="Simple Rune",z="dunmorogh",s="Simple Rune is an introductory task given to novice dwarven warriors in Coldridge Valley. Passed along by Sten Stoutarm on behalf of the warrior trainer Thran Khorman, it directs fresh recruits inside Anvilmar to begin their martial training.",h="Simple Rune is an introductory task given to novice dwarven warriors in Coldridge Valley.",sec={{t="A Summons to the Anvil",b="As young recruits clear pests and prove their grit around Coldridge Valley, veteran scouts keep a watchful eye out for promising fighters. Sten Stoutarm delivers an inscribed stone—a simple rune—handed off to him by Thran Khorman. This summons calls martial hopefuls from the snowy valley paths into the warm forge-hall of Anvilmar to formally pledge themselves to the warrior's trade.",sp=0},{t="A Changing Dun Morogh",b="Reporting to Thran offers an immediate glimpse into the harsh realities facing modern Dun Morogh. The veteran trainer speaks frankly about the kingdom's shifting landscape: displaced gnomes seeking refuge after catastrophic explosions destroyed Gnomeregan, fellow dwarves wielding foreign arcane arts or taking up human devotion to the Holy Light, and an ever-present menace of subterranean troggs clawing at the mountain borders. In Thran's eyes, solid martial discipline remains the bedrock required to withstand it all.",sp=0}},faq={{q="What is the Simple Rune?",a="The Simple Rune is a small, inscribed slate passed along by Sten Stoutarm on behalf of Thran Khorman. It serves as an official invitation and instruction for new warriors to report indoors for professional training.",al={"simple rune item","what does the rune do","simple rune lore"}},{q="Who is Thran Khorman?",a="Thran Khorman is the resident warrior trainer stationed inside Anvilmar in Coldridge Valley. He mentors fledgling dwarven and gnomish warriors, instructing them in the fundamentals of melee combat, discipline, and dwarven tenacity.",al={"who is thran","thran khorman lore","warrior trainer coldridge"}},{q="Why are gnomes living in Dun Morogh and Ironforge?",a="The gnomes were recently driven from their subterranean technological marvel, Gnomeregan, after setting off catastrophic radiation explosives in a desperate bid to repel a subterranean trogg invasion. The survivors fled up the mountainside to seek refuge with their dwarven allies in Ironforge.",al={"why are gnomes here","gnomes in ironforge","gnomeregan refugees"}},{q="Why does Thran mention troggs?",a="Troggs are primitive, vicious creatures that recently breached the surface caves in Coldridge Valley and Dun Morogh after being disturbed deep underground. They pose an immediate danger to local settlements and trade routes, requiring armed vigilance from defenders in Anvilmar.",al={"trogg threat","why are troggs around","coldridge troggs"}},{q="What does Thran mean about dwarves worshipping the Holy Light?",a="Traditionally bound to ancestral mountain traditions and titan reverence, dwarves have increasingly embraced the philosophy of the Holy Light through centuries of close cultural alliance with human kingdoms like Lordaeron and Stormwind, training their own paladins and priests.",al={"dwarves and holy light","dwarf paladins lore","dwarf priests"}},{q="Where do I take the Simple Rune?",a="The rune is taken directly to Thran Khorman, who stands by the training grounds inside the great bunker hall of Anvilmar, just up the path in Coldridge Valley.",al={"where to turn in simple rune","where is thran khorman","find thran"}}},ang={["class:Warrior"]="This rune marks a warrior's formal entrance into martial discipline, directing new blades and bludgeons directly to Thran Khorman in Anvilmar.",["race:Dwarf"]="Thran Khorman takes immense pride in teaching dwarven recruits how to fight with traditional grit, anchoring their culture in steel and iron amidst a rapidly changing world.",["race:Gnome"]="Having lost Gnomeregan to troggs and radiation, gnomish fighters starting in Coldridge Valley must learn frontline warfare alongside dwarven mentors to survive exile.",["faction:Alliance"]="Coldridge Valley serves as the initial training ground for mountain forces defending the Alliance's southern Khaz Modan approaches."},kw={"anvilmar","coldridge valley","dun morogh","ironforge","simple rune","sten stoutarm","thran khorman","troggs","warrior"},rel={"npc:thran-khorman","npc:sten-stoutarm","subzone:anvilmar","subzone:coldridge-valley","zone:dunmorogh","topic:dwarf","topic:gnome","topic:trogg"},m={start="Sten Stoutarm",["end"]="Thran Khorman",level="1",faction="Alliance",id=3106},src={"Simple Rune (Classic)"}}
E["quest:3107"] = {t="quest",n="Consecrated Rune",z="dunmorogh",s="The Consecrated Rune is an introductory summons delivered to fledgling dwarven paladins in Coldridge Valley. Passed along by Sten Stoutarm on behalf of Bromos Grummner, it marks an initiate's formal induction into the Knights of the Silver Hand.",h="The Consecrated Rune is an introductory summons delivered to fledgling dwarven paladins in Coldridge Valley.",sec={{t="A Summons to Anvilmar",b="While novice adventurers clear out troggs and wolves around Coldridge Valley, the local leaders keep a close eye on those who display a gift for divine martial prowess. Sten Stoutarm delivers this inscribed rune to young paladins, instructing them to seek out Bromos Grummner inside the warmth of Anvilmar. It serves as both an invitation and an official notice that raw potential must now be tempered with discipline.",sp=0},{t="Dwarves and the Holy Light",b="Though the Knights of the Silver Hand originated among the humans of Lordaeron, Ironforge dwarves embraced the philosophy of the Holy Light with fierce devotion. Bromos Grummner welcomes initiates into the brotherhood, reminding them that dwarven paladins now share the solemn duty of protecting Azeroth. Grounded in sacrifice, tradition, and martial virtue, the order demands that recruits take up hammer and faith in equal measure.",sp=0}},faq={{q="What is the Consecrated Rune?",a="It is an inscribed token delivered to novice dwarven paladins in Coldridge Valley, instructing them to report to Bromos Grummner inside Anvilmar for formal training.",al={"consecrated rune item","what does the rune do","paladin rune coldridge"}},{q="Who is Bromos Grummner?",a="Bromos Grummner is the resident paladin trainer stationed in Anvilmar. He instructs new dwarven members of the Knights of the Silver Hand and prepares them for the perils threatening Dun Morogh.",al={"who is bromos","paladin trainer anvilmar","bromos grummner lore"}},{q="Why are dwarves part of the Knights of the Silver Hand?",a="During the Second War and its aftermath, human priests and paladins introduced the tenets of the Holy Light to the dwarves of Ironforge. Dwarves deeply respect the order's martial discipline and willingness to sacrifice for the defense of Azeroth.",al={"dwarf paladin lore","why do dwarves have paladins","silver hand dwarves"}},{q="Who gives you the Consecrated Rune?",a="Sten Stoutarm passes the rune to you outside Anvilmar after you assist him with local tasks, noting that Bromos Grummner asked for it to be delivered.",al={"where do i get the rune","who hands you the rune"}},{q="Where is Bromos Grummner located?",a="Bromos Grummner can be found inside the great hall of Anvilmar in Coldridge Valley, standing alongside other class mentors.",al={"bromos location","where is bromos","find bromos grummner"}},{q="What happens after presenting the rune to Bromos?",a="Bromos acknowledges your acceptance into the Silver Hand and offers your first formal combat and holy training before sending you back out into Dun Morogh.",al={"what comes next","after consecrated rune"}}},ang={["class:Paladin"]="This rune marks your first formal step into the Knights of the Silver Hand, establishing your duty to channel the Light in defense of Ironforge.",["race:Dwarf"]="Dwarven paladins combine traditional dwarven fortitude with human-taught theology, bringing stalwart resolve to the teachings of the Holy Light."},kw={"anvilmar","bromos grummner","coldridge valley","consecrated rune","holy light","paladin trainer","silver hand","sten stoutarm"},rel={"npc:bromos-grummner","npc:sten-stoutarm","subzone:anvilmar","subzone:coldridge-valley","topic:light","zone:dunmorogh"},m={start="Sten Stoutarm",["end"]="Bromos Grummner",level="1",faction="Alliance",id=3107},src={"Consecrated Rune (Classic)"}}
E["quest:3108"] = {t="quest",n="Etched Rune",z="dunmorogh",s="The Etched Rune is a written summons delivered to novice dwarven hunters assisting the guard in Coldridge Valley. Passed on by Sten Stoutarm, the inscribed stone directs fledgling trackers to seek out Thorgas Grimson inside Anvilmar to formally begin their martial and wilderness training.",h="The Etched Rune is a written summons delivered to novice dwarven hunters assisting the guard in Coldridge...",sec={{t="A Summons in Stone",b="While helping Sten Stoutarm deal with nearby threats around Coldridge Valley, promising dwarven hunters are handed an inscribed stone tablet known as the Etched Rune. Rather than delivering spoken orders or simple parchment, dwarven mentors favor carved runes to impart formal missives. The rune instructs the recipient to take stock of their early work and present themselves indoors at Anvilmar for deeper instruction in the art of the hunt.",sp=0},{t="Traditions of the Dun Morogh Hunter",b="Presenting the rune to Thorgas Grimson marks a hunter's entry into formal discipline. Thorgas stresses that mountaineering and survival in Khaz Modan demand deep respect for the harsh environment: reading tracks in bitter snowdrifts, maintaining one's weapon and ammunition, and understanding the wild beasts that roam the crags. The etched stone serves as the hunter's first step from a lone wanderer with a gun into an apprentice of Anvilmar's veteran pathfinders.",sp=0}},faq={{q="What is the Etched Rune?",a="It is an inscribed stone tablet passed to novice hunters in Coldridge Valley, serving as a written invitation to seek out formal training with Thorgas Grimson inside Anvilmar.",al={"what is etched rune","etched rune item","rune meaning"}},{q="Who sends the Etched Rune?",a="The hunter trainer Thorgas Grimson sends it, though it is physically handed to you by mountaineer Sten Stoutarm once you have proven your basic competence outside Anvilmar.",al={"who gave me etched rune","sender etched rune"}},{q="Where do I take the Etched Rune?",a="You bring it to Thorgas Grimson, who can be found inside the great hall of Anvilmar in Coldridge Valley.",al={"where do i go","who do i turn it in to","thorgas location"}},{q="Why do dwarves use runes instead of letters?",a="Dwarven culture places high value on stonework, tradition, and enduring craft. Inscribing missives and sacred instructions on stone runes ensures they survive the bitter winds and harsh elements of Dun Morogh far better than fragile parchment.",al={"why an etched rune","dwarf runes lore"}},{q="What happens after presenting the rune to Thorgas Grimson?",a="Thorgas welcomes you into the ranks of dwarven trackers, explaining the core tenets of surviving in the frozen crags, maintaining your gear, and respecting the beasts of the wild before offering you training in basic hunter techniques.",al={"what does thorgas teach","turn in etched rune"}},{q="Can any class receive the Etched Rune?",a="No. The Etched Rune is given specifically to dwarf hunters starting their journey in Coldridge Valley. Other classes receive their own distinct recruitment tokens directing them to their respective mentors in Anvilmar.",al={"is etched rune hunter only","can warriors get etched rune"}}},ang={["class:Hunter"]="This rune initiates your journey as a hunter in Dun Morogh, introducing you to Thorgas Grimson and the foundational dwarven traditions of tracking, weapon care, and wilderness survival.",["race:Dwarf"]="Carving messages into solid stone reflects the long-standing dwarven reverence for enduring craft, even for everyday summons and field instructions."},kw={"anvilmar","coldridge valley","dun morogh","dwarf","etched rune","hunter","sten stoutarm","thorgas grimson"},rel={"npc:thorgas-grimson","npc:sten-stoutarm","subzone:anvilmar","subzone:coldridge-valley","zone:dunmorogh"},m={start="Sten Stoutarm",["end"]="Thorgas Grimson",level="1",faction="Alliance",id=3108},src={"Etched Rune (Classic)"}}
E["quest:3109"] = {t="quest",n="Encrypted Rune",z="dunmorogh",s="The Encrypted Rune is a coded missive delivered to aspiring rogues taking their first steps in Coldridge Valley. Passed along by Sten Stoutarm, the etched message directs promising shadows into Anvilmar to report to the rogue trainer, Solm Hargrin.",h="The Encrypted Rune is a coded missive delivered to aspiring rogues taking their first steps in Coldridge...",sec={{t="A Message in Code",b="While assisting Sten Stoutarm out in the snowy passes of Coldridge Valley, sharp-eyed rogues receive a curious etched stone. Sten admits the piece was slipped to him to hand over, suspecting it came directly from Solm Hargrin. Rather than shouting out across the courtyard for potential scouts and scoundrels, Solm uses an encrypted rune to test a novice's discretion and summon them indoors.",sp=0},{t="Under Anvilmar's Rafters",b="Inside Anvilmar, Solm Hargrin welcomes newly arrived operatives to the craft. He offers to teach the maneuvers, strikes, and subtle arts that keep an operative breathing and lining their pockets with coin. Beyond sharpening their daggers, Solm reminds dwarven rogues to look out for their displaced gnomish allies, who are still recovering from the catastrophic fall of Gnomeregan.",sp=0}},faq={{q="Who sends the Encrypted Rune?",a="The rune is authored by Solm Hargrin, the rogue trainer stationed inside the great hall of Anvilmar. He has Sten Stoutarm discreetly pass it along to promising recruits out in the snow.",al={"who wrote the rune","encrypted rune sender","who gave sten the rune"}},{q="Where do I find Solm Hargrin?",a="Solm Hargrin is located inside the main hall of Anvilmar, the stone bastion at the center of Coldridge Valley in Dun Morogh.",al={"where is solm","solm hargrin location","find solm"}},{q="What is the purpose of this rune?",a="It serves as an introductory summons for novice rogues, encouraging them to decode the message, report to their class trainer, and begin learning advanced combat techniques and survival maneuvers.",al={"what does the rune do","encrypted rune purpose","why encrypted rune"}},{q="Why does Solm mention the gnomes?",a="With Gnomeregan recently fallen to disaster, gnomish refugees share Coldridge Valley and Anvilmar with the dwarves. Solm reminds his students that the gnomes have had a rough time and need support settling into their temporary home.",al={"why help gnomes","solm gnomeregan comment"}},{q="Who gives the rune to the player?",a="Sten Stoutarm hands the stone over to rogue adventurers in Coldridge Valley after they finish lending him an initial hand with local valley tasks.",al={"who starts encrypted rune","quest giver encrypted rune"}},{q="Can other classes receive this rune?",a="No. The Encrypted Rune is intended solely for rogue initiates starting their journeys in Coldridge Valley.",al={"is this quest rogue only","can warriors get encrypted rune"}}},ang={["class:Rogue"]="This rune marks your first formal contact with the rogue network in Dun Morogh, leading you to Solm Hargrin to begin honing your stealth, martial tricks, and survival trade.",["race:Dwarf"]="Solm welcomes fellow dwarves of the Ironforge clan into the shadows, noting there is nothing quite like a cold blade and the dark to keep an operative alive in Dun Morogh.",["race:Gnome"]="Solm urges his students to show camaraderie to the gnomes sheltering in Coldridge Valley following the tragic loss of their home in Gnomeregan."},kw={"anvilmar","coldridge valley","dun morogh","encrypted rune","gnomeregan","rogue trainer","solm hargrin","sten stoutarm"},rel={"npc:solm-hargrin","npc:sten-stoutarm","subzone:anvilmar","subzone:coldridge-valley","zone:dunmorogh","zone:gnomeregan","topic:gnome","zone:ironforge"},m={start="Sten Stoutarm",["end"]="Solm Hargrin",level="1",faction="Alliance",id=3109},src={"Encrypted Rune (Classic)"}}
E["quest:311"] = {t="quest",n="Return to Marleth",z="dunmorogh",s="Return to Marleth marks the mischievous conclusion to a heated brewing feud in Dun Morogh. Having infiltrated the Kharanos cellar and swapped in a keg of Marleth's fiery Scalder, an adventurer returns to Brewnall Village with a prize barrel of Thunder Ale as indisputable proof.",h="Return to Marleth marks the mischievous conclusion to a heated brewing feud in Dun Morogh.",sec={{t="The Spoils of Sabotage",b="Dwarven rivalries are rarely settled with diplomacy when there is ale on the line. Marleth Barleybrew of Brewnall Village harbor-sits a fierce competitive grudge against the distillers of Kharanos, creators of the famed Thunder Ale. After having her potent 'Scalder' slipped into the Thunderbrew cellar unnoticed, Marleth demands evidence of the feat. Hoisting a genuine barrel of Thunder Ale from beneath their noses serves as both trophy and leverage.",sp=0},{t="A Bitter Brew Settled",b="Hauling the heavy keg back across the snowswept ridges to Brewnall Village finishes the caper. Marleth is thrilled to see the plan succeed, gleefully reveling in outsmarting Kharanos's guards and cellar masters. While harmless on the surface, the stunt cements the fierce, uncompromising pride that different dwarven families pour into their signature recipes across Dun Morogh.",sp=0}},faq={{q="What is the purpose of this quest?",a="You must deliver the stolen barrel of Thunder Ale back to Marleth Barleybrew at Brewnall Village to prove you successfully planted her Scalder in the Kharanos cellar.",al={"what do i do","return to marleth objective","barrel turn in"},it="purpose"},{q="Who is Marleth Barleybrew?",a="Marleth is a dwarven brewer residing in Brewnall Village. She takes intense pride in her family's stout recipes and holds a petty rivalry with the Thunderbrew distillers in Kharanos.",al={"who is marleth","marleth lore","barleybrew"},it="identity"},{q="Where is the barrel brought from?",a="The barrel is acquired directly from the cellar storage inside the Thunderbrew Distillery in Kharanos after swapping Marleth's Scalder into their stocks.",al={"where did barrel come from","kharanos cellar","thunder ale location"},it="origin"},{q="Where is Brewnall Village?",a="Brewnall Village sits along the frozen banks of the Iceflow Lake in western Dun Morogh, northwest of Kharanos.",al={"brewnall location","where is brewnall","how to find marleth"},it="place"},{q="Why is Marleth feudng with Kharanos?",a="Dwarven brewmasters are fiercely competitive about their recipes. Marleth wanted to prove her own blend, the Scalder, could best or humiliate the celebrated Thunder Ale produced by the Thunderbrews.",al={"why rivals","marleth vs thunderbrew","brewing feud"},it="conflict"},{q="What does Marleth do with the barrel?",a="The barrel serves primarily as proof that the switch was pulled off under the noses of the Kharanos guards, though Marleth is undoubtedly delighted to keep her rival's stock.",al={"why steal thunder ale","what happens to ale"},it="next_step"}},ang={["race:Dwarf"]="Dwarven culture treats brewing as an art form and a contest of honor, making petty cellar espionage a matter of great local pride.",["class:Rogue"]="Infiltrating a guarded cellar to swap out illicit kegs offers an amusing test of stealth and sleight of hand in the snowy hills."},kw={"brewnall village","dun morogh","kharanos","marleth barleybrew","scalder","thunder ale","thunderbrew"},rel={"quest:310","npc:marleth-barleybrew","subzone:brewnall-village","subzone:kharanos","zone:dunmorogh"},m={start="Unguarded Thunder Ale Barrel",["end"]="Marleth Barleybrew",level="7",faction="Alliance",id=311},src={"Return to Marleth"}}
E["quest:3110"] = {t="quest",n="Hallowed Rune",z="dunmorogh",s="Hallowed Rune is an introductory quest for fledgling dwarven priests in Coldridge Valley. Sten Stoutarm passes along an inscribed rune from priest trainer Branstock Khalder, summoning the novice inside Anvilmar to deepen their connection with the Holy Light.",h="Hallowed Rune is an introductory quest for fledgling dwarven priests in Coldridge Valley.",sec={{t="A Calling to the Cloth",b="While assisting Sten Stoutarm with clearing the immediate threats outside Anvilmar, a newly arrived priest catches the eye of the settlement's spiritual guide. Branstock Khalder entrusts Sten with a hallowed rune inscribed with prayers and guidance, directing the young adventurer to step inside the sturdy halls of Anvilmar to formally begin their sacred studies.",sp=0},{t="Defenders of Coldridge",b="Though dwarven culture often emphasizes martial fortitude and heavy plate, the Holy Light remains a cornerstone of Ironforge society. In Coldridge Valley, holy casters play a vital role alongside warriors and hunters in shielding the enclave from aggressive trogg incursions and dangerous wildlife creeping through the snow drifts.",sp=0}},faq={{q="What is the Hallowed Rune?",a="It is an inscribed clerical rune provided by Sten Stoutarm on behalf of Branstock Khalder. Reading it serves as an introduction to basic prayers and encourages young priests to seek out formal training.",al={"what is hallowed rune","rune purpose"}},{q="Who is Branstock Khalder?",a="Branstock Khalder is the dwarven priest trainer stationed inside Anvilmar. Known for his dry humor and steadfast faith, he mentors nascent acolytes and teaches them foundational Holy spells to aid the defense of Coldridge Valley.",al={"branstock","priest trainer coldridge"}},{q="Where do I find Branstock Khalder?",a="He can be found inside the main stone lodge of Anvilmar, located in the central clearing of Coldridge Valley in Dun Morogh.",al={"branstock location","where is branstock"}},{q="Why do dwarves need priests in Coldridge Valley?",a="Troggs have overrun parts of the valley, and the local guards rely on the mending powers and holy smiting of Light-wielders to sustain their lines and heal the wounded.",al={"why dwarven priests","priests in anvilmar"}},{q="Can any class take this quest?",a="No. The Hallowed Rune is specifically given only to young dwarf priests beginning their journey in Coldridge Valley.",al={"who can get hallowed rune","is this quest priest only"}},{q="Who delivers the rune to the player?",a="Sten Stoutarm, an Anvilmar mountaineer overseeing trials just outside the lodge, hands the rune over after you assist him with early valley defense.",al={"who starts hallowed rune","sten stoutarm role"}}},ang={["class:Priest"]="This parchment marks your formal recognition as a servant of the Holy Light in Dun Morogh, directing you to Branstock Khalder for your earliest spellcraft.",["race:Dwarf"]="Dwarven priests blend deep devotion to the Light with standard mountain grit, proving essential to holding Coldridge Valley against invading troggs."},kw={"anvilmar","branstock khalder","coldridge valley","dun morogh","dwarf priest","hallowed rune","sten stoutarm"},rel={"npc:branstock-khalder","npc:sten-stoutarm","subzone:anvilmar","subzone:coldridge-valley","zone:dunmorogh","topic:light","topic:trogg","zone:ironforge"},m={start="Sten Stoutarm",["end"]="Branstock Khalder",level="1",faction="Alliance",id=3110},src={"Hallowed Rune (Classic)"}}
E["quest:3112"] = {t="quest",n="Simple Memorandum",z="dunmorogh",s="The Simple Memorandum is a missive delivered to aspiring gnome warriors starting out in Coldridge Valley. Passed along by Sten Stoutarm outside, it directs newly trained fighters into Anvilmar to meet Thran Khorman, who has pledged to prepare them for reclaiming Gnomeregan.",h="The Simple Memorandum is a missive delivered to aspiring gnome warriors starting out in Coldridge Valley.",sec={{t="A Summons to Anvilmar",b="While clearing out the troggs and boars troubling Coldridge Valley for mountaineer Sten Stoutarm, a young gnome warrior receives a brief message slipped into the dwarf's hands. Recognizing the potential in the refugee recruit, veteran trainer Thran Khorman uses the memorandum to call the newcomer into Anvilmar's central hall to begin proper martial instruction.",sp=0},{t="A Pledge of Solidarity",b="Though dwarven trainers might occasionally tease gnome warriors about their diminutive stature, Thran Khorman takes their struggle seriously. Sympathizing with the loss of Gnomeregan, Thran likens the gnomes' plight to how dwarves would feel if Ironforge fell to the Dark Irons. In honoring his word, he pledges to instruct exile fighters in the arts of warfare until they are ready to win back their home.",sp=0}},faq={{q="What is the Simple Memorandum?",a="It is an introductory note handed to novice gnome warriors by Sten Stoutarm in Coldridge Valley. The letter instructs the warrior to seek out Thran Khorman, the warrior trainer inside the great hall of Anvilmar.",al={"simple memorandum","what is this note","memorandum quest"}},{q="Who sends the memorandum?",a="It comes from Thran Khorman, the resident dwarven warrior trainer stationed in Anvilmar. He has Sten Stoutarm pass it along to promising fighters who are assisting the mountaineers.",al={"who wrote memorandum","who sent simple memorandum"}},{q="Why does Thran Khorman train gnome warriors?",a="Thran gave his word to assist the exiled gnomes. He respects their determination and deeply empathizes with their tragedy, comparing the fall of Gnomeregan to what it would be like if Ironforge were conquered by the Dark Iron clan.",al={"why thran trains gnomes","gnome warrior lore"}},{q="Where do I find Thran Khorman?",a="Thran Khorman stands inside the main hall of Anvilmar, the central settlement located in Coldridge Valley within Dun Morogh.",al={"where is thran khorman","thran khorman location"}},{q="Who is Sten Stoutarm?",a="Sten Stoutarm is a dwarven mountaineer stationed just outside Anvilmar in Coldridge Valley who coordinates local defense against aggressive boars and invading troggs.",al={"sten stoutarm","who is sten"}},{q="Why are gnomes starting in Coldridge Valley?",a="Following the tragic fall and radiation of Gnomeregan, surviving gnomes fled into dwarven territory as refugees. Anvilmar and Ironforge have opened their doors to shelter them while they rebuild their forces.",al={"why are gnomes here","gnomes in coldridge"}}},ang={["class:Warrior"]="This missive formally begins a gnome warrior's combat education, establishing a bond with the veteran arms masters of Ironforge.",["race:Gnome"]="The memorandum highlights the gnomes' exile from Gnomeregan and their quiet determination to train soldiers capable of reclaiming their radioactive city.",["race:Dwarf"]="Dwarven mentors like Thran Khorman treat the gnomes' plight as equal to their own ancient feuds, showing deep solidarity with their displaced allies."},kw={"anvilmar","coldridge valley","dun morogh","gnomeregan","simple memorandum","sten stoutarm","thran khorman","warrior trainer"},rel={"npc:thran-khorman","npc:sten-stoutarm","subzone:anvilmar","subzone:coldridge-valley","zone:dunmorogh","zone:ironforge"},m={start="Sten Stoutarm",["end"]="Thran Khorman",level="1",faction="Alliance",id=3112},src={"Simple Memorandum (quest)"}}
E["quest:3113"] = {t="quest",n="Encrypted Memorandum",z="dunmorogh",s="The Encrypted Memorandum is an introductory summons directed at fledgling gnome rogues arriving in Coldridge Valley. Passed through Sten Stoutarm, the disguised note quietly directs new operatives to seek out Solm Hargrin inside Anvilmar.",h="The Encrypted Memorandum is an introductory summons directed at fledgling gnome rogues arriving in Coldridge...",sec={{t="A Discreet Introduction",b="While newcomer gnomes assist the mountaineers of Coldridge Valley with local trogg threats, Sten Stoutarm delivers a folded piece of parchment passed to him in confidence. Posing superficially as an official memorandum, the note is an invitation to meet Solm Hargrin, the resident rogue trainer stationed inside Anvilmar.",sp=0},{t="Shared Hardships in the Snow",b="The message reflects the uneasy reality facing the gnomes after the sudden fall of Gnomeregan. Displaced from their subterranean home, gnome survivors must share close quarters with their dwarven hosts in Dun Morogh. Solm Hargrin recognizes that rogues draw suspicion when items vanish, and he advocates for unspoken solidarity among practitioners of the craft to ensure their mutual survival.",sp=0}},faq={{q="Who wrote the Encrypted Memorandum?",a="Solm Hargrin, the rogue trainer residing inside Anvilmar, penned the note. He disguised it as an official directive from higher-ups so Sten Stoutarm would hand it over without raising suspicion.",al={"who sent memorandum","who wrote note","solm note"}},{q="Why is the memorandum disguised?",a="Rogues prefer discretion, especially in a bustling dwarven hold like Anvilmar. Solm Hargrin keeps a low profile to prevent rumors or accusations whenever gear goes missing, using coded greetings to reach out specifically to fellow scoundrels.",al={"why disguised","why encrypted"}},{q="What does this note reveal about the situation in Dun Morogh?",a="The dialogue highlights the friction and solidarity between gnomes and dwarves following the loss of Gnomeregan. While cramming both populations into Ironforge and Dun Morogh strains resources, Solm emphasizes that those in their shadow trade must watch out for one another.",al={"gnome dwarven relations","gnomeregan refugees dun morogh"}},{q="Who delivers the memorandum to the player?",a="Sten Stoutarm hands the document over after you assist him in Coldridge Valley, assuming it came from Solm Hargrin for your training.",al={"sten stoutarm delivery","who hands note"}},{q="What role does Solm Hargrin serve?",a="Solm Hargrin is the rogue trainer located inside the mountain hall of Anvilmar, responsible for instructing new rogues in combat techniques and shadowy talents.",al={"solm hargrin role","what does solm do"}},{q="Does this quest relate to Gnomeregan's fall?",a="Yes. Solm directly references Gnomeregan being overrun and stresses that, despite losing their mechanical homeland, displaced gnomish rogues can rely on their shared brotherhood to endure.",al={"gnomeregan fall lore","gnome refugee status"}}},ang={["class:Rogue"]="This task serves as the initial calling for gnome rogues, introducing them to Solm Hargrin and the philosophy of mutual protection required to ply their covert trade in dwarven lands.",["race:Gnome"]="The memorandum highlights the plight of gnome refugees following the disaster at Gnomeregan, showing how survivors band together while living as guests among the dwarves.",["race:Dwarf"]="Dwarven mountaineers like Sten Stoutarm facilitate these communications, showing the practical cooperation between Ironforge and the displaced gnomes in Coldridge Valley."},kw={"anvilmar","coldridge valley","dun morogh","encrypted memorandum","gnomeregan","rogue trainer","solm hargrin","sten stoutarm"},rel={"npc:solm-hargrin","npc:sten-stoutarm","subzone:anvilmar","subzone:coldridge-valley","zone:gnomeregan","topic:gnome","zone:dunmorogh"},m={start="Sten Stoutarm",["end"]="Solm Hargrin",level="1",faction="Alliance",id=3113},src={"Encrypted Memorandum (quest)"}}
E["quest:3114"] = {t="quest",n="Glyphic Memorandum",z="dunmorogh",s="Glyphic Memorandum is an introductory task directing novice mages in Coldridge Valley to their local trainer inside Anvilmar. Entrusted to mountaineer Sten Stoutarm, the missive summons budding arcane practitioners to seek out the eccentric gnome Marryk Nurribit to begin their formal spellcraft studies.",h="Glyphic Memorandum is an introductory task directing novice mages in Coldridge Valley to their local trainer...",sec={{t="A Missive for Novice Mages",b="While assisting mountaineer Sten Stoutarm with early duties across Coldridge Valley, newly arrived mages find themselves summoned by local arcane authority. Sten receives a written memorandum addressed to the fledgling spellcaster and passes it along, advising them to take a moment to read its contents and head inside the warmth of Anvilmar to meet its author.",sp=0},{t="Training with Marryk Nurribit",b="The author of the memorandum is Marryk Nurribit, a gnome mage trainer stationed inside Anvilmar. Rather than drowning his pupil in dense theoretical lectures, Marryk offers straightforward, grounded advice: stay out of serious trouble, save coin for training and tavern drinks, and strictly avoid the radioactive disaster that is fallen Gnomeregan. With basic expectations set, Marryk stands ready to tutor newcomers in the arcane arts.",sp=0}},faq={{q="Who delivers this memorandum?",a="Sten Stoutarm, an Alliance mountaineer stationed in Coldridge Valley, hands you the memorandum after you assist him with his initial tasks.",al={"who gives glyphic memorandum","sten stoutarm quest"}},{q="Who is Marryk Nurribit?",a="Marryk Nurribit is a gnome mage trainer residing inside Anvilmar in Coldridge Valley. He instructs fledgling mages in early spells and general arcane safety.",al={"who is marryk","anvilmar mage trainer"}},{q="Where can I find Marryk Nurribit?",a="Marryk is located inside the main hall of Anvilmar, the central dwarven outpost situated at the top of Coldridge Valley in Dun Morogh.",al={"marryk nurribit location","where is the mage trainer in coldridge valley"}},{q="Why does Marryk warn against visiting Gnomeregan?",a="Gnomeregan was recently overrun by troggs and contaminated by a catastrophic release of radioactive gas, making it perilous for any novice adventurer wandering Dun Morogh.",al={"marryk gnomeregan warning","why stay away from gnomeregan"}},{q="What classes receive this task?",a="This quest is exclusively provided to fledgling mages starting their journey in Coldridge Valley to introduce them to their class trainer.",al={"who gets glyphic memorandum","is this quest mage only"}},{q="What does Marryk expect from his students?",a="Marryk keeps his demands simple: he warns his students to stay out of trouble, save enough silver to pay for their spells and buy him an ale, and keep far away from Gnomeregan.",al={"marryk expectations","what does the trainer want"}}},ang={["class:Mage"]="This missive marks your official introduction to arcane tutelage in Dun Morogh, connecting you directly with your starting trainer.",["race:Gnome"]="Marryk Nurribit is one of several gnome specialists who took refuge in dwarven lands following the fall of Gnomeregan to teach their traditional craft.",["faction:Alliance"]="The seamless cooperation between Sten Stoutarm and Marryk Nurribit illustrates the close partnership between dwarves and gnomes sharing Coldridge Valley."},kw={"anvilmar","coldridge valley","dun morogh","glyphic memorandum","mage trainer","marryk nurribit","sten stoutarm"},rel={"npc:marryk-nurribit","npc:sten-stoutarm","subzone:anvilmar","subzone:coldridge-valley","zone:dunmorogh","zone:gnomeregan","topic:gnome"},m={start="Sten Stoutarm",["end"]="Marryk Nurribit",level="1",faction="Alliance",id=3114},src={"Glyphic Memorandum (quest)"}}
E["quest:3115"] = {t="quest",n="Tainted Memorandum",z="dunmorogh",s="Tainted Memorandum is an introductory quest for fledgling gnome warlocks taking their first steps in Coldridge Valley. Passed quietly through Sten Stoutarm, the missive summons the neophyte to the shadows of Anvilmar to meet Alamar Grimm, who preaches self-reliance through dark power rather than trust in their dwarven hosts.",h="Tainted Memorandum is an introductory quest for fledgling gnome warlocks taking their first steps in...",sec={{t="A Discreet Summons",b="Even in the frozen outpost of Coldridge Valley, the practice of the dark arts is met with deep suspicion. While helping Sten Stoutarm deal with local threats, young gnome warlocks receive a slipped note. Sten delivers it reluctantly, giving voice to the uneasy truce that allows warlocks in Alliance lands: 'watch yerself... your kind ain't too trusted 'round these parts.'",sp=0},{t="Gnomish Bitterness in Exile",b="Upon answering the note, the warlock meets Alamar Grimm lurking inside the halls of Anvilmar. Grimm does not mince words regarding the gnomes' plight. To his eyes, conventional tinkering and ordinary magic failed Gnomeregan utterly, driving their people to near extinction and leaving them stranded as second-class refugees dependent on dwarf goodwill. Rather than praying to the Holy Light or putting faith in dwarven politics, Grimm urges his pupil to summon and master fiends who offer unconditional obedience.",sp=0}},faq={{q="What is the Tainted Memorandum?",a="It is a written message handed to novice gnome warlocks by Sten Stoutarm in Coldridge Valley. It directs them to seek out Alamar Grimm, the local warlock trainer in Anvilmar.",al={"tainted memo","warlock note dun morogh","what is the memorandum"}},{q="Why are warlocks distrusted in Coldridge Valley?",a="Dwarves and their Alliance allies hold traditional virtues like martial honor and the Holy Light in high regard, viewing demonology and shadow magic as inherently corrupt and dangerous. Gnome warlocks operate under a cloud of deep social suspicion.",al={"why don't dwarves like warlocks","warlock prejudice anvilmar"}},{q="Who is Alamar Grimm?",a="Alamar Grimm is a gnome warlock trainer residing in Anvilmar. Bitter over the fall of Gnomeregan and the indignity of relying on dwarven charity, he instructs young gnomes in the binding of demonic minions to secure their own power.",al={"alamar grimm lore","who is alamar"}},{q="Why does Grimm criticize normal magic and technology?",a="Grimm believes that conventional engineering and accepted schools of magic failed the gnomes during the disaster at Gnomeregan, leaving them dependent on dwarf patrons who prioritize ties with humans over reclaiming the gnome homeland.",al={"grimm gnomeregan view","why dark magic over engineering"}},{q="Can dwarf warlocks receive this quest?",a="No. In Dun Morogh, only gnomes can practice the warlock path, making this summons exclusive to freshly arrived gnome practitioners.",al={"dwarf warlock tainted memorandum","can dwarves be warlocks"}},{q="Where does this quest take place?",a="The quest begins near Sten Stoutarm in Coldridge Valley and finishes inside Anvilmar, the central redoubt overlooking the valley in southwestern Dun Morogh.",al={"where is alamar grimm","tainted memorandum turn in"}}},ang={["class:Warlock"]="This missive marks your formal entry into the warlock craft, framing demonic pacts not as madness, but as pragmatism born of survival.",["race:Gnome"]="The memorandum reflects the deep underlying resentment felt by some exiled gnomes over their displaced status and reliance on Ironforge.",["race:Dwarf"]="Dwarven hosts tolerate these dark practitioners under their roof with obvious distaste and sharp wariness."},kw={"alamar grimm","anvilmar","coldridge valley","dun morogh","gnome warlock","gnomeregan exile","sten stoutarm","tainted memorandum"},rel={"npc:alamar-grimm","npc:sten-stoutarm","subzone:anvilmar","subzone:coldridge-valley","zone:dunmorogh","topic:light","topic:human","quest:1599"},m={start="Sten Stoutarm",["end"]="Alamar Grimm",level="1",faction="Alliance",id=3115},src={"Tainted Memorandum (quest)"}}
E["quest:312"] = {t="quest",n="Tundra MacGrann's Stolen Stash",z="dunmorogh",s="Tundra MacGrann, an injured dwarven hunter living out in the cold crags of Dun Morogh, has lost his winter supplies to a notorious local beast. A massive yeti known as Old Icebeard hauled off MacGrann's thorium-reinforced meat locker into its den. Unable to outrun the beast on a bum leg, the hunter relies on passing adventurers to slip inside and retrieve his provisions.",h="Tundra MacGrann, an injured dwarven hunter living out in the cold crags of Dun Morogh, has lost his winter...",sec={{t="Winter Stores and Stolen Lockers",b="Surviving the harsh winters of Dun Morogh demands preparation, especially for mountaineers living outside the warmth of Kharanos and Ironforge. Tundra MacGrann had diligently salted away an entire month's worth of dried meats to outlast the coming cold season flurries. Taking precautions against hungry wild bears, he sealed his rations inside a reinforced thorium meat locker. Unfortunately, he did not account for the sheer brute strength of the mountain yetis, who carried the entire chest away rather than trying to open it on the spot.",sp=0},{t="Old Icebeard's Den",b="The culprit behind the theft is Old Icebeard, a feared and vicious yeti lurking in the jagged hills. While MacGrann was away hunting deer, Icebeard snatched the chest and dragged it back to his mountain cave. Though MacGrann remains confident that even a yeti cannot shatter solid thorium plating, his own injured leg makes a recovery mission suicidal. Any brave soul venturing into the cave must either contend directly with the beast or time their intrusion carefully while the monster is out prowling the snowdrifts.",sp=0}},faq={{q="Who is Tundra MacGrann?",a="Tundra MacGrann is a dwarven trapper and hunter dwelling in the snowy expanses of Dun Morogh. Nursing a bad leg, he depends on his harvested stores to endure the harsh winter conditions.",al={"tundra macgrann","macgrann","who is macgrann"},it="identity"},{q="Who stole MacGrann's meat locker?",a="A menacing local yeti known as Old Icebeard stole the locker while MacGrann was away hunting deer, dragging the heavy thorium chest into its mountain lair.",al={"who stole the stash","who took the meats","stolen stash thief"},it="target"},{q="Why can't MacGrann get his meats back himself?",a="MacGrann suffers from an injured leg that severely limits his mobility. He knows he cannot move swiftly or quietly enough to enter and escape Old Icebeard's cave without being caught and mauled.",al={"why cant macgrann get it","macgranns leg","bum leg"},it="why_me"},{q="Did the yeti eat the food?",a="No. The dried meats were locked inside a sturdy chest crafted from solid thorium. While the yeti succeeded in carrying the heavy container off, it is unable to break through the metal.",al={"is the food eaten","can icebeard open the chest"}},{q="Do you have to fight Old Icebeard to get the meat locker?",a="No, you do not necessarily have to fight him. Old Icebeard regularly wanders outside his lair, giving nimble adventurers an opportunity to sneak into the cave and loot the locker unnoticed.",al={"can you sneak past icebeard","do i have to kill icebeard"},gp=true},{q="Where is the stolen stash located?",a="The stolen meat locker rests deep inside Old Icebeard's mountain cave, located in the hills near MacGrann's camp in Dun Morogh.",al={"where is the cave","icebeard cave location"},it="place",gp=true},{q="Why does Tundra MacGrann need his meat locker recovered?",a="MacGrann spent long days hunting and salting an entire month's worth of rations to survive the harsh Dun Morogh cold season. Without those preserved meats, he faces starvation in his remote mountain camp once the winter flurries roll in, as his injured leg prevents him from hunting enough game to replenish his winter stores in time.",al={"why help tundra macgrann","macgrann motive","why retrieve the meat locker"},it="motive",add="ceb049bb"},{q="What is MacGrann's Dried Meats?",a="It is a heavy reserve of salted venison and game that Tundra MacGrann cured specifically to outlast the mountain winter. He locked the meat inside a reinforced thorium locker to keep scavenging bears from sniffing it out, which luckily proved durable enough to keep Old Icebeard from tearing into it as well.",al={"macgranns dried meats","what is macgrann's dried meats","macgrann meat locker contents"},it="item",add="9ce729b1"}},ang={["class:Hunter"]="Fellow trackers will sympathize with MacGrann's misfortune of having months of diligent field dressing and game preservation undone by an opportunistic beast while out tracking deer.",["race:Dwarf"]="Every dwarf in Dun Morogh knows the unforgiving brutality of a mountain winter; without preserved meat or shelter, even a hardened mountaineer cannot hold out against the freeze.",["class:Rogue"]="MacGrann specifically seeks out stealthy travellers, making this theft a textbook job for scouts who can slip in behind Old Icebeard's back without ever drawing a blade."},kw={"dried meats","dun morogh","meat locker","old icebeard","stolen stash","thorium","tundra macgrann","yeti"},rel={"zone:dunmorogh"},m={start="Tundra MacGrann",level="12",faction="Alliance",id=312,ri={"MacGrann's Dried Meats"}},src={"Tundra MacGrann's Stolen Stash"}}
E["quest:313"] = {t="quest",n="The Grizzled Den",z="dunmorogh",s="Pilot Stonegear of Kharanos is looking for someone with true dwarven grit to spruce up his beloved siege engine, Trollplow. To test an aspiring adventurer's mettle, he sends them west into the perilous cavern known as the Grizzled Den to hunt savage wendigos for their thick pelts.",h="Pilot Stonegear of Kharanos is looking for someone with true dwarven grit to spruce up his beloved siege...",sec={{t="A Test of Grit",b="Operating a massive dwarven siege tank requires nerves of iron and the constitution to handle teeth-rattling machinery in freezing mountain air. Pilot Stonegear, stationed at Steelgrill's Depot near Kharanos, claims to have both in spades. Rather than simply giving up work or respect easily, he challenges newcomers to prove they possess the same stalwart temperament by trekking into the frozen hills to face native beasts.",sp=0},{t="Creature Comforts in Trollplow",b="Stonegear's siege engine bears the proud and unsubtle name of Trollplow, but its cramped, iron-plated cabin is brutally cold in the bitter Dun Morogh climate. Stonegear hits upon a practical yet wild solution: wendigo pelt. Harvesting thick manes from the ferocious wendigos stalking the Grizzled Den provides the materials needed to fashion a durable, warm rug for Trollplow's deck while keeping local beast numbers in check.",sp=0}},faq={{q="Who is Pilot Stonegear?",a="Pilot Stonegear is a dwarven siege engine driver stationed outside Kharanos in Dun Morogh. He pilots an armored war machine affectionately christened Trollplow and takes immense pride in his iron nerves and mechanical trade.",al={"pilot stonegear","who gives quest","who is stonegear"},it="identity"},{q="Where is the Grizzled Den located?",a="The Grizzled Den is a snow-covered cave system nestled in the mountains directly west of Kharanos. It serves as a notorious lair for Dun Morogh's vicious wendigos.",al={"grizzled den location","where is wendigo cave","how to find grizzled den"},it="place",gp=true},{q="Why does Stonegear want wendigo manes?",a="Stonegear wants the thick, insulating fur of the wendigos to craft a cozy rug for the interior deck of his siege engine, Trollplow, while simultaneously testing an adventurer's bravery.",al={"why wendigo manes","purpose of manes","what are manes for"},it="motive"},{q="What is Trollplow?",a="Trollplow is Pilot Stonegear's personal dwarven siege engine. Its aggressive name reflects the ongoing conflict between Ironforge dwarves and the hostile Frostmane trolls that inhabit the surrounding crags.",al={"trollplow","stonegear tank","what is trollplow"},it="identity"},{q="What kind of creatures inhabit the Grizzled Den?",a="The cavern is inhabited by savage wendigos—feral, ape-like beasts native to Dun Morogh's snowy heights that aggressively defend their territory from any who intrude.",al={"monsters in grizzled den","what lives in grizzled den"},it="residents"},{q="Are the wendigos dangerous to Kharanos?",a="While wendigos rarely organize concerted attacks like the Frostmane trolls, their violent ferocity and proximity to the main roads make them an ever-present danger to travelers and local tradesfolk alike.",al={"are wendigos a threat","wendigo danger"},it="threat"},{q="What are the Wendigo Manes used for?",a="Pilot Stonegear wants the thick, shaggy manes of the Grizzled Den's wendigos for a very practical dwarf luxury: interior decorating. Operating a massive siege engine like Trollplow in Dun Morogh's biting chill leaves the metal deck freezing underfoot. Stonegear plans to stitch the harvested manes together into a warm, heavy rug to make Trollplow's cabin much cozier during long patrols.",al={"wendigo mane use","what is wendigo mane for","why wendigo manes"},it="item",add="9edb896b"},{q="Why does Pilot Stonegear send you instead of getting the manes himself?",a="Stonegear is a siege engine pilot, and keeping an iron machine like Trollplow maintained and ready for defense in Kharanos demands his full attention. Hunting agile, ferocious wendigos inside tight, frozen cavern passages isn't work suited for a massive war machine. Stonegear also treats the task as an open challenge to see if you have the grit, mettle, and nerve required of Dun Morogh's defenders.",al={"why me stonegear","why does stonegear need help","why not get manes himself"},it="why_me",add="72b90979"}},ang={["race:Dwarf"]="For young Mountaineers and Ironforge adventurers, taking on the wendigos of the Grizzled Den is a quintessential local rite of passage.",["profession:Engineering"]="Anyone who appreciates the craft of dwarven siege vehicles knows that maintaining heavy machinery in sub-zero weather requires creative solutions for cockpit warmth.",["race:Gnome"]="Living side by side with the dwarves around Kharanos means pitching in to help equip Ironforge's heavy armored engines."},kw={"dun morogh","grizzled den","kharanos","pilot stonegear","trollplow","wendigo","wendigo mane"},rel={"subzone:grizzled-den","npc:pilot-stonegear","subzone:kharanos","zone:dunmorogh","topic:troll"},m={start="Pilot Stonegear",level="7",faction="Alliance",id=313,ri={"Wendigo Mane"}},src={"The Grizzled Den (quest)"}}
E["quest:314"] = {t="quest",n="Protecting the Herd",z="dunmorogh",s="Protecting the Herd is a task given by Rudra Amberstill at the Amberstill Ranch in Dun Morogh. A ferocious predatory beast named Vagash has been attacking the ranch's prized mountain rams in the night, and with Ironforge's military garrison spread thin across the realm, the local breeders must rely on passing adventurers for defense.",h="Protecting the Herd is a task given by Rudra Amberstill at the Amberstill Ranch in Dun Morogh.",sec={{t="A Threat to the Ranch",b="Amberstill Ranch supplies the mountain rams that serve as iconic mounts and working beasts for the Bronzebeard dwarves. Maintaining these herds is vital to Dun Morogh's rustic economy. When night fell and frantic cries echoed over the paddocks, the Amberstill family discovered two of their prized rams missing. The culprit is Vagash, a notorious and savage beast lurking in the nearby crags above the ranch, known for violently preying on local livestock.",sp=0},{t="Strained Defenses",b="Normally, local threats of this magnitude would be handled by the dwarven mountaineers or King Magni Bronzebeard's royal forces. However, Ironforge's standing army is currently stretched thin across distant frontiers supporting the broader Alliance. Left without an official military detachment to patrol the ridgelines, Rudra Amberstill is forced to ask independent fighters to hunt down Vagash and bring back one of the beast's deadly fangs as proof.",sp=0}},faq={{q="Who is Vagash?",a="Vagash is a dangerous, predatory monster that stalks the snowy ridges directly above Amberstill Ranch. Feared for his sheer strength and vicious appetite, he poses a lethal threat to both domestic ram herds and unwary travelers in eastern Dun Morogh.",al={"what is vagash","vagash monster","vagash lore"},it="target"},{q="Where can Vagash be found?",a="Vagash makes his den in a snow-covered cave high up in the crags overlooking the Amberstill Ranch. Ascending the snowy hill just past the pine trees behind the homestead leads directly to the mouth of his lair.",al={"vagash location","where is vagash","find vagash"},it="place",gp=true},{q="Why are the Ironforge guards not handling this?",a="King Magni Bronzebeard's forces are currently spread thin defending strategic garrisons and supporting distant Alliance campaign efforts. As a result, rural homesteads like Amberstill Ranch must fend for themselves or recruit capable adventurers.",al={"why no guards","where is ironforge army","why help amberstill"},it="why_me"},{q="Who is Veron mentioned by Rudra?",a="Veron Amberstill is a master ram breeder at the ranch who trains and tends the Bronzebeards' celebrated riding rams. Rudra mentions that Veron will be immensely relieved once the predatory menace stalking their prized animals is eliminated.",al={"who is veron","veron amberstill","veron"},it="people"},{q="Why is proof of the kill required?",a="Rudra asks for Vagash's fang to ensure beyond a shadow of a doubt that the genuine monster terrorizing their herds has been slain, rather than a common prowler from the mountain slopes.",al={"why vagash fang","fang of vagash","what is the proof"},it="why_wanted"},{q="What importance do the rams have to Dun Morogh?",a="Mountain rams are hardy, sure-footed creatures uniquely suited to navigating the freezing, rocky terrain of Khaz Modan. They serve as essential draft animals, wool sources, and cavalry mounts for the dwarven kingdom.",al={"why are rams important","amberstill ram purpose","dwarf rams lore"},it="ties"},{q="Why does Rudra Amberstill want this done?",a="Rudra Amberstill is defending her family's livelihood. The Amberstill ranch breeds and tends the sturdy mountain rams prized throughout Dun Morogh and Ironforge. Vagash has begun prowling close to the homestead, creeping in under cover of darkness to slaughter the livestock. With two prized rams already dragged away in a single night, the ranch cannot survive ongoing raids from such a vicious predator.",al={"why does Rudra want Vagash dead","rudra amberstill motive","why kill vagash"},it="motive",add="81b569d0"},{q="What is the Fang of Vagash for?",a="The fang serves as undeniable physical proof that the feared beast has truly been slain. Vagash is infamous around the ranch for his size and ferocity, and Rudra Amberstill needs absolute certainty that the predator stalking the crags above is dead before she and her family can rest easy about their surviving herd.",al={"why need fang of vagash","fang of vagash purpose","vagash tooth"},it="item",add="34abe682"}},ang={["race:Dwarf"]="For dwarven wanderers, defending Amberstill Ranch protects the very mountain rams that carry your kin into battle across Khaz Modan.",["class:Hunter"]="Tracking down a notorious apex predator like Vagash in his mountain den is a classic proving ground for any tracker honing their skills in Dun Morogh's snowdrifts.",["faction:Alliance"]="With High Seat regiments drawn outward to bolster Alliance commitments across the Eastern Kingdoms, aiding hard-pressed rural homesteads helps stabilize the home front."},kw={"amberstill ranch","dun morogh","ironforge","mountain rams","protecting the herd","rudra amberstill","vagash","veron amberstill"},rel={"zone:dunmorogh","zone:ironforge","topic:alliance"},m={start="Rudra Amberstill",faction="Alliance",id=314,ri={"Fang of Vagash"}},src={"Protecting the Herd"}}
E["quest:315"] = {t="quest",n="The Perfect Stout",z="dunmorogh",s="Rejold Barleybrew of Brewnall Village is determined to craft the ultimate dwarven stout, combining family brewing tradition with exotic local ingredients. To perfect his experimental recipe, he seeks shimmerweed, a pungent plant cultivated exclusively by the hostile Frostmane trolls atop Shimmer Ridge. Daring travelers are sent into the troll encampment to lift the herb straight from tribal baskets.",h="Rejold Barleybrew of Brewnall Village is determined to craft the ultimate dwarven stout, combining family...",sec={{t="A Brewer's Ambition",b="In Brewnall Village, brewing is more than a trade—it is a way of life, especially for the Barleybrew family. Rejold Barleybrew believes that brewing greatness is in his blood, but achieving the legendary 'perfect stout' demands unconventional innovation. Rather than relying solely on standard hops, malt, and mountain spring water, Rejold looks toward the untamed flora of Dun Morogh to give his ale an unmistakable bite.",sp=0},{t="The Troll Herb of Shimmer Ridge",b="The secret ingredient Rejold covets is shimmerweed, a cold-hardy plant cultivated by the Frostmane trolls up on Shimmer Ridge to the northwest. While the Frostmanes gather it for their own tribal and mystic rituals, dwarves have had little practical use for it outside of noting its sharp, distinct flavor. Snatched directly from storage baskets in the troll village, the weed serves as the centerpiece for Rejold's latest and boldest fermentation experiment.",sp=0}},faq={{q="What is shimmerweed?",a="Shimmerweed is a distinct plant grown and harvested by the Frostmane trolls on Shimmer Ridge. While the trolls use it primarily in their tribal ceremonies and rituals, Rejold Barleybrew seeks to test its sharp, unique flavor as an unconventional flavoring agent in dwarven brewing.",al={"shimmerweed lore","what does shimmerweed do","frostmane plant"},it="item"},{q="Where is Shimmer Ridge located?",a="Shimmer Ridge lies in the snowy heights to the northwest of Brewnall Village in Dun Morogh. It serves as a fortified camp for the indigenous Frostmane trolls, making any herb-gathering excursion there a dangerous foray into hostile territory.",al={"shimmer ridge location","where is shimmer ridge","how to find shimmer ridge"},it="place",gp=true},{q="Why does Rejold want to steal from the Frostmane trolls?",a="The Frostmane trolls hold a monopoly on cultivating shimmerweed in Dun Morogh, and tensions between dwarves and trolls make peaceful trade impossible. Since the plants are already harvested and bundled into tribal baskets in their encampment, sneaking in or fighting through to seize them is Rejold's only option.",al={"why steal from trolls","why troll baskets","rejold troll plan"},it="motive"},{q="Who is Rejold Barleybrew?",a="Rejold Barleybrew is an ambitious dwarf brewer residing in Brewnall Village. True to his family name, he has dedicated his craft to discovering the recipe for the perfect stout, constantly experimenting with new flavors and potent wild ingredients.",al={"who is rejold","rejold barleybrew","barleybrew family"},it="identity"},{q="Is shimmerweed considered an alchemy herb?",a="No. Shimmerweed is not an alchemical reagent gathered from wild nodes. It is a quest item stored in wicker baskets and caches throughout the Frostmane settlements atop Shimmer Ridge.",al={"can herbalists pick shimmerweed","is shimmerweed herbalism","shimmerweed gather"},gp=true},{q="What becomes of the shimmerweed once turned in?",a="Rejold throws the freshly gathered shimmerweed directly into an active fermentation batch in Brewnall Village, hoping its unique profile will finally unlock the flawless recipe he has sought.",al={"does the stout work","rejold brew result","shimmerweed beer"},it="next_step"},{q="Who are the Frostmane trolls?",a="The Frostmane are an indigenous tribe of ice trolls native to the snowy crags of Dun Morogh. Driven out of their historic hunting grounds by the expanding Ironforge dwarves, they harbor deep hostility toward their dwarven neighbors. From settlements like the one on Shimmer Ridge, they cultivate shimmerweed for their tribal rituals and fiercely defend their camps against any intruders.",al={"frostmane trolls","who are the trolls on shimmer ridge","frostmane tribe"},it="target",add="3780a202"}},ang={["race:Dwarf"]="Brewing is practically sacred to the Bronzebeard clan, and finding an exotic wild herb to outdo rival taverns is considered a noble pursuit.",["profession:Herbalism"]="Though not a standard crafting herb, the unique botanical traits of frost-resistant shimmerweed make it an intriguing novelty in the frozen crags of Dun Morogh."},kw={"brewnall village","dun morogh","dwarf brew","frostmane","perfect stout","rejold barleybrew","shimmer ridge","shimmerweed"},rel={"npc:rejold-barleybrew","subzone:brewnall-village","subzone:shimmer-ridge","zone:dunmorogh","topic:troll"},m={start="Rejold Barleybrew",faction="Alliance",id=315,ri={"Shimmerweed"}},src={"The Perfect Stout"}}
E["quest:317"] = {t="quest",n="Stocking Jetsteam",z="dunmorogh",s="Stocking Jetsteam is an Alliance quest offered by Pilot Bellowfiz at Steelgrill's Depot in Dun Morogh. Preparing his siege engine for an extended deployment with the Ironforge Siege Brigade, the pilot enlists local hunters to gather boar meat and bear pelts to provision his crew.",h="Stocking Jetsteam is an Alliance quest offered by Pilot Bellowfiz at Steelgrill's Depot in Dun Morogh.",sec={{t="Provisioning the Engine",b="Stationed just outside Kharanos at Steelgrill's Depot, Pilot Bellowfiz oversees preparations for an upcoming long-haul operation on behalf of the Siege Brigade. His siege tank, dubbed Jetsteam, requires both mechanical tuning from master engineer Beldin Steelgrill and a month's worth of field provisions to keep its crew functional in the harsh sub-zero temperatures of Dun Morogh.",sp=0},{t="Hunting the Snow Fields",b="Because Beldin Steelgrill is occupied under Jetsteam's hood, Bellowfiz cannot abandon his vehicle to gather rations and insulation. He directs travelers to hunt in the snowy plains south of the Grizzled Den, where indigenous boars provide hardy meat for food and native bears yield thick pelts suitable for warm tank bedding.",sp=0}},faq={{q="What is Jetsteam?",a="Jetsteam is the siege tank operated by the dwarf Pilot Bellowfiz. Stationed at Steelgrill's Depot, it is being tuned and provisioned for an extended military deployment on behalf of the Ironforge Siege Brigade.",al={"jetsteam","who is jetsteam","what is jetstream","bellowfiz tank"},it="identity"},{q="Who is Pilot Bellowfiz?",a="Pilot Bellowfiz, nicknamed Fizzer, is a dwarven siege engine pilot of the Ironforge Siege Brigade. While his vehicle undergoes mechanical adjustments at Steelgrill's Depot, he coordinates field supplies for his upcoming mission.",al={"pilot bellowfiz","bellowfiz","who is pilot bellowfiz"},it="people"},{q="Where can the required supplies be gathered?",a="Pilot Bellowfiz points hunters toward the snowy flats south of the Grizzled Den, an area inhabited by local boars and bears whose meat and pelts provide adequate provisions and bedding.",al={"where are the boars","where are bears","hunting location","boar meat dun morogh"},it="place",gp=true},{q="What is the Siege Brigade?",a="The Siege Brigade is Ironforge's corps of siege engine pilots, operating heavily armored war machines like Jetsteam and Trollplow in support of dwarven defense and Alliance campaigns.",al={"siege brigade"},it="allies"},{q="Where does this mission lead next?",a="After restocking Jetsteam with meat and furs, Pilot Bellowfiz sends travelers west to Brewnall Village in the quest Evershine, seeking a potent brew he uses both to keep warm and as emergency fuel for the tank's furnace.",al={"next quest","what comes after stocking jetsteam","stocking jetsteam follow up"},sp=1,it="next_step"},{q="Why does a siege engine require animal furs?",a="The interior of a dwarven or gnomish steam tank is frigid and drafty during long operations in the mountain snows. Thick bear pelts provide vital warmth and insulation for crew bedding during prolonged stays away from camp.",al={"why fur","thick bear fur use","bedding"},it="item"},{q="Why does Pilot Bellowfiz want this done?",a="Pilot Bellowfiz is gearing up for an extended deployment with the Siege Brigade. The mission ahead will keep him out in the field for at least a month, and operating deep in Dun Morogh's frigid wilderness requires careful preparation. He needs substantial provisions stowed aboard Jetsteam before heading out into active duty.",al={"pilot bellowfiz motive","why stock jetsteam","why does bellowfiz need supplies"},it="motive",add="bd6a237a"},{q="What is the Chunk of Boar Meat for?",a="The boar meat serves as vital rations for Pilot Bellowfiz's upcoming month-long deployment. Operating a heavy siege engine in the freezing cold burns serious energy, and durable meat gathered from the local crag boars provides the sustenance he needs while deployed far from friendly outposts.",al={"chunk of boar meat use","why boar meat","boar meat jetsteam"},it="item",add="f0e85f28"},{q="Why does Pilot Bellowfiz need you to do the hunting?",a="Bellowfiz cannot spare the time to hunt because he is overseeing the maintenance of Jetsteam. Master mechanic Beldin Steelgrill is actively tuning and repairing the tank at Steelgrill's Depot, requiring the pilot to stay close by and ensure the machine is properly prepped for departure.",al={"why cant bellowfiz hunt","why me bellowfiz","why do i have to hunt for bellowfiz"},it="why_me",add="779906a6"}},ang={["race:Gnome"]="Assisting Bellowfiz keeps the dwarven Siege Brigade, Ironforge's mechanized ally to the exiled gnomes, fully supplied for the long campaigns ahead.",["race:Dwarf"]="Providing game from Dun Morogh's crags keeps the Siege Brigade's dwarven crews fed and rested while working out of Khaz Modan's machine yards.",["profession:Cooking"]="Harvesting thick cuts of boar meat in the Dun Morogh drifts highlights the staple game that sustains local mountain garrisons.",["faction:Alliance"]="Cooperation between dwarven repair yards and the Siege Brigade's armored crews keeps the Alliance's frontline siege technology functional."},kw={"bear furs","boar meat","dun morogh","grizzled den","jetsteam","pilot bellowfiz","siege brigade","steelgrill's depot"},rel={"npc:pilot-bellowfiz","subzone:steelgrill-s-depot","quest:318","quest:319","subzone:grizzled-den","quest:313","zone:dunmorogh","topic:gnome"},m={start="Pilot Bellowfiz",level="6",faction="Alliance",id=317,ri={"Chunk of Boar Meat","Thick Bear Fur"}},src={"Stocking Jetsteam"}}
E["quest:318"] = {t="quest",n="Evershine",z="dunmorogh",s="Evershine is an Alliance delivery quest beginning with Pilot Bellowfiz near Kharanos. The dwarven siege engine pilot sends travelers westward to Brewnall Village to fetch a potent dwarven brew concocted by Rejold Barleybrew. The liquor doubles as a warming drink and an emergency, high-octane fuel for Bellowfiz's siege engine.",h="Evershine is an Alliance delivery quest beginning with Pilot Bellowfiz near Kharanos.",sec={{t="A Potent Concoction",b="Dwarven brewing is famed throughout Khaz Modan, but Rejold Barleybrew's recipes in Brewnall Village push the boundaries of standard fermentation. His experimental beverage, Evershine, is infamous for knocking all but the sturdiest dwarves flat on their backs. Despite its fierce potency, it is prized in the bitter cold of Dun Morogh for its sheer heating power.",sp=0},{t="Fuel for Pilot Bellowfiz",b="Siege pilots often find unorthodox uses for everyday materials, and Pilot Bellowfiz is no exception. Operating out of Steelgrill's Depot outside Kharanos, Bellowfiz relies on Evershine not just as a nip to stave off the freezing winds, but as supplementary fuel. Dumping the volatile alcohol directly into the furnace of his siege engine, Jetsteam, provides an explosive surge of emergency power that has gotten him out of more than one tight spot.",sp=0}},faq={{q="What is Evershine?",a="Evershine is an exceptionally strong, experimental alcoholic brew concocted by the dwarven brewmaster Rejold Barleybrew in Brewnall Village. It is famous for its fiery kick and ability to fell even hardy dwarven drinkers.",al={"what is evershine","evershine brew","what kind of drink is evershine"},it="item"},{q="Why does Pilot Bellowfiz want Evershine?",a="Pilot Bellowfiz uses Evershine both to keep warm against Dun Morogh's chill and as emergency combustible fuel. When poured into the furnace of his siege engine, Jetsteam, the volatile spirit yields an immediate burst of propulsion.",al={"why bellowsfiz wants brew","pilot bellowfiz evershine","why does bellowfiz need it"},it="motive"},{q="Where is Brewnall Village?",a="Brewnall Village is located in western Dun Morogh, directly along the road west of Kharanos. It sits nestled near the snowy hills and is home to local brewers like Rejold Barleybrew.",al={"where is brewnall","brewnall village location","find brewnall"},it="place",gp=true},{q="Who is Rejold Barleybrew?",a="Rejold Barleybrew is an experimental dwarven brewer stationed in Brewnall Village. He crafts a wide variety of drinks, ranging from pleasant ales to fierce concoctions potent enough to ignite machine furnaces.",al={"who is rejold","rejold barleybrew info","barleybrew brewer"},it="people"},{q="What comes next after reaching Rejold Barleybrew?",a="Rejold does not part with his prized liquor without assistance. Arriving at Brewnall Village leads into the quest 'A Favor for Evershine', where players must help the brewer before he hands over a cask for Pilot Bellowfiz.",al={"next quest after evershine","what after evershine","rejold quest followup"},sp=1,it="next_step"},{q="Is Evershine truly safe to drink?",a="According to Pilot Bellowfiz, Evershine will flatten almost any dwarf who tries it. While technically consumable by the most iron-stomached mountain folk, its extreme flammability makes it just as suitable for fueling an engine furnace.",al={"can you drink evershine","is evershine poison","evershine dangerous"},it="item"}},ang={["race:Gnome"]="Pilot Bellowfiz's habit of repurposing mundane objects—even dwarven booze—into improvised fuel would impress any gnomish tinker.",["race:Dwarf"]="Rejold Barleybrew's potent spirit represents the fiery extremes of dwarven brewing tradition in the cold peaks of Dun Morogh.",["profession:Engineering"]="Using volatile distilled spirits as an auxiliary fuel booster shows how pilots like Bellowfiz keep their siege engines running in harsh environments."},kw={"brewnall village","dun morogh","evershine","jetsteam","kharanos","pilot bellowfiz","rejold barleybrew"},rel={"npc:pilot-bellowfiz","npc:rejold-barleybrew","quest:319","quest:317","subzone:brewnall-village","subzone:kharanos","zone:dunmorogh","topic:dwarf"},m={start="Pilot Bellowfiz",["end"]="Rejold Barleybrew",level="7",faction="Alliance",id=318},src={"Evershine"}}
E["quest:319"] = {t="quest",n="A Favor for Evershine",z="dunmorogh",s="To secure a cask of Evershine for Pilot Bellowfiz at Steelgrill's Depot, an adventurer must first lend a hand to Brewnall Village. Brewer Rejold Barleybrew refuses to part with his liquor until the dangerous predators roaming the nearby snowdrifts are thinned out.",h="To secure a cask of Evershine for Pilot Bellowfiz at Steelgrill's Depot, an adventurer must first lend a hand...",sec={{t="A Brewer's Bargain",b="Rejold Barleybrew has the cask of Evershine that Pilot Bellowfiz requires, but he is in no hurry to surrender his prized brew for free. Rather than asking for coin, Rejold asks for protection. The wild beasts of western Dun Morogh—ravenous Ice Claw Bears, thick-hided Elder Crag Boars, and prowling Snow Leopards—wander uncomfortably close to Brewnall Village, creating constant distraction and peril for the locals.",sp=0},{t="Peace for the Craftsmen",b="While Rejold is quick to insist that no self-respecting dwarf cowers before wild animals, dealing with predators around the clock consumes valuable hours. Culling the local wildlife gives the villagers the peace they need to focus on distillation and smithing without keeping one eye perpetually on the tree line.",sp=0}},faq={{q="Why does Rejold want these animals killed?",a="Prowling bears, boars, and snow leopards wander close to Brewnall Village. While the dwarves are not afraid of them, driving them off wastes valuable working hours that could be spent brewing and crafting.",al={"why kill bears","why cull animals brewnall","rejold task reason"},it="motive"},{q="What is Evershine?",a="Evershine is a potent, celebrated liquor brewed exclusively in Brewnall Village by Rejold Barleybrew. Siege engine pilots like Pilot Bellowfiz find it remarkably useful, both as a beverage and as a volatile fuel additive.",al={"what is evershine","evershine brew","rejold liquor"},it="item"},{q="Who originally asked for the Evershine?",a="Pilot Bellowfiz back at Steelgrill's Depot sent you to procure it to keep him warm on the road and to throw into the furnace of his own siege engine, Jetsteam, for a burst of power.",al={"who sent me for evershine","who wants evershine","quest chain start"},it="origin"},{q="Where can the animals be found?",a="They wander the frozen fields and crags immediately surrounding Brewnall Village and Iceflow Lake in western Dun Morogh.",al={"where are ice claw bears","snow leopard location","elder crag boar location"},it="target",gp=true},{q="What happens after completing the favor?",a="Once the beasts are culled, Rejold hands over the cask of Evershine, allowing you to return it directly to Pilot Bellowfiz at Steelgrill's Depot.",al={"next quest","what after favor for evershine"},it="next_step"},{q="Are the villagers in actual danger from the predators?",a="Rejold maintains that no self-respecting dwarf fears a beast in the snow, but having dangerous predators snarl outside the doorstep is a persistent disruption and danger to daily work.",al={"is brewnall in danger","are dwarves scared"},it="danger"},{q="What animals is Rejold Barleybrew sending you to hunt?",a="Rejold sends you to cull the wild predators and beasts roaming the snowy drifts around Brewnall Village: Ice Claw Bears, Elder Crag Boars, and Snow Leopards. These native beasts wander dangerously close to the settlement's perimeter, growling and snorting outside while the villagers try to tend to their vats and workshops.",al={"rejold targets","which beasts","animals to kill evershine","what animals brewnall"},it="target",add="02738ac5"},{q="Why does Rejold ask you instead of having Brewnall's villagers handle the beasts?",a="The dwarves of Brewnall Village are hardly afraid of local wildlife—no self-respecting dwarf would cower before a boar or snow leopard. However, hunting down packs of prowling predators takes valuable time away from their true passions: brewing ale, crafting, and tending their vats. Since you are an able-bodied traveler already looking for a cask of Evershine, Rejold strikes a trade so his folk can keep working in peace.",al={"why can't villagers kill them","why me rejold","why does rejold need help","brewnall village hunters"},it="why_me",add="fe0fe64f"}},ang={["race:Dwarf"]="Every dwarf understands the importance of keeping wild predators away from an honest still, ensuring Brewnall's legendary casks remain undisturbed.",["race:Gnome"]="The siege pilots and tinkerers at Steelgrill's Depot urgently await this cask, relying on adventurers to appease the stubborn brewer so the Jetsteam's preparations can continue.",["class:Hunter"]="Thinning the aggressive predators of western Dun Morogh tests marksmanship against the hardiest winter beasts of the crags."},kw={"bellowfiz","brewnall village","dun morogh","elder crag boar","evershine","ice claw bear","rejold barleybrew","snow leopard"},rel={"npc:rejold-barleybrew","quest:318","subzone:brewnall-village","quest:317","zone:dunmorogh","topic:dwarf"},m={start="Rejold Barleybrew",level="8",faction="Alliance",id=319},src={"A Favor for Evershine"}}
E["quest:3361"] = {t="quest",n="A Refugee's Quandary",z="dunmorogh",s="Following the disastrous fall of Gnomeregan to troggs and radiation, displaced gnomes have fled into the snowy wilds of Dun Morogh. Outside Anvilmar, an engineer named Felix Whindlebolt lost his vital belongings and tools to Frostmane troll scavengers during the panicked evacuation.",h="Following the disastrous fall of Gnomeregan to troggs and radiation, displaced gnomes have fled into the...",sec={{t="The Flight from Gnomeregan",b="When subterranean troggs overran the high-tech city of Gnomeregan, High Tinker Gelbin Mekkatorque and his advisors authorized the release of radioactive gas in a desperate bid to eradicate the invaders. The gambit backfired catastrophically, slaying thousands of innocents, mutating survivors into mindless leper gnomes, and forcing the remaining populace into a frantic exodus across Dun Morogh.",sp=0},{t="Scavengers in the Snow",b="Fleeing engineers and tinkerers carried whatever prized tools and blueprints they could save. However, the icy mountain passes between Gnomeregan and Coldridge Valley are prowled by indigenous Frostmane trolls. As Felix Whindlebolt scrambled toward the sanctuary of Anvilmar, Frostmane raiders snatched his tool chest, lockbox, and bucket of bolts, carting them off to their camps southwest of town.",sp=0}},faq={{q="Who is Felix Whindlebolt?",a="Felix Whindlebolt is a gnome engineer who narrowly escaped the radioactive destruction of Gnomeregan. Lacking the martial skill to fight off the dangers of Dun Morogh, he shelters near Anvilmar while attempting to recover his stolen equipment.",al={"felix whindlebolt","who is felix","felix anvilmar"},it="identity"},{q="Why is Gnomeregan irradiated?",a="During an unexpected trogg invasion, gnome authorities unleashed volatile radioactive gas intended to wipe out the monsters. The gas contaminated the city's ventilation systems instead, slaughtering or mutating most residents and rendering the capital uninhabitable.",al={"what happened to gnomeregan","gnomeregan radiation","fall of gnomeregan"},it="history"},{q="Who stole Felix's belongings?",a="Frostmane trolls took his chest, box, and bucket of bolts. These native trolls ambush travelers along the mountain trails of Dun Morogh and haul stolen scrap and gear back to their crude encampments southwest of Anvilmar.",al={"who stole the bolts","who has felix's stuff","frostmane trolls"},it="threat"},{q="Where did the displaced gnomes seek refuge?",a="Many gnomes fled across Dun Morogh to the dwarven kingdom of Ironforge, while others sought temporary shelter in smaller settlements like Anvilmar and Kharanos throughout Dun Morogh.",al={"where are gnomes living","gnome refugees","gnome settlement"},it="place"},{q="Why does a bucket of bolts matter so much?",a="For an exiled gnome tinkerer, tools, specialized screws, and machined bolts represent their entire livelihood. Without proper equipment, refugee engineers have no way to ply their trade, fashion defenses, or rebuild their lives in exile.",al={"why bolts","felix bucket of bolts"},it="item"},{q="What threat do the Frostmane trolls pose to Coldridge Valley?",a="The Frostmane tribe has long inhabited the harsh peaks of Dun Morogh. With the recent trogg outbreaks and the chaos of the Gnomeregan evacuation, the trolls have grown bolder, raiding supply lines and ambushing travelers.",al={"trolls in dun morogh","frostmane threat","frostmane camp"},it="danger"},{q="Why does Felix Whindlebolt want his belongings back?",a="Having fled the radiation poisoning Gnomeregan with barely the clothes on his back, Felix lost the last remnants of his livelihood and trade. Without his personal chest, box, and tools, he is completely stranded in Anvilmar with no means to rebuild his life or ply his craft as a refugee.",al={"felix motive","why does felix need this","felix whindlebolt belongings"},it="motive",add="0b2d3aab"},{q="Why can't Felix retrieve his belongings himself?",a="Felix is an ordinary tinkerer and displaced refugee, not an adventurer or soldier. Terrified by the hostile wilderness and outmatched by the Frostmane trolls who carried off his gear, he cannot risk venturing into their encampments alone.",al={"why doesn't felix get his stuff","why does felix need me","felix why me"},it="why_me",add="48f90e68"},{q="What is inside Felix's Box and Chest?",a="Felix's chest and box contain the personal belongings and specialized tools he managed to pack when fleeing the disaster in Gnomeregan. To a displaced craftsman far from home, these containers hold everything required to make a fresh start.",al={"felix's box","felix's chest","what is in felix's chest"},it="item",add="6a13a14f"}},ang={["race:Gnome"]="This quest encapsulates the bitter tragedy facing your people: having lost your wondrous home to poison and betrayal, everyday tinkerers must now beg strangers to pry basic tools from crude trolls.",["race:Dwarf"]="The Coldridge mountains have sheltered your kin for centuries; helping gnome refugees secure their footing in Anvilmar honors the ancient alliance between Ironforge and Gnomeregan.",["profession:Engineering"]="No self-respecting craftsman can stand by while scavengers make off with precision bolts, calipers, and toolboxes that took a lifetime to assemble."},kw={"anvilmar","bucket of bolts","coldridge","felix whindlebolt","frostmane","gnomeregan","radiation"},rel={"npc:felix-whindlebolt","zone:gnomeregan","subzone:anvilmar","zone:dunmorogh","topic:gnome","topic:troll","topic:trogg"},m={start="Felix Whindlebolt",level="3",faction="Alliance",id=3361,ri={"Felix's Box","Felix's Bucket of Bolts","Felix's Chest"}},src={"A Refugee's Quandary (Classic)"}}
E["quest:3364"] = {t="quest",n="Scalding Mornbrew Delivery",z="dunmorogh",s="Scalding Mornbrew Delivery is a hurried errand through Coldridge Valley to deliver fresh hot drink before it chills in the mountain frost. Nori Pridedrift entrusts the delivery to an adventurer to ensure Durnan Furcutter receives his mornbrew piping hot.",h="Scalding Mornbrew Delivery is a hurried errand through Coldridge Valley to deliver fresh hot drink before it...",sec={{t="A Race Against the Frost",b="Dun Morogh's biting cold has ruined many a hot meal, and Mornbrew is no exception. After completing a delivery to Grelin Whitebeard, Nori Pridedrift realizes he lacks the time to bring another fresh cup to Anvilmar before it freezes into an unpalatable slush. Rather than let his customer down, he enlists any swift traveler willing to brave the snow.",sp=0},{t="The Price of a Warm Mug",b="Durnan Furcutter, stationed inside the warmth of Anvilmar's mountain hall, is known to be particular about his refreshments. Chilly Mornbrew simply will not do. Delivering the piping drink intact earns a weary dwarf a much-needed break from his duties, though Nori still expects his favorite mug returned in one piece.",sp=0}},faq={{q="Who is Durnan Furcutter?",a="Durnan Furcutter is a dwarf residing inside the subterranean hall of Anvilmar in Coldridge Valley. He relies on local deliveries from Nori Pridedrift for his hot mornbrew.",al={"durnan furcutter","who is durnan","furcutter"},it="identity"},{q="Why does the delivery need to be so fast?",a="The freezing alpine weather of Coldridge Valley causes hot drinks to cool rapidly. Durnan specifically ordered scalding mornbrew, and cold ale or tea is considered ruined by dwarf standards.",al={"why timed","mornbrew timer","why hurry"}},{q="Who is Nori Pridedrift?",a="Nori Pridedrift is a dwarf stationed out in the snowy paths of Coldridge Valley. He tends to deliveries between local encampments, including bringing drinks to Grelin Whitebeard and workers in Anvilmar.",al={"nori pridedrift","nori","who is nori"},it="identity"},{q="What is mornbrew?",a="Mornbrew is a warm, invigorating dwarven morning brew, crafted to cut through the freezing chill of the Dun Morogh peaks and sustain hardy mountain workers.",al={"what is mornbrew","mornbrew lore"},it="item"},{q="Where is Anvilmar located?",a="Anvilmar is situated directly northeast of Nori's post, carved into the mountain rock of Coldridge Valley to shelter young mountaineers and craftsmen from the blizzards.",al={"where is anvilmar","anvilmar location","find anvilmar"},it="place",gp=true},{q="Does Nori want the mug back?",a="Yes. Once Durnan finishes enjoying his hot brew, he hands back the empty container so it can be returned to Nori in Coldridge Valley.",al={"mug return","bring back the mug","nori's mug"},it="next_step"},{q="Why does Nori Pridedrift want the mornbrew delivered?",a="Nori was supposed to deliver fresh, piping-hot mornbrew to Durnan Furcutter, but a prior delivery to Grelin Whitebeard held him up. Durnan specifically expects his brew piping hot, not lukewarm or chilly, so Nori is scrambling to get the drink to Anvilmar before it completely cools off.",al={"why deliver mornbrew","nori motive","why does nori need this delivered"},it="motive",add="77d8ea01"},{q="Why does Nori ask you to deliver it instead of taking it himself?",a="Nori has already fallen behind schedule after stopping to serve Grelin Whitebeard. Knowing the brew only stays scalding hot for a few short minutes, he realizes he cannot sprint up the mountain path quickly enough on his own. Spotting you, he relies on your fresh legs to dash to Anvilmar before the drink turns cold.",al={"why does nori need me","why cant nori deliver it","why me nori delivery"},it="why_me",add="4fdc3467"}},ang={["race:Dwarf"]="Every dwarf understands the tragedy of cold brew in freezing mountain air, making this dash across the valley a matter of pure principle.",["profession:Cooking"]="Serving beverages at the proper temperature is a mark of true culinary respect, especially under Dun Morogh's punishing sub-zero conditions."},kw={"anvilmar","coldridge valley","dun morogh","durnan furcutter","mornbrew","nori pridedrift"},rel={"npc:nori-pridedrift","npc:durnan-furcutter","subzone:anvilmar","quest:3365","zone:dunmorogh"},m={start="Nori Pridedrift",["end"]="Durnan Furcutter",level="5",faction="Alliance",id=3364},src={"Scalding Mornbrew Delivery"}}
E["quest:3365"] = {t="quest",n="Bring Back the Mug",z="dunmorogh",s="After delivering a piping hot draught of Mornbrew across the snowdrifts of Dun Morogh, one final errand remains: returning the empty tankard. Durnan Furcutter sends the runner back across Coldridge Valley to return Nori Pridedrift's prized mug. It is a simple courtesy, but one the brew seller deeply appreciates.",h="After delivering a piping hot draught of Mornbrew across the snowdrifts of Dun Morogh, one final errand...",sec={{t="A Matter of Tavern Etiquette",b="Serving piping hot Mornbrew out in the biting freeze of Dun Morogh is a delicate business. Once Durnan Furcutter has finished warming his bones with the scalding brew, the empty tankard cannot simply be tossed in the snow. Dwarven hospitality runs on mutual respect, and letting good dishware go missing is a sure way to find oneself cut off from future rounds.",sp=0},{t="Mugs Don't Grow on Trees",b="Returning to Coldridge Valley completes the delivery run for Nori Pridedrift. As Nori is fond of reminding forgetful couriers, sturdy drinkware does not simply grow on trees—especially not in the subzero crags of the dwarven homeland. Returning the empty vessel in one piece cements an adventurer's reputation as a reliable hand in the local community.",sp=0}},faq={{q="Who starts this errand?",a="Durnan Furcutter gives you this task immediately after you deliver the freshly brewed Mornbrew to him out in Dun Morogh.",al={"quest giver","who gives bring back the mug","durnan furcutter quest"},gp=true},{q="Who do I return the mug to?",a="You return the empty mug to Nori Pridedrift, who wanders Coldridge Valley in Dun Morogh selling his mornbrew.",al={"where do i take the mug","who gets the mug","nori location"},gp=true},{q="Is there a time limit to return the mug?",a="No. While the initial delivery of the Scalding Mornbrew had a strict timer to keep the drink piping hot, returning the empty mug can be done at your own pace.",al={"is this quest timed","mug timer","do i have to hurry back"},gp=true},{q="Why does Nori care so much about an empty mug?",a="Quality mugs and steins are valuable barware in Dun Morogh. As Nori points out, mugs do not grow on trees, and taverns cannot afford to lose drinkware to every passing courier.",al={"why does nori want the mug back","importance of the mug"},it="why_wanted"},{q="What quest leads directly into this one?",a="This errand is the direct follow-up to 'Scalding Mornbrew Delivery', beginning the moment Durnan drinks the beverage you brought him.",al={"prerequisite quest","what comes before bring back the mug"},gp=true},{q="Where can Durnan Furcutter be found?",a="Durnan Furcutter is a cloth and leather armor merchant found inside Anvilmar, the settlement dug into the mountain in Coldridge Valley.",al={"durnan location","where is durnan"},it="place",gp=true},{q="Why does Durnan Furcutter want this done?",a="Durnan Furcutter just finished enjoying the piping hot scalding mornbrew delivered by Nori in Coldridge Valley to keep the chill away. Returning the empty mug is basic courtesy to Nori Pridedrift, who expects his glassware back rather than letting couriers leave it scattered out in the freezing snow of Dun Morogh.",al={"why return mug","durnan return mug","why send back the mug"},it="motive",add="aa771bb6"}},ang={["race:Dwarf"]="Every dwarf knows that keeping a tavernkeeper's tankard is a quick route to a brawl; returning Nori's mug is basic dwarven manners.",["profession:Cooking"]="Any proper cook or brewer knows that quality service does not end until the dishware is accounted for and returned to the kitchen."},kw={"bring back the mug","dun morogh","durnan furcutter","kharanos","mornbrew","nori pridedrift","tankard"},rel={"quest:3364","npc:nori-pridedrift","npc:durnan-furcutter","zone:dunmorogh"},m={start="Durnan Furcutter",["end"]="Nori Pridedrift",level="5",faction="Alliance",id=3365},src={"Bring Back the Mug"}}
E["quest:384"] = {t="quest",n="Beer Basted Boar Ribs",z="dunmorogh",s="Ragnar Thunderbrew of the Thunderbrew Distillery in Kharanos needs fresh crag boar ribs and a mug of Rhapsody Malt to feed his hungry tavern patrons. With his regular meat supplier away fighting in the King's Army, Ragnar relies on passing travelers to keep his famed ribs on the menu.",h="Ragnar Thunderbrew of the Thunderbrew Distillery in Kharanos needs fresh crag boar ribs and a mug of Rhapsody...",sec={{t="A Tavern in Need",b="The Thunderbrew Distillery in Kharanos is famous for hearty dwarven ale and hearty tavern fare. Chief among its offerings are the legendary Beer Basted Boar Ribs. However, tavern keeper Ragnar Thunderbrew finds himself in a bind: the local hunter who usually kept the pantry stocked with fresh meat recently enlisted in the King's Army to reinforce the Alliance front, leaving Ragnar with plenty of eager customers and completely empty larders.",sp=0},{t="The Secret Ingredient",b="To recreate the dish, fresh meat must be harvested from the tough crag boars roaming the snowy foothills around Kharanos. The true magic of the recipe, however, lies in the baste. Ragnar insists on using fresh Rhapsody Malt drawn straight from the taps of the distillery. The malt breaks down the tough game meat, turning rough mountain game into a savory feast worthy of a dwarf's praise.",sp=0}},faq={{q="Why is Ragnar Thunderbrew short on meat?",a="Ragnar's regular meat supplier, a local mountain trapper, left Kharanos to enlist in the King's Army to support Alliance operations abroad, leaving the tavern without a steady supply of game.",al={"why ragnar need boar ribs","what happened to ragnar meat supplier","who supplies the ribs"},it="motive"},{q="Where does Rhapsody Malt come from?",a="Rhapsody Malt is brewed and served directly inside the Thunderbrew Distillery in Kharanos, available straight from the innkeeper at the tavern bar.",al={"where get rhapsody malt","how to get malt for ragnar","who sells rhapsody malt"},it="item",gp=true},{q="What kind of boars provide the ribs?",a="The meat is taken from the crag boars that roam the hills, snowdrifts, and frozen valleys surrounding Kharanos throughout Dun Morogh.",al={"which boars drop ribs","where find boar ribs dun morogh","crag boars dun morogh"},it="target",gp=true},{q="What is the secret to Ragnar's rib recipe?",a="The secret is basting the tough boar ribs in Rhapsody Malt, which tenderizes the cold-weather game and infuses it with the rich flavor of dwarven brewing.",al={"secret to beer basted ribs","beer basted boar ribs secret"},it="item"},{q="Who is fighting on the front lines for the King's Army?",a="Dwarven recruits regularly join the King's Army to support the Alliance in ongoing conflicts against troggs, dark iron incursions, and broader military fronts across the Eastern Kingdoms.",al={"why did the trapper enlist","what war is the kings army fighting","alliance front lines 25 adp"}},{q="Where is the Thunderbrew Distillery located?",a="The distillery serves as the primary tavern and inn of Kharanos, situated along the main roadway running through central Dun Morogh.",al={"where is thunderbrew distillery","where is ragnar thunderbrew","kharanos inn location"},it="place"},{q="What are the Crag Boar Ribs for?",a="Ragnar needs these ribs to prepare his tavern's signature dish, Beer Basted Boar Ribs. The local patrons crave them, but his regular meat supplier enlisted in the King's Army to fight on the front lines, leaving the Thunderbrew Distillery completely out of fresh stock.",al={"crag boar ribs use","why ribs","what are boar ribs for"},it="item",add="44c418cd"},{q="Why does Ragnar need an adventurer to gather the ingredients?",a="Ragnar is busy running the Thunderbrew Distillery and serving thirsty tavern patrons in Kharanos. With his usual supplier off fighting in the King's Army, he must rely on passing travelers like you to hunt the local crag boars and fetch ingredients from the innkeeper inside.",al={"why me ragnar","why can't ragnar get ribs","why ask me ragnar"},it="why_me",add="ba894b88"}},ang={["profession:Cooking"]="Adventurers with an interest in hearthside cooking can learn the secret to blending malt liquor with wild game directly from one of Dun Morogh's most famed brewmasters.",["race:Dwarf"]="For dwarves, hearty ale and roasted boar are the bedrock of mountain hospitality, making stocking the distillery a matter of local pride.",["faction:Alliance"]="Even domestic tavern shortages in Kharanos stem from the broader Alliance war effort, as local mountain folk leave their trades to answer the call to arms."},kw={"beer basted boar ribs","crag boar","dun morogh","kharanos","ragnar thunderbrew","rhapsody malt","thunderbrew distillery"},rel={"npc:ragnar-thunderbrew","subzone:thunderbrew-distillery","subzone:kharanos","quest:117","zone:dunmorogh","topic:alliance"},m={start="Ragnar Thunderbrew",["end"]="Ragnar Thunderbrew",faction="Alliance",id=384,ri={"Rhapsody Malt","Tender Boar Ribs"}},src={"Beer Basted Boar Ribs (quest)"}}
E["quest:400"] = {t="quest",n="Tools for Steelgrill",z="dunmorogh",s="Tools for Steelgrill is an early Alliance delivery errand that introduces travelers leaving Kharanos to the nearby mechanic workshop at Steelgrill's Depot. Tharek Blackstone sends you up the road with a fresh crate of heavy equipment for Beldin Steelgrill, the master siege engine tech who works through spanners and ratchets faster than town suppliers can keep up.",h="Tools for Steelgrill is an early Alliance delivery errand that introduces travelers leaving Kharanos to the...",sec={{t="A Master Rough on His Gear",b="Beldin Steelgrill carries an undisputed reputation across Dun Morogh as the sharpest siege engine mechanic in the mountains, but his violent work ethic takes a heavy toll on his workshop. According to Tharek Blackstone in Kharanos, Steelgrill cracks arclight spanners and snaps tools almost as fast as local supply crates can arrive. When a fresh batch of durable gear is assembled in Kharanos, anyone heading northeast is quickly recruited to lug the heavy parcel out to the depot.",sp=0},{t="Keeping the Engines Running",b="Arriving at Steelgrill's Depot, travelers find the yard crowded with smoke, grease, and idling iron war machines. Beldin's backlog is thick with demanding military repairs, including critical work on Pilot Stonegear's siege engine. Beldin had snapped his last fang-ratchet mere hours before your arrival, making the delivered crate an immediate lifeline for Ironforge's tracked armor fleet.",sp=0}},faq={{q="Where do I take the tools?",a="Take them northeast out of Kharanos along the road leading toward Ironforge. Beldin Steelgrill works out in the open at Steelgrill's Depot, surrounded by parked siege engines and tanks.",al={"where is steelgrill","where to deliver tools","beldin steelgrill location"},it="place",gp=true},{q="Who is Beldin Steelgrill?",a="Beldin Steelgrill is a renowned dwarven mechanic and siege engine specialist who runs Steelgrill's Depot in Dun Morogh. He oversees repairs, modifications, and maintenance for veteran pilots serving Ironforge's mechanized armored forces.",al={"who is beldin","beldin lore","siege engine tech"},it="identity"},{q="Why does Beldin break so many tools?",a="Siege engines are massive, heavily plated war machines held together by oversized iron fittings. Working on these reinforced hulls demands tremendous leverage and brute force, which routinely snaps delicate arclight spanners and fang-ratchets during urgent repairs.",al={"why broken tools","arclight spanners breaking","steelgrill tools"}},{q="Whose siege engine is Beldin fixing?",a="When you deliver the tools, Beldin is actively working to finish vital repairs on the siege engine belonging to Pilot Stonegear, a veteran dwarven pilot stationed at the depot.",al={"pilot stonegear tank","what engine is broken","stonegear siege engine"}},{q="What is Steelgrill's Depot?",a="Steelgrill's Depot is an open-air mechanical staging ground and workshop northeast of Kharanos. It acts as a gathering hub for veteran siege engine pilots and tank crews testing, tuning, and repairing their armored treads.",al={"what is the depot","depot purpose","steelgrill workshop"},it="place"},{q="Why does Tharek Blackstone ask an adventurer to carry them?",a="Tharek had just filled Steelgrill's latest tool order and needed a reliable traveler heading northeast to carry the heavy crate, offering modest coin and an introduction to the veteran pilots gathering up the road.",al={"why ask me","tharek delivery reason"},it="why_me"},{q="Why does Tharek Blackstone want these tools delivered?",a="Tharek runs Kharanos's supply trade and has just assembled Beldin Steelgrill's latest order of equipment. Beldin is the finest siege engine technician in Dun Morogh, but his rough hands chew through delicate gear like arclight spanners at an alarming rate. Keeping Beldin supplied ensures the dwarven siege engines keeping the roads and mountains secure remain fully operational.",al={"tharek blackstone motive","why deliver tools for steelgrill","why send steelgrill tools"},it="motive",add="fd264fde"}},ang={["profession:Engineering"]="Beldin's trade hinges on precision engineering instruments like arclight spanners and fang-ratchets, illustrating the heavy strain mechanical warfare places on crafted tools.",["race:Dwarf"]="Dwarven armored warfare depends entirely on field repair stations like Steelgrill's Depot to keep Ironforge's mighty siege engines rolling across the frozen passes.",["race:Gnome"]="The arclight spanners and intricate ratchets Beldin exhausts are hallmarks of gnomish-influenced precision engineering adapted for brutal dwarven plate."},kw={"arclight spanner","beldin steelgrill","dun morogh","fang-ratchet","kharanos","pilot stonegear","siege engine","steelgrill's depot","tharek blackstone"},rel={"subzone:steelgrill-s-depot","npc:beldin-steelgrill","npc:tharek-blackstone","npc:pilot-stonegear","subzone:kharanos","zone:dunmorogh"},m={start="Tharek Blackstone",["end"]="Beldin Steelgrill",level="5",faction="Alliance",id=400},src={"Tools for Steelgrill"}}
E["quest:403"] = {t="quest",n="Guarded Thunderbrew Barrel",z="dunmorogh",s="The Guarded Thunderbrew Barrel rests in the cellar of the Thunderbrew Distillery in Kharanos. It represents the prized stock of the famed dwarven brewing family, watched over day and night to keep thieves and rivals from meddling with their craft.",h="The Guarded Thunderbrew Barrel rests in the cellar of the Thunderbrew Distillery in Kharanos.",sec={{t="A Cellar Under Watch",b="In the cold snows of Dun Morogh, few things are guarded more fiercely than good ale. Beneath the floorboards of the Thunderbrew Distillery in Kharanos, stout casks of potent brew age in peace. The family takes no chances with their stock, posting watchful sentries like Jarven Thunderbrew right beside the barrels to ensure not a single drop is tampered with or siphoned off.",sp=0},{t="Family Pride and Rivalries",b="Dwarven brewing is as serious a discipline as smithing or mining. The Thunderbrews take immense pride in their proprietary recipes, particularly potent batches of Thunder Ale. Between greedy troggs creeping around Dun Morogh and bitter brewing rivalries across the Alliance, Jarven's vigilant presence ensures the family's liquid gold remains untouched until properly tapped.",sp=0}},faq={{q="Why can't I open this barrel?",a="Jarven Thunderbrew is standing right there in the basement keeping watch. As long as he remains on guard, no one is permitted to disturb the Thunderbrew family's barrels.",al={"cannot open barrel","why cant i touch the ale","jarven guarding barrel"},it="purpose",gp=true},{q="Who is Jarven Thunderbrew?",a="Jarven is a member of the Thunderbrew clan stationed in the Kharanos distillery cellar. His primary duty is to keep an eye on the family's finest ales and stop any would-be thieves or troublemakers from tampering with the stock.",al={"who is jarven","jarven lore","dwarf in cellar"},it="identity"},{q="Where is this barrel located?",a="The barrel sits down in the cellar beneath the Thunderbrew Distillery, located in the town of Kharanos in Dun Morogh.",al={"where is the guarded barrel","cellar location","thunderbrew basement"},it="place",gp=true},{q="Why do the Thunderbrews guard their ale so closely?",a="To dwarves, brewing is a revered craft and a family legacy. With competing brewers, sneaky thieves, and nearby threats like troggs and leper gnomes, rare vintage barrels of Thunder Ale require constant protection.",al={"why guard ale","importance of thunderbrew ale"},it="motive"},{q="Is this part of another quest?",a="Yes. It ties into Marleth Barleybrew's quest Bitter Rivals, in which you must sneak a barrel of Barleybrew Scalder in among the Thunderbrews' barrels of Thunder Ale.",al={"thunderbrew questline","what quest is this for"},it="ties",gp=true},{q="Can you distract or move Jarven?",a="Yes. Jarven has strict orders not to touch the stock, but he admits he would love a taste of Thunder Ale. Bringing him one in the quest Distracting Jarven draws his attention away from the barrels.",al={"how to get past jarven","distract jarven"},gp=true}},ang={["race:Dwarf"]="Every dwarf understands that a family's secret brew is worth defending with life and limb, making Jarven's stubborn vigil down in the cellar completely natural.",["class:Rogue"]="Slipping into a cellar to pilfer a cask of stout dwarven ale is classic work, but a vigilant dwarf watching the keg makes a quiet heist much trickier."},kw={"dun morogh","dwarven brew","guarded thunderbrew barrel","jarven thunderbrew","kharanos","thunder ale","thunderbrew distillery"},rel={"zone:dunmorogh","quest:117"},m={start="Guarded Thunder Ale Barrel",level="1",faction="Alliance",id=403},src={"Guarded Thunderbrew Barrel"}}
E["quest:412"] = {t="quest",n="Operation Recombobulation",z="dunmorogh",s="Operation Recombobulation is a bold engineering effort orchestrated by Razzle Sprysprocket in Kharanos. In response to the tragedy of Gnomeregan, Razzle and Ozzie Togglevolt seek to reverse the horrific transformation of their afflicted kin into leper gnomes using an experimental contraption known as the Recombobulator.",h="Operation Recombobulation is a bold engineering effort orchestrated by Razzle Sprysprocket in Kharanos.",sec={{t="A Remedy for a Calamity",b="When radiation flooded Gnomeregan to purge the trogg menace, it failed to destroy the invaders and instead warped the majority of the gnomish population into deranged, sickly leper gnomes. Refusing to accept this tragic mutation as permanent, inventor Razzle Sprysprocket has partnered with Ozzie Togglevolt to develop a technological cure: the Recombobulator. Their audacious goal is nothing less than restoring their mutated brethren back to health and sanity.",sp=0},{t="Scavenging from the Afflicted",b="Building a delicate prototype requires precise components, namely Restabilization Cogs and Gyromechanic Gears. In an ironic twist of fate, these essential parts are salvaged directly from the hostile leper gnomes wandering outside the sealed gates of Gnomeregan. By harvesting mechanical debris from their corrupted brothers and sisters, Razzle hopes to assemble the very device that will undo their shared tragedy.",sp=0}},faq={{q="What is the Recombobulator supposed to do?",a="The Recombobulator is an experimental machine designed by Razzle Sprysprocket and Ozzie Togglevolt intended to reverse the horrific mutagenic effects of Gnomeregan's radiation and cure the leper gnomes.",al={"what is recombobulator","purpose of recombobulator","recombobulate meaning"},it="purpose"},{q="Who are Razzle Sprysprocket and Ozzie?",a="They are gnomish inventors operating out of Kharanos in Dun Morogh. Following the fall of Gnomeregan, they have dedicated their engineering talents to studying the crisis and fabricating technological solutions to rescue their displaced and irradiated people.",al={"who is razzle","who is ozzie togglevolt","razzle sprysprocket lore"},it="people"},{q="Why are there leper gnomes outside Gnomeregan?",a="During the trogg invasion of Gnomeregan, radiation was released into the city to wipe out the beasts. The gambit backfired catastrophically: it failed to stop the troggs and instead drove many surviving gnomes mad, mutating them into hostile leper gnomes.",al={"why are gnomes lepers","how did leper gnomes happen","gnomeregan radiation"},it="threat"},{q="Where do the parts for the Recombobulator come from?",a="They are salvaged directly from the deranged leper gnomes pacing outside the entrance of Gnomeregan in western Dun Morogh, who still carry salvaged technological hardware on their bodies.",al={"where to get cogs and gears","restabilization cogs source","gyromechanic gears"},it="origin"},{q="Does the Recombobulator actually work?",a="Razzle claims that with the right parts, hydrolubricant, and adjustments to the electrogum gel, the machine will restore the gnomes to normal. However, gnomish engineering is famously prone to volatility, and whether it can truly undo toxic irradiation remains uncertain.",al={"did recombobulator cure them","can leper gnomes be cured","recombobulator success"},it="history"},{q="Why does Razzle Sprysprocket want this done?",a="The fall of Gnomeregan did not just leave the city overrun by troggs; the radiation released during the catastrophe twisted the vast majority of the gnomish population into mindless, hostile leper gnomes. Razzle Sprysprocket and his partner Ozzie refuse to accept that their people are lost forever. They believe their invention, the Recombobulator, can reverse the terrible afflictions of the fallout and restore the gnomish race to its former self.",al={"why does razzle want this","razzle motive","why build the recombobulator"},it="motive",add="8df716ac"},{q="What are the Restabilization Cogs and Gyromechanic Gears for?",a="These precision components are essential mechanical parts needed to finish building the Recombobulation Device according to Ozzie's intricate schematics. Once assembled into the apparatus alongside hydrolubricant, crank-o-ratchets, and electrogum gel, the gears and cogs will balance and regulate the machinery designed to undo the radiation that corrupted the leper gnomes.",al={"what are restabilization cogs","gyromechanic gears use","what are the parts for"},it="item",add="ed729e1a"},{q="Who are you sent against at Gnomeregan?",a="You are dispatched to hunt down the leper gnomes prowling outside the entrance gates of Gnomeregan. Formerly ordinary citizens, their minds and bodies were warped by the toxic radiation deployed to purge the trogg invasion. Driven mad, they now carry the scavenged machinery, gears, and cogs from the ruined city while violently attacking anyone who approaches.",al={"who am i fighting","operation recombobulation enemies","gnomeregan target"},it="target",add="c92cc687"}},ang={["race:Gnome"]="For gnomes, this task represents a desperate, heartfelt hope to save lost family and friends who were warped into violent shells during the fall of their capital.",["profession:Engineering"]="Engineers will appreciate Razzle's unorthodox tinkering, featuring intricate Restabilization Cogs, crank-o-ratchets, and viscous electrogum gel to manipulate biophysical radiation."},kw={"dun morogh","gnomeregan","gyromechanic gear","kharanos","leper gnome","ozzie togglevolt","razzle sprysprocket","recombobulator","restabilization cog"},rel={"npc:razzle-sprysprocket","zone:gnomeregan","topic:leper-gnome","subzone:kharanos","topic:gnome","topic:trogg","zone:dunmorogh"},m={start="Razzle Sprysprocket",level="10",faction="Alliance",id=412,ri={"Gyromechanic Gear","Restabilization Cog"}},src={"Operation Recombobulation (Classic)"}}
E["quest:413"] = {t="quest",n="Shimmer Stout",z="dunmorogh",s="Following the creation of his experimental Shimmer Stout in Brewnall Village, Rejold Barleybrew asks travelers to carry a fresh barrel out to his brother Wellart. Wellart serves as a dwarf Mountaineer stationed at the southern guard tower guarding the pass toward Loch Modan, where a cold post makes a strong drink all the more welcome.",h="Following the creation of his experimental Shimmer Stout in Brewnall Village, Rejold Barleybrew asks...",sec={{t="A Family Recipe on the Frontier",b="Rejold Barleybrew has perfected his new creation, Shimmer Stout, using shimmering fronds gathered from the icy crags of Dun Morogh. While the rest of the Barleybrew family dedicates their craft to the vats and kegs of Brewnall Village, Rejold's brother Wellart chose the life of a Mountaineer. Knowing the lonely conditions of guard duty on the frontier, Rejold sends a fresh barrel along with passing travelers as both a brotherly favor and a true taste test.",sp=0},{t="The South Gate Guard Tower",b="Wellart Barleybrew is stationed at the southern guard tower flanking the South Gate Pass into Loch Modan. High atop the mountain pass, the Mountaineers endure bitter winds and occasional beast attacks while keeping watch over travelers walking the mountain road. Running low on drink and restless for excitement, Wellart finds that Shimmer Stout delivers quite a punch—so much so that it seems to brighten his vision in the dim mountain night.",sp=0}},faq={{q="Who is Mountaineer Barleybrew?",a="Mountaineer Wellart Barleybrew is the brother of Rejold Barleybrew. Unlike his kin who brew ale in Brewnall Village, Wellart chose service in the Dun Morogh Mountaineers, keeping watch over the high pass connecting Dun Morogh to Loch Modan.",al={"who is wellart barleybrew","wellart barleybrew","mountaineer barleybrew lore"},it="identity"},{q="Where is the southern guard tower located?",a="The tower sits along the eastern border of Dun Morogh guarding the South Gate Pass, which cuts through the mountains toward the neighboring valley of Loch Modan.",al={"where is southern guard tower","mountaineer barleybrew location","where is wellart"},it="place",gp=true},{q="What makes Shimmer Stout special?",a="Shimmer Stout is brewed using special shimmering fronds collected in the snowy wilderness. According to Wellart, drinking it puts a bright shine in his eyes and makes him feel as though he can see straight through the dark.",al={"what does shimmer stout do","shimmer stout effect"},it="item"},{q="What happens after Wellart drinks the stout?",a="Wellart enjoys the brew so much that he asks travelers to haul an additional keg down into Loch Modan to share with Mountaineer Kadrell, who patrols the road through Thelsamar.",al={"what is next after shimmer stout","next quest after shimmer stout"},sp=1,it="next_step"},{q="Why does Rejold Barleybrew want this done?",a="Rejold is eager to share the fruits of his craft with his brother, Mountaineer Wellart Barleybrew. Having just perfected his new recipe for Shimmer Stout at the family distillery, Rejold knows that while Wellart walked away from the brewing trade to patrol the borders, he remains a true dwarf at heart who loves a hearty drink. Delivering a fresh barrel is both a gesture of brotherly pride and a way to get an honest verdict on his latest concoction from a thirsty soldier in the field.",al={"why send shimmer stout","rejold barleybrew motive","why deliver the stout"},it="motive",add="cd95a50e"}},ang={["race:Dwarf"]="For dwarves, sharing ale among family is as vital a duty as guarding the mountain passes, making this delivery a quintessential part of Ironforge frontier life.",["faction:Alliance"]="Keeping the vigilant Mountaineers supplied helps sustain the network of guards protecting the highway between Dun Morogh and Loch Modan."},kw={"dun morogh","kharanos","mountaineer barleybrew","rejold barleybrew","shimmer stout","south gate pass","wellart"},rel={"npc:rejold-barleybrew","npc:mountaineer-barleybrew","quest:415","quest:414","zone:dunmorogh","zone:lochmodan"},m={start="Rejold Barleybrew",["end"]="Mountaineer Barleybrew",level="10",faction="Alliance",id=413},src={"Shimmer Stout (quest)"}}
E["quest:414"] = {t="quest",n="Stout to Kadrell",z="dunmorogh",s="Stout to Kadrell is an Alliance delivery quest that leads travelers out of the frozen heights of Dun Morogh and into the temperate valley of Loch Modan. Entrusted with a cask of Rejold Barleybrew's newly perfected Shimmer Stout, you carry the potent brew across the territorial border to share with Mountaineer Kadrell on patrol in Thelsamar.",h="Stout to Kadrell is an Alliance delivery quest that leads travelers out of the frozen heights of Dun Morogh...",sec={{t="A Taste Beyond the Mountains",b="After tasting the newly finished Shimmer Stout created by his brother Rejold, Mountaineer Barleybrew is convinced it is too good to keep entirely within Dun Morogh. Stationed at the eastern border post guarding the mountain passes, Barleybrew looks out toward his kin guarding neighboring lands. Dwarven mountaineering can be a cold, grueling assignment, and a stout heart calls for stout drink. Wanting an honest appraisal from a fellow patrolman on the line, Barleybrew sends a cask eastward with passing travelers bound for Loch Modan.",sp=0},{t="The Road to Thelsamar",b="The journey marks a natural rite of passage for young dwarven and gnomish adventurers who have spent their early days among the snowbound crags of Dun Morogh. Passing southeast through the South Gate Outpost and traversing the long tunnels cut through the mountain bedrock, travelers suddenly emerge into the warmer, wooded basin of Loch Modan. Patrolling along the road through the settlement of Thelsamar, Mountaineer Kadrell gladly takes a break from his vigil to tap the cask, discovering that Barleybrew's new recipe has an astonishing kick.",sp=0}},faq={{q="Who is Mountaineer Kadrell?",a="Mountaineer Kadrell is a dwarven defender stationed in Loch Modan. He spends his days patrolling the central road that runs directly through the township of Thelsamar.",al={"kadrell","who is kadrell","mountaineer kadrell location"},it="identity"},{q="What is Shimmer Stout?",a="Shimmer Stout is a potent specialty ale brewed by Rejold Barleybrew at the Brewnall Village distillery in western Dun Morogh, renowned for its head-spinning kick and invigorating warmth.",al={"what is shimmer stout","shimmer stout","rejold brew"},it="item"},{q="How do I reach Loch Modan from Dun Morogh?",a="From the eastern guard posts in Dun Morogh, head southeast through the mountain tunnels past the South Gate. Once you emerge into Loch Modan, follow the road as it forks northeast straight toward the lakeside settlement of Thelsamar.",al={"how to get to loch modan","road to thelsamar","dun morogh to loch modan"},gp=true},{q="Why does Barleybrew want Kadrell to try the beer?",a="Mountaineer Barleybrew and Mountaineer Kadrell are fellow members of the dwarven Mountaineers. Barleybrew is so impressed by his brother's new recipe that he wants his comrade-in-arms stationed in the neighboring valley to sample it.",al={"why send stout to kadrell","barleybrew kadrell connection"},it="motive"},{q="What does Kadrell think of the brew?",a="Upon taking a sip, Kadrell is astonished by its strength, swearing by Magni's beard that the stout spins his head and lightens his limbs to the point that he feels like he can fly.",al={"kadrell reaction","is shimmer stout good"}},{q="Does this quest lead to further tasks?",a="While it concludes the specific Shimmer Stout delivery chain begun in Dun Morogh, delivering the cask brings travelers directly into Thelsamar, opening up numerous new quests and duties across Loch Modan.",al={"stout to kadrell follow up","what comes next"},it="next_step",gp=true},{q="Why does Mountaineer Barleybrew need you to deliver the cask?",a="Barleybrew is on active watch at the South Gate Outpost, tasked with guarding Dun Morogh's eastern borders and monitoring travelers. As a Mountaineer on duty, he cannot abandon his post simply to share a drink, leaving him dependent on passing adventurers traveling southeast toward Loch Modan to carry the cask to Kadrell.",al={"why cant barleybrew deliver the stout","why does barleybrew need me","why send an adventurer to thelsamar"},it="why_me",add="46258ba9"}},ang={["race:Dwarf"]="Carrying a cask of mountain ale across territorial lines is classic dwarven camaraderie, connecting the brewers of Brewnall Village with the border patrols guarding Khaz Modan.",["faction:Alliance"]="This task serves as the natural guiding thread leading Alliance heroes out of the starting snowy reaches of Dun Morogh and into the broader frontier of Loch Modan."},kw={"ale","barleybrew","cask","dun morogh","kadrell","loch modan","rejold","shimmer stout","thelsamar"},rel={"quest:413","quest:415","npc:mountaineer-kadrell","npc:mountaineer-barleybrew","subzone:thelsamar","zone:lochmodan","zone:dunmorogh"},m={start="Mountaineer Barleybrew",["end"]="Mountaineer Kadrell",level="10",faction="Alliance",id=414},src={"Stout to Kadrell"}}
E["quest:415"] = {t="quest",n="Rejold's New Brew",z="dunmorogh",s="Rejold's New Brew is an Alliance errand in Dun Morogh summoning an adventurer back to Brewnall Village. Having perfected a new concoction using gathered Shimmerweed, brewmaster Rejold Barleybrew wants a trusted friend to sample his latest recipe. It serves as the bridge between gathering brewing supplies and distributing his prized Shimmer Stout across the mountain realm.",h="Rejold's New Brew is an Alliance errand in Dun Morogh summoning an adventurer back to Brewnall Village.",sec={{t="A Summons to Brewnall",b="Word spreads quickly through Dun Morogh when a dwarven brewer strikes gold in his cellar. After securing Shimmerweed from the bitter slopes, local contacts like Tharek Blackstone or Pilot Bellowfiz urge passing adventurers to report back to Brewnall Village. Rejold Barleybrew has finished fermenting his experimental batches and is eager to share the spoils with the traveler who made it possible.",sp=0},{t="Tasting the Fruit of Labor",b="Brewnall Village thrives on distinct ale craft, and Barleybrew's newest batch is no ordinary draught. Infusing local herbs into his mash produced a distinct beverage known as Shimmer Stout. Before shipping barrels off to neighboring outposts and thirsty patrons in Loch Modan, Rejold insists that the adventurer who risked life and limb for the herbs gets the honor of the inaugural sip.",sp=0}},faq={{q="Who sends me back to Rejold Barleybrew?",a="Allies stationed out in Dun Morogh, such as Tharek Blackstone or Pilot Bellowfiz, inform you that Rejold is asking for your presence back at Brewnall Village.",al={"who starts rejolds new brew","quest giver","where to get quest"},it="identity"},{q="Where is Brewnall Village?",a="Brewnall Village sits nestled in the western reaches of Dun Morogh, along the shores of the frozen Iceflow Lake.",al={"where is brewnall","brewnall village location","rejold barleybrew location"},it="place",gp=true},{q="What is Rejold's new drink made of?",a="Rejold brewed his new concoction by incorporating wild Shimmerweed, a peculiar native flora found in the chilly crags of Dun Morogh, into his traditional ale recipes.",al={"what is in the brew","what did rejold make","shimmerweed recipe"},it="origin"},{q="What happens after I speak to Rejold?",a="Rejold offers you a sample of his new creation and then tasks you with bringing a barrel of Shimmer Stout out to his brother Wellart, a Mountaineer stationed in the southern guard tower on the border to Loch Modan.",al={"next quest","what comes next","rejold chain"},sp=1,it="next_step"},{q="Why does Rejold want me specifically to try it?",a="Because you assisted him in obtaining the rare Shimmerweed needed for the experimental recipe, Rejold considers it proper dwarven courtesy to let you sample the final result first.",al={"why does rejold want me","who tested the beer"},it="why_me"},{q="What is the name of the final beverage?",a="The experimental blend becomes known as Shimmer Stout, named after the key ingredient that gives it its distinct kick.",al={"what drink did he make","drink name","rejold's beer"},it="name"},{q="Why does the quest giver send you to Rejold Barleybrew?",a="Rejold Barleybrew has been actively asking around for you specifically. Word reached outposts like Steelgrill's Depot, and whether it was Tharek Blackstone or Pilot Bellowfiz who caught wind of it, they are simply passing the message along. Rejold needs your help testing a promising new recipe, and as far as your informants are concerned, answering his call might just earn you a taste of free booze.",al={"why does tharek send me to rejold","why does pilot bellowfiz send me to brewnall","why return to rejold"},it="motive",add="4916bbae"}},ang={["race:Dwarf"]="For a dwarf, there is hardly a higher honor than being personally summoned by a respected brewmaster to take the first pull from a fresh cask.",["faction:Alliance"]="Hearty dwarven ales fuel Alliance garrisons throughout the Eastern Kingdoms, keeping spirits high in harsh frontier outposts like Dun Morogh."},kw={"ale","brew","brewnall village","dun morogh","pilot bellowfiz","rejold barleybrew","shimmer stout","shimmerweed","tharek blackstone"},rel={"npc:rejold-barleybrew","subzone:brewnall-village","quest:413","quest:414","zone:dunmorogh"},m={start="Tharek BlackstonePilot Bellowfiz",["end"]="Rejold Barleybrew",level="10",faction="Alliance",id=415},src={"Rejold's New Brew"}}
E["quest:417"] = {t="quest",n="A Pilot's Revenge",z="dunmorogh",s="Following the trail of a missing dwarven siege engine pilot leads to a frozen corpse in the wilds of Dun Morogh. Found among the remains, Hildelve's personal journal details his fatal struggle against a notorious predator known as Mangeclaw, leaving behind a dying wish for vengeance.",h="Following the trail of a missing dwarven siege engine pilot leads to a frozen corpse in the wilds of Dun...",sec={{t="A Final Entry",b="Pilot Hildelve did not survive his time stranded in the rugged snowy crags. When travelers locate his remains, they discover his journal resting beside him. In his last penned words, Hildelve recorded a savage encounter with a massive Ice Claw bear he named Mangeclaw. Though he managed to fend off the monstrosity initially, the injuries proved severe, and the beast eventually returned to finish off the weakened pilot.",sp=0},{t="A Pilot's Dying Wish",b="Knowing his end was near, Hildelve wrote down one final plea in his journal: retribution against the monster that took his life. Returning to Pilot Hammerfoot with the journal and a claw torn from the fallen beast brings grim closure to the Ironforge Siege Brigade, honoring their lost comrade and removing a deadly menace from the mountain paths.",sp=0}},faq={{q="Who was Hildelve?",a="Pilot Hildelve was a dwarven siege engine pilot and a member of the Ironforge Siege Brigade. After his engine broke down and he set out on foot into the mountains of Dun Morogh, his friend Pilot Hammerfoot sent searchers to locate him, only to uncover his remains in the snow.",al={"hildelve","who is the dead dwarf","lost pilot"},it="identity"},{q="What is Mangeclaw?",a="Mangeclaw is an exceptionally large and ferocious Ice Claw bear roaming the slopes of Dun Morogh. It ambushed Pilot Hildelve and inflicted mortal wounds before eventually returning to kill him.",al={"mangeclaw","ice claw bear","who killed hildelve"},it="target"},{q="Who is Pilot Hammerfoot?",a="Pilot Hammerfoot is a seasoned siege engine pilot stationed in Dun Morogh who belongs to the Ironforge Siege Brigade. Deeply concerned about his missing friend Hildelve, he directs adventurers into the wilderness to find out what happened.",al={"hammerfoot","pilot hammerfoot"},it="people"},{q="Why does Hildelve's death matter to Ironforge?",a="The Ironforge Siege Brigade depends on its trained pilots and machinery to scout and defend the mountainous territory around the capital. Losing a skilled pilot like Hildelve is a harsh blow to the brigade's ranks.",al={"why care about hildelve","siege brigade importance"},it="ties"},{q="Where does this quest chain begin?",a="The journey begins with Pilot Hammerfoot offering 'The Lost Pilot', asking you to search for his missing friend. That leads to finding Hildelve's corpse, which starts 'A Pilot's Revenge'.",al={"how to start a pilot's revenge","lost pilot quest chain"},gp=true},{q="What proof do you need to bring to Hammerfoot?",a="You must present both Hildelve's Journal, recovered from the pilot's corpse, and a Mangy Claw taken from the carcass of Mangeclaw to prove the beast was slain.",al={"mangeclaw proof","what items needed"},it="item"},{q="Why does the dwarven corpse give you this task?",a="The corpse is that of Pilot Hildelve, who recorded his final moments in his recovered journal. Although he initially fended off the massive ice claw bear Mangeclaw, the beast returned to finish him off. His journal makes his dying wish clear: he wanted vengeance against the beast that ended his life in the frozen crags.",al={"why dwarven corpse quest","hildelve motive","why revenge on mangeclaw"},it="motive",add="5ec072c3"},{q="Why can't Ironforge handle Mangeclaw themselves?",a="Pilot Hammerfoot is stationed at the remote camp awaiting word of his missing comrade, unaware of Hildelve's fate until you discover the body. With Hildelve lying dead in the snow and no patrol nearby to stumble upon his journal, you are the only one on the scene capable of carrying out his final wish.",al={"why do i have to kill mangeclaw","why me a pilots revenge","why doesn't hammerfoot kill mangeclaw"},it="why_me",add="b9e5721c"}},ang={["race:Dwarf"]="Avenging a fallen brother of the Ironforge Siege Brigade is a matter of honor, ensuring Hildelve's memory is respected and his killer punished.",["faction:Alliance"]="The pilots of Ironforge form a crucial branch of dwarven and Alliance defense, making the recovery of lost pilots an essential duty.",["class:Hunter"]="Tracking down an unusually vicious alpha beast like Mangeclaw in the freezing winds of Dun Morogh is a true test of mountain survival."},kw={"dun morogh","hammerfoot","hildelve","ice claw bear","ironforge siege brigade","mangeclaw","revenge"},rel={"quest:419","npc:pilot-hammerfoot","zone:dunmorogh","zone:ironforge"},m={start="A Dwarven Corpse",["end"]="Pilot Hammerfoot",level="11",faction="Alliance",id=417,ri={"Mangy Claw"}},src={"A Pilot's Revenge (Classic)"}}
E["quest:419"] = {t="quest",n="The Lost Pilot",z="dunmorogh",s="Pilot Hammerfoot fears the worst for his comrade, Mori Hildelve, who ventured into the craggy hills of Dun Morogh on foot after wrecking his siege engine. Hildelve was searching for a rare ore vital for potent blastpowder, but days have passed amidst unsettling roars echoing through the peaks.",h="Pilot Hammerfoot fears the worst for his comrade, Mori Hildelve, who ventured into the craggy hills of Dun...",sec={{t="A Search Cut Short",b="Dwarven siege engines are formidable war machines, but even iron treads struggle against the treacherous, jagged ridges of Dun Morogh. While scouring the slopes for a rare mineral deposit required to produce high-grade blastpowder, Pilot Mori Hildelve pushed his engine too far up a steep hill and busted the machine. Undeterred by the breakdown, Hildelve ordered his companion, Pilot Hammerfoot, to stay behind and guard the broken machinery while he pressed higher into the frozen wilderness on foot.",sp=0},{t="Echoes in the Snow",b="Days went by with no sign of Hildelve returning to camp. In the dead of night, strange and vicious beastly growls began echoing down from the rocky crags, turning Hammerfoot's mild impatience into creeping dread. Though Hildelve had a reputation for being as tough as nails, surviving the frigid heights of Dun Morogh without mechanized armor or heavy support against prowling predators is a dangerous gamble.",sp=0},{t="A Grim Discovery",b="Following Hildelve's path up the slopes leads not to a stranded scout, but to a frozen tragedy. The dwarf's remains lie exposed to the elements, mauled and stripped by mountain scavengers. Clutched tightly in his lifeless hand are his roughly scribbled notes—and still draped over his ruined frame is his brigadier's vest, confirming that the brave siege engineer met an untimely and violent end.",sp=1}},faq={{q="Why was Pilot Hildelve out in the wilderness alone?",a="Hildelve was searching for a rare type of ore needed to craft high-grade dwarven blastpowder. When his siege engine broke down on a steep mountain slope, he chose to press on into the crags on foot rather than abandon the prospect.",al={"why hildelve left","what was hildelve doing","pilot hildelve mission"},it="purpose"},{q="Who sends you to look for Hildelve?",a="Pilot Hammerfoot, Hildelve's friend and fellow siege engine operator, asks travelers to investigate. He was ordered to stay behind and guard their damaged machinery while Hildelve scouted ahead.",al={"who gives quest","lost pilot quest giver"},it="identity"},{q="What happened to Hildelve's siege engine?",a="Hildelve attempted to pilot his heavy machine straight up a steep, icy hillside while scouting for ore, wrecking its mechanics and stranding it in the snow.",al={"broken siege engine","why engine broke"},it="history"},{q="What killed Pilot Hildelve?",a="Hammerfoot has heard beastly growls in the hills and fears for Hildelve. The pilot's fate is discovered by following his trail.",al={"hildelve killer","how did pilot die","who killed hildelve"},sp=1,it="threat"},{q="What proof is found at Hildelve's remains?",a="Hammerfoot asks you to find Hildelve after he continued the ore search on foot. Any evidence of what happened to him is uncovered at the end of the search.",al={"hildelve evidence","hildelve corpse items","proof of death"},sp=1,it="item"},{q="What happens after Hildelve's body is discovered?",a="Finding Hildelve reveals what happened during his search. The investigation then continues with the evidence found there.",al={"what next lost pilot","revenge quest"},sp=1,it="next_step"},{q="Why does Pilot Hammerfoot want you to find Hildelve?",a="Pilot Hammerfoot and Mori Hildelve are close friends and fellow Siege Engine pilots who journeyed into the hills together searching for rare ore. Mori set off on foot days ago after wrecking his engine, leaving Hammerfoot behind. Having heard ferocious growls echoing through the mountains every night since, Hammerfoot is deeply worried for his comrade's survival and desperate to learn his fate.",al={"why does hammerfoot want hildelve","pilot hammerfoot motive","why search for hildelve"},it="motive",add="da1c7c00"},{q="Why doesn't Pilot Hammerfoot look for Hildelve himself?",a="Before venturing into the snow-covered peaks alone, Hildelve explicitly charged Hammerfoot with guarding their valuable siege engines. With one machine damaged and both stranded out in the rugged wilds of Dun Morogh, Hammerfoot cannot abandon his post to launch a solitary search without leaving Ironforge's heavy machinery completely defenseless to wandering beasts and scavengers.",al={"why cant hammerfoot search","why does hammerfoot need me","why send an adventurer"},it="why_me",add="120a5684"}},ang={["race:Dwarf"]="The loss of a skilled Siege Engine driver to wild beasts hits close to home, underscoring the lethal dangers that linger even in Khaz Modan's backyard.",["profession:Engineering"]="Hildelve's expedition highlights the relentless dwarven search for volatile minerals to refine potent explosives and blastpowder."},kw={"blastpowder","brigadier vest","dun morogh","lost pilot","mori hildelve","pilot hammerfoot","siege engine"},rel={"npc:pilot-hammerfoot","quest:417","zone:dunmorogh","topic:dwarf"},m={start="Pilot Hammerfoot",["end"]="Mori Hildelve",level="10",faction="Alliance",id=419},src={"The Lost Pilot (Classic)"}}
E["quest:420"] = {t="quest",n="Senir's Observations",z="dunmorogh",s="This errand completes a scouting line out of Coldridge Valley, carrying Grelin Whitebeard's completed report through the trogg-infested pass to his brother Senir in Kharanos. It bridges the secluded training grounds of Anvilmar with the broader troubles facing Dun Morogh. Through Senir's candid reception, travelers catch their first glimpse of political friction simmering between field scouts and the Ironforge Senate.",h="This errand completes a scouting line out of Coldridge Valley, carrying Grelin Whitebeard's completed report...",sec={{t="Through the Tunnel to Kharanos",b="After Grelin Whitebeard recovers his stolen journal from the Frostmane trolls, he prepares a detailed report of the valley's threats for his brother Senir. Mountaineer Thalos, stationed guarding the gate out of Coldridge Valley, entrusts passing adventurers with carrying this dispatch. Leaving the relative seclusion of the introductory vale means braving the tunnel cut through the mountain, which has recently been overrun by violent troggs ambushing all traffic. Travelers who punch through emerge onto the snowblown highways of central Dun Morogh, following the main road straight into the cozy hub of Kharanos.",sp=0},{t="A Grumpy Welcome and Senate Politics",b="Senir Whitebeard, found seeking warmth over drinks at the Thunderbrew Distillery in Kharanos, greets newcomers with rough mountaineer hospitality. Reading through Grelin's findings, Senir chuckles over his brother's aggressive rhetoric. Grelin liberally invokes the name of King Magni Bronzebeard to press for urgent action, an assertive tactic Senir notes is bound to agitate the stubborn Ironforge Senate. Senir admits he has fallen behind on filing his own observations due to the bitter cold, but receiving Grelin's dispatch nudges him back into service, opening further work monitoring hostile forces across the snowfields.",sp=0}},faq={{q="Why is Mountaineer Thalos having a traveler deliver the report?",a="Mountaineer Thalos is posted to hold the defense line at the Coldridge Valley tunnel against aggressive troggs. He cannot abandon his watchpost, so when an able adventurer comes through, he tasks them with carrying Grelin's dispatch safely into Kharanos.",al={"why thalos asks you","thalos courier","who gives this quest"},it="why_me"},{q="Who is Senir Whitebeard?",a="Senir Whitebeard is a dwarven scout and brother to Grelin Whitebeard. Stationed at Kharanos, he collates scouting field reports on local threats to pass along to the high command in Ironforge.",al={"who is senir","senir whitebeard kharanos","senir background"},it="identity"},{q="What is in Grelin's report?",a="The report compiles Grelin's findings on the Frostmane troll activity and incursions within Coldridge Valley. Written urgently, it invokes King Magni Bronzebeard's authority to demand reinforcements and attention from the authorities.",al={"what does the report say","grelin report contents","grelins report lore"},it="item"},{q="Why does Senir say Grelin's report will ruffle feathers in the Senate?",a="Grelin invokes King Magni's name forcefully to demand action. In Ironforge politics, relying on royal decrees can bypass or challenge the bureaucratic authority and pride of the dwarven Senate, irritating council members who prefer formal deliberation.",al={"senate feathers ruffled","senir ironforge senate","why is the senate mad"},it="conflict"},{q="Why is the tunnel between Coldridge Valley and Kharanos dangerous?",a="A clan of Rockjaw troggs has recently emerged from the deep subterranean cracks and seized the mountain tunnel, attacking any dwarven travelers, merchants, or messengers trying to pass through.",al={"coldridge tunnel dangerous","trogg tunnel dun morogh","why are troggs in the tunnel"},it="danger"},{q="Where does the road lead after delivering this message?",a="Arriving in Kharanos integrates adventurers into the broader defense of Dun Morogh. Senir Whitebeard later enlists help investigating further Frostmane and trogg threats, while town leaders direct aid toward Brewnall Village, Ironforge, and the outlying farms.",al={"what next after senir","next quest after senirs observations","where does kharanos lead"},it="next_step",gp=true},{q="Why does Mountaineer Thalos want this report delivered?",a="Mountaineer Thalos is stationed to guard the dangerous pass out of Coldridge Valley and cannot abandon his post. Grelin Whitebeard's reconnaissance on the trogg and troll threats is vital intelligence meant for his brother Senir, who coordinates broader defensive reports for Ironforge. Ensuring the report reaches Senir in Kharanos is crucial for warning the rest of Dun Morogh about the brewing dangers.",al={"why send grelins report","thalos motive","why deliver the report to senir"},it="motive",add="bc98cde7"}},ang={["race:Dwarf"]="Passing from the sheltered training valley into Kharanos marks your true graduation into the defense of Khaz Modan, offering an early taste of how field scouts clash with Ironforge's cautious Senate.",["race:Gnome"]="Heading through the pass to Kharanos brings exiled gnomes closer to the main hubs of Dun Morogh and the ongoing efforts to support their dwarven hosts.",["faction:Alliance"]="Helping scouts coordinate intelligence keeps Dun Morogh secure at a time when Stormwind is paralyzed by domestic strife and cannot spare aid for its northern allies."},kw={"coldridge valley","dun morogh","grelin whitebeard","grelin's report","ironforge senate","kharanos","mountaineer thalos","senir whitebeard","troggs"},rel={"quest:282","quest:218","quest:182","npc:senir-whitebeard","npc:mountaineer-thalos","subzone:kharanos","zone:dunmorogh","zone:ironforge"},m={start="Mountaineer Thalos",["end"]="Senir Whitebeard",level="5",faction="Alliance",id=420},src={"Senir's Observations (2)"}}
E["quest:432"] = {t="quest",n="Those Blasted Troggs!",z="dunmorogh",s="Foreman Stonebrow is at his wit's end after troggs completely overran his operations at Gol'Bolar Quarry. Destructive and aggressive, the beasts have trashed his mining equipment and powder barrels, leaving him furious and demanding retaliation. Unable to fight them himself due to failing aim, he pays brave adventurers to head down into the pit and cull the brute Skullthumpers.",h="Foreman Stonebrow is at his wit's end after troggs completely overran his operations at Gol'Bolar Quarry.",sec={{t="Chaos in the Quarry",b="Gol'Bolar Quarry was once a proud, productive dwarf excavation site nestled in the snowy hills of eastern Dun Morogh. That prosperity ended abruptly when subterranean troggs broke through the bedrock and swarmed the lower terraces. Instead of merely occupying the tunnels, the savages have wreaked wanton havoc, smashing scaffolding and blowing through precious barrels of blasting powder.",sp=0},{t="Stonebrow's Boiling Rage",b="Watching the ruin of his life's work from the safety of the ridge has pushed Foreman Stonebrow to the brink of apoplexy. Frustrated by his own aging hands and poor aim, he relies on passing wanderers and Alliance recruits to execute raw vengeance. Thinning the ranks of the burly Rockjaw Skullthumpers provides him a brief moment of relief, though nothing short of total extermination will truly satisfy his wrath.",sp=0}},faq={{q="Where is Gol'Bolar Quarry?",a="Gol'Bolar Quarry sits in eastern Dun Morogh, south of the main road that leads east toward the gates of Loch Modan. Foreman Stonebrow stands along the rim overlooking the infested excavation pits.",al={"gol'bolar location","where is the quarry","stonebrow location"},it="place",gp=true},{q="Why are the troggs attacking the quarry?",a="Troggs dwell deep beneath the earth across Khaz Modan. Dwarven excavations frequently breach subterranean caverns where troggs nest, inciting violent surface surges that quickly overwhelm active mines.",al={"why troggs here","trogg invasion reason"},it="threat"},{q="Who is Foreman Stonebrow?",a="Foreman Stonebrow is the dwarven supervisor in charge of Gol'Bolar Quarry. Bitter, hot-tempered, and troubled by fading combat skills, he directs willing fighters to clear out the trogg infestation.",al={"stonebrow","who gives quest"},it="identity"},{q="What is a Rockjaw Skullthumper?",a="Rockjaw Skullthumpers are the brutish, frontline enforcers of the trogg tribe occupying Gol'Bolar Quarry, relying on raw physical strength and primitive clubs to bludgeon intruders.",al={"skullthumper","skullthumpers"},it="target"},{q="Why can't Stonebrow clear the quarry himself?",a="Stonebrow admits that his eyesight and aim are no longer what they used to be in his youth. Hampered by age, he chooses to hire adventurers rather than risk getting overwhelmed down in the quarry pits.",al={"why doesn't stonebrow fight"},it="why_me"},{q="What are the troggs destroying in the quarry?",a="Beyond disrupting mining operations, the troggs are actively wrecking heavy equipment and detonating supplies, including precious barrels of dwarven blasting powder.",al={"trogg destruction","what are troggs breaking"},it="conflict"},{q="Why does Foreman Stonebrow want the troggs killed?",a="Foreman Stonebrow is beside himself with fury watching his life's work get torn apart. The invading troggs have overrun the Gol'Bolar Quarry, smashing equipment and detonating his precious blasting powder. Left with nothing but stress and boiling anger, Stonebrow wants sheer vengeance: he wants to see every single trogg down there wiped out so his blood pressure can settle and order can eventually return to the site.",al={"stonebrow motive","why kill troggs","stonebrow quarry revenge"},it="motive",add="dd6a776f"}},ang={["race:Dwarf"]="The trogg infestation in Khaz Modan strikes close to home for every dwarf. Seeing Gol'Bolar's stonecutters driven out by mindless brute troggs makes vengeance down in the pit personal.",["profession:Mining"]="Gol'Bolar Quarry represents crucial dwarven stonecutting and mineral extraction. Clearing the invaders is the first step toward getting the picks swinging again."},kw={"dun morogh","gol'bolar","powder","quarry","rockjaw","skullthumper","stonebrow","troggs"},rel={"npc:foreman-stonebrow","subzone:gol-bolar-quarry","topic:trogg","zone:dunmorogh","topic:light"},m={start="Foreman Stonebrow",level="9",faction="Alliance",id=432},src={"Those Blasted Troggs! (Classic)"}}
E["quest:433"] = {t="quest",n="The Public Servant",z="dunmorogh",s="Senator Mehr Stonehallow of Ironforge has traveled directly to Gol'Bolar Quarry to address the sudden trogg invasion threatening Dun Morogh's mining operations. Seeking to reclaim the site, he enlists adventurers to cut down the aggressive Rockjaw Bonesnappers so miners can return to work.",h="Senator Mehr Stonehallow of Ironforge has traveled directly to Gol'Bolar Quarry to address the sudden trogg...",sec={{t="A Senator in the Field",b="It is rare to find a member of Ironforge's Senate standing in the slush and dirt of a contested mine, but Senator Mehr Stonehallow is no typical politician. Holding dual allegiance to the dwarven ruling body and the scholarly Explorers' League, Stonehallow has taken personal responsibility for organizing a response to the trogg infestation at Gol'Bolar Quarry. Rather than waiting for slow legislative measures, he directly contracts capable mercenaries and travelers to cull the invaders.",sp=0},{t="The Disaster at Gol'Bolar",b="Gol'Bolar Quarry was once a vital source of stone and mineral wealth for Dun Morogh, but deep excavations broke into previously sealed subterranean hollows. Primitive, savage troggs of the Rockjaw tribe flooded into the pits, wrecking delicate mining equipment and driving out civilian laborers. Stonehallow's objective is to clear out the vicious Rockjaw Bonesnappers, paving the way for Mountaineer garrisons to secure the quarry and restore iron-shoveling infrastructure.",sp=0}},faq={{q="Who is Senator Mehr Stonehallow?",a="Mehr Stonehallow is a dwarven dignitary who serves in the Ironforge Senate while also holding membership in the Explorers' League. He has taken a direct, hands-on role in dealing with the trogg threat at Gol'Bolar Quarry rather than remaining behind city walls.",al={"stonehallow","senator stonehallow","who is the senator"},it="identity"},{q="Why is Gol'Bolar Quarry overrun with troggs?",a="Dwarven miners dug too deeply into the earth beneath the quarry, unwittingly breaching caverns inhabited by the Rockjaw trogg tribe. The creatures burst into the open excavations, smashed machinery, and forced the workers to flee.",al={"why are troggs at gol bolar","quarry troggs","what happened to the quarry"},it="conflict"},{q="What are Rockjaw Bonesnappers?",a="Rockjaw Bonesnappers are brute-force combatants within the subterranean Rockjaw trogg clan. They wield crude weapons and rely on sheer ferocity to overwhelm dwarven miners and defenders.",al={"rockjaw bonesnapper","bonesnappers","bonesnapper troggs"},it="target"},{q="What is the plan after clearing out the troggs?",a="Once the initial trogg forces are culled, Senator Stonehallow aims to bring in Ironforge Mountaineers to properly fortify the quarry, rebuild the wrecked machinery, and resume resource extraction.",al={"stonehallow plan","what happens next gol bolar"},it="next_step"},{q="Why is the Explorers' League involved here?",a="Senator Stonehallow is affiliated with the Explorers' League, whose members frequently investigate ancient excavations, subterranean ruins, and trogg incursions throughout the Khaz Modan mountain ranges.",al={"explorers league mining","why league here"},it="allies"},{q="Where is Gol'Bolar Quarry located?",a="Gol'Bolar Quarry lies in southeastern Dun Morogh, cut into the snowy hills south of the road between Kharanos and the South Gate heading toward Loch Modan.",al={"gol bolar location","where is quarry"},it="place",gp=true},{q="Why does Senator Mehr Stonehallow want the troggs killed?",a="Senator Stonehallow views clearing Gol'Bolar Quarry as his civic duty as both an Explorers' League scholar and a member of Ironforge's Senate. The sudden trogg uprising wrecked vital mining machinery and drove out dwarven workers. Exterminating the pests is the essential first step toward reclaiming the site, repairing infrastructure, and getting the miners back underground.",al={"why kill troggs","mehr stonehallow motive","why clear gol'bolar"},it="motive",add="78fbc7a2"},{q="Why does Senator Stonehallow need an adventurer instead of the Mountaineers?",a="Ironforge's military forces are stretched thin across Dun Morogh dealing with trogg invasions and Frostmane troll raids. Senator Stonehallow has taken personal charge of the situation at Gol'Bolar Quarry, but the Mountaineers cannot safely establish a perimeter until the initial frontline of violent Rockjaw troggs is thinned out by willing travelers.",al={"why does mehr need me","why no mountaineers","why send an adventurer"},it="why_me",add="b5671d80"}},ang={["race:Dwarf"]="The trogg breach at Gol'Bolar strikes directly at your homeland's industry, proving once more how costly it is when deep digging meets subterranean terrors.",["profession:Mining"]="Miners feel the sting of Gol'Bolar's shutdown, as rich veins of stone and ore sit abandoned under the clubs of invading troggs.",["faction:Alliance"]="Ironforge's resources are critical for the broader Alliance, making the defense of Dun Morogh's quarries an economic necessity."},kw={"bonesnapper","dun morogh","gol'bolar","quarry","rockjaw","senate","stonehallow","trogg"},rel={"subzone:gol-bolar-quarry","npc:senator-mehr-stonehallow","topic:trogg","zone:dunmorogh","topic:explorers-league"},m={start="Senator Mehr Stonehallow",level="11",faction="Alliance",id=433},src={"The Public Servant (Classic)"}}
E["quest:466"] = {t="quest",n="Search for Incendicite",z="dunmorogh",s="Pilot Stonegear at Steelgrill's Depot seeks samples of volatile incendicite ore discovered in the Wetlands. Believing its explosive properties could revolutionize artillery munitions, he tasks miners with venturing north to extract the dangerous mineral from a secluded cave.",h="Pilot Stonegear at Steelgrill's Depot seeks samples of volatile incendicite ore discovered in the Wetlands.",sec={{t="A Volatile Discovery",b="Word of a rare and unstable mineral known as incendicite has reached the siege engine pilots and mechanics at Steelgrill's Depot. Rumors place rich veins inside a cavern northwest of Algaz Gate in the sodden marshlands of the Wetlands. Highly reactive and hazardous to handle, incendicite has developed a reputation for detonating in the faces of careless miners.",sp=0},{t="Munitions of Tomorrow",b="Where others see a mining hazard, Pilot Stonegear sees military potential. If refined properly, incendicite could serve as a devastating propellant or payload for dwarven artillery, producing cannon shells capable of shattering fortified defenses. Stonegear aims to procure raw samples so courageous, or foolhardy, researchers can begin testing smelting techniques without leveling the depot.",sp=0}},faq={{q="What is incendicite ore used for?",a="Incendicite is an intensely volatile, explosive mineral. Pilot Stonegear intends to test smelting methods to harness its reactive nature for high-yield artillery ammunition and cannon shells.",al={"incendicite uses","what does incendicite do"},it="why_wanted"},{q="Where is incendicite found?",a="Veins of the ore are located within a cave system northwest of Algaz Gate, nestled in the southern mountains of the Wetlands.",al={"incendicite location","where to get incendicite"},it="place",gp=true},{q="Who is Pilot Stonegear?",a="Pilot Stonegear is a dwarven siege engine pilot of the Ironforge Siege Brigade stationed at Steelgrill's Depot in Dun Morogh, working alongside mechanics and siege engineers to improve dwarven combat machinery.",al={"pilot stonegear","who gives this quest"},it="identity"},{q="Why does harvesting this ore require a pickaxe?",a="Incendicite occurs naturally in raw mineral veins rather than loose surface deposits. Miners must have sufficient skill to safely chip the brittle, explosive ore from the rock face without setting it off.",al={"do i need mining","mining skill needed"},gp=true},{q="Is incendicite safe to handle?",a="No. The ore is notoriously unstable and poses a severe threat of accidental detonation during excavation, transportation, and smelting.",al={"is incendicite dangerous","does incendicite explode"},it="danger"},{q="How does this connect to Stonegear's Search?",a="This assignment directly follows 'Stonegear's Search', wherein Pilot Stonegear initially gathered intelligence on potential material innovations before directing prospects to the Wetlands.",al={"stonegear search followup","quest chain"},it="ties"},{q="Why does Pilot Stonegear want incendicite ore?",a="Pilot Stonegear believes the volatile mineral holds untapped military potential. Incendicite is notoriously unstable and dangerous to handle, but he is convinced that properly smelted ore could be used to manufacture devastating cannon shells. Stationed at Steelgrill's Depot, Stonegear hopes to gather samples so Ironforge technicians can experiment with the explosive material and bolster their weaponry.",al={"why does stonegear want incendicite","stonegear incendicite motive","pilot stonegear goal"},it="motive",add="1b52d5e2"}},ang={["profession:Mining"]="Extracting incendicite requires practiced hands with a pick; the mineral's volatility makes delicate vein extraction a true test of a miner's craftsmanship.",["race:Dwarf"]="Dwarven engineers and artillerymen are renowned for pushing gunpowder technology forward, and unlocking incendicite shells fits right into Khaz Modan's siege traditions.",["profession:Engineering"]="Explosive compounds that threaten to blow up their creators are everyday business for tinkering engineers looking for the next big blast."},kw={"algaz gate","artillery","cannon shells","dun morogh","incendicite","mining","ore","pilot stonegear","steelgrill's depot","wetlands"},rel={"npc:pilot-stonegear","subzone:steelgrill-s-depot","quest:467","zone:dunmorogh","zone:wetlands"},m={start="Pilot Stonegear",level="22",faction="Alliance",id=466},src={"Search for Incendicite"}}
E["quest:5541"] = {t="quest",n="Ammo for Rumbleshot",z="dunmorogh",s="Gunsmith Hegnar Rumbleshot is running low on shot and powder for the riflemen practicing outside Anvilmar. A missing crate of ammunition was abandoned in the snowy wilds near the Grizzled Den when a courier was routed by hungry wendigo.",h="Gunsmith Hegnar Rumbleshot is running low on shot and powder for the riflemen practicing outside Anvilmar.",sec={{t="A Courier's Flight",b="Loslor Rudge at Steelgrill's Depot keeps steady supply lines flowing to tradesmen across Dun Morogh, but the valley's wildlife often interferes. His latest shipment of heavy ammunition never reached Hegnar Rumbleshot's roadside workshop. While camping near the cave system known as the Grizzled Den, the terrified courier crossed paths with local wendigo and fled for his life, abandoning the heavy wooden crate in the snow.",sp=0},{t="Powder and Shot",b="Hegnar Rumbleshot operates a gun shop situated right along the main road leading away from Anvilmar. The clearing outside his forge sees constant traffic from Ironforge riflemen, mountaineers, and dwarven mortar squads looking to zero their sights and drill with live fire. Without steady crates of powder and lead from suppliers like Loslor, the riflemen's marksmanship training quickly grinds to a dead stop.",sp=0}},faq={{q="Where was the ammo crate lost?",a="Loslor Rudge's frightened courier dropped the shipment while encamped just outside the Grizzled Den, a wendigo-infested cave nestled in the snowy hills southwest of Kharanos.",al={"ammo location","where is rumbleshot ammo","crate location"},it="place",gp=true},{q="Who is Hegnar Rumbleshot?",a="Hegnar Rumbleshot is a dwarven gunsmith who runs a weapon shop along the road near Anvilmar. He supplies powder, bullets, and firearms to the mountaineers, hunters, and siege teams drilling nearby.",al={"who is hegnar","rumbleshot","hegnar rumbleshot"},it="identity"},{q="Why was the courier chased off?",a="The courier made the mistake of camping near the Grizzled Den, the den of the savage, territorial wendigo that roam the hills southwest of Kharanos.",al={"why courier ran","wendigo attack","courier story"},it="threat"},{q="Why is Hegnar Rumbleshot out of ammunition?",a="Dwarven riflemen and mortar teams constantly burn through powder and lead practicing target drills near Hegnar's shop, keeping his inventory in high demand.",al={"why low on ammo","rumbleshot out of ammo"},it="purpose"},{q="Who is Loslor Rudge?",a="Loslor Rudge is a dwarven engineering supplier at Steelgrill's Depot whose business ships ammunition to Hegnar Rumbleshot.",al={"loslor rudge","who is loslor"},it="identity"},{q="Does recovered ammunition spoil in the snow?",a="Dwarven munitions are traditionally packed in heavy, weather-sealed wooden crates to keep black powder dry and ready to burn even in Dun Morogh's sub-zero blizzards.",al={"ammo ruined by snow","wet powder"}},{q="Why does Loslor Rudge need this ammo delivered?",a="Loslor Rudge operates out of Steelgrill's Depot and supplies vendors across Dun Morogh. Hegnar Rumbleshot is waiting on an overdue shipment to keep local riflemen and mortar teams supplied with practice rounds. A courier panicked and abandoned the crate when wendigo attacked their camp, leaving Loslor's business commitment unfulfilled and a valued customer empty-handed until you recover it.",al={"why does loslor care","loslor rudge motive","why send the ammo"},it="motive",add="76205b16"},{q="What is Rumbleshot's Ammo used for?",a="The crate contains fresh ammunition meant for Hegnar Rumbleshot's shop along the road to Anvilmar. Dwarven riflemen and mortar teams frequently train nearby and burn through supplies quickly, relying on Hegnar to keep their powder horns and shot pouches filled.",al={"what is rumbleshot ammo","rumbleshot crate use","why is ammo needed"},it="item",add="c1dcb566"}},ang={["class:Hunter"]="Every marksman in Coldridge knows Hegnar's shop well; keeping his shelves stocked with fresh powder and shot ensures you never face the wilderness with an empty rifle.",["race:Dwarf"]="Dwarven craftsmanship relies on an unyielding supply chain between Anvilmar's smithies and frontline gunsmiths like Rumbleshot.",["profession:Engineering"]="Dwarven firearms and mortars demand finely milled powder and uniform shot, making Rumbleshot's inventory essential for local tinkerers and gunners."},kw={"ammo","anvilmar","coldridge","grizzled den","hegnar","loslor rudge","rumbleshot","wendigo"},rel={"npc:hegnar-rumbleshot","npc:loslor-rudge","subzone:grizzled-den","quest:313","subzone:anvilmar","zone:dunmorogh"},m={start="Loslor Rudge",["end"]="Hegnar Rumbleshot",level="6",faction="Alliance",id=5541,ri={"Rumbleshot's Ammo"}},src={"Ammo for Rumbleshot"}}
E["quest:5625"] = {t="quest",n="Garments of the Light",z="dunmorogh",s="Garments of the Light is an early rite of passage for fledgling dwarven priests in Dun Morogh. Directed by Priest Trainer Maxan Anvol in Kharanos, the initiate is tasked with aiding a wounded mountaineer just outside town to earn their vestments.",h="Garments of the Light is an early rite of passage for fledgling dwarven priests in Dun Morogh.",sec={{t="An Urgent Trial",b="Traditionally, acolytes of the Holy Light undergo formal trials to prove they are worthy of wearing church vestments. In Kharanos, however, priest trainer Maxan Anvol favors practical results over ceremony. With local patrols hard-pressed against troggs and wild beasts, theoretical exams take a back seat when actual defenders lie bleeding in the snow.",sp=0},{t="Aiding the Mountaineers",b="To earn their robes, young priests are sent just south of town to locate Mountaineer Dolf, who was wounded in the line of duty. By mending Dolf's injuries with restorative prayers and bolstering his constitution with Power Word: Fortitude, the initiate proves that their devotion translates directly into survival for the defenders of Ironforge.",sp=0},{t="Robes of the Church",b="Upon aiding the mountaineer, Maxan Anvol presents the acolyte with their formal garments. Beyond providing warm insulation against Dun Morogh's chill, these robes serve as a visual badge of office, signaling to wounded wanderers and local guards alike that a servant of the Light is present to offer aid.",sp=0}},faq={{q="What is the purpose of this quest?",a="The quest tests a novice priest's practical application of their early spells. Instead of an academic examination, trainer Maxan Anvol sends you to locate the injured Mountaineer Dolf south of Kharanos, heal his wounds, and bolster his resilience with Power Word: Fortitude.",al={"what do i do","garments of the light goal"},it="purpose"},{q="Who is Maxan Anvol?",a="Maxan Anvol is the dwarven priest trainer stationed in Kharanos. Pragmatic and unpretentious, he mentors young priests arriving from Coldridge Valley and emphasizes the direct, life-saving utility of the Light over strict formal liturgy.",al={"who is maxan anvol","kharanos priest trainer"},it="identity"},{q="Who is Mountaineer Dolf?",a="Dolf is an Ironforge mountaineer stationed near Kharanos who sustained injuries while on patrol. He waits south of the settlement, serving as the practical test for initiates sent to mend his wounds and grant him Fortitude.",al={"dolf location","who is dolf"},it="identity"},{q="Why does a priest receive specific garments for this task?",a="Vestments and robes visually denote a practitioner's devotion and rank within the Holy Light. For community members and soldiers alike, spotting a robed priest immediately identifies someone capable of tending life-threatening injuries and offering spiritual guidance.",al={"why do priests wear robes","priest garments lore"},it="item"},{q="Why do dwarves worship the Holy Light?",a="The dwarves of Ironforge adopted the philosophy of the Holy Light through centuries of close cultural exchange and alliance with the humans of Lordaeron and Stormwind. Dwarven priests combine traditional highland grit with devout reverence for the Light's virtues of compassion, tenacity, and protection.",al={"dwarf light lore","do dwarves believe in the light"},it="history"},{q="What happens after completing this trial?",a="Maxan Anvol encourages the newly vested acolyte to venture out, practice their combat and support spells, and test their limits alongside other travelers. Harder trials within the church await as the priest grows in experience and power.",al={"what comes after garments of the light","next priest trial"},it="next_step"},{q="Why does Maxan Anvol want you to heal Dolf?",a="Priests of your standing are normally put through formal trials to prove they are worthy of wearing church vestments. However, Maxan Anvol has more pressing matters on his mind and received word that Mountaineer Dolf lies injured just south of Kharanos. Rather than conducting an idle test, Maxan uses this real emergency to see if you can put your faith into practice by mending and bolstering an ally on the field.",al={"why does maxan send you","maxan anvol motive","why help mountaineer dolf"},it="motive",add="21e41a20"},{q="Why does Maxan Anvol send you instead of tending to Dolf himself?",a="Maxan is tied down with broader duties tending to the parish and church matters in Kharanos, and you happen to be standing before him in need of your trial. Sending you out into the snow solves two problems at once: it provides immediate aid to the wounded mountaineer and simultaneously proves whether your training in the Light has prepared you for the harsh realities of Dun Morogh.",al={"why can't maxan heal dolf","why does maxan need me","why send an initiate"},it="why_me",add="574078e1"}},ang={["class:Priest"]="This rite of passage marks your transition from an unproven novice into a recognized minister of the Holy Light, trusted to keep companions alive on the front lines.",["race:Dwarf"]="Ironforge mountaineers guard the dangerous passes of Dun Morogh; tending to wounded scouts like Dolf reinforces the vital bond between dwarven faith and military defense.",["faction:Alliance"]="The Holy Light forms the spiritual backbone of the Alliance, offering comfort and battlefield restoration to soldiers holding the line against troggs, beasts, and worse."},kw={"dun morogh","fortitude","garments of the light","holy light","ironforge","kharanos","lesser heal","maxan anvol","mountaineer dolf","priest"},rel={"quest:5623","npc:maxan-anvol","subzone:kharanos","zone:dunmorogh","topic:light"},m={start="Maxan Anvol",level="4",faction="Alliance",id=5625},src={"Garments of the Light (Dun Morogh)"}}
E["quest:5626"] = {t="quest",n="In Favor of the Light",z="dunmorogh",s="\"In Favor of the Light\" marks a young priest's rite of passage from the isolated training grounds of Coldridge Valley into the wider reaches of Dun Morogh. Instructed by Branstock Khalder, novitiates are sent through the mountain tunnel to Kharanos to further their studies under Priest Trainer Maxan Anvol. It signals that an acolyte is ready to shoulder real responsibilities and earn the traditional vestments of their calling.",h="\"In Favor of the Light\" marks a young priest's rite of passage from the isolated training grounds of...",sec={{t="Leaving the Anvil",b="In the secluded cradle of Coldridge Valley, dwarven priests begin their studies under the watchful eye of instructors like Branstock Khalder. Once a novice demonstrates sufficient dedication and grasp of Holy magic, their preliminary instruction comes to an end. Rather than keeping them sheltered in Anvilmar, Khalder directs promising students beyond the mountains to Kharanos, where the demands of ministry and defense intersect with the daily struggles of Dun Morogh's folk.",sp=0},{t="A Step Toward Kharanos",b="Reaching Kharanos requires trekking through the Coldridge Pass tunnel into the windswept snows of central Dun Morogh. Waiting at the settlement is Maxan Anvol, a senior priest tasked with guiding students beyond rudimentary prayers. Anvol believes firmly that devotion to the Holy Light requires equal measures of moral character, physical hardiness, and an unyielding will. For acolytes who prove their resolve under his tutelage, Anvol prepares to bestow their first formal garments of office.",sp=0}},faq={{q="Who sends you on this journey?",a="Branstock Khalder, the dwarven priest trainer stationed at Anvilmar in Coldridge Valley, sends you to Kharanos once you have shown enough aptitude with the Holy Light to pursue advanced study.",al={"who gives quest","quest giver","branstock khalder"},it="identity"},{q="Who is Maxan Anvol?",a="Maxan Anvol is the priest trainer stationed in the mountain village of Kharanos. He guides developing priests, teaching them to temper their devotion with physical endurance and mental fortitude.",al={"maxan anvol lore","who is maxan anvol","kharanos priest trainer"},it="identity"},{q="What happens after reaching Maxan Anvol?",a="Maxan Anvol challenges you to prove your worthiness through the quest 'Garments of the Light', tasking you to aid injured locals before awarding your first official priest robes.",al={"next quest","what follows in favor of the light","garments of the light"},it="next_step"},{q="Why must priests leave Coldridge Valley so early?",a="Coldridge Valley offers only the basics of combat and spellcraft. Broader communities like Kharanos face immediate logistical and defensive threats, offering fledgling priests real-world experience in serving their people.",al={"why leave coldridge","leaving anvilmar","why go to kharanos"},it="why_here"},{q="Do human priests receive this same quest?",a="Human priests in Elwynn Forest undertake an equivalent rite of passage under the exact same name, directed by Priestess Anetta in Northshire to visit Priestess Josetta in Goldshire.",al={"human in favor of the light","northshire version"}},{q="How does the dwarven view of the Light differ here?",a="Dwarves place great emphasis on physical strength, will, and practical endurance alongside piety. As Maxan Anvol notes, serving the Light in the freezing mountain peaks demands strength of body as much as faith.",al={"dwarf light beliefs","dwarves and the light"},it="origin"},{q="Why does Branstock Khalder send you to Kharanos?",a="Branstock recognizes that you have advanced past the basic teachings in Coldridge Valley. To continue your spiritual journey and earn the vestments appropriate for an ordained servant of the Holy Light, he sends you to Maxan Anvol, a senior priest in Kharanos who can test your worthiness and guide your next steps.",al={"why send me to kharanos","branstock khalder motive","why visit maxan anvol"},it="motive",add="7dcff5c0"}},ang={["class:Priest"]="This task is a milestone for fledgling priests, representing their formal graduation from basic training into active service and the acquisition of their first vestments.",["race:Dwarf"]="Dwarven priesthood blends spiritual devotion with practical resilience, sending acolytes straight from Coldridge's fires into the harsh, freezing winds of Dun Morogh."},kw={"branstock khalder","coldridge valley","dun morogh","in favor of the light","kharanos","light","maxan anvol","priest","vestments"},rel={"quest:5624","npc:maxan-anvol","npc:branstock-khalder","subzone:kharanos","zone:dunmorogh","topic:light","quest:5623"},m={start="Branstock Khalder",["end"]="Maxan Anvol",level="4",faction="Alliance",id=5626},src={"In Favor of the Light (Dun Morogh)"}}
E["quest:6064"] = {t="quest",n="Taming the Beast",z="dunmorogh",s="Taming the Beast is the first trial in a dwarven hunter's journey to mastering companion beasts in Dun Morogh. Guided by Grif Wildheart in Kharanos, young trackers learn to quell and bond with a ferocious Large Crag Boar using an enchanted taming rod.",h="Taming the Beast is the first trial in a dwarven hunter's journey to mastering companion beasts in Dun Morogh.",sec={{t="A Hunter's Companion",b="Up to this point, dwarven mountaineers and trackers rely solely on their gunplay, traps, and wilderness instincts. Yet the true soul of a hunter lies in forging a lifelong partnership with a wild beast. Grif Wildheart, stationed outside the Thunderbrew Distillery in Kharanos, oversees this rite of passage. Rather than expecting a novice to permanently bind the first beast they come across, Grif instructs them to test their patience and resolve against several native species of Dun Morogh.",sp=0},{t="The Crag Boar",b="The first trial pits the tracker against a Large Crag Boar, one of the rugged, thick-hided swine that roam the snowy foothills of Dun Morogh. Armored in bristling fur and tough flesh, these beasts are stubborn and aggressive, making them an ideal starting test of will. By wielding the enchanted Taming Rod provided by Grif, the hunter must withstand the boar's charge and soothe its ferocity until it submits to their command.",sp=0}},faq={{q="Who offers this trial?",a="The trial is given by Grif Wildheart, a seasoned dwarven hunter trainer located outside the Thunderbrew Distillery in Kharanos.",al={"quest giver","who starts taming the beast","grif wildheart location"},it="identity"},{q="Why do I tame a Large Crag Boar first?",a="Large Crag Boars are sturdy and stubborn yet plentiful throughout the snowy ridges of Dun Morogh. Subduing such a hardy, thick-skinned creature serves as a foundational exercise in asserting calm authority over an aggressive beast.",al={"why crag boar","what beast do i tame","boar taming"},it="target"},{q="Do I get to keep this boar forever?",a="No. This trial is purely practice. The bond forged with the Taming Rod is temporary, allowing you to experience commanding the creature before returning the rod and trying out other species.",al={"is this boar permanent","keep crag boar","can i keep the pet"},gp=true},{q="Where can I find Large Crag Boars?",a="Large Crag Boars roam widely across the open snowfields and pine groves around Kharanos and the frozen slopes of Dun Morogh.",al={"boar locations","where are large crag boars","large crag boar spawn"},it="place",gp=true},{q="What comes after taming the crag boar?",a="Returning to Grif Wildheart completes this first lesson and leads directly to the second trial, where you are tasked with taming a Snow Leopard.",al={"next trial","what is after this quest","hunter chain next"},it="next_step"},{q="How does the Taming Rod work?",a="The Taming Rod is an enchanted tool provided by hunter trainers to help novices channel their will and pacify wild instincts without requiring advanced magical training or lifelong beast-whispering experience.",al={"taming rod lore","what is the rod","how do i tame"},it="item"},{q="Why does Grif Wildheart want you to tame a beast?",a="Grif Wildheart is training you in the fundamentals of being a true dwarven hunter. In his eyes, knowing how to bond with and command a beast companion is just as crucial as maintaining your weapon. Rather than handing you a pet, he believes the only proper way to learn is through hands-on experience in the wild, testing your patience and mastery against different kinds of local creatures before you choose a permanent companion.",al={"grif wildheart motive","why tame a beast","grif wildheart training reason"},it="motive",add="49cdd252"}},ang={["class:Hunter"]="This quest marks the definitive threshold where a novice marksman becomes a true beast master, beginning the trial sequence that unlocks permanent animal companions.",["race:Dwarf"]="Mountaineers of Ironforge revere beasts that can endure the biting cold of Dun Morogh; starting with the rugged crag boar reflects dwarven appreciation for grit and resilience."},kw={"beast","boar","crag boar","dun morogh","grif wildheart","hunter","kharanos","taming","taming rod"},rel={"npc:grif-wildheart","subzone:kharanos","zone:dunmorogh","quest:6065","quest:6081","quest:6061","topic:dwarf"},m={start="Grif Wildheart",["end"]="Grif Wildheart",level="10",faction="Alliance",id=6064},src={"Taming the Beast (Dwarf 1)"}}
E["quest:6074"] = {t="quest",n="The Hunter's Path",z="dunmorogh",s="The Hunter's Path is a rite of passage offered to novice dwarven hunters across Dun Morogh once they reach basic competence in tracking and marksmanship. Local trainers direct their apprentices to Grif Wildheart in Kharanos to begin learning the art of taming wild beasts as permanent companions.",h="The Hunter's Path is a rite of passage offered to novice dwarven hunters across Dun Morogh once they reach...",sec={{t="A Hunter's True Calling",b="Until a hunter masters the art of beast bonding, they walk the snowy crags of Dun Morogh alone, relying solely on axe, rifle, or bow. Trainers like Olmin Burningbeard and Tristane Shadowstone watch their pupils closely until they demonstrate the poise required to face a savage creature without killing it. Once a novice shows sufficient discipline, they are sent down the mountain roads toward Kharanos.",sp=0},{t="Reporting to Grif Wildheart",b="In Kharanos, Grif Wildheart oversees the final trials of dwarven huntsmanship. Taming a beast is considered far more demanding than bringing one down for meat or pelt; it requires patience, physical endurance, and an intuitive bond with the wild predators of the mountains. Wildheart acts as the gateway to these trials, preparing the hunter for the grueling task of testing their willpower against Dun Morogh's fiercest wildlife.",sp=0}},faq={{q="What is the purpose of this quest?",a="It serves as the formal summons sending a maturing hunter to Kharanos to begin their pet-taming trials under Grif Wildheart.",al={"why do this quest","what is hunter's path","hunter pet quest start"},it="purpose"},{q="Who sends me on this path?",a="Hunter trainers—including Olmin Burningbeard in Ironforge's Hall of Arms, Tristane Shadowstone, and Einris Brightspear—direct their pupils to take up this task.",al={"quest giver","who gives hunters path","where to pick up"},it="identity"},{q="Where can I find Grif Wildheart?",a="Grif Wildheart is stationed outside the Thunderbrew Distillery in Kharanos, within the snowy valley of Dun Morogh.",al={"grif wildheart location","where is grif","kharanos hunter trainer"},it="place",gp=true},{q="Why do hunters need a trainer to tame beasts?",a="Taming wild beasts requires specialized techniques and a taming rod to commune with predatory creatures without provoking a fight to the death. Grif Wildheart teaches these traditions.",al={"why need taming training","lore behind pet taming","why cant i tame yet"},it="history"},{q="What happens after reporting to Grif Wildheart?",a="Grif Wildheart immediately tests your mettle by sending you into the wilderness with a taming rod to subdue several distinct beasts native to Dun Morogh.",al={"next quest","what follows hunters path","chain after this"},it="next_step"},{q="Can any hunter take this specific quest?",a="This particular summons is tailored for dwarven hunters operating in Dun Morogh, directing them to the local trainer in Kharanos.",al={"is this dwarf only","can night elves do this","race restriction"},gp=true},{q="Why do the hunter trainers send you to Grif Wildheart?",a="Your trainers recognize that you have developed the basic prowess necessary to commune with and manage wild beasts. Rather than continuing standard martial instruction, they direct you to Grif Wildheart in Kharanos so you can undergo specialized training. In their eyes, mastering the art of beast companionship is the essential next milestone in your growth as a true hunter.",al={"why send me to grif","hunter trainers motive","why see grif wildheart"},it="motive",add="5e8bda0f"}},ang={["class:Hunter"]="This quest marks the defining transition from a solitary tracker to a true beastmaster capable of commanding wild predators.",["race:Dwarf"]="Dwarven mountaineers have long kept bears and boars as trusted scouting companions across the snowy peaks of Dun Morogh."},kw={"dun morogh","grif wildheart","hunter","kharanos","olmin burningbeard","pet quest","taming","tristane shadowstone"},rel={"npc:grif-wildheart","quest:6061","quest:6081","subzone:kharanos","zone:dunmorogh","topic:dwarf"},m={start="Olmin Burningbeard, Tristane Shadowstone, Einris Brightspear",["end"]="Grif Wildheart",level="10",faction="Alliance",id=6074},src={"The Hunter's Path (Dwarf)"}}
E["quest:6084"] = {t="quest",n="Taming the Beast",z="dunmorogh",s="This quest is the second trial in the dwarf hunter initiation given by Grif Wildheart in Kharanos. After learning to handle the brute resilience of a crag boar, the young hunter is tasked with mastering the swiftness and lethal grace of a native snow leopard.",h="This quest is the second trial in the dwarf hunter initiation given by Grif Wildheart in Kharanos.",sec={{t="A Lesson in Finesse",b="While crag boars teach a mountaineer how to withstand raw ferocity and absorb blows, Grif Wildheart emphasizes that a master hunter must understand different styles of combat. He points his students southeast toward the prowling snow leopards of Dun Morogh. Grif compares these graceful predators to an elegantly crafted rifle: outwardly striking, yet concealing devastating power beneath their pristine white coats.",sp=0},{t="Mastering the Taming Rod",b="Using an enchanted taming rod, the hunter must confront a wild leopard and bend its hunting instincts into partnership. Snow leopards test agility, speed, and sharp reflexes rather than pure endurance. Mastering such a creature demonstrates that the novice can harmonize with predators that strike swiftly from the snowy crags, taking another step toward true command over the beasts of the wild.",sp=0}},faq={{q="What is the purpose of this quest?",a="It is the second stage of the hunter rite of passage for dwarves. Hunter trainer Grif Wildheart requires his students to test their skills against diverse wilderness beasts before granting them the knowledge to permanently bond with animal companions.",al={"why do this quest","snow leopard quest dwarf","taming the beast 2"},it="purpose"},{q="Where do I find the snow leopards?",a="Snow leopards can be found prowling the rocky crags and snowy slopes south and east of Kharanos in Dun Morogh.",al={"snow leopard location","where are snow leopards dun morogh","leopard location"},it="place",gp=true},{q="Why does Grif Wildheart want me to tame a leopard?",a="Grif believes a hunter must experience both burly strength and refined finesse. Where the crag boar relies on brute resilience, the snow leopard teaches the hunter how to fight alongside a swift, agile, and lethal damage dealer.",al={"why snow leopard","grif wildheart leopard reasoning"},it="motive"},{q="Do I get to keep this snow leopard permanently?",a="No. The beasts tamed during these initial trials are temporary training partners bound by the magic of the taming rod. Once Grif deems your training complete at the end of the quest chain, you gain the permanent ability to tame any wild beast you choose.",al={"can i keep the snow leopard","is the leopard permanent"},gp=true},{q="Who assigns this trial?",a="Grif Wildheart, the dwarf hunter trainer stationed outside the inn in Kharanos, Dun Morogh.",al={"who gives quest","quest giver","grif wildheart role"},it="identity"},{q="What comes next in the chain?",a="After demonstrating mastery over the snow leopard, Grif sends you on a third and final taming trial to master an Ice Claw Bear before officially teaching you how to tame and train wild beasts on your own.",al={"next quest","what after snow leopard"},sp=1,it="next_step"},{q="What kind of beast is the snow leopard?",a="Snow leopards are swift, agile predators native to the snowy ridges of Dun Morogh. Unlike the sturdy and stubborn crag boars of your first trial, these large white cats rely on finesse, speed, and lethal strikes. Grif Wildheart directs you to them so you can learn how to handle a delicate, aggressive hunting partner that fights very differently from a brute beast.",al={"snow leopard lore","why tame snow leopard","snow leopards dun morogh"},it="target",add="baf34ad8"},{q="Why does Grif Wildheart have me tame the snow leopard myself?",a="This is your rite of passage as a young hunter, not a chore Grif needs handled for the town. Taming requires establishing personal dominance and empathy with wild beasts. Grif already knows the craft; you are the one who must learn how to channel the taming rod's magic and withstand a charging predator to prove you are ready to command a lifelong companion.",al={"why do i have to tame it","why me taming rod","why grif wildheart sends me"},it="why_me",add="4533de88"}},ang={["class:Hunter"]="This rite of passage teaches novice dwarven hunters the contrast between high-durability pets like boars and swift, aggressive damage dealers like cats.",["race:Dwarf"]="Mountaineers of Khaz Modan have long shared the frozen peaks of Dun Morogh with snow leopards, respecting both their stealth and lethal hunting prowess."},kw={"dun morogh","grif wildheart","hunter quest","kharanos","snow leopard","taming rod","taming the beast"},rel={"npc:grif-wildheart","quest:6061","quest:6081","quest:6065","subzone:kharanos","zone:dunmorogh","topic:dwarf"},m={start="Grif Wildheart",level="10",faction="Alliance",id=6084},src={"Taming the Beast (Dwarf 2)"}}
E["quest:6085"] = {t="quest",n="Taming the Beast",z="dunmorogh",s="This quest marks the final trial in a dwarven hunter's basic training under Grif Wildheart in Kharanos. By using an enchanted rod to subdue and understand an aggressive Ice Claw Bear, the hunter demonstrates mastery over sheer brute strength. Completing this exercise unlocks the foundational abilities needed to tame, call, and dismiss a permanent wild companion.",h="This quest marks the final trial in a dwarven hunter's basic training under Grif Wildheart in Kharanos.",sec={{t="The Strength of the Wild",b="Throughout Dun Morogh, mountaineers and scouts have long relied on hardy beasts to endure the freezing crags. After directing his students to practice on swift and cunning predators, master huntsman Grif Wildheart tasks budding hunters with capturing an Ice Claw Bear. Found prowling the snowdrifts east of Kharanos, these massive beasts embody raw physical power and relentless endurance—qualities every dwarven huntsman must learn to control.",sp=0},{t="Earning a Companion",b="The trials with the Taming Rod are strictly educational exercises meant to teach hunters how wild instincts respond to will and calm intent. Once the rod holds the bear docile, the temporary bond fulfills its purpose. Returning the tool to Grif concludes the formal trials, prompting the master to share the permanent secrets of beast mastery: how to pacify any compatible wild creature and call upon it throughout a lifetime of adventure.",sp=0}},faq={{q="What animal do I need to tame for this quest?",a="You must seek out an Ice Claw Bear, which prowls the frozen foothills east of Kharanos in Dun Morogh. Using the provided Taming Rod subdues the creature so you can experience handling raw brute force.",al={"which bear","target animal","taming target"},it="target",gp=true},{q="Do I keep the Ice Claw Bear after turning in the quest?",a="No. The bear subdued by the Taming Rod is only a temporary test of discipline and skill. Once you hand the rod back to Grif Wildheart, the beast departs, and you are granted the true abilities to tame any wild beast you choose.",al={"do i keep the bear","keep pet","is bear permanent"},gp=true},{q="Where is Grif Wildheart located?",a="Grif Wildheart is stationed outside the Thunderbrew Distillery in Kharanos, Dun Morogh, where he trains fledgling hunters in the ways of marksmanship and beast mastery.",al={"grif location","where is grif","hunter trainer kharanos"},it="place",gp=true},{q="What abilities do I learn upon finishing this trial?",a="Completing this final trial teaches you the foundational spells of a hunter: Tame Beast, Call Pet, and Dismiss Pet. This allows you to venture out into the world and bond with a permanent companion.",al={"quest rewards","hunter skills learned","tame beast reward"},gp=true},{q="What is the next step after completing this quest?",a="Grif will send you onward with the quest 'Training the Beast', directing you to learn how to feed, nurture, and instruct your new companion properly so it stays loyal in combat.",al={"next quest","what comes next","training the beast"},it="next_step",gp=true},{q="Why does Grif have hunters test multiple types of beasts?",a="The three trials expose a novice hunter to different fighting styles—agility, cunning, and brute power. Experiencing these distinct temperaments prepares a mountaineer to choose the best companion for their hunting style.",al={"why three beasts","purpose of trials","three animals"},it="motive"},{q="What are Ice Claw Bears and why are they around Kharanos?",a="Ice Claw Bears are sturdy, thick-furred predators native to the snowy crags of Dun Morogh, commonly prowling the wilderness east of Kharanos. Grif Wildheart considers them an ideal companion for a developing hunter because of their raw fortitude and brute strength. Facing one forces you to prove you can stand your ground against immense physical power and dominate a truly hardy mountain beast before claiming full mastery over wild creatures.",al={"ice claw bear lore","why tame ice claw bear","ice claw bears dun morogh"},it="target",rc="Dwarf",add="d0a90924"}},ang={["class:Hunter"]="This quest is the rite of passage that turns an isolated archer into a true pet-taming hunter, unlocking the essential abilities to tame and summon beasts.",["race:Dwarf"]="Bears have long served as iconic companions for dwarven mountaineers patrolling Dun Morogh, renowned for matching their masters in stubborn resilience."},kw={"dun morogh","grif wildheart","hunter quest","ice claw bear","kharanos","pet taming","taming rod","taming the beast"},rel={"npc:grif-wildheart","subzone:kharanos","quest:6081","quest:6065","zone:dunmorogh","topic:dwarf"},m={start="Grif Wildheart",level="10",faction="Alliance",id=6085},src={"Taming the Beast (Dwarf 3)"}}
E["quest:6086"] = {t="quest",n="Training the Beast",z="dunmorogh",s="Training the Beast is the culminating rite of passage for young dwarven hunters in Dun Morogh. Having mastered the art of soothing and taming wild predators in the snowy crags, novice rangers are directed into the heart of Ironforge to learn how to sustain, discipline, and care for a lifelong animal companion.",h="Training the Beast is the culminating rite of passage for young dwarven hunters in Dun Morogh.",sec={{t="From the Wild to the Forge",b="After proving their mettle against the savage beasts of Dun Morogh—soothing large crag boars, snow leopards, and sturdy ice claw bears with a taming rod—apprentice hunters complete their trial under the watchful eye of Grif Wildheart near Kharanos. Yet capturing the wild heart of an animal is only half the bond. Grif sends his newly seasoned pupils up the mountain pass into Ironforge to find the military district known as the Hall of Arms.",sp=0},{t="Belia Thundergranite's Teachings",b="Within the stone vaults of Ironforge's Hall of Arms stands Belia Thundergranite, one of the dwarven kingdom's most revered master animal trainers. Belia imparts the essential knowledge that turns a wild, terrified beast into a fiercely loyal partner. Her teachings go far beyond simple commands: she shows young hunters how to nourish their pets, teach them new battlefield skills, and even call their spirits back from death should they fall defending their master.",sp=0},{t="The Dwarven Hunter's Bond",b="Dwarven tradition emphasizes that beast mastery is fundamentally built on respect rather than subjugation. Belia reminds every young hunter that an animal companion reflects the care it receives. If kept well-fed, respected, and properly trained, a beast will offer unwavering loyalty against troggs, frost trolls, and any threat that dares imperil Khaz Modan.",sp=0}},faq={{q="What is the purpose of this quest?",a="This quest marks the final step in a dwarf hunter's foundational training. It rewards you with the core knowledge to maintain a permanent combat pet, allowing you to feed it, train its capabilities, call it to your side, and resurrect it if it dies.",al={"why do this quest","training the beast purpose","hunter pet quest reward"},it="purpose"},{q="Who is Belia Thundergranite?",a="Belia Thundergranite is a revered master beast trainer stationed in the Hall of Arms in Ironforge. She serves as a senior instructor for dwarf rangers, teaching them the discipline, diet, and commands required to turn tamed wild animals into lifelong allies.",al={"who is belia","belia thundergranite lore","hunter trainer ironforge"},it="identity"},{q="Where do I find Belia Thundergranite?",a="Belia Thundergranite is located inside Ironforge in the Hall of Arms, the city's military wing where dwarf and gnome warriors, hunters, and paladins gather and train.",al={"belia location","where is belia thundergranite","where is hall of arms ironforge"},it="place",gp=true},{q="What beasts do dwarven hunters tame before receiving this training?",a="During the trials leading up to this quest, Grif Wildheart tests young hunters by having them use an enchanted rod to temporarily pacify a large crag boar, a snow leopard, and an ice claw bear across Dun Morogh.",al={"what beasts do you tame","dwarf pet trial beasts","prior quests beasts"},it="history"},{q="Why must dwarven hunters feed their pets?",a="Dwarven beast lore holds that animal companions are partners, not tools. Neglecting a beast's hunger causes its mood to deteriorate and saps its willingness to fight, whereas keeping it well-fed ensures fierce loyalty and maximum effectiveness in battle.",al={"why feed pet","pet happiness lore","beast loyalty dwarf"},it="purpose"},{q="Who gives this quest?",a="Grif Wildheart, the veteran hunter trainer stationed at the side of the road east of Kharanos in Dun Morogh, gives this quest upon the successful completion of your third taming trial.",al={"who starts training the beast","grif wildheart role","quest giver"},it="people"},{q="Why does Grif Wildheart send you to Ironforge?",a="Grif Wildheart has guided your basic trials across the crags of Dun Morogh, teaching you to tame wild beasts. However, mastering the care, feeding, and discipline of a beast companion requires advanced expertise. Grif sends you to Ironforge so that Belia Thundergranite, one of the dwarves' most respected master trainers in the Hall of Arms, can complete your education and ensure your pet becomes a steadfast ally.",al={"why does grif send you","grif wildheart motive","why go to ironforge hunter"},it="motive",add="5ee43731"}},ang={["class:Hunter"]="This milestone unlocks the defining core of the hunter discipline: the abilities to properly feed, command, and revive a permanent animal companion.",["race:Dwarf"]="Dwarves view hunting as an enduring tradition of Khaz Modan's mountainous wilderness, treating bears, boars, and mountain cats as respected partners in exploration and defense.",["faction:Alliance"]="The beastmasters of Ironforge contribute heavily to Alliance scouting forces, relying on loyal wilderness companions to patrol the frigid mountain passes."},kw={"belia thundergranite","dun morogh","dwarf hunter","grif wildheart","hall of arms","ironforge","pet training","training the beast"},rel={"npc:grif-wildheart","quest:6061","quest:6065","zone:ironforge","zone:dunmorogh","topic:dwarf"},m={start="Grif Wildheart",["end"]="Belia Thundergranite",level="10",faction="Alliance",id=6086},src={"Training the Beast (Dwarf)"}}
E["quest:637"] = {t="quest",n="Sully Balloo's Letter",z="dunmorogh",s="Recovered from a drowned skeleton beneath the shattered arches of the Thandol Span, this waterlogged letter contains the dying words of a dwarven soldier named Sully Balloo. Addressed to his wife Sara in Ironforge, it carries the final thoughts of a defender lost beneath the icy river waters during the battles for the bridge.",h="Recovered from a drowned skeleton beneath the shattered arches of the Thandol Span, this waterlogged letter...",sec={{t="A Voice from the Riverbed",b="Beneath the massive stone pilings supporting the Thandol Span—the crucial land bridge linking the Wetlands to the Arathi Highlands—rests the drowned skeleton of a fallen dwarf. Still clutched in his skeletal grasp is a water-damaged envelope that barely survives handling. Written with painstaking care amid the fires of battle, the pages open with the tender phrase, 'My dear Sara...', preserving the soldier's voice long after the tides claimed him.",sp=0},{t="The Price of the Span",b="The Thandol Span has seen fierce fighting between Alliance forces and their enemies, from Dark Iron saboteurs to marauding warbands contesting the borderlands. Sully Balloo was one of the many dwarven soldiers sent north to defend the vital thoroughfare. When he perished beneath the waves, his fate remained unknown to his family in the mountains until a diver finally retrieved his farewell testament.",sp=0},{t="A Widow in Ironforge",b="Returning the salvaged letter to Ironforge brings quiet devastation to Sully's widow, Sara Balloo. Living amid the bustling halls of the dwarven capital, she had remained suspended between grief and lingering hope, unsure whether her husband was missing in action or lost forever. Confronted with his handwritten words and the knowledge of his watery resting place, she is finally forced to face the bitter reality of his death.",sp=1}},faq={{q="Where is Sully Balloo's letter found?",a="The letter is held in the hand of a submerged skeleton resting deep on the riverbed directly beneath the massive stone pillars of the Thandol Span, connecting the Wetlands and the Arathi Highlands.",al={"letter location","where is sully balloo","thandol span skeleton"}},{q="Who was Sully Balloo?",a="Sully Balloo was an Alliance dwarven soldier who fell defending the Thandol Span. Pinned under the icy waters during the conflicts along the crossing, he managed to pen a final letter to his wife Sara before dying.",al={"who is sully","sully balloo lore","who was sully balloo"}},{q="Who is Sara Balloo?",a="Sara Balloo is Sully's widow, residing in the great dwarven capital of Ironforge. She has spent months waiting for news of her husband's fate on the northern frontier.",al={"where is sara balloo","who is sara","sara balloo location"}},{q="What happens after you deliver the letter?",a="Upon receiving the heartbreaking confirmation of Sully's death, Sara Balloo is overcome with sorrow and makes a plea for memorializing him, continuing the story through a subsequent request in Ironforge.",al={"what next","sully quest chain","after delivering letter"},sp=1},{q="Why was the letter still intact underwater?",a="The letter was protected inside an envelope clutched tightly by the soldier's remains. Though partially dissolved and waterlogged by the time it is retrieved, several pages written in careful script remain legible enough to read.",al={"why is letter readable","how did envelope survive"}},{q="What real-world inspiration is behind this quest?",a="The quest is an homage to Major Sullivan Ballou of the 2nd Rhode Island Infantry during the American Civil War, who wrote an iconic and poetic farewell letter to his wife shortly before his death at the First Battle of Bull Run.",al={"sully balloo trivia","sullivan ballou","civil war reference"}}},ang={["race:Dwarf"]="For dwarves of Ironforge, returning Sully's final words honors a brother-in-arms who laid down his life holding the grand works of dwarven stonemasonry against northern threats.",["faction:Alliance"]="The letter is a poignant reminder of the personal sacrifice paid by regular frontline soldiers safeguarding the fragile overland links between the southern and northern Alliance territories."},kw={"arathi","dwarf soldier","ironforge","sara balloo","skeleton","sully balloo","thandol span","waterlogged envelope","wetlands"},rel={"npc:sara-balloo","subzone:thandol-span","quest:631","zone:ironforge","zone:dunmorogh"},m={start="Waterlogged Envelope",["end"]="Sara Balloo",level="30",faction="Alliance",id=637},src={"Sully Balloo's Letter (quest)"}}
E["quest:683"] = {t="quest",n="Sara Balloo's Plea",z="dunmorogh",s="Sara Balloo's Plea is a somber errand undertaken on behalf of a grieving dwarven widow in Ironforge. Unable to face her monarch directly in her state of sorrow, Sara entrusts a personal appeal to King Magni Bronzebeard regarding her fallen husband, Sully Balloo.",h="Sara Balloo's Plea is a somber errand undertaken on behalf of a grieving dwarven widow in Ironforge.",sec={{t="A Widow's Request",b="After receiving the tragic final letter recovered from the watery depths of the Thandol Span, Sara Balloo finds herself paralyzed by mourning. Rather than let her husband Sully's sacrifice fade into obscurity, she writes a plea addressed directly to the throne of Ironforge. Too overwhelmed by heartbreak to appear before court etiquette herself, she entrusts the sealed parchment to a trusted champion of the Alliance to petition King Magni Bronzebeard on her behalf.",sp=0},{t="Audience with the King",b="Carrying a private petition to the High Seat of Ironforge is no routine chore, but Magni Bronzebeard takes personal note of the brave defenders of Khaz Modan. Upon receiving the message, the King pauses the affairs of state to read the humble plea of a soldier's widow, demonstrating his bond with the common dwarves who built and defend his mountain kingdom.",sp=1}},faq={{q="Who is Sara Balloo?",a="Sara Balloo is an Ironforge dwarf whose husband, the soldier Sully Balloo, died in the Thandol Span tragedy. She lives in the city, holding his memory dear.",al={"sara balloo","who is sara"},it="identity"},{q="Why does Sara want me to see the King instead of going herself?",a="Sara is overcome by grief after finally learning the definitive fate of her husband. She feels she cannot maintain the composure expected when petitioning King Magni Bronzebeard in the High Seat.",al={"why cant sara go","sara grief"},it="why_me"},{q="Who was Sully Balloo?",a="Sully Balloo was a dwarf soldier who defended the Thandol Span. He perished during fighting along the bridge, leaving behind a waterlogged letter to his wife.",al={"sully balloo","saras husband"},it="history"},{q="Where do I deliver Sara Balloo's Plea?",a="You deliver the plea directly to King Magni Bronzebeard in the High Seat at the center of Ironforge.",al={"where is magni","king magni location","turn in location"},it="next_step",gp=true},{q="What happens after King Magni reads the plea?",a="Reading Sara's plea moves King Magni to honor the fallen soldier properly, leading directly into the quest 'A King's Tribute' to establish a lasting monument.",al={"quest continuation","next quest"},sp=1,it="next_step"},{q="What faction can undertake this task?",a="This errand is exclusive to members of the Alliance, as it involves internal dwarven affairs and an audience with King Magni Bronzebeard.",al={"can horde do this","faction requirement"},it="side",gp=true},{q="Why does Sara Balloo want her plea delivered to King Magni?",a="Sara Balloo is grieving the loss of her husband, Sully Balloo, who fell defending the Thandol Span. Having finally received his last letter, recovered from beneath the span, she wants King Magni Bronzebeard to formally recognize Sully's sacrifice and honor his memory. Delivering this plea is her way of ensuring her late husband's devotion to the Alliance is remembered in Ironforge.",al={"why does sara balloo want this done","sara balloo motive","why send plea to magni"},it="motive",add="ca82ce02"}},ang={["race:Dwarf"]="Delivering a grieving widow's plea directly to your King touches the deep cultural importance dwarves place on stonework, lineage, and honoring ancestral sacrifice.",["faction:Alliance"]="Carrying word between grieving citizens and Alliance leadership highlights the personal costs borne by common folk during the conflicts preserving the realm."},kw={"a king's tribute","dun morogh","ironforge","magni bronzebeard","sara balloo","sully balloo","thandol span"},rel={"npc:sara-balloo","npc:magni-bronzebeard","quest:686","zone:ironforge","zone:dunmorogh","topic:alliance"},m={start="Sara Balloo",["end"]="King Magni Bronzebeard",level="30",faction="Alliance",id=683},src={"Sara Balloo's Plea (quest)"}}
E["quest:689"] = {t="quest",n="A King's Tribute",z="dunmorogh",s="King Magni Bronzebeard has commissioned a monument to Sully Balloo, a dwarven soldier who perished defending the Thandol Span. To honor the fallen warrior with enduring dignity, Grand Mason Marblesten dispatches travelers to Hillsbrad to retrieve pristine Alterac Granite.",h="King Magni Bronzebeard has commissioned a monument to Sully Balloo, a dwarven soldier who perished defending...",sec={{t="A Royal Commission",b="When King Magni Bronzebeard decided that fallen soldier Sully Balloo deserved a lasting memorial, the task fell directly to Ironforge's finest craftsman, Grand Mason Marblesten. Balloo lost his life during the disaster at the Thandol Span, a vital artery connecting the dwarven lands to northern kingdoms that has suffered brutal attacks by Dark Iron saboteurs. To Marblesten, fulfilling the king's royal decree means creating a sculpture that will withstand both time and war, ensuring that dwarven sacrifice is neither overlooked nor forgotten in the Great Forge.",sp=0},{t="Stone of the North",b="A master dwarven mason will not settle for ordinary quarry rock for a king's project. Marblesten insists that Sully Balloo's likeness can only be captured in Alterac Granite, a dense, resilient stone prized for its durability and clean texture. The challenge lies in securing it: the best deposits lie around Darrow Hill within the contested foothills of Hillsbrad. Venturing deep into the troubled north is dangerous, but dwarven stonework demands materials worthy of the heroism they commemorate.",sp=0}},faq={{q="Who is Sully Balloo?",a="Sully Balloo was an Alliance soldier who died defending the Thandol Span during its catastrophic sabotage. Moved by a grieving letter from his widow, Sara Balloo, King Magni Bronzebeard ordered a permanent statue erected in his honor.",al={"sully balloo","who was sully balloo","sully balloo lore"},it="people"},{q="Who is Grand Mason Marblesten?",a="Grand Mason Marblesten is the master sculptor and stoneworker of Ironforge. Operating out of the city's Commons, he handles royal commissions and takes fierce pride in working with only the finest regional stones.",al={"grand mason marblesten","marblesten ironforge","who is marblesten"},it="identity"},{q="Why is Alterac Granite needed?",a="Alterac Granite is celebrated across the Eastern Kingdoms for its exceptional density, fine grain, and endurance against erosion. Marblesten insists that only stone of this caliber is worthy of a royal tribute that will last through the ages.",al={"why alterac granite","alterac granite purpose","what is alterac granite"},it="item"},{q="Where is Darrow Hill?",a="Darrow Hill is a hilly area in northern Hillsbrad Foothills, just below the Headland and near the border of Alterac, where Alterac Granite is found in the caves.",al={"where is darrow hill","darrow hill location","find darrow hill"},it="place",gp=true},{q="What happened at the Thandol Span?",a="The Thandol Span, the colossal bridge spanning the chasm between the Wetlands and the Arathi Highlands, suffered an assault by Dark Iron saboteurs who planted explosives to cut Alliance supply routes, claiming many defenders' lives.",al={"thandol span tragedy","thandol span catastrophe","what happened to thandol span"},it="history"},{q="What happens after bringing the granite to Marblesten?",a="Once supplied with the Alterac Granite, Marblesten completes the memorial and asks you to report to King Magni that it is finished.",al={"after turning in granite","marblesten statue progress"},it="next_step"},{q="Why does Grand Mason Marblesten want this done?",a="King Magni Bronzebeard personally commissioned a memorial to honor the fallen soldier Sully Balloo. For Grand Mason Marblesten, royal commissions carry the highest priority and demand his absolute best work. Though he laments the endless bloodshed across Azeroth, he insists on using only the finest stone to craft a truly epic, lasting tribute worthy of the king's request.",al={"why does marblesten care","marblesten motive","why build sully balloo monument"},it="motive",add="1680ec58"}},ang={["race:Dwarf"]="Honoring Sully Balloo touches the heart of dwarven culture, where stonework, martial sacrifice, and steadfast loyalty to King Bronzebeard are deeply intertwined.",["profession:Mining"]="Miners understand Marblesten's selective eye; the hard, unyielding veins of Alterac Granite require seasoned hands to extract cleanly without fracturing.",["faction:Alliance"]="Securing materials from Hillsbrad reinforces the Alliance presence in the fractured north while honoring an ordinary soldier who gave his life for the common cause."},kw={"alterac granite","darrow hill","ironforge","magni bronzebeard","marblesten","stonemason","sully balloo","thandol span"},rel={"npc:grand-mason-marblesten","quest:686","subzone:thandol-span","subzone:darrow-hill","zone:ironforge","topic:alterac-kingdom","quest:631","zone:dunmorogh"},m={start="Grand Mason Marblesten",level="31",faction="Alliance",id=689,ri={"Alterac Granite"}},src={"A King's Tribute (2)"}}
E["quest:8653"] = {t="quest",n="Goldwell the Elder",z="dunmorogh",s="Goldwell the Elder is a Lunar Festival quest offered by Elder Goldwell in Kharanos, Dun Morogh. Honoring him reflects the enduring tradition of seeking out ancestral spirits across the snowbound dwarven lands. In exchange for your respects, he bestows a token of ancestral blessing.",h="Goldwell the Elder is a Lunar Festival quest offered by Elder Goldwell in Kharanos, Dun Morogh.",sec={{t="A Mountain Greeting",b="Standing in the bitter cold beside the Thunderbrew Distillery in Kharanos, Elder Goldwell watches over the bustling trade path leading to the gates of Ironforge. During the Lunar Festival, this venerable figure welcomes weary travelers, adventurers, and locals alike, embodying the long memory of ancient days when early mortals walked beneath the stars of Azeroth.",sp=0},{t="Honoring the Ancestors",b="Approaching Goldwell offers a moment of reflection amidst the harsh winter winds of Dun Morogh. He expresses relief and joy that mortals still remember the ancient races and their deeds, thanking all who pause their journeys to show respect. In turn, he awards a sacred Coin of Ancestry as an emblem of his blessing.",sp=0}},faq={{q="Where can I find Elder Goldwell?",a="Elder Goldwell stands right outside the Thunderbrew Distillery inn in the town of Kharanos, situated along the snowy road of Dun Morogh just southwest of the gates to Ironforge.",al={"elder goldwell location","where is elder goldwell","goldwell spot"}},{q="What is the purpose of seeking out Elder Goldwell?",a="Elder Goldwell is visited during the Lunar Festival as part of honoring the world's ancient spirits. Paying him your respects proves that the mortal races have not forgotten the sacrifices and wisdom of antiquity.",al={"why visit elder goldwell","what does elder goldwell do","goldwell quest"}},{q="What reward does Elder Goldwell provide?",a="He rewards travelers with a Coin of Ancestry, a blessed token bestowed by the festival elders that can be presented to the Cenarion Circle in Moonglade for celebratory festival goods.",al={"elder goldwell reward","what do i get from elder goldwell","coin of ancestry goldwell"}},{q="Is this quest available to Horde travelers?",a="Yes. Festival elders like Goldwell are neutral ancestral spirits who welcome adventurers of any faction, though Horde travelers must tread carefully to avoid the watchful dwarven mountaineers patrolling Kharanos.",al={"can horde talk to elder goldwell","horde elder goldwell","is elder goldwell friendly to horde"}},{q="Why does Elder Goldwell reside in Dun Morogh?",a="The Lunar Festival elders manifest across every corner of Azeroth where mortal civilizations have forged enduring communities. Goldwell chose Kharanos to share his blessings with those dwelling near the dwarven kingdom's heart.",al={"why is goldwell in kharanos","why dun morogh","goldwell dwarven land"}},{q="Can you complete this quest more than once?",a="No. The honor paid to Elder Goldwell is offered once per festival season, granting a single blessing and coin to each adventurer who seeks his counsel.",al={"is elder goldwell repeatable","elder goldwell daily","goldwell reset"}}},ang={["race:Dwarf"]="For dwarves returning from Ironforge, meeting an elder of ancient lineage right outside their premier tavern in Kharanos bridges timeless reverence with hometown pride.",["faction:Alliance"]="Nestled in safe Alliance territory, Goldwell is one of the easiest elders for young Alliance heroes journeying between Coldridge Valley and Ironforge to visit.",["faction:Horde"]="Reaching Goldwell requires sneaking deep into Dun Morogh, braving dwarven guards and bitter cold just outside the high gates of Ironforge."},kw={"ancestor","coin of ancestry","dun morogh","elder goldwell","goldwell","ironforge","kharanos","lunar festival","thunderbrew"},rel={"npc:elder-goldwell","subzone:kharanos","zone:dunmorogh","zone:ironforge"},m={start="Elder Goldwell",id=8653},src={"Goldwell the Elder"}}
E["quest:95041"] = {t="quest",n="Data Hoarders",z="dunmorogh",s="Data Hoarders is a task given by Jemma Quikswitch, an exiled gnome residing in Ironforge. During the desperate evacuation of Gnomeregan, she copied her family's most prized archives onto punch cards, only to lose several in the freezing drifts outside the city gates. Recovering these lost data cards means salvaging everything from advanced naval engineering schematics to irreplaceable family recipes.",h="Data Hoarders is a task given by Jemma Quikswitch, an exiled gnome residing in Ironforge.",sec={{t="A Scramble in the Snow",b="When the trogg invasion and subsequent radiation disaster forced the gnomes out of Gnomeregan, thousands fled with whatever belongings they could snatch up in the chaos. Jemma Quikswitch took the prudent step of transcribing generations of family knowledge into physical punch card archives. Tragically, a damaged satchel spilled several key cards into the snowfields surrounding the fallen city. Without these missing punch cards, the remaining data registers as indecipherable gibberish, threatening to erase her family's intellectual legacy.",sp=0},{t="Equations and Chili",b="Gnomish data archives reflect the peculiar breadth of their civilization's priorities. The Quikswitch family records include profound arcanotechnical field equations, vital Second War submarine hull blueprints, and Grandma Quikswitch's secret chili recipe. To an outsider, combining military engineering with household cooking might seem odd, but to surviving refugees in Ironforge, preserving domestic comforts matters just as much as preserving technological marvels.",sp=0}},faq={{q="Who is Jemma Quikswitch?",a="Jemma Quikswitch is a gnomish refugee who managed to escape the fall of Gnomeregan and now resides safely among the dwarven halls of Ironforge.",al={"jemma quikswitch","who gives data hoarders","quest giver data hoarders"}},{q="What data is stored on the lost cards?",a="The punch cards hold the Quikswitch family's archives, including arcanotechnical equations, submarine hull schematics dating back to the Second War, and Grandma Quikswitch's chili recipe.",al={"what are the punch cards","what was on the cards","quikswitch archives"}},{q="Where did the data cards get lost?",a="They slipped out through a hole in Jemma's pack while she was fleeing Gnomeregan, leaving them buried in the snowy terrain just outside the subterranean city's gates in Dun Morogh.",al={"where are cards","data card location","where did she drop them"}},{q="Why can't Jemma read the surviving cards without the missing ones?",a="Jemma says the data is too scrambled to recover without the missing punch cards. The quest does not explain how the cards encode or organize that information.",al={"why need all cards","scrambled data","punch card data"}},{q="What role did gnomes play in the Second War regarding submarines?",a="During the Second War, gnomes contributed heavily to the Alliance military effort through advanced engineering, specifically designing and piloting submersible vessels to counter the Horde's naval forces.",al={"gnome submarines second war","submarine hull designs"}},{q="Why are gnomish refugees living in Ironforge?",a="Following the sudden fall of Gnomeregan to trogg invaders and catastrophic radiation, the surviving gnomes fled their subterranean home and were offered sanctuary by King Magni Bronzebeard in the neighboring dwarven city of Ironforge.",al={"why are gnomes in ironforge","gnomes living with dwarves"}}},ang={["race:Gnome"]="For gnomish adventurers, recovering these punch cards is a matter of cultural preservation, ensuring that vital inventions and family memories are not lost to the radioactive ruins of their homeland.",["profession:Engineering"]="Engineers can appreciate the immense value hidden on these cards, which contain authentic Second War submarine hull blueprints and complex arcanotechnical equations.",["profession:Cooking"]="Tucked alongside world-class engineering schematics is Grandma Quikswitch's personal chili recipe, proving that good food holds as much sentimental value as military science.",["faction:Alliance"]="The Alliance relies heavily on gnomish ingenuity; helping displaced refugees preserve wartime engineering records ensures that valuable Alliance technical knowledge isn't lost forever."},kw={"data hoarders","dun morogh","gnomeregan","ironforge","jemma quikswitch","punch cards","second war","submarine hull"},rel={"zone:gnomeregan","zone:ironforge","topic:gnome","zone:dunmorogh","topic:second-war"},m={level="10",id=95041},src={"In-game quest text: Data Hoarders"},fv=true}
E["quest:96047"] = {t="quest",n="Camping 101: First Aid",z="dunmorogh",s="This task directs novice medics in Dun Morogh to expand their survival craft beyond simple bandages. By seeking out Thamner Pol in Kharanos, adventurers learn how to assemble a dedicated First Aid Kit to keep campers alive in the field.",h="This task directs novice medics in Dun Morogh to expand their survival craft beyond simple bandages.",sec={{t="Tending Wounds in the Wild",b="Adventurers braving the frozen reaches of Dun Morogh quickly discover that linen scraps and hasty stitches are only the beginning of survival medicine. True wilderness survival often depends on having established supplies at a resting site. Those who show aptitude in basic treatment are steered toward local craft instructors in Kharanos who can teach them how to turn raw medical supplies into complete kits tailored for camp survival.",sp=0},{t="The Lessons of Kharanos",b="In the bustling hamlet of Kharanos, Thamner Pol passes along practical techniques for outfitting expedition sites with emergency supplies. Knowing how to construct a proper field kit ensures that an entire party can bandage lacerations and recover their stamina together around the hearth fire before venturing back into the biting cold.",sp=0}},faq={{q="What is the purpose of this task?",a="The task guides newly trained field medics to Thamner Pol in Kharanos, who teaches them how to craft functional First Aid Kits designed for adventurer campsites.",al={"why do camping 101 first aid","what does this quest do","camping 101 goal"}},{q="Who is Thamner Pol?",a="Thamner Pol is a trainer based in the town of Kharanos in Dun Morogh. He instructs skilled survivalists on crafting profession-related gear to upgrade their wilderness camps.",al={"who is thamner pol","thamner pol location","where is thamner pol"}},{q="Where does this training take place?",a="The training takes place in Kharanos, the primary settlement situated in central Dun Morogh south of Ironforge.",al={"where do i go","camping 101 location","kharanos first aid"}},{q="Why is a camp first aid kit important?",a="Injuries are common during expeditions in harsh wilderness. A dedicated First Aid Kit supplies resting adventurers with essential healing resources, allowing travelers to bind wounds and recover safely between battles.",al={"what does first aid kit do","why make a first aid kit","camping first aid utility"}},{q="Do you need prior medical training before seeking Thamner Pol?",a="Yes. Adventurers are expected to already know the basics of First Aid and demonstrate basic competence in the craft before Thamner Pol will teach them advanced camping recipes.",al={"requirements for camping 101","first aid skill required","do i need first aid first"}},{q="Is this pursuit open to any adventurer?",a="Any adventurer can take up First Aid regardless of their calling, making camp medicine a pragmatic skill for every traveler roaming Dun Morogh.",al={"can anyone do this","class requirements","who can learn camp first aid"}}},ang={["race:Dwarf"]="Dwarven mountaineers rely heavily on sturdy, practical equipment when patrolling the high snowy passes of Dun Morogh, making a camp first aid kit an essential survival staple.",["race:Gnome"]="Refugees and gnomish wanderers operating out of Kharanos find efficient field medicine invaluable while surviving outside the lost halls of Gnomeregan.",["faction:Alliance"]="Alliance recruits training in the frozen heart of Khaz Modan learn early that self-sufficiency and field medicine are vital assets to any military or exploratory unit."},kw={"bandages","camping 101","dun morogh","first aid","first aid kit","kharanos","survival","thamner pol"},rel={"subzone:kharanos","zone:dunmorogh"},m={level="6",id=96047},src={"In-game quest text: Camping 101: First Aid"},fv=true}
E["quest:96390"] = {t="quest",n="Nip 'Em in the Bud",z="dunmorogh",s="Nip 'Em in the Bud is a mission directed by Earthseer Farsen to eliminate Dark Iron spies infiltrating Dun Morogh. The clandestine operatives have been spotted lurking near Ironband's Compound, threatening the security of the Bronzebeard homeland.",h="Nip 'Em in the Bud is a mission directed by Earthseer Farsen to eliminate Dark Iron spies infiltrating Dun...",sec={{t="Eyes in the Cold",b="Dun Morogh has long been a fortified sanctuary for the Ironforge dwarves, but the ancient enmity between the dwarven clans never truly sleeps. Dark Iron infiltrators have slipped through the high passes and snowy crags, skulking suspiciously close to vital excavations and settlements. Earthseer Farsen recognizes that even a few hidden observers can presage a devastating strike, calling on stalwart defenders of the Alliance to root them out before their schemes take hold.",sp=0},{t="Threat Near Ironband's Compound",b="The spies have concentrated their prowling around Ironband's Compound, an important site in eastern Dun Morogh. While Farsen cannot initially discern their exact motives, dispatching the covert agents reveals physical proof of their larger design. Searching the defeated scouts uncovers an Underground Map, confirming that their trespassing is no mere scouting expedition, but preparation tied to ancient beneath-ground secrets like the Hall of Thanes.",sp=1}},faq={{q="Who offers the quest Nip 'Em in the Bud?",a="The quest is offered by Earthseer Farsen following the task Farsen's Watch, calling for aid in dealing with intruders in Dun Morogh.",al={"quest giver nip em in the bud","who starts nip em in the bud","farsen quest"},it="identity"},{q="Why are Dark Iron spies in Dun Morogh?",a="The Dark Iron clan constantly schemes against their Bronzebeard cousins. Infiltrating eastern Dun Morogh allows their operatives to surveil settlements and excavate or scout buried subterranean passages near Ironband's Compound.",al={"why dark iron spies here","what are dark irons doing in dun morogh","ironband dark iron spies"},it="target"},{q="Where are the Dark Iron spies located?",a="They are concentrated to the east near Ironband's Compound in eastern Dun Morogh, keeping watch from the snowy perimeter.",al={"spy location","where are dark iron spies","where to find spies"},it="place",gp=true},{q="What leads into this task?",a="This assignment follows after reporting in for Farsen's Watch, stepping up defensive efforts from mere observation to active eradication.",al={"prerequisite quest","what comes before nip em in the bud","nip em in the bud prequest"},it="origin"},{q="What is uncovered while hunting these spies?",a="Slain spies yield a Dark Iron Map, which begins the quest Underground Map and points toward deeper secrets tied to the Hall of Thanes.",al={"what drops from spies","dark iron map drop","next quest after nip em in the bud"},sp=1,it="next_step"},{q="Who is Earthseer Farsen?",a="Earthseer Farsen is an observant dwarf stationed in Dun Morogh who monitors unusual seismic and hostile clan movements across the snowy mountains.",al={"who is farsen","earthseer farsen lore"},it="leader"},{q="Why does Earthseer Farsen want the Dark Iron spies dealt with?",a="Earthseer Farsen knows that any Dark Iron foothold in Dun Morogh spells danger for Ironforge and the surrounding lands. Though their precise motives remain unclear to him, allowing infiltrators to operate unchecked invites greater sabotage or open assault. He wants to crush their presence immediately before whatever scheme they are preparing takes root.",al={"why does farsen want spies dead","earthseer farsen motive","nip em in the bud why"},it="motive",add="bdd12e65"}},ang={["race:Dwarf"]="For Bronzebeard dwarves, purging Dark Iron infiltrators from their ancestral mountains is a matter of home defense and lingering clan vengeance.",["faction:Alliance"]="Neutralizing enemy scouts in Dun Morogh keeps Ironforge's vital supply lines and surrounding outposts safe from sabotage."},kw={"dark iron map","dark iron spy","dun morogh","earthseer farsen","hall of thanes","ironband's compound","nip 'em in the bud","underground map"},rel={"quest:96392","quest:96391","subzone:ironband-s-compound","zone:dunmorogh","zone:hallofthanes"},m={start="Earthseer Farsen",level="13",id=96390},src={"Nip 'Em in the Bud"},fv=true}
E["quest:96391"] = {t="quest",n="Underground Map",z="dunmorogh",s="Recovered from infiltrating spies near Ironband's Compound, the Underground Map reveals clandestine tunnel networks burrowing toward the roots of Ironforge. Its jagged Dark Iron runes outline a stealthy subterranean route piercing straight toward ancient chambers beneath the mountain. Delivering it to Earthseer Farsen marks the first step in uncovering an impending invasion below.",h="Recovered from infiltrating spies near Ironband's Compound, the Underground Map reveals clandestine tunnel...",sec={{t="A Blueprint of Infiltration",b="The parchment recovered from Dark Iron spies near Ironband's Compound displays an intricate maze of subterranean roads. Inscribed in harsh, jagged runes unique to the Dark Iron clan, the diagrams map deep underground passages that converge directly beneath Ironforge. The converging passages suggest a possible threat beneath the Bronzebeard capital, but the map's Dark Iron annotations remain uncertain.",sp=0},{t="Whispers on the Wind",b="Upon studying the crude cartography, an unnatural gust of wind carries the faint murmur of a dwarven voice, urging swift action. The mystic prompt points straight to Earthseer Farsen. Reporting this intelligence exposes early movements toward the ancient halls sealed away deep below the city, threatening the sanctuary of the mountain kingdom.",sp=1}},faq={{q="Where did this underground map come from?",a="The map is carried by Dark Iron spies surveying the perimeter of Ironband's Compound in Dun Morogh. It can be found while dealing with their scouts in the foothills.",al={"map drop","where find map","how to get underground map"},it="origin"},{q="What does the map show?",a="It outlines a complex network of underground highways and tunnels snaking through the earth, all converging directly beneath the city of Ironforge.",al={"what is on the map","map details","dark iron map purpose"},it="purpose"},{q="Who is Earthseer Farsen?",a="Earthseer Farsen is a dwarven earthseer from Aerie Peak attuned to the deep rocks and spirits of the mountain. Sensing the unnatural subterranean movements, he requires the map to assess the breach beneath Ironforge.",al={"where is farsen","who is farsen","earthseer"},it="identity"},{q="Why are the Dark Irons tunneling under Ironforge?",a="The map suggests a possible route beneath Ironforge, but its Dark Iron annotations have not been deciphered. Earthseer Farsen needs to examine it before the plan can be established.",al={"why dark iron tunneling","dark iron plot dun morogh"},it="conflict"},{q="What does this quest lead to?",a="Delivering this map to Earthseer Farsen begins the investigative effort into the depths beneath the city, leading directly into the Old Ironforge Incursion and opening access toward the Hall of Thanes.",al={"underground map follow up","next quest after underground map"},sp=1,it="next_step"},{q="What language are the map's runes written in?",a="The map uses the jagged runic script of the Dark Iron dwarves. The person who finds it cannot be sure what the annotations say.",al={"map runes","dark iron language"}},{q="Why must the Dark Iron Map be brought to Earthseer Farsen?",a="The map details an alarming network of subterranean tunnels and highways all converging directly beneath Ironforge. Its jagged Dark Iron runes require translation, and the eerie dwarven voice carried on the wind makes it clear that Earthseer Farsen must inspect the possible subterranean threat immediately to warn the mountain kingdom of the subterranean threat.",al={"why bring map to farsen","dark iron map motive","why deliver map"},it="motive",add="1c73103d"}},ang={["race:Dwarf"]="For Bronzebeard dwarves, discovering Dark Iron tunnels cutting directly toward Ironforge's foundation is a grave breach of the capital's territorial integrity.",["class:Shaman"]="The subtle gust of wind guiding you to Earthseer Farsen hints at elemental spirits warning of unnatural subterranean excavations beneath Dun Morogh.",["faction:Alliance"]="Neutralizing this subterranean infiltration route is essential to preserving the security of Ironforge and the Alliance's northern anchor."},kw={"dark iron map","dun morogh","earthseer farsen","hall of thanes","ironband's compound","ironforge","underground map"},rel={"quest:96390","quest:96393","zone:hallofthanes","subzone:ironband-s-compound","zone:ironforge","zone:dunmorogh"},m={start="Dark Iron Map",["end"]="Earthseer Farsen",level="15",id=96391},src={"Underground Map"},fv=true}
E["quest:96392"] = {t="quest",n="Farsen's Watch",z="dunmorogh",s="Farsen's Watch is an observational task given by Earthseer Farsen, a visiting Wildhammer shaman stationed high above Gol'Bolar Quarry. Using the earthseer's shamanic far sight, adventurers witness firsthand the growing infiltration of Dark Iron dwarves into the heart of Dun Morogh. This crucial survey marks an early step along the path toward the Hall of Thanes.",h="Farsen's Watch is an observational task given by Earthseer Farsen, a visiting Wildhammer shaman stationed...",sec={{t="Eyes Across the Ridge",b="Perched above the snowblown excavation of Gol'Bolar Quarry, Earthseer Farsen keeps a vigilant watch over the lower reaches of Dun Morogh. Having journeyed south from the crags of Aerie Peak, the Wildhammer visitor brings a keen spiritual awareness to lands usually patrolled by Ironforge mountaineers. Rather than relying on simple scouts, Farsen uses the traditional arts of his clan to monitor subterranean rumblings and unexpected movement along the hillsides.",sp=0},{t="A Borrowed Vision",b="To convince travelers of the imminent danger, Farsen lends them his farsight—a shamanic gift that projects one's awareness across vast distances. Looking through the spiritual lens, it becomes obvious that Dun Morogh's troubles extend far beyond unruly troggs and wild beasts. Dark Iron dwarves have slipped close to Ironforge's industrial center, entrenching themselves for an operation that demands immediate confrontation before it takes root.",sp=0}},faq={{q="Who is Earthseer Farsen?",a="Earthseer Farsen is a Wildhammer dwarf visiting Dun Morogh from Aerie Peak in the Hinterlands. As an earthseer, he commands shamanic magic that allows him to sense disturbances in the land and observe threats from afar.",al={"earthseer farsen","who is farsen","farsen wildhammer"},it="identity"},{q="Where is this watch taking place?",a="Earthseer Farsen is positioned overlooking Gol'Bolar Quarry, a key Bronzebeard mining excavation located in eastern Dun Morogh.",al={"farsen location","where is farsen","quarry overlook"},it="place"},{q="What threat does Farsen reveal?",a="Through his shamanic farsight, Farsen reveals that hostile Dark Iron dwarves have established a foothold nearby, posing an active and dangerous threat to the region.",al={"what does farsight show","dark iron threat","farsen vision"},it="threat"},{q="How does this connect to the Hall of Thanes?",a="Investigating the Dark Iron presence identified during Farsen's watch begins the larger chain of tasks required for adventurers seeking entry to the Hall of Thanes.",al={"hall of thanes attunement","hall of thanes questline"},it="ties"},{q="Why is a Wildhammer dwarf involved in Dun Morogh's defense?",a="While Wildhammers call the Hinterlands home, ties of kinship and shared enmity toward the Dark Irons occasionally bring travelers like Farsen to the ancestral Bronzebeard lands of Dun Morogh.",al={"why is wildhammer here","aerie peak dwarf dun morogh"},it="why_here"},{q="What comes directly after completing Farsen's Watch?",a="Once you have witnessed the Dark Iron infiltration through his vision, Farsen urges you forward with the task 'Nip 'Em in the Bud' to actively suppress the encroaching enemy.",al={"next quest","what comes after farsen's watch","nip em in the bud"},it="next_step"},{q="Why does Earthseer Farsen want this done?",a="While traveling through Dun Morogh from Aerie Peak, Earthseer Farsen spotted signs of Dark Iron dwarf aggression encroaching near Gol'Bolar Quarry. Before acting or raising alarms, the shaman wants you to witness the brewing danger firsthand through his far-seeing magic, ensuring Ironforge's defenders grasp the true scope of the hostile infiltration before it spirals out of control.",al={"why farsens watch","farsen motive","why does farsen want me to look"},it="motive",add="73fc96dc"}},ang={["race:Dwarf"]="For Bronzebeard defenders, receiving warning from an Aerie Peak cousin highlights just how brazen the Dark Iron infiltration of their homeland has become.",["class:Shaman"]="Wildhammer earthseers demonstrate the earthen and spiritual vision of their tradition, offering a glimpse into dwarf shamanism rooted in the crags of Aerie Peak.",["faction:Alliance"]="Uncovering Dark Iron plots in Dun Morogh is vital to preserving the safety of Ironforge and the surrounding mountain passes for all Alliance travel."},kw={"aerie peak","dark iron","dun morogh","earthseer","farsen","farsight","gol'bolar","hall of thanes","wildhammer"},rel={"zone:dunmorogh","subzone:gol-bolar-quarry","quest:96408","quest:96390","zone:hallofthanes","topic:dark-iron-dwarf","topic:dwarf"},m={start="Earthseer Farsen",level="13",id=96392},src={"Farsen's Watch"},fv=true}
E["quest:96393"] = {t="quest",n="Old Ironforge Incursion",z="dunmorogh",s="Old Ironforge Incursion is the culminating mission in the investigation of Dark Iron infiltrators lurking deep beneath Ironforge. Directed by Earthseer Farsen, champions delve into the ancient Hall of Thanes beneath Old Ironforge to eliminate the enemy commander, Durgen Dirgehammer, and report the threat directly to King Magni Bronzebeard.",h="Old Ironforge Incursion is the culminating mission in the investigation of Dark Iron infiltrators lurking...",sec={{t="Breaching the Vaults",b="Following the discovery of an underground map revealing Dark Iron movements, Earthseer Farsen identifies the mastermind behind the subterranean intrusion. Deep within the ancient stone halls of Old Ironforge lies the entrance to the Hall of Thanes. While the upper city busies itself with surface matters, insidious forces have slipped into these dormant caverns right under the kingdom's feet.",sp=0},{t="Durgen Dirgehammer",b="Farsen's translation of captured Dark Iron documents points to a single commander orchestrating the operations: Durgen Dirgehammer. Positioned deep within the lower vaults, Dirgehammer represents a direct threat to the heart of the Bronzebeard mountain kingdom. To break the incursion's spine, adventurers must plunge into the depths, strike him down, and carry his severed head to King Magni Bronzebeard above.",sp=1},{t="Audience with the King",b="Presenting Durgen Dirgehammer's head to King Magni Bronzebeard confirms the grim reality of the Dark Iron threat creeping through the city's ancient roots. Carrying both the grisly proof of victory and a personal greeting from his old friend Farsen, adventurers formally conclude the investigation and secure Magni's awareness of what lurks below.",sp=1}},faq={{q="What is Old Ironforge Incursion?",a="It is the finale of a quest chain investigating Dark Iron activity beneath Dun Morogh. Given by Earthseer Farsen, it tasks players with entering the Hall of Thanes beneath Old Ironforge to slay the Dark Iron commander Durgen Dirgehammer.",al={"old ironforge incursion quest","durgen dirgehammer quest"},it="purpose"},{q="Where does this quest take place?",a="The mission takes adventurers into the Hall of Thanes, an ancient subterranean chamber located beneath Old Ironforge, deep in the bedrock under the mountain capital.",al={"where is hall of thanes","hall of thanes location"},it="place"},{q="Who is Durgen Dirgehammer?",a="Durgen Dirgehammer is the Dark Iron commander leading the subterranean incursion into the Hall of Thanes beneath Old Ironforge. Earthseer Farsen identifies his name from recovered Dark Iron documents.",al={"who is dirgehammer","durgen dirgehammer"},it="target"},{q="Who gives the quest, and who receives it?",a="The quest is given by Earthseer Farsen following the recovery of the Underground Map. It is turned in directly to King Magni Bronzebeard in Ironforge.",al={"quest giver old ironforge incursion","who turns in old ironforge incursion"},it="people"},{q="How do I start the quest chain that leads to this?",a="The chain begins with the quest A Visitor to Dun Morogh, offered by Beldin Steelgrill outside Kharanos in Dun Morogh.",al={"how to start hall of thanes quest","visitor to dun morogh start"},gp=true},{q="What is the connection between Earthseer Farsen and King Magni?",a="Earthseer Farsen considers himself an old friend of King Magni Bronzebeard, instructing adventurers to send his personal regards when presenting Durgen Dirgehammer's head in the throne room.",al={"farsen and magni","earthseer farsen lore"},it="ties"},{q="Why does Earthseer Farsen want Durgen Dirgehammer killed?",a="Farsen uncovered enemy movements beneath the mountain and deciphered orders pointing to Durgen Dirgehammer as the commander leading the incursion into Old Ironforge. The Dark Iron presence in the ancient Hall of Thanes directly threatens the dwarven capital from below. By sending you to cut down their leader, Farsen aims to shatter the assault before the Dark Irons can entrench themselves, while sending undeniable proof of the threat directly to King Magni Bronzebeard.",al={"farsen motive","why kill durgen dirgehammer","why does farsen send you"},it="motive",add="bdae81a8"},{q="What is Durgen Dirgehammer's Head for?",a="You need Durgen Dirgehammer's Head as absolute proof for King Magni Bronzebeard that the commander of the subterranean assault has been dealt with. Delivering the gruesome trophy directly to the throne room confirms that the hostile Dark Iron strike force in the Hall of Thanes has lost its leader and carries Earthseer Farsen's personal warning to the king.",al={"durgen dirgehammer head use","why take durgen's head","head of durgen dirgehammer"},it="item",add="664606f0"}},ang={["race:Dwarf"]="For the Bronzebeards, Dark Iron infiltrators lurking in the forgotten vaults beneath the High Seat is an intolerable violation of their ancestral fortress.",["faction:Alliance"]="Stopping the incursion prevents a devastating sneak attack against the Alliance's primary stronghold in the Eastern Kingdoms."},kw={"dark iron","dirgehammer","farsen","incursion","ironforge","kharanos","magni","thanes"},rel={"zone:hallofthanes","subzone:old-ironforge","quest:96391","npc:magni-bronzebeard","npc:beldin-steelgrill","quest:96408","zone:ironforge","zone:dunmorogh"},m={start="Earthseer Farsen",["end"]="King Magni Bronzebeard",level="16",id=96393,ri={"Durgen Dirgehammer's Head"}},src={"Old Ironforge Incursion"},fv=true}
E["quest:96408"] = {t="quest",n="A Visitor to Dun Morogh",z="dunmorogh",s="A Visitor to Dun Morogh is an investigative task offered by Beldin Steelgrill outside Kharanos. Mountaineers reported an unfamiliar campfire high on the cliffs overlooking Gol'Bolar Quarry, prompting a scout to check whether the stranger poses a threat to the local dwarves.",h="A Visitor to Dun Morogh is an investigative task offered by Beldin Steelgrill outside Kharanos.",sec={{t="A Smoke Plume on the Heights",b="Dun Morogh's mountaineers keep a diligent watch over the crags and snowy valleys surrounding Ironforge. When a campfire suddenly appeared high above Gol'Bolar Quarry, it raised eyebrows in Kharanos. Beldin Steelgrill, concerned by the unusual encampment situated directly above a vital dwarven excavation, recruits travelers to scale the ridges and determine whether the mysterious stranger is a benign traveler or an intruder.",sp=0},{t="Meeting the Earthseer",b="Investigating the ridge reveals that the traveler is Earthseer Farsen, a mystic who has set up camp on the windswept heights. Far from being a marauding trogg or an outright hostile spy, this mysterious observer possesses deep spiritual ties to the earth. His presence on the precipice overlooking the quarry begins a journey uncovering deeper disturbances hidden beneath Khaz Modan, ultimately tying into the mystery of the Hall of Thanes.",sp=1}},faq={{q="Who sends you to investigate the visitor?",a="Beldin Steelgrill, stationed outside Kharanos in Dun Morogh, gives the quest after mountaineers report an unfamiliar fire up in the hills.",al={"who gives this quest","quest starter","beldin steelgrill quest"},gp=true},{q="Where is the mysterious campsite located?",a="The campfire sits high up on the snowy ridges to the east of Kharanos, perched directly overlooking the Gol'Bolar Quarry excavation.",al={"camp location","where is the visitor","visitor spot"},gp=true},{q="Who is the visitor overlooking the quarry?",a="The visitor is Earthseer Farsen, a spiritual observer residing in a secluded camp on the heights above the quarry.",al={"who is farsen","who is the visitor","earthseer farsen"},sp=1,it="target"},{q="Why were the dwarves suspicious of the campfire?",a="Gol'Bolar Quarry is a critical dwarven operation already under pressure from local troggs. Any unknown encampment set high above the pit could easily belong to scouts or hostile forces watching dwarven movements.",al={"why suspicious","why investigate","why send me"},it="motive"},{q="What does this quest lead into?",a="Reporting to Earthseer Farsen leads directly into the quest 'Farsen's Watch' and serves as the opening breadcrumb for the Hall of Thanes attunement chain.",al={"what comes next","followup quest","hall of thanes intro"},sp=1,it="next_step"},{q="Do you need to fight the stranger at the camp?",a="No. While Beldin Steelgrill prepares you for the possibility of violence, the visitor is Earthseer Farsen, a peaceful observer willing to speak with you.",al={"is the visitor hostile","do i kill the visitor","visitor fight"},sp=1,gp=true},{q="Why does Beldin Steelgrill ask an adventurer instead of the Mountaineers?",a="The local Mountaineers spotted the hillside campfire from afar, but their ranks are stretched thin guarding the roads, settlements, and quarry operations from troggs and wild beasts. Since the fire is likely harmless, Beldin relies on a capable traveler passing through Kharanos to quickly scout the ridge rather than pulling guards from active duty.",al={"why send me","why not send guards","beldin steelgrill why me"},it="why_me",add="3b0d76fb"}},ang={["race:Dwarf"]="For Bronzebeard dwarves, monitoring uninvited observers overlooking major mining sites like Gol'Bolar is standard security for protecting Khaz Modan's borders.",["class:Shaman"]="Meeting Earthseer Farsen connects directly to spiritual communion with the mountain stones, a rare sight in the snowy highlands of Dun Morogh.",["faction:Alliance"]="Aiding the local mountaineers outside Kharanos ensures the supply lines and quarry workers remain safe from unforeseen threats."},kw={"beldin steelgrill","dun morogh","earthseer farsen","farsen's watch","gol'bolar quarry","hall of thanes","kharanos","visitor"},rel={"npc:beldin-steelgrill","subzone:gol-bolar-quarry","subzone:kharanos","zone:dunmorogh","quest:96392","zone:hallofthanes"},m={start="Beldin Steelgrill",["end"]="Earthseer Farsen",level="13",faction="Alliance",id=96408},src={"A Visitor to Dun Morogh"},fv=true}
E["quest:96628"] = {t="quest",n="The Adventurer",z="dunmorogh",s="The Adventurer is a local errand given by Mountaineer Thalos at the southern gate of Dun Morogh. Before sending travelers through the mountain tunnel toward Kharanos, Thalos asks them to carry a bundle of supplies to Eric Brighthammer, a newcomer camped just outside the village.",h="The Adventurer is a local errand given by Mountaineer Thalos at the southern gate of Dun Morogh.",sec={{t="A Favor for the Mountaineers",b="Guarding the high passes and tunnels between Coldridge Valley and the broader snowy expanses of Dun Morogh is demanding work for the Ironforge Mountaineers. Stationed at the border gate, Mountaineer Thalos keeps an eye out for both local dangers and travelers passing along the beaten trail. When word reaches the post about a lone adventurer arriving near Kharanos, Thalos uses trusted passersby to haul necessary supplies onward to support newcomers venturing into the frozen crags.",sp=0},{t="Supplies for Kharanos",b="The road descending from the southern pass winds into the settlement of Kharanos, the primary hub for dwarven craft and travel in central Dun Morogh. Eric Brighthammer has recently established himself just on the outskirts of the village. By delivering the Mountaineers' bundle of provisions to him, travelers help establish a vital link between the outlying ridge sentries and those actively wandering the wilderness.",sp=0}},faq={{q="Who starts the quest The Adventurer?",a="Mountaineer Thalos offers this quest. He stands watch at the mountain pass gate connecting the Coldridge Valley trail to greater Dun Morogh.",al={"quest giver","who gives the adventurer","thalos quest"},gp=true},{q="Who is Eric Brighthammer?",a="Eric Brighthammer is an adventurer who has recently arrived outside the dwarven town of Kharanos. Mountaineer Thalos sends travelers to bring him an essential bundle of supplies.",al={"where is eric brighthammer","who is the adventurer","brighthammer"},it="identity"},{q="Where does this delivery take place?",a="The delivery takes place just outside Kharanos in Dun Morogh, north of the Coldridge Pass tunnel where Mountaineer Thalos is posted.",al={"where to deliver supplies","eric brighthammer location","supply bundle drop"},it="place"},{q="Why is Mountaineer Thalos sending supplies?",a="The Mountaineers keep tabs on travelers throughout Dun Morogh. When Thalos learns an adventurer has set up camp near Kharanos, he arranges for provisions to be carried out to support him in the cold.",al={"why send supplies","thalos purpose","reason for bundle"},it="motive"},{q="What item are you carrying?",a="You are carrying a Supply Bundle provided directly by Mountaineer Thalos to give to Eric Brighthammer.",al={"what supplies","supply bundle item"},it="item"},{q="Is this quest available to Horde players?",a="No. Mountaineer Thalos is an Alliance-aligned dwarven guard in Dun Morogh, making this task exclusive to the Alliance.",al={"can horde do this","is it alliance only","horde adventurer quest"},gp=true},{q="Why does Mountaineer Thalos ask you to deliver the supplies?",a="Mountaineer Thalos and his patrol are stationed at the pass, tasked with watching the road and securing the tunnel against local perils. Because you are already travelling onward through the pass toward Kharanos, he asks you to take the delivery along your route rather than pulling his mountaineers away from their guard posts.",al={"why me the adventurer","why does thalos need me","why send player to eric brighthammer"},it="why_me",add="95095969"}},ang={["race:Dwarf"]="For young dwarves leaving Coldridge Valley, taking provisions to Eric Brighthammer marks their first cooperative act with the Mountaineers in the wider realm of Dun Morogh.",["faction:Alliance"]="The Mountaineers rely on Alliance recruits to carry critical supplies across the icy roads, ensuring wandering allies outside Kharanos remain provisioned."},kw={"coldridge pass","dun morogh","eric brighthammer","kharanos","mountaineer thalos","supply bundle","the adventurer"},rel={"npc:mountaineer-thalos","subzone:kharanos","zone:dunmorogh"},m={start="Mountaineer Thalos",["end"]="Eric Brighthammer",level="6",faction="Alliance",id=96628},src={"The Adventurer (Dun Morogh)"},fv=true}
E["subzone:amberstill-ranch"] = {t="subzone",n="Amberstill Ranch",z="dunmorogh",s="Amberstill Ranch is a tranquil dwarven homestead nestled along the snowy roadway toward Loch Modan, directly north of Gol'Bolar Quarry. It serves as the primary breeding and training grounds for Ironforge's celebrated mountain rams. Adventurers visit the ranch to acquire hardy dwarven mounts, train in riding, or help the family defend their livestock from local predators.",h="Amberstill Ranch is a tranquil dwarven homestead nestled along the snowy roadway toward Loch Modan, directly...",sec={{t="Home of the Mountain Rams",b="Tucked against the crags of Dun Morogh, Amberstill Ranch is renowned throughout Khaz Modan for raising the sturdiest mountain rams in the Eastern Kingdoms. The Amberstill family manages the stables and paddocks, training these sure-footed beasts to navigate treacherous snowy passes and steep alpine cliffs. Outside of supplying riding mounts and domestic livestock, the family often contends with the savage fauna of the hills, particularly wandering wendigos drawn by the scent of fresh flock.",sp=0}},faq={{q="What is Amberstill Ranch known for?",a="The ranch is the Alliance's central hub for breeding Barak Tor'ol mountain rams. Dwarves and honored Alliance champions come here to learn ram riding and purchase mounts from the local stable masters.",al={"amberstill purpose","why visit amberstill","amberstill rams"},it="purpose"},{q="Can non-dwarves purchase mounts here?",a="Rams are traditionally reserved for dwarven riders who understand their stubborn temperament. Members of other Alliance races may only learn to ride and purchase them if they have earned the utmost trust and exalted standing with Ironforge.",al={"buy rams non dwarf","human buy ram","ram mount requirements"},gp=true},{q="What threats does the ranch face?",a="The herd is under constant threat from hungry wendigos descending from the frozen bluffs. The most notorious predator prowling the surrounding heights is Vagash, a massive wendigo that regularly targets the vulnerable livestock.",al={"amberstill danger","wendigo threat","vagash quest"},it="threat"},{q="Can you obtain anything else at the ranch?",a="Young Yarlyn Amberstill keeps a collection of domestic snowshoe rabbits and is willing to sell crated rabbits to travelers looking for a companion pet on the road.",al={"amberstill rabbit","snowshoe rabbit pet","yarlyn amberstill"},gp=true},{q="What is Amberstill Ranch?",a="Amberstill Ranch is a dwarven homestead and breeding ground tucked into the hills of eastern Dun Morogh, north of the Gol'Bolar Quarry. It serves as the primary stables for raising the hardy mountain rams prized by the Ironforge dwarves as trustworthy mounts in Khaz Modan's rugged terrain.",al={"what is amberstill ranch","amberstill ranch purpose","what is this place amberstill"},it="place",add="0dde8a5d"},{q="Who lives at Amberstill Ranch?",a="The ranch is home to the Amberstill family, who breed, tend, and train Dun Morogh's famous mountain rams. Members of the family manage the stables, sell local pets like snowshoe rabbits, and offer riding instruction to those who have earned the deep trust of Ironforge.",al={"who runs amberstill ranch","amberstill ranch residents","who lives here"},it="residents",add="f9ed26f9"},{q="Is Amberstill Ranch dangerous?",a="The ranch itself is a safe Alliance haven, but its outskirts are perilous. Fierce wild beasts roam the snowy bluffs nearby, none more feared by the local breeders than the monstrous wendigo Vagash, who preys upon their livestock.",al={"amberstill ranch danger","is amberstill safe","dangers at amberstill ranch"},it="danger",add="1facab92"}},ang={["race:Dwarf"]="For dwarven adventurers, the ranch is a proud cultural cornerstone where young heroes acquire their first Barak Tor'ol ram mount.",["faction:Alliance"]="The sturdy rams raised by the Amberstills provide the Alliance with dependable, cold-weather cavalry suitable for rugged mountain terrain."},kw={"amberstill","mount vendor","rams","ranch","riding trainer","snowshoe rabbit","vagash","yarlyn"},rel={"zone:dunmorogh","zone:lochmodan","zone:ironforge","subzone:gol-bolar-quarry","quest:314","topic:alliance"},src={"Amberstill Ranch"}}
E["subzone:anvilmar"] = {t="subzone",n="Anvilmar",z="dunmorogh",s="Anvilmar is a fortified dwarven outpost nestled in the snowy depths of Coldridge Valley in Dun Morogh. Centered around a massive stone forge, it serves as the primary training grounds and rallying point for young Bronzebeard dwarves and displaced gnomish refugees beginning their adventures.",h="Anvilmar is a fortified dwarven outpost nestled in the snowy depths of Coldridge Valley in Dun Morogh.",sec={{t="The Hearth of Coldridge",b="Tucked away in the northern crags of Coldridge Valley, Anvilmar stands as an enduring symbol of dwarven perseverance. Dominated by a roaring central forge, this sturdy masonry complex houses class mentors, supply vendors, and veteran mountain mountaineers who drill recruits before sending them out into the wider kingdom. Though sheltered behind towering drifts, the settlement remains on constant guard against the hostile Frostmane trolls and aggressive wild beasts prowling the frozen valley.",sp=0},{t="A Legacy of Iron and Trolls",b="The settlement likely takes its proud name from High King Modimus Anvilmar, the ancient sovereign who ruled all dwarven clans before the War of the Three Hammers. However, its history has not been without strife. In bygone days, a towering Frostmane troll managed to breach the perimeter and lay waste to the enclave. Today, the garrison remains vigilant, ensuring the forge fires stay lit and no such disaster ever strikes the starting grounds again.",sp=0}},faq={{q="What is Anvilmar?",a="Anvilmar is a dwarven stronghold and settlement located in northern Coldridge Valley within Dun Morogh. It functions as the initial staging post and training hub for newly recruited dwarven and gnomish adventurers.",al={"what is anvilmar","anvilmar location","anvilmar overview"},it="place"},{q="Why is it named Anvilmar?",a="The outpost may be named after High King Modimus Anvilmar or the Anvilmar bloodline. Modimus ruled the dwarven clans before the War of the Three Hammers, but the settlement's naming is not confirmed.",al={"who was anvilmar","anvilmar name origin","name meaning"},it="name"},{q="What threats does Anvilmar face?",a="The outpost faces constant danger from the native Frostmane trolls occupying the crags of Coldridge Valley, as well as dangerous local wildlife like wolves and wendigos. Historically, a giant Frostmane troll even managed to rampage through the settlement.",al={"anvilmar enemies","who attacks anvilmar","threats to anvilmar"},it="threat"},{q="Can you learn professions here?",a="While Anvilmar features a roaring forge suitable for smithing and smelting, there are no professional tradeskill trainers stationed here. Young recruits must venture further into Dun Morogh, such as to Kharanos or Ironforge, to formally learn crafting arts.",al={"professions in anvilmar","anvilmar forge","blacksmithing anvilmar"},gp=true},{q="What happened at Anvilmar in the past?",a="While Anvilmar normally serves as a peaceful haven and training ground for newly aspiring dwarven and gnomish adventurers, it has seen violence in its history. In the past, a giant Frostmane troll attacked and laid waste to the outpost, demonstrating that even nestled deep within Coldridge Valley, the settlement is never entirely safe from the savage trolls prowling the snowy ridges.",al={"anvilmar history","past of anvilmar","frostmane attack anvilmar"},it="history",add="8e79e4f7"},{q="Is Anvilmar dangerous?",a="The settlement itself is safe and protected, serving as a haven with a grand forge, hearth, trainers, and guards. However, just beyond its immediate perimeter, danger lurks in every direction. Aggressive wolves, hungry bears, and raiding parties of hostile Frostmane trolls roam the snowy drifts of Coldridge Valley, posing constant hazards to unwary travelers and new recruits.",al={"is anvilmar safe","danger anvilmar","threats in anvilmar"},it="danger",add="449334a9"}},ang={["race:Dwarf"]="For dwarves, Anvilmar represents the beginning of the journey into the world, possibly bearing the name of the ancient High King who once ruled a unified dwarven kingdom.",["race:Gnome"]="Gnomes taking shelter here after the fall of Gnomeregan find stout dwarven allies, warm hearths, and instructors ready to help them adapt to the frozen wilderness."},kw={"anvilmar","coldridge valley","dun morogh","forge","frostmane","modimus anvilmar","starting zone"},rel={"subzone:coldridge-valley","zone:dunmorogh","subzone:coldridge-pass","topic:troll"},src={"Anvilmar"}}
E["subzone:brewnall-village"] = {t="subzone",n="Brewnall Village",z="dunmorogh",s="Brewnall Village is a small dwarven settlement nestled in Chill Breeze Valley near the entrance to Gnomeregan. Established by the Barleybrew family, this outpost serves as a proving ground for bold brewing experiments and regional defense against wild beasts. Despite being called a village, it functions largely as a rustic encampment in the snowy gnomish lowlands of Dun Morogh.",h="Brewnall Village is a small dwarven settlement nestled in Chill Breeze Valley near the entrance to Gnomeregan.",sec={{t="A Bitter Brew in the Valley",b="Tucked away in the snowdrifts of Chill Breeze Valley, Brewnall Village lies squarely within the traditional gnomish reaches of western Dun Morogh. The settlement is home to the Barleybrew clan, stalwart dwarven brewers devoted to perfecting age-old recipes and crafting the ultimate stout. Though dubbed a village, the outpost consists mostly of tents and outdoor brewing equipment rather than permanent stone architecture. Between testing experimental batches of ale and defending against the ferocious local wolves and bears, the Barleybrews rely heavily on wandering mountaineers to gather rare ingredients and keep the valley secure.",sp=0}},faq={{q="What is Brewnall Village?",a="Brewnall Village is a small dwarven camp located in Chill Breeze Valley within western Dun Morogh, just east of Gnomeregan. It serves as an outpost where the Barleybrew clan experiments with new beer recipes and manages local wildlife threats.",al={"where is brewnall","what is brewnall village","brewnall info"},it="place"},{q="Why is it called a village if there are no buildings?",a="Despite carrying the name village, the site is essentially an open-air encampment made up of tents and supply kegs. The Barleybrews have staked out their brewing operation here in the cold climate without building formal stone houses.",al={"why is it a camp","where are the houses","brewnall buildings"},it="name"},{q="Why is a dwarven settlement located in gnomish territory?",a="While the western half of Dun Morogh surrounds Gnomeregan and is primarily inhabited by gnomes, the close alliance between Ironforge and the gnomes makes shared settlement common. The Barleybrews settled here in Chill Breeze Valley to pursue their craft undisturbed.",al={"dwarves near gnomeregan","why are dwarves here","gnome territory dwarf camp"}},{q="What problems do the residents face?",a="The encampment faces frequent attacks from the valley's aggressive wildlife, particularly crag boars, bears, and frost wolves. Additionally, the Barleybrews are constantly searching for rare and exotic ingredients to invent new, superior brews.",al={"brewnall quests","what do the barleybrews need","village problems"},it="danger"},{q="Who lives in Brewnall Village?",a="Brewnall Village serves as the home and testing ground for the Barleybrew family. These dwarven brewers have set up camp here in Chill Breeze Valley to dedicate themselves entirely to their craft, endlessly experimenting to refine and perfect the art of dwarven ale brewing.",al={"who runs brewnall","brewnall village residents","who lives at brewnall village"},it="residents",add="c4fa2ce1"}},ang={["race:Dwarf"]="For dwarves, the Barleybrews' quest for the ultimate recipe is an honorable pursuit that upholds one of Ironforge's finest traditions.",["race:Gnome"]="Situated close to Gnomeregan, the village is an unexpected dwarven outpost deep within western Dun Morogh's gnomish valleys."},kw={"barleybrew","beer","brewnall","chill breeze valley","dun morogh","gnomeregan","stout"},rel={"subzone:chill-breeze-valley","quest:315","quest:319","zone:dunmorogh","zone:gnomeregan","topic:gnome","zone:ironforge"},src={"Brewnall Village"}}
E["subzone:chill-breeze-valley"] = {t="subzone",n="Chill Breeze Valley",z="dunmorogh",s="Chill Breeze Valley is a rugged, snow-covered pass in western Dun Morogh linking the dwarven settlement of Kharanos with the embattled city of Gnomeregan. While its main path is a well-traveled thoroughfare for young travelers and refugees, its secluded recesses harbor dangerous beasts and bloody dens.",h="Chill Breeze Valley is a rugged, snow-covered pass in western Dun Morogh linking the dwarven settlement of...",sec={{t="A Crossroads of Snow and Claws",b="Chill Breeze Valley forms a T-shaped trench through the mountains of western Dun Morogh. The main east-west trail sees steady foot traffic from novice dwarves and gnomes journeying between Kharanos and the outskirts of Gnomeregan. However, straying into the valley's north-south offshoot is another matter entirely. Strewn with bloodstains and mangled carcasses, these shadowy reaches harbor ferocious predators—most notably savage wendigos that lair in deep ice caves and prey on anyone reckless enough to wander into their hunting grounds.",sp=0}},faq={{q="Where is Chill Breeze Valley located?",a="Chill Breeze Valley is situated in western Dun Morogh, positioned directly between the bustling mountain hub of Kharanos to the east and the technological gnome city of Gnomeregan to the west.",al={"chill breeze valley location","where is chill breeze valley","chill breeze valley map"},it="place",gp=true},{q="Why is the valley so dangerous to travel through?",a="While the main path between Kharanos and Gnomeregan is relatively safe and heavily traveled, the northern and southern offshoots of the valley are hunting grounds for predatory beasts. The snow there is stained with blood and torn carcasses, leading to caves inhabited by vicious, territorial wendigos.",al={"chill breeze valley monsters","dangers in chill breeze valley","why are there bones here"},it="danger"},{q="What kinds of beasts make their dens here?",a="The deeper recesses of the valley are home to ferocious wendigos, including particularly large and elite alpha beasts that have claimed several cave dens as their personal lairs.",al={"wendigo in chill breeze valley","what lives in chill breeze valley"},it="residents"},{q="What is Chill Breeze Valley?",a="Chill Breeze Valley is a rugged, T-shaped pass nestled in western Dun Morogh, linking the ruins of Gnomeregan to the west with the town of Kharanos to the east. Its central path serves as a vital transit corridor for traveling dwarves and gnome refugees, while its deeper reaches remain treacherous snowy wilderness.",al={"chill breeze valley","what is this valley","about chill breeze valley"},it="place",add="746bfe00"}},ang={["race:Gnome"]="For gnomish refugees fleeing the fallout of Gnomeregan toward the safety of Kharanos and Ironforge, surviving the trek through Chill Breeze Valley's predatory perimeter is a critical first step.",["race:Dwarf"]="Mountaineers and young dwarven hunters test their mettle clearing out the ferocious wendigos that menace the vital passage connecting central Dun Morogh to the western highlands."},kw={"caves","chill breeze valley","dun morogh","gnomeregan","kharanos","t-shaped","wendigo"},rel={"zone:dunmorogh","subzone:kharanos","zone:gnomeregan","topic:gnome"},src={"Chill Breeze Valley"}}
E["subzone:coldridge-pass"] = {t="subzone",n="Coldridge Pass",z="dunmorogh",s="Coldridge Pass is a rugged, snowbound tunnel cutting through the southern mountain ridge of Dun Morogh. It serves as the sole overland route connecting the secluded training grounds of Coldridge Valley to the rest of the kingdom, emerging near the bustling town of Kharanos. Because hostile troggs have overrun the passage, any traveler attempting the journey must either fight their way through or make a desperate dash for the other side.",h="Coldridge Pass is a rugged, snowbound tunnel cutting through the southern mountain ridge of Dun Morogh.",sec={{t="The Gateway Out of the Valley",b="For young dwarven recruits and gnome novices taking their first steps beyond Coldridge Valley, Coldridge Pass is a harsh rite of passage. Chiseled straight through the rock, this tunnel forms the primary link sending newly trained adventurers eastward toward the frontier hub of Kharanos. What was once a secure mountain corridor has become a perilous choke point, infested with aggressive troggs that have pushed up from dark sub-terrains to menace any soul trying to travel between the sheltered valley and the wider reaches of Dun Morogh.",sp=0}},faq={{q="Where does Coldridge Pass lead?",a="The pass connects Coldridge Valley in the southwest to the greater region of Dun Morogh, emptying out into the snowy hills just west of the town of Kharanos.",al={"where does coldridge pass go","coldridge pass destination","how to leave coldridge valley"},it="place"},{q="Why are there troggs in Coldridge Pass?",a="Troggs have recently surged forth from the deep subterranean cracks beneath Dun Morogh, seizing dark caves and tunnels throughout the region. Coldridge Pass provided them shelter and an easy ambush point against mountain travelers.",al={"why are troggs here","coldridge pass monsters","trogg infestation"},it="threat"},{q="Is Coldridge Pass safe to travel through?",a="No, it is not safe. The tunnel is swarming with hostile troggs, meaning recruits and travelers must cut their way through the brutes or sprint through the darkness to reach the opposite end.",al={"is coldridge pass dangerous","can i walk through coldridge pass"},it="danger"},{q="Who guards or maintains the pass?",a="Mountaineers watch the valley and road exits, but the tunnel interior remains contested and uncleared, leaving individual travelers to defend themselves as they make the crossing.",al={"dwarf guards at coldridge pass","who controls the pass"},it="in_charge"},{q="What is the history of Coldridge Pass?",a="Carved through the mountains of Dun Morogh, Coldridge Pass was established as the primary lifeline connecting the isolated training grounds of Coldridge Valley to the wider realm and the frontier town of Kharanos. For generations, dwarven recruits and mountaineers used this corridor to travel freely between the valley and the rest of the kingdom. However, the recent emergence of hostile troggs inside the tunnel disrupted that peace, forcing travelers to fight their way through what was once a secure transit route.",al={"coldridge pass history","what happened at coldridge pass","coldridge pass background"},it="history",add="7f71f8e0"}},ang={["race:Dwarf"]="For dwarven mountaineers and recruits, traversing Coldridge Pass represents your departure from novice training at Anvilmar into active service across Ironforge's lands.",["race:Gnome"]="Exiled gnomes seeking to aid the Alliance must push through this trogg-infested choke point to reach Kharanos and the higher road toward Ironforge."},kw={"anvilmar","coldridge pass","coldridge valley","dun morogh","kharanos","mountain pass","trogg","tunnel"},rel={"subzone:coldridge-valley","subzone:kharanos","zone:dunmorogh","topic:trogg"},src={"Coldridge Pass"}}
E["subzone:coldridge-valley"] = {t="subzone",n="Coldridge Valley",z="dunmorogh",s="Coldridge Valley is a sheltered, snow-covered vale tucked into the southwestern heights of Dun Morogh. Centered around the hamlet of Anvilmar, it serves as the training ground where young dwarves and gnome refugees first take up arms in service of Ironforge. A single tunnel, Coldridge Pass, connects this secluded hollow to the wider mountain realm.",h="Coldridge Valley is a sheltered, snow-covered vale tucked into the southwestern heights of Dun Morogh.",sec={{t="A Secluded Proving Ground",b="Cradled by sheer mountain cliffs, Coldridge Valley remains largely cut off from the bustling trade routes of Dun Morogh. At its heart sits Anvilmar, a sturdy stone hall and hamlet where veteran dwarven instructors and displaced gnome scholars train fresh recruits in the arts of battle, stealth, and sorcery. Outside the warmth of Anvilmar's hearths, the valley floor is carpeted in thick snow and prowled by boars and hungry winter wolves, providing novices with their first real taste of frontier survival.",sp=0},{t="Encroaching Foes",b="Despite its isolation, Coldridge Valley faces immediate danger from two relentless enemies. Indigenous Frostmane trolls have established camps like the Frostmane Hovel, skirmishing with mountaineers and defending their ancestral claims against dwarven encroachment. Worse still, savage Rockjaw troggs have overrun Coldridge Pass, the natural tunnel linking the valley to Kharanos. Until these subterranean brutes are pushed back, travelers and supplies cannot freely move between the valley and the high seat of Ironforge.",sp=0}},faq={{q="How do you leave Coldridge Valley?",a="The only overland route out of the valley leads through Coldridge Pass, a snowy tunnel cutting northeast through the mountain ridge. Once through the pass, the road heads east directly toward the town of Kharanos and onward to the great gates of Ironforge.",al={"exit coldridge","how to get out","path to kharanos"},it="next_step",gp=true},{q="Why are gnomes starting here alongside dwarves?",a="Following the tragic fall of Gnomeregan to troggs and radioactive fallout, surviving gnomes fled into Dun Morogh as refugees. High Tinker Mekkatorque's people were welcomed by King Magni Bronzebeard, leading many exiled gnomish apprentices to train side by side with young dwarves in Anvilmar.",al={"gnomes in coldridge","why are gnomes here","gnome starting area"},it="arrival"},{q="What threats are troubling the valley?",a="The valley faces two major menaces: the hostile Frostmane trolls, who resent dwarven settlements on their mountain territory, and crude Rockjaw troggs, who have clawed up from the deep earth to choke Coldridge Pass. Local predators like wolves and boars also harass unwary travelers.",al={"coldridge enemies","valley threats","who is attacking"},it="threat"},{q="What is Anvilmar?",a="Anvilmar is the central fortress-lodge and settlement within Coldridge Valley. It houses class trainers, forge-masters, and local mountaineer officers who coordinate the defense of the valley and prepare newly forged adventurers for the wider world.",al={"anvilmar town","what is the town here"},it="place"},{q="What is Coldridge Valley?",a="Coldridge Valley is a sheltered, snow-covered basin tucked into the southwestern corner of Dun Morogh. Ringed by jagged mountain peaks, it serves as the secluded training ground and staging camp for young dwarves and gnome refugees before they venture out into the wider kingdom.",al={"coldridge valley overview","where is coldridge valley","coldridge info"},it="place",add="80e4cacf",nx={6}},{q="Is Coldridge Valley part of Dun Morogh?",a="Yes, it sits in the southwestern heights of Dun Morogh. It remains physically separated from the rest of the snowbound region by a ring of mountains, linked to the mainland only through the narrow tunnel of Coldridge Pass to the northeast.",al={"is coldridge in dun morogh","dun morogh coldridge valley"},it="place",add="73aec6cd"},{q="Is Coldridge Valley dangerous?",a="While intended as a quiet, sheltered training ground, trouble has recently spilled into the valley. Hostile Frostmane trolls lurk in nearby camps, aggressive wildlife prowls the snowdrifts, and vicious troggs have overrun the only mountain pass leading out to the rest of Dun Morogh.",al={"coldridge danger","is it safe here","coldridge threats"},it="danger",add="0ba4a80e"},{q="Who rules the dwarves?",a="The dwarves of Ironforge are ruled by King Magni Bronzebeard. A steadfast leader and veteran of the Great Wars, King Magni governs the Kingdom of Ironforge from his mighty mountain throne room and stands as one of the Alliance's most resolute champions.",al={"who is the dwarf king","king of ironforge","dwarf leader"},it="leader",add="7fc500c6"},{q="What's in Kharanos and why does everyone keep mentioning it?",a="Kharanos is the lively frontier town located just beyond Coldridge Pass along the main road to Ironforge. It serves as the primary outpost for young recruits to report for active duty, boast craft training, and sample world-famous ale at the Thunderbrew Distillery.",al={"what is kharanos","why go to kharanos","kharanos town"},it="next_step",add="ff57e405",nx={10}},{q="Who is Senir Whitebeard?",a="Senir Whitebeard is a prominent dwarven leader stationed in the nearby frontier town of Kharanos. He coordinates defense efforts in the region, actively working to eradicate the dangerous foothold that the Frostmane ice trolls have carved out across Dun Morogh's peaks.",al={"senir whitebeard","senir kharanos"},it="people",add="966deec9"},{q="How did I end up in Coldridge Valley?",a="You arrived in Coldridge Valley because it serves as the sheltered training ground for new recruits in Dun Morogh. Tucked away in the southwestern mountains, the valley offers aspiring defenders a secluded place to learn their craft, gather gear, and prove their mettle before braving the wider, harsher realm beyond.",al={"how did i get here","why am i here","how did i end up here","what brought me here"},it="arrival",add="a3c72edd"},{q="What am I supposed to be doing in Coldridge Valley?",a="Your task is to undergo basic training, hone your combat skills, and aid the local authorities stationed at Anvilmar. You are expected to cull unruly local wildlife, push back encroaching Frostmane trolls and troggs, and eventually clear a path through Coldridge Pass to report for service in Kharanos.",al={"what do i do here","what is my mission","what should i do in coldridge","what am i doing here"},it="purpose",add="8bdf0a70"},{q="Why does a new Dwarf start here, in Coldridge Valley?",a="As a young dwarven adventurer, you have come to Anvilmar to master your martial and magical traditions under veteran trainers. Ironforge needs stalwart champions to protect its realm, and this mountain cradle offers the ideal proving ground to forge fresh recruits into seasoned defenders of Khaz Modan.",al={"why do dwarves start here","why am i here dwarf","dwarf starting area","why coldridge valley dwarf"},it="arrival",rc="Dwarf",add="2eeaa2be"},{q="Why does a new Gnome start here, in Coldridge Valley?",a="With Gnomeregan recently fallen to the trogg invasion, surviving gnomes have fled their home and found shelter among their dwarven allies. As an exiled gnome eager to aid the Alliance and rebuild your people's future, you begin your training alongside dwarven recruits in the safety of Coldridge Valley.",al={"why do gnomes start here","why am i here gnome","gnome starting area","why coldridge valley gnome"},it="arrival",rc="Gnome",add="ef9153cd"}},ang={["race:Dwarf"]="As the traditional starting ground for Bronzebeard mountaineers and clerics, the valley represents a dwarf's first steps beyond the hearth and into service of the High Seat.",["race:Gnome"]="For gnome exiles forced from Gnomeregan, the snows of Coldridge Valley offer a safe haven to master their spells and machinery alongside their dwarven hosts."},kw={"anvilmar","coldridge pass","coldridge valley","dun morogh","frostmane","ironforge","starting area","troggs"},rel={"subzone:anvilmar","zone:dunmorogh","subzone:coldridge-pass","subzone:frostmane-hovel","subzone:kharanos","topic:dwarf","topic:gnome","topic:trogg"},src={"Coldridge Valley"}}
E["subzone:frostmane-hold"] = {t="subzone",n="Frostmane Hold",z="dunmorogh",s="Frostmane Hold is a fortified encampment and cavern complex claimed by the Frostmane ice trolls in western Dun Morogh. Tucked into the crags south of Gnomeregan, it serves as a central staging ground for troll raiders encroaching on dwarven territory. The Ironforge Guard keeps a close watch on the hold to gauge the growing troll threat.",h="Frostmane Hold is a fortified encampment and cavern complex claimed by the Frostmane ice trolls in western...",sec={{t="A Troll Bastion in the Snows",b="Carved into the freezing cliffs of western Dun Morogh, Frostmane Hold consists of rough outdoor structures and a winding cave system. For the Frostmane tribe, it functions as a primary stronghold, densely guarded by hideskinners and headhunters. From here, the trolls launch raids into the surrounding valleys, testing the defenses of nearby settlements like Kharanos and menacing travelers along the mountain passes.",sp=0},{t="A Thorn in Kharanos' Side",b="As tensions in Dun Morogh mount, dwarven commanders in Kharanos have grown increasingly concerned about the scale of the Frostmane buildup. Young mountaineers and adventurers are routinely dispatched to scout the interior caverns, map out the defenses, and cull the warbands before the tribe can muster an organized assault against dwarven outposts.",sp=0}},faq={{q="Who lives in Frostmane Hold?",a="The stronghold is occupied by the Frostmane tribe of ice trolls, specifically their hunters, hideskinners, and headhunters, along with their chieftains and raiders.",al={"who is in frostmane hold","frostmane hold mobs","trolls in frostmane hold"},it="residents"},{q="Where is Frostmane Hold located?",a="It lies in the western mountains of Dun Morogh, situated south of the industrial ruins of Gnomeregan and west of Kharanos.",al={"frostmane hold location","where is frostmane hold","find frostmane hold"},gp=true},{q="Why are the dwarves interested in this cave?",a="Dwarven leaders in Kharanos fear that the Frostmane are massing in numbers large enough to stage serious raids on settlements, prompting military leaders to send scouts to map the caves and thin their ranks.",al={"why scout frostmane hold","kharanos troll quest"},it="purpose"},{q="Are there troggs in Frostmane Hold?",a="No. In the present era, the stronghold belongs firmly to the Frostmane ice trolls. Trogg activity in Dun Morogh remains primarily centered around their own dens and the ruins of Gnomeregan.",al={"troggs frostmane hold","rockjaw frostmane"},it="threat"},{q="What is Frostmane Hold?",a="Frostmane Hold is a sprawling cave system and base camp nestled into the frigid mountains in western Dun Morogh, just south of Gnomeregan. Composed of rustic structures and deep caverns, it serves as a central stronghold for the indigenous Frostmane ice trolls.",al={"what is frostmane hold","frostmane hold dun morogh","about frostmane hold"},it="place",add="81bf3a2c"},{q="Is Frostmane Hold dangerous?",a="It is extremely hazardous for any Alliance traveler. The hold is fiercely defended by Frostmane headhunters and hideskinners who show no mercy to outsiders wandering into their territory.",al={"is frostmane hold dangerous","frostmane hold danger","how safe is frostmane hold"},it="danger",add="406236bf"},{q="Why is it called Frostmane Hold?",a="The stronghold takes its name directly from the Frostmane tribe of ice trolls who carved out the caves and claim these frozen mountains as their ancestral homeland.",al={"why is it called frostmane hold","frostmane hold name meaning","where did the name frostmane hold come from"},it="name",add="0c447a8f"}},ang={["race:Dwarf"]="The Frostmane have contested Dun Morogh for centuries, and clearing out Frostmane Hold is a rite of passage for mountaineers seeking to safeguard Ironforge's snowy heartland.",["race:Gnome"]="Nestled just south of Gnomeregan, the hold represents yet another dangerous hostile front bordering the embattled former gnome capital."},kw={"dun morogh","frostmane","frostmane hold","headhunter","hideskinner","ice troll","kharanos","vejrek"},rel={"quest:287","zone:dunmorogh","subzone:kharanos","zone:gnomeregan","topic:troll"},src={"Frostmane Hold"}}
E["subzone:frostmane-hovel"] = {t="subzone",n="Frostmane Hovel",z="dunmorogh",s="Frostmane Hovel is a rugged cave den tucked into the southern crags of Coldridge Valley in Dun Morogh. It serves as an entrenched shelter for aggressive Frostmane trolls pressing directly into dwarven training grounds.",h="Frostmane Hovel is a rugged cave den tucked into the southern crags of Coldridge Valley in Dun Morogh.",sec={{t="A Troll Den in the Valley",b="Carved into the southern mountains flanking Coldridge Valley, the Frostmane Hovel shelters indigenous Frostmane trolls who refuse to yield the high snows to Ironforge. Operating out of crude caverns like this, the trolls mount continuous raids against local dwarven camps and disrupt supply lines into the valley.",sp=0}},faq={{q="What is the Frostmane Hovel?",a="The Frostmane Hovel is a natural cavern in southern Coldridge Valley used as a foul-weather encampment by indigenous Frostmane trolls encroaching on dwarven territory.",al={"frostmane hovel","what is this cave","coldridge troll cave"},it="place"},{q="Why are there trolls in Coldridge Valley?",a="The Frostmane tribe has inhabited the snowy peaks of Dun Morogh for generations. Bitter rivals of the Bronzebeard dwarves, they constantly push inward from the high ridges to raid supply paths and challenge dwarven settlements.",al={"why trolls here","dun morogh trolls","frostmane presence"},it="why_here"},{q="Who controls this cave?",a="The cave is occupied by raiding Frostmane trolls who use the sheltered crevice to stage incursions across the southern shelf of the valley.",al={"who leads the cave","who lives in frostmane hovel"},it="in_charge"}},ang={["race:Dwarf"]="For young Bronzebeard recruits training in Coldridge Valley, securing the perimeter against the hostile Frostmane tribe in caves like this is an essential rite of passage.",["faction:Alliance"]="The persistent Frostmane presence right outside Anvilmar highlights how even the heartland of Ironforge must constantly defend itself against local adversaries."},kw={"anvilmar","coldridge valley","dun morogh","frostmane","hovel","trolls"},rel={"subzone:coldridge-valley","zone:dunmorogh","topic:troll"},src={"Frostmane Hovel"}}
E["subzone:gnomeregan"] = {t="subzone",n="Gnomeregan",z="dunmorogh",s="Gnomeregan was the magnificent subterranean capital of the gnomish race, renowned across Azeroth for its mechanical brilliance and technological marvels. Today, it stands as a radioactive tomb, overrun by subterranean troggs, haywire defense automatons, and deranged leper gnomes after a desperate defense ended in catastrophe.",h="Gnomeregan was the magnificent subterranean capital of the gnomish race, renowned across Azeroth for its...",sec={{t="A Wonder of Engineering",b="Carved into the snowy crags of western Dun Morogh, Gnomeregan was built with the aid of the Ironforge dwarves centuries ago. Inside, massive steam-driven gears, intricate copper piping, and cavernous assembly halls formed the intellectual and industrial beating heart of gnomekind. It was from these subterranean halls that gnomish designs, flying machines, and complex armaments supplied the Alliance throughout the Second War, standing firm even when besieged by Orgrim Doomhammer's Horde.",sp=0},{t="The Fall and the Poisoned Halls",b="During the Third War, a subterranean surge of troggs erupted from deep beneath the earth, breaching the city's lowest chambers. Unwilling to divert Alliance armies from the slaughter in Lordaeron, High Tinker Gelbin Mekkatorque attempted to handle the crisis alone. On the advice of his chief engineer, Sicco Thermaplugg, Mekkatorque ordered radioactive gas vented through the lower chambers to wipe out the brutes. The plan backfired horrifyingly: the gas empowered many troggs while killing nearly eighty percent of the gnomish populace. Those exposed who did not perish mutated into twisted leper gnomes, while Thermaplugg seized rule over the poisoned ruins.",sp=0}},faq={{q="Why is Gnomeregan full of radiation?",a="When subterranean troggs overran the city, High Tinker Mekkatorque released radioactive gas into the lower vents on the advice of Sicco Thermaplugg. The desperate gambit was intended to eradicate the beasts, but instead it slaughtered thousands of gnomes, mutated the survivors into leper gnomes, and left the city permanently irradiated.",al={"why is it radioactive","gnomeregan toxic gas","what poisoned gnomeregan"},it="ruin"},{q="Where are all the surviving gnomes now?",a="The survivors escaped to the nearby dwarven city of Ironforge. King Magni Bronzebeard granted them asylum within the Tinkers' Court, where High Tinker Gelbin Mekkatorque now coordinates efforts to aid his scattered people and plan the reclaiming of their home.",al={"where do gnomes live","gnome refugees","where is mekkatorque"},it="people"},{q="Who controls Gnomeregan now?",a="Sicco Thermaplugg, Mekkatorque's former chief advisor, declared himself King of Gnomeregan. Driven mad by toxic exposure and megalomania, he commands the city's rogue defense automatons, irradiated leper gnomes, and mutant troggs from deep within the core.",al={"who is the boss of gnomeregan","gnomeregan leader","thermaplugg"},it="in_charge"},{q="Why didn't the Alliance help save Gnomeregan during the invasion?",a="Mekkatorque deliberately chose not to ask the Alliance for help. With humanity collapsing under the weight of the Scourge during the Third War, the gnomes kept their subterranean struggle secret so as not to siphon vital defenders away from Lordaeron.",al={"why alliance no help","why didn't humans help gnomes","gnomes in third war"},it="history"},{q="What is Gnomeregan?",a="Gnomeregan is the subterranean capital city of the gnomes, built beneath the snowy peaks of Dun Morogh. A marvel of wrought-iron engineering, clockwork machinery, and steam-driven technology, it stood for generations as the bustling heart of gnomish culture, ingenuity, and political power alongside their dwarven allies.",al={"what is gnomeregan","gnomeregan city","gnome capital"},it="place",add="927c35f4"},{q="Is Gnomeregan dangerous?",a="Extremely dangerous. The lower depths are awash in lingering, lethal radiation capable of warping the body and mind. The halls swarm with savage troggs, deranged leper gnomes, malfunctioning combat automatons, and the lethal traps of the self-proclaimed King Thermaplugg. Entering without proper preparation or a stout group invites a horrific death.",al={"is gnomeregan dangerous","dangers of gnomeregan","how dangerous is gnomeregan"},it="danger",add="702e95d4"}},ang={["race:Gnome"]="Every gnome carries the trauma of Gnomeregan's loss. Entering the irradiated halls is a solemn pilgrimage to destroy the usurper Thermaplugg and recover lost mechanical heirlooms.",["profession:Engineering"]="Even choked with radioactive poison, Gnomeregan is the greatest concentration of schematics, advanced spare parts, and functional industrial machinery in the Eastern Kingdoms."},kw={"dun morogh","gnomeregan","leper gnome","mekkatorque","thermaplugg","tinkers court","trogg"},rel={"zone:dunmorogh","npc:gelbin-mekkatorque","npc:sicco-thermaplugg","topic:leper-gnome","topic:trogg","subzone:tinkers-court","quest:412"},src={"Gnomeregan"}}
E["subzone:gol-bolar-quarry"] = {t="subzone",n="Gol'Bolar Quarry",z="dunmorogh",s="Gol'Bolar Quarry is a dwarven excavation site carved into the snowy hills of southeastern Dun Morogh. Rich in stone and ore, the bustling mining operation has ground to a halt after being overrun by vicious troggs surging from the depths.",h="Gol'Bolar Quarry is a dwarven excavation site carved into the snowy hills of southeastern Dun Morogh.",sec={{t="A Quarry Under Siege",b="Situated southeast of Kharanos, Gol'Bolar Quarry was established by Ironforge dwarves to extract vital stone and mineral wealth from the mountains. However, deep excavation work uncovered underground warrens, unleashing a horde of hostile troggs that quickly drove out the miners. Today, the upper camp serves as an embattled staging ground where overseers, tradesfolk, and Prospector Gehn rally dwarven and gnomish recruits to drive the beasts back and reclaim the pit.",sp=0}},faq={{q="What is Gol'Bolar Quarry?",a="Gol'Bolar Quarry is an open-pit mining operation in southeastern Dun Morogh. Maintained by Ironforge dwarves, it serves as both an excavation site and a small outpost providing supplies and work for local adventurers.",al={"gol bolar","what is this place","quarry info"},it="place"},{q="Why are there so many troggs here?",a="Dwarven miners dug too deeply into the earth and breached subterranean tunnels inhabited by troggs. The creatures swarmed into the open pits and adjoining mine shafts, forcing the miners to fall back to the quarry's upper rim.",al={"why are troggs here","trogg infestation","who attacked the quarry"},it="threat"},{q="Who is Prospector Gehn?",a="Prospector Gehn is a dwarven supervisor stationed at the quarry's camp. He oversees efforts to secure the dig site, issuing bounties and tasks to adventurers willing to cull the trogg population.",al={"who is gehn","prospector gehn"},it="identity"},{q="What happened at Gol'Bolar Quarry?",a="Gol'Bolar began as an active dwarven excavation site and mining camp in southeastern Dun Morogh, dedicated to carving stone and unearthing valuable minerals. However, standard operations ground to a sudden halt when subterranean troggs broke through into the lower dig and the nearby mine. The vicious creatures quickly overwhelmed the miners, forcing the dwarves to pull back and establish a fortified camp on the quarry's upper ridges to recruit help in reclaiming it.",al={"gol'bolar quarry history","what happened at golbolar","gol'bolar background"},it="history",add="e8696793"},{q="Who lives in or runs Gol'Bolar Quarry?",a="A resilient group of dwarven miners, overseers, and support staff hold the camp overlooking the pit. Overseen by Prospector Gehn and fellow excavators, the outpost includes weapon vendors, provisioners, and profession trainers who support young mountaineers and explorers working to drive back the trogg menace.",al={"who runs gol'bolar quarry","gol'bolar quarry camp","who lives at gol'bolar"},it="residents",add="3a8dc0a0"},{q="Is Gol'Bolar Quarry dangerous?",a="Yes. While the upper rim and small camp remain protected by local dwarves, the open pit and the quarry mine below swarm with hostile troggs. Any traveler descending into the excavation without caution risks being swarmed by aggressive tunnelers claiming the dig site as their own.",al={"is gol'bolar dangerous","danger in gol'bolar quarry","threats in gol'bolar"},it="danger",add="becb3bb6"}},ang={["profession:Mining"]="The exposed rock tiers and adjacent tunnels offer plentiful mineral veins, though prospectors must fight through entrenched troggs to reach them.",["race:Dwarf"]="Clearing Gol'Bolar Quarry is a matter of both economic necessity and clan pride, as Ironforge cannot afford to let brutish troggs seize its mountain resources."},kw={"dun morogh","gol'bolar","mine","prospector gehn","quarry","trogg"},rel={"subzone:gol-bolar-quarry-mine","zone:dunmorogh","topic:trogg","topic:gnome"},src={"Gol'Bolar Quarry"}}
E["subzone:gol-bolar-quarry-mine"] = {t="subzone",n="Gol'Bolar Quarry Mine",z="dunmorogh",s="Gol'Bolar Quarry Mine is an overrun excavation pit deep within the heart of Gol'Bolar Quarry in eastern Dun Morogh. Originally worked by dwarven miners, the tunnels breached subterranean trogg caverns, unleashing a violent infestation that claimed the entire site. Today, the deepest shafts serve as the stronghold for the trogg warband led by the brute Hammerspine.",h="Gol'Bolar Quarry Mine is an overrun excavation pit deep within the heart of Gol'Bolar Quarry in eastern Dun...",sec={{t="A Breach in the Deep",b="The mine was established by Ironforge dwarves seeking stone and rich ore deposits beneath the craggy peaks of Dun Morogh. Work came to an abrupt, violent halt when pickaxes fractured a wall into an ancient subterranean cavern system inhabited by troggs. Swarming out from the dark, the subterranean beasts overwhelmed the work crews and forced a hasty retreat, ultimately spilling outward to overrun the surrounding quarry pit as well.",sp=0},{t="Lair of Hammerspine",b="While younger, weaker troggs roam the sunlit terraces of the quarry basin, the mine itself harbors the warband's fiercest fighters. Deep within these cramped, torchlit tunnels lurks their vicious chieftain, Hammerspine. Reclaiming the valuable quarry remains an urgent priority for the local mountaineers, but driving the infestation out requires venturing into the blackest depths of the mine to cut off the beasts at their source.",sp=0}},faq={{q="Why is the mine full of troggs?",a="Dwarven miners accidentally broke into a hidden underground cavern while digging. The slumbering troggs inside swarmed through the breach, slaughtered or drove out the excavators, and claimed the mine shafts as their home.",al={"why are troggs in gol bolar","how did troggs get here","who took over the mine"},it="ruin"},{q="Who leads the troggs inside Gol'Bolar Quarry Mine?",a="The troggs inside the mine are led by Hammerspine, a hulking brute who commands the strongest members of the warband from deep within the shafts.",al={"mine boss","trogg leader gol bolar","who is hammerspine"},it="residents"},{q="Is the mine different from the rest of the quarry?",a="Yes. The outer quarry pit contains the surface works and weaker troggs, while the mine consists of deep, claustrophobic subterranean tunnels containing the toughest troggs and their chieftain.",al={"quarry vs mine","are the mine troggs harder"},it="place"},{q="Can miners still work here?",a="No. All mining operations have completely ceased. The site is an active war zone where dwarven mountaineers and adventurers work to purge the trogg threat rather than harvest stone.",al={"is the mine active","are dwarves still mining"}},{q="What happened at Gol'Bolar Quarry Mine?",a="The mine was actively excavated by dwarven prospectors until their digging broke directly into an underground cavern system inhabited by troggs. Surprised and overwhelmed by the feral onslaught, the dwarves were violently driven from the depths, losing both the inner tunnels and the surrounding quarry to the invaders.",al={"gol bolar quarry mine history","what happened at the mine","gol bolar mine backstory"},it="history",add="58d8a204"},{q="Is Gol'Bolar Quarry Mine dangerous?",a="It is considerably more perilous than the quarry outside. While weaker scavengers wander the open pits, the deepest and strongest troggs lurk in these cramped tunnels under the command of their brutal leader, Hammerspine. Anyone entering unprepared faces a lethal subterranean ambush.",al={"is gol bolar mine dangerous","how dangerous is gol bolar mine","gol bolar mine trogg danger"},it="danger",add="2d64c093"}},ang={["race:Dwarf"]="Every pick swing into the mountain carries the risk of awakening what lies beneath. Reclaiming Gol'Bolar Mine is a matter of both economic necessity and dwarven pride.",["profession:Mining"]="A stark reminder of the hazards of subterranean excavation, this mine remains entirely blocked by hostile troggs until its deepest tunnels are purged."},kw={"dun morogh","gol'bolar","gol'bolar quarry mine","hammerspine","mine","quarry","troggs"},rel={"subzone:gol-bolar-quarry","topic:trogg","zone:dunmorogh"},src={"Gol'Bolar Quarry Mine"}}
E["subzone:grizzled-den"] = {t="subzone",n="Grizzled Den",z="dunmorogh",s="The Grizzled Den is a cavern nestled in the snowy hills just southwest of Kharanos. It serves as a notorious lair for the ferocious, frost-breathing wendigos indigenous to Dun Morogh.",h="The Grizzled Den is a cavern nestled in the snowy hills just southwest of Kharanos.",sec={{t="A Frost-Chilled Lair",b="Carved deep into the crags southwest of Kharanos, the Grizzled Den is notorious among local mountaineers as the nesting ground of Dun Morogh's wendigo packs. These aggressive, ape-like beasts wield frosty breath against intruders and band together to protect their hollows. Despite the peril, daring hunters regularly brave the cavern's depths to harvest thick wendigo manes, which fetch a respectable sum among craftsmen looking to line cold chairs and carriage seats with insulated fur.",sp=0},{t="Hidden Treasures",b="Beyond its fearsome inhabitants, the twisting tunnels of the Grizzled Den draw opportunists searching for natural wealth. Prospectors frequently venture past the outer entrance to hammer at copper veins jutting from the frozen stone walls, while adventurous scouts often scour the darker corners for discarded footlockers. However, delve too far into the inner reaches, and you are bound to face the dens' largest and most vicious predators lurking in the shadows.",sp=0}},faq={{q="Where is the Grizzled Den located?",a="The Grizzled Den is found southwest of Kharanos in Dun Morogh, tucked away into the snow-covered mountain ridges.",al={"grizzled den location","where is grizzled den","how to get to grizzled den"},it="place",gp=true},{q="What creatures live in the Grizzled Den?",a="The cavern is overrun with packs of ferocious wendigos. These aggressive, white-furred beasts can exhale freezing frost and will readily swarm any interloper.",al={"what is in grizzled den","grizzled den mobs","creatures inside grizzled den"},it="residents"},{q="Why do people venture into the Grizzled Den?",a="Hunters and adventurers brave the den primarily to hunt wendigos for their thick manes, which are highly prized for crafting warm seat covers. Others brave the freezing tunnels to extract raw copper ore from the cavern walls.",al={"why go to grizzled den","grizzled den quests","wendigo manes"},it="purpose"},{q="What is the Grizzled Den?",a="The Grizzled Den is an expansive cave system tucked into the snowy hills southwest of Kharanos in Dun Morogh. It serves as a natural lair carved into the mountains, notorious across the region for its frosty interior and the wild beasts sheltering within its rocky depths.",al={"what is grizzled den","grizzled den overview","about grizzled den"},it="place",add="4377d186"},{q="Is the Grizzled Den dangerous?",a="Yes, it poses a genuine peril to lone travelers and novice adventurers. The cave is infested with aggressive wendigos capable of breathing frost spells. Worse still, these beasts tend to flock together to overwhelm invaders, and an exceptionally ferocious specimen lurks deep within the caverns.",al={"how dangerous is grizzled den","grizzled den danger","is grizzled den safe"},it="danger",add="44a06046"}},ang={["profession:Mining"]="The outer and inner tunnels of the den hold exposed copper deposits, making it a viable early digging spot if you can keep the wendigos off your back.",["race:Dwarf"]="Clearing the Grizzled Den is practically a rite of passage for young dwarven mountaineers training around Kharanos."},kw={"cave","dun morogh","frost","grizzled den","kharanos","wendigo"},rel={"quest:313","subzone:kharanos","zone:dunmorogh"},src={"Grizzled Den"}}
E["subzone:helm-s-bed-lake"] = {t="subzone",n="Helm's Bed Lake",z="dunmorogh",s="Helm's Bed Lake is a frozen body of water nestled in the southeastern hills of Dun Morogh. A maintained hole in the thick ice provides crucial fresh water to local mountaineers and travelers. However, the surrounding shoreline has become perilous due to prowling wildlife, encroaching troggs, and hostile Dark Iron infiltrators.",h="Helm's Bed Lake is a frozen body of water nestled in the southeastern hills of Dun Morogh.",sec={{t="A Treacherous Shoreline",b="Helm's Bed Lake sits quietly beneath a thick sheet of winter ice in southeastern Dun Morogh. Local dwarves keep an opening chopped through the frost to draw clean, fresh water. While crossing the frozen expanse is stable enough, lingering near the banks has become increasingly risky. Wild beasts wander the edges, displaced troggs scavenge along the ridges, and a cell of hostile Dark Iron dwarves has commandeered an abandoned lodge just south of the water, aggressively ambushing any travelers who pass through.",sp=0}},faq={{q="Why is there an open hole in the middle of the frozen lake?",a="The hole in the thick ice is deliberately maintained by local dwarves to allow consistent access to fresh, unfrozen water amid Dun Morogh's sub-zero climate.",al={"ice hole","water access","why is the ice broken"},it="purpose"},{q="What dangers lurk around Helm's Bed Lake?",a="While the lake surface itself is solid, the perimeter is hunted by predatory beasts and stray troggs. To the south, an encampment of hostile Dark Iron dwarves occupies an old building and violently repels anyone who draws near.",al={"threats at helms bed lake","who is attacking here","enemies nearby"},it="threat"},{q="Who is Narm Faulk?",a="Narm Faulk is an unfortunate dwarf whose body can be found along the shoreline of Helm's Bed Lake, a grim casualty of the sudden surge of hostile threats and Dark Iron infiltrators in the area.",al={"narm faulk corpse","dead dwarf near lake","dead body at helms bed lake"},it="identity"},{q="Are the Dark Iron dwarves officially occupying the lake?",a="They have not seized the lake outright, but an armed squad has claimed an abandoned structure just to the south, using it as a forward position to stage skirmishes into central Dun Morogh.",al={"dark irons at the lake","dark iron dwarf lodge"},it="conflict"},{q="What is Helm's Bed Lake?",a="Helm's Bed Lake is a small, mostly frozen lake nestled in southeastern Dun Morogh. A hole in the thick ice is kept open to allow access to fresh drinking water. While the frozen surface itself offers steady footing, the wilderness surrounding the lake is far less welcoming, teeming with predators, roaming troggs, and hostile Dark Iron infiltrators.",al={"helms bed lake","where is helms bed lake","what is this lake"},it="place",add="ba815d26"}},ang={["race:Dwarf"]="For the Ironforge dwarves, Helm's Bed Lake represents both a vital freshwater spot and an irritating security failure, as Dark Iron saboteurs and troggs push deeper into Dun Morogh's heartland.",["faction:Alliance"]="Alliance scouts traveling east toward Loch Modan must stay alert here, as the southward trail skirts uncomfortably close to aggressive Dark Iron ambushes."},kw={"dark iron","dun morogh","helm's bed lake","ice hole","narm faulk","trogg"},rel={"zone:dunmorogh","topic:trogg"},src={"Helm's Bed Lake"}}
E["subzone:iceflow-lake"] = {t="subzone",n="Iceflow Lake",z="dunmorogh",s="Iceflow Lake is a frigid, partially frozen body of water situated in western Dun Morogh, directly north of Brewnall Village. Despite the relentless frost, local dwarves maintain fishing holes through the sheet ice to secure fresh water and fish. The snow-covered islands in the center of the lake are prowled by aggressive winter wolves and their alpha, Timber.",h="Iceflow Lake is a frigid, partially frozen body of water situated in western Dun Morogh, directly north of...",sec={{t="Frozen Depths and Island Predators",b="Spanning western Dun Morogh just outside Brewnall Village, Iceflow Lake battles the bitter Khaz Modan climate year-round. Thick ice sheets continually creep across the surface, forcing local residents like Paxton Ganter to regularly clear holes for ice fishing and drinking water. While the shore provides sustenance, the islands rising from the middle of the lake are far less welcoming. A fierce pack of wild wolves has made these icy mounds their territory, dominated by the notoriously savage gray worg known as Timber.",sp=0}},faq={{q="Why is there an open hole in the frozen lake?",a="The biting cold of Dun Morogh freezes the lake solid, so the dwarves of nearby Brewnall Village deliberately keep a section cleared of ice. This hole grants access to unfrozen drinking water and gives local fishermen a place to cast their lines.",al={"ice hole","why is the ice broken","brewnall fishing hole"},it="purpose"},{q="Who is Paxton Ganter?",a="Paxton Ganter is a dwarven fisherman and fishing trainer found beside Iceflow Lake. He helps travelers learn to fish in Dun Morogh.",al={"paxton ganter","dwarf at iceflow lake","lake dwarf"},it="people"},{q="What threats live on the lake's islands?",a="The central islands are infested by hungry winter wolves and their alpha, a ferocious worg named Timber. Travelers who attempt to cross the ice into the middle of the lake frequently find themselves ambushed by the pack.",al={"timber","wolves in the lake","island wolves dun morogh"},it="threat"},{q="What is Iceflow Lake?",a="Iceflow Lake is a medium-sized, frozen body of water located in western Dun Morogh, just outside Brewnall Village. The bitter mountain altitude keeps its waters locked beneath thick ice year-round, save for a designated hole maintained by local dwarves for fishing and fresh water. Dominated by central islands overrun with aggressive predators, it serves as both a vital local resource and a treacherous crossing for travelers traversing the snowy crags.",al={"what is iceflow lake","iceflow lake dun morogh","where is iceflow lake"},it="place",add="26667757"},{q="Is Iceflow Lake dangerous?",a="Yes, traversing Iceflow Lake carries significant risk. While the ice itself is thick enough to walk upon, the large islands rising from the center of the lake are inhabited by a vicious pack of ravenous winter wolves led by the fearsome worg Timber. Anyone wandering onto the ice without watching their surroundings risks drawing the attention of these hungry predators.",al={"is iceflow lake dangerous","dangers at iceflow lake","iceflow lake threats"},it="danger",add="d98fd8f9"}},ang={["race:Dwarf"]="For the mountaineers of Brewnall Village, Iceflow Lake is both a vital freshwater lifeline and a persistent hazard, requiring constant vigilance against predatory wolves crossing the ice.",["class:Hunter"]="The snowy shores and central islands of the lake offer prime tracking grounds for hardy winter beasts, particularly the fearsome worg alpha, Timber."},kw={"brewnall village","dun morogh","frozen lake","ice fishing","iceflow lake","paxton ganter","timber"},rel={"zone:dunmorogh","subzone:brewnall-village"},src={"Iceflow Lake"}}
E["subzone:ironband-s-compound"] = {t="subzone",n="Ironband's Compound",z="dunmorogh",s="Ironband's Compound is a fortified outpost tucked into the snowy hills south of Helm's Bed Lake in eastern Dun Morogh. Formerly home to the prospector Sturgy Ironband, the camp has been overrun by hostile Dark Iron dwarves who attack anyone venturing too close.",h="Ironband's Compound is a fortified outpost tucked into the snowy hills south of Helm's Bed Lake in eastern...",sec={{t="A Fall to the Dark Irons",b="Originally established by Sturgy Ironband, this compound south of Helm's Bed Lake once served as a staging post in the snowy wilderness of Dun Morogh. That changed when Dark Iron infiltrators pushed deep into Bronzebeard territory and seized the site for themselves. Now bristling with hostile dwarves, the compound serves as an enemy forward base threatening travelers and nearby settlements, right under the nose of Ironforge.",sp=0},{t="A Threat to Ironforge",b="The presence of a fortified Dark Iron camp within Dun Morogh's own borders is a serious provocation. Ironforge keeps a wary eye on the compound, dispatching seasoned warriors to recover fallen scouts and secure vital intelligence proving the extent of the Dark Iron threat in the mountain kingdom.",sp=0}},faq={{q="Who originally built Ironband's Compound?",a="The outpost was formerly inhabited and used by Sturgy Ironband before hostile forces drove him out and took control of the site.",al={"who made this camp","sturgy ironband","who owns ironbands compound"},it="origin"},{q="Who controls Ironband's Compound now?",a="The camp has been seized by a band of hostile Dark Iron dwarves who readily assault any wanderers or Ironforge patrols that approach.",al={"who is here","what enemies are here","dark irons dun morogh"},it="residents"},{q="Where is Ironband's Compound located?",a="You can find it nestled in the snowy hills of eastern Dun Morogh, just south of Helm's Bed Lake.",al={"where is ironbands compound","how to find ironband compound","ironband location"},it="place",gp=true},{q="Why is this camp important to the leaders of Ironforge?",a="Having an enemy clan establish a fortified base so close to the dwarf capital is an alarming security breach. Ironforge authorities send fighters here to gather hard evidence of Dark Iron infiltration.",al={"why care about this camp","ironforge response","dark iron threat"},it="threat"},{q="What is Ironband's Compound?",a="Ironband's Compound is a fortified campsite situated south of Helm's Bed Lake in eastern Dun Morogh. Originally an outpost inhabited by the dwarf Sturgy Ironband, the compound has recently been overrun and occupied by a hostile contingent of Dark Iron dwarves.",al={"what is ironbands compound","ironbands compound dun morogh","tell me about ironband compound"},it="place",add="18d4f4e7"},{q="What happened at Ironband's Compound?",a="Once held peacefully by Sturgy Ironband, this remote outpost was violently ambushed and seized by infiltrating Dark Iron dwarves. The invaders drove out its rightful occupants and established an entrenched staging ground directly within Dun Morogh's borders, alarming the authorities in Ironforge.",al={"ironbands compound history","what happened here ironband","how was ironbands compound lost"},it="history",add="ea846983"},{q="Why is Ironband's Compound abandoned?",a="The outpost was not simply abandoned—it was violently captured. Sturgy Ironband and his allies were forced out when Dark Iron infiltrators launched a surprise assault, turning the dwarven camp into a heavily guarded enemy encampment.",al={"why is ironbands compound abandoned","is ironbands compound ruined","what happened to sturgy ironband"},it="ruin",add="be9cbc3a"},{q="Is Ironband's Compound dangerous?",a="It is extremely hazardous for lone travelers. The Dark Iron dwarves stationed here are openly hostile, heavily armed, and will assault anyone venturing near the compound to protect their foothold in Dun Morogh.",al={"is ironbands compound dangerous","ironbands compound threats","can i go to ironbands compound"},it="danger",add="c49e4d1f"},{q="Why is it called Ironband's Compound?",a="The encampment bears the name of Sturgy Ironband, the dwarf who originally established and inhabited the site before hostile Dark Iron forces seized it.",al={"why called ironbands compound","who is ironband","ironbands compound name origin"},it="name",add="8089f1d9"}},ang={["race:Dwarf"]="For the Bronzebeards, seeing the treacherous Dark Irons entrenching themselves within Dun Morogh's borders is a direct insult and a persistent danger to their homeland.",["class:Warrior"]="Aspiring warriors are dispatched here by Ironforge's veteran trainers to prove their mettle by aiding fallen comrades and collecting proof of the Dark Iron presence."},kw={"dark iron","dun morogh","dwarf","helm's bed lake","ironband's compound","ironforge","sturgy ironband"},rel={"zone:dunmorogh","subzone:helm-s-bed-lake","zone:ironforge","topic:dwarf"},src={"Ironband's Compound"}}
E["subzone:ironforge"] = {t="subzone",n="Ironforge",z="dunmorogh",s="Ironforge is the underground capital city of the dwarves, excavated deep into the stone of Ironforge Mountain within Dun Morogh. Centered around the roaring Great Forge, it serves as the political and mercantile anchor of the Kingdom of Khaz Modan and a bulwark of the Alliance.",h="Ironforge is the underground capital city of the dwarves, excavated deep into the stone of Ironforge Mountain...",sec={{t="The Mountain Fortress",b="Carved into the subterranean depths of Ironforge Mountain, the city is arranged in concentric stone rings radiating out from the monumental Great Forge. Originally founded millenia ago after the dwarves awakened and migrated from Uldaman, it has weathered ages of history, including the ancient War of the Three Hammers that left the Bronzebeard clan in sole control. Powered by cascading torrents of molten magma and fortified behind massive stone gates, the cavern city is equal parts industrial powerhouse and impenetrable bastion. Beyond dwarven craftsmen and warriors, its halls also host a substantial population of exiled gnomes following the recent fall of Gnomeregan.",sp=0},{t="Heart of Alliance Trade",b="In 25 ADP, Ironforge stands as perhaps the busiest center of commerce and industry across the Alliance. King Magni Bronzebeard presides over Khaz Modan from the High Seat, while dwarven prospectors, miners, and engineers work in concert with gnome refugees settled in Tinker Town. The subterranean Deeprun Tram establishes an unbroken, high-speed transit line beneath the mountains directly to Stormwind City, keeping both capitals tightly linked through trade, troop movements, and mutual defense.",sp=0}},faq={{q="Who rules Ironforge right now?",a="Ironforge is ruled by King Magni Bronzebeard, who holds court from the High Seat. The city serves as the seat of the Kingdom of Khaz Modan under the sole leadership of the Bronzebeard clan.",al={"who is the king of ironforge","ironforge leader","who leads ironforge"},it="in_charge"},{q="Why are there so many gnomes living in Ironforge?",a="Following the disastrous fall and radiation of their nearby capital city, Gnomeregan, the surviving gnomes fled to Ironforge. The Bronzebeards welcomed their longtime allies, giving them sanctuary within the district known as Tinker Town.",al={"why are gnomes in ironforge","gnomes tinker town","where did gnomes come from"},it="people"},{q="How does Ironforge connect to Stormwind City?",a="Ironforge connects directly to Stormwind through the Deeprun Tram, an engineering marvel constructed by gnomes that runs underground from Tinker Town all the way to Stormwind's Dwarven District.",al={"tram to stormwind","how to get to stormwind","subway to stormwind"}},{q="What is the Great Forge in the center of the city?",a="The Great Forge is an immense furnace fueled by natural rivers of magma channeled straight through the heart of the mountain. It serves as the primary smithing and smelting center for the Kingdom of Khaz Modan.",al={"giant forge in ironforge","what is the great forge","lava in ironforge center"},it="origin"},{q="What is Ironforge?",a="Ironforge is the underground capital city of the dwarves and the seat of the Kingdom of Khaz Modan. Carved entirely out of stone beneath the tallest mountain in Dun Morogh, it stands as an impregnable subterranean fortress and an industrial heartland for the Alliance. Its districts radiate out in concentric rings around the massive Great Forge, packed with smelters, smithies, lively taverns, and military halls.",al={"what is ironforge","ironforge lore","about ironforge"},it="place",add="492ad021"},{q="What happened at Ironforge?",a="Ironforge was founded millennia ago when ancient dwarves wandered from Uldaman and built the Great Forge to honor the titan Khaz'goroth. Centuries later, civil strife tore through the mountain during the War of the Three Hammers. Following the death of High King Modimus Anvilmar, the Bronzebeard, Wildhammer, and Dark Iron clans fought violently for control until the Bronzebeards ousted their rivals, claiming sole dominion over the mountain fortress.",al={"ironforge history","what happened here","ironforge past"},it="history",add="f6c71775"},{q="Is Ironforge dangerous?",a="Within its massive stone gates, Ironforge is one of the safest sanctuaries in the Eastern Kingdoms. Guarded heavily by dwarven mountaineers and royal sentries, its thick mountain walls keep surface perils at bay. So long as you do not fall into the molten rivers of the Great Forge or belong to the Horde, you face little peril walking its bustling, cozy streets.",al={"is ironforge safe","dangers in ironforge","threats in ironforge"},it="danger",add="9692900f"},{q="Why is the city called Ironforge?",a="The city takes its name from the Great Forge that sits at the center of the cavern, as well as the towering mountain it was carved beneath. When the early dwarves first carved into the peak and constructed their grand smelting works, the entire underground metropolis grew outward around that monumental forge.",al={"why is it called ironforge","how ironforge got its name","ironforge name origin"},it="name",add="ea3b645e"}},ang={["race:Dwarf"]="Ironforge is the ancestral capital and heart of the Bronzebeard clan, where dwarven craft, valor, and history are carved directly into living mountain stone.",["race:Gnome"]="Having lost Gnomeregan to troggs and radiation, gnomes have made Tinker Town their temporary refuge and the staging ground for their reclamation efforts."},kw={"bronzebeard","deeprun tram","dun morogh","great forge","high seat","ironforge","khaz modan","magni","tinker town"},rel={"zone:dunmorogh","subzone:great-forge","subzone:high-seat","subzone:tinker-town","subzone:deeprun-tram","topic:bronzebeard-clan","zone:gnomeregan","zone:stormwind"},src={"Ironforge"}}
E["subzone:ironforge-airfield"] = {t="subzone",n="Ironforge Airfield",z="dunmorogh",s="Tucked away high in the snowy peaks northeast of Ironforge, this remote dwarven airstrip serves as a proving ground and staging area for gnome flying machines and dwarven mountaineers. Unmarked by main roads, the plateau overlooks the jagged crags of Dun Morogh and the steep descent toward the Wetlands.",h="Tucked away high in the snowy peaks northeast of Ironforge, this remote dwarven airstrip serves as a proving...",sec={{t="A Hidden Redoubt in the Crags",b="Perched far above the beaten trails of Dun Morogh, the high-altitude airfield is a quiet marvel of Alliance cooperation. Sheltered by surrounding mountain peaks, dwarven masonry anchors the blustery ridgelines while gnomish flying machines sit parked along open landing strips. Mountaineers keep watch over the perimeter alongside engineers busy wrenching gears and inspecting steam-belching engines in the biting cold.",sp=0},{t="Frontier Skirmishes and Frozen Valleys",b="Despite its isolation, the airfield is far from serene. The surrounding valley features frozen waters and crags contested by Frostmane trolls, who dwell in nearby caves and constantly harass the dwarven sentries. In the shadow of the peaks, dwarven defenders and Stormpike patrols clash regularly with troll raiders across the ice, keeping the remote installation in a state of quiet, vigilant standoff.",sp=0}},faq={{q="How do you get up to the airfield?",a="There are no roads, flights, or maintained tunnels connecting the valley to Ironforge or lower Dun Morogh. Reaching it requires scaling the steep mountainsides on foot, typically via tricky ridgeline climbing paths beginning out of Loch Modan or near the passes of Dun Morogh.",al={"get to airfield","how to climb to airfield","airfield location","airfield path"},it="arrival",gp=true},{q="What is the purpose of this place?",a="It serves as an elevated flight testing and military outpost where dwarven mountaineers and gnome engineers maintain flying machines and scout the high mountain borderlands separating Dun Morogh, Loch Modan, and the Wetlands.",al={"why is there an airstrip","what is ironforge airfield for"},it="purpose"},{q="Who is attacking the dwarven guards here?",a="Local Frostmane trolls inhabit caves in the southern cliffs of the valley. Dwarven mountaineers clash regularly with them over the frozen lake just beneath the runway.",al={"who attacks airfield","who is fighting on the lake"},it="threat"},{q="Is the airfield tied to any official quests?",a="No standard quests direct adventurers to visit the airstrip in everyday travels. It remains an obscure, remote plateau largely separated from the main logistics of the dwarven kingdom.",al={"any quests here","airfield quests"},gp=true},{q="What is Ironforge Airfield?",a="Ironforge Airfield, also called the Dun Morogh Airstrip, is a high mountain base nestled in the peaks northeast above Ironforge. Constructed with landing strips, dwarven battlements, and mechanical hangars, it serves as a staging ground and testing site for gnomish flying machines and dwarven aerial operations high above the snowy crags.",al={"ironforge airfield","what is the dun morogh airstrip","what is this airfield"},it="place",add="d601e954"},{q="Who lives in or runs Ironforge Airfield?",a="The airfield is manned by Ironforge Mountaineers and dwarven guards protecting the mountain perimeter, alongside gnomish engineers and pilots tinkering with flying machines along the runways. Scouts affiliated with the Stormpike Guard also maintain a presence in the surrounding snowy passes.",al={"who controls ironforge airfield","who runs the airfield","who is at the airstrip"},it="residents",add="ef0ab7f8"},{q="Is Ironforge Airfield dangerous?",a="While the airfield itself is secured by dwarven sentries and gnomish aviators, the surrounding valley holds real danger. Hostile Frostmane trolls inhabit caves bordering the southern frozen lake and frequently clash with dwarven patrols, while wild bears roam the icy ridges nearby.",al={"is ironforge airfield dangerous","airfield threats","danger at the airstrip"},it="danger",add="74586b0d"}},ang={["profession:Engineering"]="For tinkers, the airstrip showcases the apex of gnomish aviation, featuring fully assembled flying machines stationed in extreme, sub-zero conditions.",["race:Dwarf"]="A testament to dwarven territorial watchfulness, the airfield proves that Ironforge's Mountaineers stand sentry even in the most inaccessible heights of Khaz Modan."},kw={"airfield","airstrip","dun morogh","flying machine","frostmane","ironforge","mountaineers"},rel={"zone:dunmorogh","zone:ironforge","zone:lochmodan","subzone:north-gate-pass","subzone:gol-bolar-quarry","topic:gnome","topic:troll"},src={"Ironforge Airfield"}}
E["subzone:kharanos"] = {t="subzone",n="Kharanos",z="dunmorogh",s="Kharanos is a bustling mountain settlement nestled in the snowy heart of Dun Morogh, just down the road from Ironforge. Serving as the primary hub for travelers leaving Coldridge Valley, the town hosts a forge, gnomish workshops, and the famous Thunderbrew Distillery.",h="Kharanos is a bustling mountain settlement nestled in the snowy heart of Dun Morogh, just down the road from...",sec={{t="A Hearty Frontier Haven",b="Situated along the central road of Dun Morogh, Kharanos is the first true town welcoming recruits arriving from Anvilmar. Despite the biting cold and biting winds, the settlement thrives thanks to local dwarven grit and gnomish ingenuity. It centers around a roaring public forge and the Thunderbrew Distillery, renowned across the eastern mountains for producing some of the finest ale in Khaz Modan. Between bustling crafters and weary travelers seeking warmth, the town stands as the essential staging ground for business in the lower peaks.",sp=0},{t="Guarding the Lowlands",b="Behind its cozy hearths, Kharanos serves as a vital military outpost tasked with keeping the mountain passes secure. Fierce indigenous wendigo prowl the frozen caverns directly to the west, while aggressive Frostmane trolls remain entrenched atop Shimmer Ridge to the northwest. With Ironforge's regular forces stretched thin across the realm, the town relies heavily on visiting adventurers and local watchmen to drive back raiding parties, cull dangerous predators, and ensure the trade routes remain open.",sp=0}},faq={{q="What is Kharanos?",a="Kharanos is the primary dwarf and gnome settlement in central Dun Morogh. It acts as a crossroads connecting Coldridge Valley, Ironforge, and the outer wilderness, featuring essential trade, training services, and an inn.",al={"kharanos overview","where is kharanos","kharanos town"},it="place"},{q="What services and facilities are in Kharanos?",a="The town features the famous Thunderbrew Distillery, which serves as an inn and taproom, as well as a large public forge and class and profession trainers. Nearby workshops like Steelgrill's Depot provide mechanized engineering supplies.",al={"kharanos trainers","what is in kharanos","kharanos inn"},gp=true},{q="What threats endanger the town?",a="Kharanos faces constant pressure from aggressive Frostmane troll tribes entrenched on Shimmer Ridge to the northwest, as well as predatory wendigo roaming the icy caves directly to the west.",al={"kharanos enemies","frostmane trolls kharanos","wendigo kharanos"},it="threat"},{q="Who lives in Kharanos?",a="Kharanos is a bustling settlement inhabited primarily by Bronzebeard dwarves alongside gnomish refugees and engineers. Craftspeople, smiths, distillers, and military recruits mingle here, patronizing the local forge, gnomish workshops, and the famous Thunderbrew Distillery. While no single lord governs it openly, it operates as a vital local hub and garrison for Ironforge's forces in Dun Morogh.",al={"who lives here kharanos","who runs kharanos","kharanos residents"},it="residents",add="2ba82cf7"},{q="Is Kharanos dangerous?",a="The town itself is heavily guarded and safe behind dwarf patrols, but the surrounding wilderness poses constant danger. Savage wendigo prowl caverns directly to the west, while hostile Frostmane trolls hold fortified positions atop Shimmer Ridge to the northwest. The town stays on high alert, regularly dispatching recruits to keep Dun Morogh's predators and encroaching trolls at bay.",al={"is kharanos safe","kharanos danger","threats in kharanos"},it="danger",add="d56d3e20"}},ang={["race:Dwarf"]="For dwarves leaving the sheltered crags of Coldridge Valley, Kharanos is the first taste of the wider kingdom, filled with steaming forges and the legendary stout of the Thunderbrew clan.",["race:Gnome"]="Refugees and tinkerers from Gnomeregan frequently base themselves in and around Kharanos, collaborating with local smiths and operating out of nearby depots."},kw={"distillery","dun morogh","frostmane","kharanos","shimmer ridge","thunderbrew"},rel={"zone:dunmorogh","subzone:thunderbrew-distillery","zone:ironforge","subzone:anvilmar","subzone:shimmer-ridge","subzone:steelgrill-s-depot","subzone:gol-bolar-quarry","topic:dwarf"},src={"Kharanos"}}
E["subzone:misty-pine-refuge"] = {t="subzone",n="Misty Pine Refuge",z="dunmorogh",s="Misty Pine Refuge is a small outpost building of the Argent Dawn tucked amidst the frigid snows of central Dun Morogh.",h="Misty Pine Refuge is a small outpost building of the Argent Dawn tucked amidst the frigid snows of central...",sec={{t="Shelter in the Snow",b="Situated amid the windswept hills of Dun Morogh, Misty Pine Refuge is an unassuming outpost of the Argent Dawn in the dwarven realm. While the surrounding crags are patrolled by Ironforge mountaineers, the refuge is home to Father Gavin, the order's lone agent here, who offers a quiet hearth amid the bitter elements and the perils that threaten the mountain roads.",sp=0}},faq={{q="What is Misty Pine Refuge?",a="It is an outpost building of the Argent Dawn in central Dun Morogh, kept by a single agent of the order, Father Gavin.",al={"what is this place","misty pine","misty pine refuge overview"},it="place"},{q="Why is the Argent Dawn here in Dun Morogh?",a="While the Argent Dawn focuses primarily on the undead menace in the north, agents like Father Gavin keep watch from quieter corners of the Alliance's lands as well.",al={"why argent dawn here","father gavin argent dawn","argent dawn dwarf lands"},it="purpose"},{q="Who stays at the refuge?",a="Father Gavin, an agent of the Argent Dawn, is the only member of the order stationed at the refuge.",al={"who is at misty pine","misty pine npcs"},it="residents"},{q="Is Misty Pine Refuge dangerous?",a="No, the refuge itself is a safe haven amidst the cold wilderness of Dun Morogh. It is an outpost of the Argent Dawn under the watchful eye of Father Gavin, though the snowy wilds surrounding it still carry the usual perils of prowling beasts and troggs.",al={"is misty pine refuge safe","misty pine refuge danger","threats at misty pine refuge"},it="danger",add="f4fbb46a"}},ang={["class:Priest"]="Father Gavin's humble post demonstrates that the Light's service often lies in quiet vigilance far from the battlefields."},kw={"argent dawn","dun morogh","father gavin","misty pine refuge"},rel={"zone:dunmorogh","topic:argent-dawn","topic:dwarf"},src={"Misty Pine Refuge"}}
E["subzone:north-gate-outpost"] = {t="subzone",n="North Gate Outpost",z="dunmorogh",s="North Gate Outpost is a fortified dwarven camp situated high in the North Gate Pass of Dun Morogh. Manning the rugged route between Ironforge's snowy heartland and Loch Modan, its mountaineers guard travelers against the hostile wildlife that infests the crags.",h="North Gate Outpost is a fortified dwarven camp situated high in the North Gate Pass of Dun Morogh.",sec={{t="Guards of the Pass",b="Positioned in the middle of North Gate Pass, this small settlement serves as the northeastern threshold of Dun Morogh. Dwarven mountaineers stationed here keep the main roadway cleared of prowling beasts and monitor traffic heading through the mountain tunnels into Loch Modan. The harsh climate and steep ravines make patrol duty treacherous, and the garrison frequently calls upon travelers to scout the surrounding ridges for missing patrols and dangerous predators.",sp=0}},faq={{q="What is North Gate Outpost used for?",a="It serves as a mountain military checkpoint that secures North Gate Pass, the northern roadway connecting Dun Morogh to Loch Modan. Mountaineers stationed here keep the pass open to trade and travel by curbing wild beast populations.",al={"north gate outpost purpose","why is north gate outpost here"},it="purpose"},{q="Where does the road through the pass lead?",a="Traveling east through the mountain tunnels beyond the outpost leads into the temperate valley of Loch Modan, while heading west leads back down toward Kharanos and Ironforge.",al={"where does north gate pass go","road past north gate outpost"}},{q="Why do the mountaineers need help from travelers?",a="The local wildlife along the snowy cliffs is fiercely territorial. Several mountaineers have gone missing into the crags while hunting dangerous beasts, forcing the garrison to enlist capable scouts to discover their fates.",al={"north gate outpost quests","missing mountaineers"},it="threat"},{q="What is North Gate Outpost?",a="North Gate Outpost is the northeasternmost dwarven settlement in Dun Morogh. Nestled high in North Gate Pass, it sits along the vital mountain roadway that connects Dun Morogh in the west to the valley of Loch Modan to the east, serving as a fortified checkpoint for travelers and supply caravans.",al={"what is north gate outpost","north gate outpost lore","tell me about north gate outpost"},it="place",add="c46f381d"},{q="Who lives in or runs North Gate Outpost?",a="The outpost is manned by dwarven mountaineers tasked with patrolling the high pass and safeguarding travel between Dun Morogh and Loch Modan. They maintain a watchful eye over the icy road, though harsh weather and aggressive beasts keep their small garrison stretched thin.",al={"who is at north gate outpost","who runs north gate outpost","north gate outpost residents"},it="residents",add="650c30dc"},{q="Is North Gate Outpost dangerous?",a="While the outpost itself offers shelter, the surrounding pass is perilous. Encroaching mountain predators frequently threaten the perimeter, and several mountaineers have recently gone missing in the snows while tracking down particularly ferocious beasts that stalk the crags.",al={"is north gate pass dangerous","dangers near north gate outpost","threats north gate outpost"},it="danger",add="5e6548b7"},{q="Why is it called North Gate Outpost?",a="The outpost takes its name from North Gate Pass, the northern mountain corridor it guards. Positioned directly in the middle of this transit route, it serves as the northern gateway connecting Dun Morogh to Loch Modan.",al={"why north gate outpost","north gate outpost name","how did north gate outpost get its name"},it="name",add="aaf153dc"}},ang={["race:Dwarf"]="The outpost showcases the stoic duty of Ironforge's Mountaineers, who hold the harsh highland passes open regardless of freezing weather or prowling predators.",["race:Gnome"]="Having resettled across Dun Morogh, gnomes often lend their wits and marksmanship to assist the dwarven garrison in tracking down lost patrols."},kw={"dun morogh","ironforge","loch modan","mountaineers","north gate outpost","north gate pass"},rel={"subzone:north-gate-pass","zone:dunmorogh","zone:lochmodan","topic:gnome"},src={"North Gate Outpost"}}
E["subzone:shimmer-ridge"] = {t="subzone",n="Shimmer Ridge",z="dunmorogh",s="Shimmer Ridge is a rugged highland nestled in northern Dun Morogh, directly west of the Gates of Ironforge. Occupied by hostile Frostmane trolls, the rocky heights consist of two camps joined by a rickety bridge and are renowned as the sole harvesting ground for potent shimmerweed.",h="Shimmer Ridge is a rugged highland nestled in northern Dun Morogh, directly west of the Gates of Ironforge.",sec={{t="A Frostmane Stronghold",b="Perched along the craggy slopes just west of Ironforge's mighty entryway, Shimmer Ridge serves as an active redoubt for the Frostmane troll tribe. Divided into twin camps straddling a chasm and linked by a wooden span, the enclave is heavily guarded by troll scavengers and their tamed mountain boars. Their proximity to the main roadway and the dwarven capital poses a continuous nuisance to travelers and mountain patrols, who must constantly remain on guard against opportunistic raids from the high ground.",sp=0},{t="The Price of Shimmerweed",b="Aside from strategic positioning, the ridge is famous for cultivating shimmerweed, a plant grown by the Frostmane trolls. Prized by local dwarven brewmasters for crafting potent, flavorful highland ales, the herb cannot easily be gathered elsewhere. Daring mountaineers and young recruits frequently risk Frostmane ambushes and savage tusked beasts simply to harvest fresh baskets of the precious botanical directly from the trolls' plots.",sp=0}},faq={{q="Where is Shimmer Ridge located?",a="Shimmer Ridge is situated in northern Dun Morogh, directly to the west of the massive Gates of Ironforge that lead into the dwarven capital.",al={"shimmer ridge location","where is shimmer ridge","find shimmer ridge"},it="place",gp=true},{q="Who controls Shimmer Ridge?",a="The ridge is occupied by the indigenous Frostmane troll tribe, who have established dual camps connected by a bridge and defend the heights alongside their tamed boars.",al={"who lives at shimmer ridge","shimmer ridge enemies","trolls at shimmer ridge"},it="residents"},{q="What is shimmerweed and why is it sought after?",a="Shimmerweed is a distinct mountain herb that thrives on the cold slopes of the ridge. Local dwarven brewers value it immensely as an essential ingredient for specialized, flavorful recipes of highland ale.",al={"shimmerweed use","what is shimmerweed","shimmer weed purpose"},it="item"},{q="Why don't the dwarves clear out the trolls completely?",a="Ironforge's military is occupied with broader defense and external matters, leaving local threats like the Frostmane enclaves in Dun Morogh to be managed by regional mountaineers and wandering recruits.",al={"why ironforge ignores shimmer ridge","ironforge vs frostmane","dwarf response shimmer ridge"},it="conflict"},{q="What is Shimmer Ridge?",a="Shimmer Ridge is a rugged highland nestled in northern Dun Morogh, situated just west of the massive Gates of Ironforge. It is a hostile territory dominated by Frostmane trolls, who have carved out two distinct encampments across the heights, connected by a wooden bridge. In addition to harboring troll warbands and their tamed boars, the ridge is famous for producing shimmerweed, a potent local plant prize by nearby dwarven brewers.",al={"what is shimmer ridge","shimmer ridge overview","tell me about shimmer ridge"},it="place",add="0fc03156"},{q="Is Shimmer Ridge dangerous?",a="Yes, it is quite hazardous for unseasoned travelers. The Frostmane trolls living across the ridge are intensely hostile to outsiders and vigorously guard their camps and shimmerweed patches. Between aggressive troll defenders and the wild boars they keep and tame, anyone venturing up the heights without caution risks being quickly overwhelmed by local warbands.",al={"is shimmer ridge safe","shimmer ridge dangers","how dangerous is shimmer ridge"},it="danger",add="aaffe09f"},{q="Why is it called Shimmer Ridge?",a="The origin of the name is unknown. The ridge is known for shimmerweed, which the Frostmane trolls grow and dwarven brewers seek for ale.",al={"shimmer ridge name origin","why is it named shimmer ridge","where does the name shimmer ridge come from"},it="name",add="e59eca35"}},ang={["race:Dwarf"]="Nestled in the shadow of Ironforge's gates, Shimmer Ridge is an irritating reminder of the persistent Frostmane threat and the dangerous source of choice shimmerweed for legendary dwarven stout.",["profession:Herbalism"]="While ordinary flora struggles in Dun Morogh's sub-zero climate, Shimmer Ridge uniquely supports valuable shimmerweed baskets tended among the Frostmane camps."},kw={"dun morogh","frostmane","ironforge","mountaineers","shimmer ridge","shimmerweed","trolls"},rel={"zone:dunmorogh","subzone:gates-of-ironforge","zone:ironforge","topic:troll"},src={"Shimmer Ridge"}}
E["subzone:south-gate-outpost"] = {t="subzone",n="South Gate Outpost",z="dunmorogh",s="South Gate Outpost is a fortified dwarven mountain post situated along the South Gate Pass between Dun Morogh and Loch Modan. Manning the snowy southern road, its mountaineers guard the steady flow of travelers walking between Ironforge's frigid heights and the temperate valley of the Loch.",h="South Gate Outpost is a fortified dwarven mountain post situated along the South Gate Pass between Dun Morogh...",sec={{t="Watchers of the Southern Road",b="Perched midway through the high mountain cut of South Gate Pass, South Gate Outpost marks the frontier between the snowy slopes of Dun Morogh and the verdant basin of Loch Modan. Stationed here are Ironforge mountaineers tasked with patrolling the rocky switchbacks and keeping dangerous wildlife off the main highway. Compared to their hard-pressed kin up at North Gate Outpost, the defenders here have largely secured their stretch of road, allowing travelers, pilgrims, and trade wagons headed toward Thelsamar to journey in relative safety.",sp=0}},faq={{q="What is the purpose of South Gate Outpost?",a="It serves as a fortified border checkpoint and garrison along South Gate Pass. Mountaineers stationed here keep the snowy transit road clear of mountain beasts and hostile interlopers traveling between Dun Morogh and Loch Modan.",al={"why is south gate outpost here","south gate outpost purpose","what is south gate outpost"},it="purpose"},{q="Why is it so much calmer here than at North Gate Outpost?",a="The garrison at South Gate Outpost has successfully culled the aggressive wildlife immediately bordering the road. North Gate Outpost, by contrast, contends with heavier incursions and wilder mountain terrain, leaving the southern pass comparatively calm.",al={"difference between north gate and south gate","is south gate safe","south gate vs north gate"}},{q="Where does the road through South Gate Outpost lead?",a="Heading westward up the pass brings you into the snowy highlands of Dun Morogh toward Ironforge. Traveling eastward downhill leads directly out into the temperate valley of Loch Modan, with the road winding straight toward the settlement of Thelsamar.",al={"where does this road go","south gate road destination","south gate pass path"}},{q="What is South Gate Outpost?",a="South Gate Outpost is a fortified dwarven mountain waystation nestled along South Gate Pass in eastern Dun Morogh. It sits directly on the snowy high pass connecting Dun Morogh to the wider valley, welcoming travelers and couriers journeying east toward Thelsamar.",al={"what is south gate outpost","south gate outpost info","south gate pass outpost"},it="place",add="3c6e6693"},{q="Who lives in or runs South Gate Outpost?",a="Ironforge mountaineers man this remote border station. They keep watch over travelers traversing the pass, manage supplies, and coordinate closely with local patrolmen to ensure secure transit through the mountain corridors between Dun Morogh and Loch Modan.",al={"who controls south gate outpost","who runs south gate outpost","who lives at south gate outpost"},it="residents",add="790564b9"},{q="Is South Gate Outpost dangerous?",a="The outpost itself is quite safe. The stationed mountaineers have diligently cleared out most of the encroaching mountain wildlife along the pass, sparing this station from the violent creature attacks and harsh pressures facing North Gate Outpost.",al={"is south gate safe","is south gate outpost dangerous","danger south gate outpost"},it="danger",add="94f233ba"},{q="Why is it called South Gate Outpost?",a="It takes its name from South Gate Pass, the southern mountain gap carved through the crags between Dun Morogh and Loch Modan, as opposed to the northern crossing defended by North Gate Outpost.",al={"why is it called south gate outpost","south gate outpost name origin","why south gate"},it="name",add="09ad7c8c"}},ang={["race:Dwarf"]="For dwarves leaving Coldridge Valley and Dun Morogh for the first time, South Gate Outpost is the final chilly landmark before descending into the vibrant, sunlit lands of Loch Modan.",["faction:Alliance"]="The outpost serves as a dependable military shelter along one of Khaz Modan's primary domestic supply lines, keeping the passage between the capital and eastern settlements open."},kw={"dun morogh","dwarf","ironforge road","loch modan","mountaineers","south gate outpost","south gate pass","thelsamar"},rel={"subzone:south-gate-pass","zone:lochmodan","zone:dunmorogh","subzone:thelsamar","subzone:north-gate-outpost","subzone:the-loch"},src={"South Gate Outpost"}}
E["subzone:steelgrill-s-depot"] = {t="subzone",n="Steelgrill's Depot",z="dunmorogh",s="Steelgrill's Depot is a bustling engineering workshop and repair station situated directly east of Kharanos in Dun Morogh. Overseen by Beldin Steelgrill and a crew of craftsmen, it serves as a frontline hub for vehicle maintenance, tinker supply runs, and salvage efforts.",h="Steelgrill's Depot is a bustling engineering workshop and repair station situated directly east of Kharanos...",sec={{t="A Bastion of Steam and Steel",b="Nestled just off the snowy road east of Kharanos, Steelgrill's Depot buzzes with the clamor of clanking metal, hissing steam vents, and the hum of experimental engines. Dwarven miners and eccentric gnome engineers gather here amid heavy machinery, mechanized walking frames, and stockpiles of raw ores hauled out from nearby quarries. With Dun Morogh facing relentless trogg disruptions and mechanical supply shortages, Beldin Steelgrill and his crew keep Alliance machinery in working order, serving as an indispensable stop for travelers seeking spare parts or technical guidance in the bitter cold.",sp=0}},faq={{q="What is Steelgrill's Depot?",a="Steelgrill's Depot is an engineering workshop and outpost in Dun Morogh, located just down the road east of Kharanos. It caters to miners, tinkerers, and field technicians maintaining heavy machinery.",al={"steelgrill depot","what is this place","steelgrills"},it="place"},{q="Who runs the depot?",a="The depot is managed by the Steelgrill family, notably Beldin Steelgrill, alongside fellow dwarven and gnomish crafters who maintain the surrounding machinery and oversee mining operations.",al={"who leads steelgrills","who runs steelgrill depot","belbi steelgrill"},it="residents"},{q="What services are available here?",a="The depot houses trade suppliers, repair services, and trainers for craftsmen looking to hone their engineering and gathering skills out in the field.",al={"trainers at steelgrills","what can i do here","steelgrills depot services"},gp=true},{q="Is Steelgrill's Depot dangerous?",a="Not directly. Steelgrill's Depot is a secure dwarven work camp and trade stop nestled safely along the snowy road east of Kharanos. While the surrounding crags and hills crawl with wild beasts, roaming troggs, and pesky leper gnomes fleeing the fall of Gnomeregan, the depot itself remains firmly in Alliance hands, guarded by hearty miners, craftworkers, and nearby mountaineers.",al={"is steelgrills depot dangerous","steelgrills depot danger","is it safe at steelgrills depot"},it="danger",add="01d49f70"},{q="Why is it called Steelgrill's Depot?",a="The outpost takes its name from Beldin Steelgrill, the master engineer and entrepreneur overseeing operations here. Beldin and his fellow artisans established this wayside camp to service, assemble, and test dwarven and gnomish mechanical marvels, siege machinery, and mining gear just outside the busy settlement of Kharanos.",al={"why steelgrills depot","who is steelgrill","steelgrill name origin"},it="name",add="14c76990"}},ang={["profession:Engineering"]="The depot is an open-air laboratory surrounded by steam machinery and tinkering supplies, making it a natural rest stop for aspiring engineers traveling through Dun Morogh.",["race:Gnome"]="Working closely with their dwarven hosts, exiled gnomish tinkers often use the depot's forge fires and spare components to keep their salvaged contraptions running."},kw={"belbi steelgrill","dun morogh","engineering","kharanos","steelgrill","steelgrill's depot","workshop"},rel={"subzone:kharanos","zone:dunmorogh","topic:gnome","zone:gnomeregan"},src={"Steelgrill's Depot"}}
E["subzone:thunderbrew-distillery"] = {t="subzone",n="Thunderbrew Distillery",z="dunmorogh",s="Thunderbrew Distillery serves as the bustling tavern and central gathering place of Kharanos in Dun Morogh. Renowned far and wide for its potent ales, it functions as both an active brewhouse and an essential rest stop for travelers passing through the snowy mountain passes. Inside, patrons find warm hearths, cold pints, and a wide array of class mentors and local tradesfolk.",h="Thunderbrew Distillery serves as the bustling tavern and central gathering place of Kharanos in Dun Morogh.",sec={{t="The Warm Hearth of Kharanos",b="Perched in the center of Kharanos, the Thunderbrew Distillery is the heart of civic life in southern Dun Morogh. Founded by the Thunderbrew clan—established by Arkilus Thunderbrew and maintained by his kin—the brewhouse is famous across Khaz Modan for producing robust, warming ales built to ward off the biting mountain chill. It operates as the local inn, managed on the floor by Innkeeper Belm, offering weary mountaineers a roaring fire, hearty fare, and beds to escape the blizzards outside.",sp=0},{t="A Crossroads of Knowledge and Craft",b="Beyond pouring renowned stouts, the distillery doubles as a vital hub for developing adventurers. Because Kharanos is the first major settlement travelers reach after departing Coldridge Valley, the Thunderbrew tavern plays host to diverse trainers. Mentors in martial arts, holy rites, arcane studies, and roguecraft congregate under its sturdy timber rafters alongside instructors in cooking and emergency medical aid, turning a boisterous drinking hall into an indispensable preparation post.",sp=0}},faq={{q="Who owns and operates the Thunderbrew Distillery?",a="The establishment belongs to the Thunderbrew family, founded by Arkilus Thunderbrew. His son Ragnar Thunderbrew actively looks after the family brewing traditions, while Innkeeper Belm handles hospitality and rooms for travelers resting in Kharanos.",al={"distillery owner","who runs thunderbrew","thunderbrew family"},it="residents"},{q="What services are available inside the distillery?",a="The distillery serves as the primary inn of Kharanos. Inside, travelers can bind their hearthstones with Innkeeper Belm, purchase drinks and supplies from vendors, and seek instruction from trainers for warriors, paladins, priests, mages, rogues, cooking, and first aid.",al={"what is in thunderbrew distillery","distillery trainers","kharanos inn services"},gp=true},{q="Why is the distillery so famous?",a="The distillery is celebrated throughout the Eastern Kingdoms for crafting exceptionally potent dwarven ales, particularly Thunderbrew Ale. Its brews are known to fortify travelers against the harsh freezing temperatures of the Dun Morogh peaks.",al={"why is thunderbrew ale famous","thunderbrew ale reputation"},it="fame"},{q="What is the Thunderbrew Distillery?",a="The Thunderbrew Distillery is a bustling dwarven tavern and inn standing at the heart of Kharanos. Beyond offering warm beds, hearthstones, and hearty drinks, it serves as the community's primary gathering place where mountaineers, craftsmen, class mentors, and travelers rest and share news from across Dun Morogh.",al={"what is thunderbrew distillery","thunderbrew tavern","distillery in kharanos"},it="place",add="1fa2ba89"},{q="What is the history of the Thunderbrew Distillery?",a="Founded by the dwarven brewer Arkilus Thunderbrew, the distillery has stood for generations as one of Dun Morogh's finest breweries. Today, it remains family-run under his son Ragnar and continues crafting its famed ales.",al={"distillery history","history of thunderbrew distillery","who founded thunderbrew distillery"},it="history",add="6c9338b8"},{q="Is the Thunderbrew Distillery dangerous?",a="Not at all. The distillery is a safe haven for travelers and Alliance defenders, well protected by mountaineers and town guards from the troggs, frost trolls, and hungry beasts wandering the snowy hills outside Kharanos.",al={"is thunderbrew distillery dangerous","distillery safe","is it safe here"},it="danger",add="ec3a2fd6"},{q="Why is it called the Thunderbrew Distillery?",a="The distillery takes its name from the Thunderbrew family, who founded and maintained the business across generations, as well as the potent dwarven ales they brew inside its cellars.",al={"why is it named thunderbrew distillery","origin of thunderbrew name","thunderbrew distillery name"},it="name",add="1194a384"}},ang={["race:Dwarf"]="For dwarves leaving Coldridge Valley, the distillery is a beloved homecoming, providing familiar stout, a seat near a blazing hearth, and trusted mentors in iron and faith.",["profession:Cooking"]="The kitchen inside the distillery offers culinary training and supplies, making it a key stop for cooks looking to learn how to prepare hearty mountain provisions."},kw={"dun morogh","dwarven ale","innkeeper belm","kharanos","ragnar thunderbrew","thunderbrew distillery"},rel={"subzone:kharanos","npc:ragnar-thunderbrew","zone:dunmorogh","npc:marleth-barleybrew","quest:117"},src={"Thunderbrew Distillery"}}
E["subzone:tundrid-hills"] = {t="subzone",n="Tundrid Hills",z="dunmorogh",s="The Tundrid Hills are a rugged, snowbound stretch of highland in south-central Dun Morogh, lying just west of the Gol'Bolar Quarry. Inhabited by dangerous mountain wildlife, the rocky passes are rarely traversed by casual travelers.",h="The Tundrid Hills are a rugged, snowbound stretch of highland in south-central Dun Morogh, lying just west of...",sec={{t="A Treacherous Wilderness",b="Stretching between Coldridge Valley and the lowlands of eastern Dun Morogh, the Tundrid Hills offer a rugged cross-country route for those looking to bypass the main roads through Kharanos. However, convenience comes at a steep price. The jagged snowy slopes are prowled by ferocious predators, making the territory perilous for unwary travelers who venture off the beaten path without a drawn weapon.",sp=0}},faq={{q="Where are the Tundrid Hills located?",a="The Tundrid Hills span the south-central portion of Dun Morogh, positioned west of the Gol'Bolar Quarry and forming a natural, elevated boundary south of the main road connecting Kharanos to eastern lands.",al={"tundrid hills location","where is tundrid hills","tundrid hills map"},it="place"},{q="Why would anyone travel through the Tundrid Hills?",a="Adventurers sometimes navigate these harsh ridges as an overland shortcut between Coldridge Valley and eastern Dun Morogh, bypassing the established settlement routes, though it is far more hazardous than sticking to the patrolled roads.",al={"why go to tundrid hills","tundrid hills shortcut"},it="purpose"},{q="What threats can be found in the Tundrid Hills?",a="The hills are home to fierce native wildlife accustomed to the freezing heights, and few travel here without a weapon at hand.",al={"what lives here","tundrid hills enemies","monsters in tundrid hills"},it="threat"},{q="Is traveling through the Tundrid Hills dangerous?",a="Yes, traversing these snowy hills is considerably more hazardous than sticking to the patrolled roads. The heights are populated by fierce, predatory wildlife and offer no organized dwarven guard patrols or shelter. While it provides a direct shortcut between Coldridge Valley and eastern Dun Morogh, few travelers venture off the beaten path without a ready weapon and a watchful eye.",al={"are the tundrid hills dangerous","tundrid hills danger","is it safe in tundrid hills"},it="danger",add="6d54f98b"}},ang={["race:Dwarf"]="For mountaineers of Ironforge, these heights serve as an ever-present reminder that wilderness and hostile Frostmane trolls press close against Dun Morogh's heartland.",["class:Hunter"]="The wind-battered crags provide rugged tracking grounds filled with hardy beasts adapted to Dun Morogh's punishing mountain chill."},kw={"coldridge valley","dun morogh","frostmane","gol'bolar quarry","ironforge","kharanos","tundrid hills"},rel={"zone:dunmorogh","subzone:gol-bolar-quarry","subzone:coldridge-valley","subzone:kharanos","topic:troll"},src={"Tundrid Hills"}}
E["topic:frostmane-tribe"] = {t="topic",n="Frostmane tribe",z="dunmorogh",s="The Frostmane tribe consists of fierce ice trolls indigenous to the frigid peaks of Dun Morogh. Driven into caves and remote ridges by the dwarves of Ironforge centuries ago, they wage an unrelenting guerrilla war to reclaim their ancestral home.",h="The Frostmane tribe consists of fierce ice trolls indigenous to the frigid peaks of Dun Morogh.",sec={{t="Exiles of the High Crags",b="Long before the Bronzebeard clan united under Ironforge, the Frostmane trolls held dominion across the snowbound expanses of Dun Morogh. The rise and expansion of the dwarven kingdom crushed their realm, pushing the surviving ice trolls into retreat along the frozen ridges and crags. This humiliating defeat sparked a bitter generational hatred that endures to this day. The Frostmane treat every mountaineer, traveler, and homestead as an invading enemy to be driven out or slaughtered.",sp=0},{t="A Seized Opportunity",b="For decades, the Ironforge Senate regarded the Frostmane as little more than a persistent nuisance lurking in the hills. However, the sudden emergence of the trogg menace deep beneath Dun Morogh has thrown dwarven defense into disarray. Sensing an opportune moment while the mountaineers are overwhelmed and dwarven forces fight Alliance wars abroad, the Frostmane have launched renewed and violent raids from strongholds such as Frostmane Hold and Shimmer Ridge to retake their ancient territories.",sp=0},{t="Raiders of the Valleys",b="The Senate of Ironforge eventually took note of the growing threat and sent Grelin Whitebeard and his brother Senir to deal with it. From the caves of Frostmane Hold and the heights of Shimmer Ridge, the trolls strike at the dwarves, and in Coldridge Valley war leaders like Grik'nir the Cold direct aggressive incursions against the mountaineers.",sp=1}},faq={{q="Who are the Frostmane trolls?",a="They are a tribe of ice trolls native to the snowy crags of Dun Morogh. Centuries ago, they ruled the region before dwarven armies defeated them and forced them into the high ridges.",al={"frostmane lore","what are frostmane","dun morogh trolls"},it="identity"},{q="Why are the Frostmane attacking the dwarves now?",a="With dwarven mountaineers strained by trogg invasions and military commitments across the Alliance, the Frostmane see an opening to reclaim their ancestral hunting grounds and take revenge on Ironforge.",al={"why do frostmane attack","frostmane uprising","troll attacks dun morogh"},it="hostile"},{q="Who leads the Frostmane tribe?",a="The tribe raids from Frostmane Hold and Shimmer Ridge, and its war bands are led by aggressive figures like Grik'nir the Cold, who harries the dwarves of Coldridge Valley.",al={"frostmane leader","chief of frostmane","who runs the frostmane"},it="leader"},{q="What happened to Frostmane Hold?",a="Frostmane Hold remains the tribe's stronghold, a troll-held cave in the hills of Dun Morogh from which the Frostmane launch their raids. The Senate of Ironforge sent Grelin Whitebeard and his brother Senir to deal with the threat.",al={"frostmane hold troggs","what happened to troll cave","why did trolls leave hold"},it="place"},{q="What is Shimmerweed, and why do the trolls gather it?",a="Shimmerweed is a resilient plant growing in the bitter winds of Shimmer Ridge. The Frostmane cultivate and harvest it for their sacred tribal rituals, though dwarven brewers prize it as an ingredient for potent stout.",al={"shimmerweed","frostmane shimmerweed","what is shimmerweed used for"},it="item"},{q="Are the Frostmane aligned with the Horde?",a="No. The Frostmane are independent ice trolls who bear virulent hatred toward all outsiders, attacking travelers and explorers regardless of faction.",al={"are frostmane horde","frostmane faction","frostmane friendly to horde"},it="allies"},{q="Why are the Frostmane trolls in Dun Morogh?",a="The Frostmane view the snowy peaks of Dun Morogh as their ancestral homeland. Long before Ironforge rose to power, their forebears ruled these mountains until dwarven armies broke their empire and forced them into the frigid hills. Today, scattered camps like Frostmane Hovel and Shimmer Ridge serve as bases for their ongoing guerrilla war to reclaim their lost territory from the dwarves.",al={"why are frostmane in dun morogh","why are trolls in dun morogh","frostmane dun morogh why"},it="why_here",add="a2fffb42"},{q="What is the history of the Frostmane tribe?",a="The Frostmane trace their lineage back to the Drakkari Empire of Northrend. Following the Great Sundering, both the Frostmane and Winterax branches split away and migrated into the Eastern Kingdoms. The Frostmane established dominion over the snowy crags of Dun Morogh, only to be defeated and displaced by the dwarves centuries later. Reduced to living in remote caves and camps, they have waged a persistent war against Ironforge ever since.",al={"frostmane history","where did frostmane trolls come from","frostmane origins","frostmane lore"},it="history",add="07db22cc"}},ang={["race:Dwarf"]="For dwarves, the Frostmane are a constant reminder of ancestral blood feuds. Queen Eimear herself fell to an ambush by Frostmane trolls, making the mountaineers' defense of Dun Morogh deeply personal.",["race:Troll"]="While Darkspear trolls share the broad heritage of trollkind, the isolated Frostmane are savage ice trolls with little interest in kinship, treating Horde visitors as intruders on their sacred peaks.",["profession:Cooking"]="The crag boars and beasts kept around Frostmane encampments provide rough game meat for hearthside rations amidst Dun Morogh's biting snows."},kw={"battok","coldridge valley","dun morogh","frostmane","frostmane hold","grik'nir","ice troll","shimmer ridge"},rel={"zone:dunmorogh","subzone:coldridge-valley","quest:182","quest:287","subzone:shimmer-ridge","subzone:frostmane-hovel","topic:trogg","npc:grelin-whitebeard"},src={"Frostmane tribe"}}
E["zone:dunmorogh"] = {t="zone",n="Dun Morogh",z="dunmorogh",s="Dun Morogh is a snow-swept mountain highland situated at the heart of Khaz Modan. It serves as the ancestral starting ground and shared homeland for the dwarves of Ironforge and the displaced gnomes of Gnomeregan. Though guarded by towering peaks and fortified passes, the snowy realm faces rising internal threats from troggs, Frostmane trolls, and irradiated leper gnomes.",h="Dun Morogh is a snow-swept mountain highland situated at the heart of Khaz Modan.",sec={{t="A Mountain Stronghold",b="Dun Morogh occupies the highest peaks in the Eastern Kingdoms, an alpine expanse ringed by jagged summits that shield it from Searing Gorge to the south and the Wetlands to the north. These snowy mountains feed the rivers flowing across Khaz Modan and provide near-limitless veins of copper and iron. Access is heavily restricted to mountain tunnels like North Gate Pass and South Gate Pass, watched closely by dwarven Mountaineers. At the heart of the region sits Ironforge, an ancient subterranean wonder and the capital of King Magni Bronzebeard's realm, linked straight to Stormwind by the marvel of the Deeprun Tram.",sp=0},{t="A Refuge Divided",b="Centuries ago, the dwarves drove the native Frostmane ice trolls into the crags, carving out room for themselves alongside their brilliant gnome allies. The two races flourished in neighboring mountain halls until the recent catastrophe in Gnomeregan during the Third War. A horrific trogg invasion and a catastrophic radioactive venting ruined the technological wonder, turning its defenders into mindless leper gnomes and driving High Tinker Gelbin Mekkatorque and his surviving folk into exile. Now, the gnomes dwell as guests inside Ironforge, while leper gnomes and surviving troggs spill out into Chill Breeze Valley.",sp=0},{t="Trouble in the Drifts",b="Life in the drifts is far from quiet. The Frostmane tribe has grown emboldened, establishing heavily armed encampments from Shimmer Ridge down to Coldridge Valley. Meanwhile, primitive troggs have clawed their way out of ancient subterranean fissures into Gol'Bolar Quarry, threatening the region's mining operations. Between prowling wendigos, wild boars, infiltrating Dark Iron dwarven agents, and toxic fallout spreading from the ruins of Gnomeregan, the dwarven Mountaineers are stretched thin maintaining order from Kharanos to the border gates.",sp=0}},faq={{q="What races start in Dun Morogh?",a="Both dwarves and gnomes begin their journeys here in Coldridge Valley, a sheltered basin in southwestern Dun Morogh, before venturing out through Coldridge Pass into Kharanos and the wider zone.",al={"dun morogh starting race","who starts here","dwarf start zone","gnome start zone"},it="residents",gp=true},{q="What happened to Gnomeregan?",a="During the Third War, a subterranean race called troggs swarmed Gnomeregan. In an attempt to purge the invaders, High Tinker Gelbin Mekkatorque released radioactive gas into the lower levels. The plan failed catastrophically, killing thousands and irradiating many gnomes into crazed leper gnomes, forcing the healthy survivors to flee to Ironforge.",al={"why is gnomeregan ruined","what happened to the gnomes","why are leper gnomes here"},it="ruin"},{q="How do you leave Dun Morogh on foot?",a="Dun Morogh is walled in by high mountain ridges. To travel eastward into Loch Modan on foot, take the roads leading to North Gate Pass or South Gate Pass in the northeastern mountains. You can also travel directly to Stormwind City via the Deeprun Tram inside Ironforge.",al={"exit dun morogh","dun morogh to loch modan","leave dun morogh"},gp=true},{q="Where is the flight master in Dun Morogh?",a="The only functional Alliance flight master in the zone is located inside the Great Forge of Ironforge, connecting travelers to locations across Khaz Modan, Stormwind, and the northern Alliance outposts.",al={"dun morogh flight master","dun morogh flight path","where to fly dun morogh"},it="place",gp=true},{q="Who are the Frostmane trolls?",a="The Frostmane are a tribe of ice trolls who ruled Dun Morogh long before the dwarves emerged from Uldaman. Though defeated and driven into the crags generations ago, they remain bitter enemies of Ironforge, routinely raiding dwarven farms and roads from retreats like Frostmane Hold.",al={"why are there trolls in dun morogh","dun morogh trolls","frostmane tribe"},it="threat"},{q="What is Kharanos?",a="Kharanos is the primary dwarven settlement in central Dun Morogh. It houses the Thunderbrew Distillery, trainers, and supplies, serving as the central operational hub for young adventurers and Mountaineers tackling local troll and wildlife problems.",al={"town in dun morogh","kharanos hub","what is the main town"},it="place"},{q="What is Dun Morogh?",a="Dun Morogh is a high, snowy mountain region in western Khaz Modan. Ringed on all sides by towering peaks, it forms the ancestral heartland of the Ironforge dwarves and the refuge of the gnomes. The realm is known for its bitter cold, dense pine forests, frozen lakes, and vast mineral wealth. It houses the magnificent mountain citadel of Ironforge along its northern ridges, as well as the besieged techno-city of Gnomeregan tucked away in the western hills.",al={"what is this place","where are we","dun morogh zone"},it="place",add="ee70a2d7",nx={8}},{q="What happened in Dun Morogh's past?",a="Dun Morogh was originally held by the Frostmane ice trolls. The dwarves and gnomes later settled these snowy peaks and forged a lasting kinship, building Ironforge and Gnomeregan while pushing the Frostmane back into the remote crags. During the Second War, dwarven and gnomish defenders successfully held their mountain fortresses against the orcish Horde. Today, the peaceful lands face unrest following the fall of Gnomeregan and rising trogg incursions.",al={"dun morogh history","history of dun morogh","what happened here"},it="history",add="8c7c9511"},{q="Who lives in and rules Dun Morogh?",a="Dun Morogh is governed primarily by King Magni Bronzebeard from his throne in the mountain fortress of Ironforge. The Bronzebeard dwarves maintain mountain garrisons, outposts, and watchtowers across the passes. Dun Morogh is also home to the gnomes, whose leader High Tinker Gelbin Mekkatorque and surviving populace currently shelter alongside their dwarven allies following the tragic loss of Gnomeregan. Beyond the settlements, Frostmane trolls and primitive troggs contest dwarven authority in the wild crags and quarries.",al={"who rules dun morogh","who controls dun morogh","who lives here"},it="in_charge",add="4399d516"},{q="Is Dun Morogh dangerous?",a="While the highways and towns are guarded by dwarven mountaineers, the wilderness presents serious peril. Savage wildlife like grizzly bears, mountain boars, starving wolves, and ferocious wendigos roam the snowbanks. Hostile Frostmane ice trolls mount raids from mountain ridges like Shimmer Ridge and Frostmane Hold. Meanwhile, subterranean troggs have overrun Gol'Bolar Quarry and Coldridge Pass, and radioactive leper gnomes prowl the contaminated outskirts of Gnomeregan.",al={"is dun morogh safe","dun morogh threats","dangers in dun morogh"},it="danger",add="1f8f2322"},{q="Why does everyone want me killing troggs at Gol'Bolar Quarry?",a="Gol'Bolar Quarry in southeastern Dun Morogh is a vital dwarven excavation and mining camp. While digging for stone and precious ore, the miners broke into subterranean tunnels and unearthed hordes of savage troggs. The creatures swarmed into the open pit and the quarry mine, driving back workers and shutting down operations. The mountaineers and overseers rely on able-bodied recruits to wipe out the infesting troggs so the kingdom can reclaim its quarry.",al={"gol bolar troggs","why kill troggs quarry","gol bolar quarry problem"},it="threat",add="6bfc0e90"},{q="Where should I head after Dun Morogh?",a="Once you have completed your tasks in Dun Morogh and reached sufficient experience, your journey naturally leads eastward into Loch Modan. You can pass on foot through either the North Gate Pass or South Gate Pass tunnels, or catch a gryphon ride from the great flight master's roost inside Ironforge directly to the lakeside village of Thelsamar.",al={"where do i go after dun morogh","dun morogh next zone","after dun morogh"},it="next_step",add="bf67ca5d"},{q="How did I end up in Dun Morogh?",a="If you are a dwarf or gnome beginning your journey, you started in the sheltered training grounds of Coldridge Valley before venturing out through the pass into Dun Morogh proper. Dwarves hail from these rugged peaks, while gnome refugees fled here after the fall of Gnomeregan to seek haven with their dwarven allies. Travelers from other kingdoms usually arrive through the grand gates of Ironforge via the Deeprun Tram from Stormwind, or by trekking westward through the mountain passes leading out of Loch Modan.",al={"how did i get here","how did i get to dun morogh","why did i come here"},it="arrival",add="44145090"},{q="What am I supposed to be doing in Dun Morogh?",a="The snowy realm of Ironforge needs every able defender. Hostile Frostmane trolls threaten dwarven settlements from the high ridges, savage troggs have overrun Gol'Bolar Quarry, and mutated leper gnomes prowl the contaminated ruins of Gnomeregan to the west. Local settlements like Kharanos and Brewnall Village desperately need recruits to drive back wild beasts and clear the trails. Lend your strength to secure the region, hone your skills, and prove yourself worthy to answer the broader call of the Alliance.",al={"what should i do here","what is my goal in dun morogh","what am i doing here"},it="purpose",add="8cf74af4"}},ang={["race:Dwarf"]="This is your ancestral homeland. From the hearthfires of Anvilmar to the blazing core of the Great Forge in Ironforge, defending these peaks from trolls and troggs is your duty to King Magni.",["race:Gnome"]="Your lost home, Gnomeregan, lies irradiated in the western valley. Dun Morogh serves as your base in exile alongside your dwarven cousins while you fight back against troggs and rogue leper gnomes.",["profession:Mining"]="The mountain crags of Dun Morogh are rich with surface deposits of Copper Veins, particularly around the quarry at Gol'Bolar and along the snowy rock faces.",["profession:Cooking"]="Local hunters and innkeepers in Kharanos and Brewnall Village make hearty use of boar meat, bear ribs, and dwarven stout to ward off the biting mountain frost."},kw={"anvilmar","brewnall village","coldridge valley","deeprun tram","dun morogh","frostmane","gnomeregan","gol'bolar","ironforge","kharanos","magni bronzebeard","troggs"},rel={"zone:ironforge","zone:gnomeregan","zone:lochmodan","subzone:kharanos","subzone:coldridge-valley","subzone:deeprun-tram","subzone:gol-bolar-quarry","subzone:anvilmar"},m={levels="1-10"},src={"Dun Morogh (Classic)","Dun Morogh"}}
